INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('accounting', 'Introduction to Accounting', 'Fundamentals', 'Accounting — The Language of Business', '["Define accounting and its purpose","Identify the users of accounting information","Explain the basic accounting equation","Distinguish between bookkeeping and accounting"]'::jsonb, 'medium', '20', '[{"id":"act_hook_01","type":"hook","order":1,"content":{"text":"Every business — from a small shop in the market to a multinational corporation — needs to track money coming in and going out. Accounting is the system that records, summarizes, and reports financial transactions. Without it, businesses would be flying blind.","prediction_prompt":"Why do you think even small traders need to keep track of their money?"}},{"id":"act_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Accounting is like keeping a diary of money. Every time money comes in (revenue) or goes out (expenses), you write it down. At the end of the month, you check: did I make a profit or a loss? The basic rule: what you own (assets) = what you owe (liabilities) + your investment (equity).","analogy":"Think of accounting like a health tracker. Just as a fitness app tracks your calories in vs calories out, accounting tracks money in vs money out. The result tells you if your business is ''healthy'' (profitable) or ''sick'' (losing money)."}},{"id":"act_formal_01","type":"formal_explanation","order":3,"content":{"text":"Accounting principles: (1) Going Concern — business will continue operating. (2) Consistency — use same methods year to year. (3) Accrual — record when earned/incurred, not when cash moves. (4) Prudence — don''t overstate assets or income. Users of accounting: internal (management, employees) and external (investors, government, creditors).","key_terms":[{"term":"Assets","definition":"Resources owned by the business (cash, equipment, inventory)"},{"term":"Liabilities","definition":"Debts or obligations the business owes (loans, payables)"},{"term":"Equity","definition":"Owner''s claim on assets (capital + retained earnings)"},{"term":"Revenue","definition":"Income earned from selling goods or services"},{"term":"Expenses","definition":"Costs incurred to generate revenue"}]}},{"id":"act_formula_01","type":"formula","order":4,"content":{"formula":"Assets = Liabilities + Owner''s Equity (Accounting Equation)","variables":[{"name":"Assets","description":"What the business owns (cash, inventory, equipment)"},{"name":"Liabilities","description":"What the business owes (loans, accounts payable)"},{"name":"Equity","description":"Owner''s investment in the business (capital)"}],"when_to_use":"This equation must always balance. Every transaction affects at least two accounts.","common_traps":["Confusing assets with expenses — assets are owned, expenses are spent","Forgetting the accounting equation must always balance","Not understanding that profit increases equity"],"units_note":"The accounting equation is the foundation of double-entry bookkeeping."}},{"id":"act_practice_01","type":"worked_example","order":5,"content":{"scenario":"A business starts with ₦500,000 cash. It buys equipment for ₦200,000 cash. It takes a loan of ₦100,000. What are the assets, liabilities, and equity?","given":["Starting cash: ₦500,000","Equipment purchased: ₦200,000","Loan: ₦100,000"],"required":"Calculate total assets, liabilities, and equity","principle":"Apply the accounting equation: Assets = Liabilities + Equity","steps":[{"explanation":"Calculate assets","calculation":"Cash: ₦500,000 − ₦200,000 + ₦100,000 = ₦400,000. Equipment: ₦200,000. Total assets: ₦600,000"},{"explanation":"Identify liabilities","calculation":"Loan: ₦100,000"},{"explanation":"Calculate equity","calculation":"Equity = Assets − Liabilities = ₦600,000 − ₦100,000 = ₦500,000"},{"explanation":"Verify equation","calculation":"₦600,000 = ₦100,000 + ₦500,000 ✓"}],"answer":"Assets: ₦600,000. Liabilities: ₦100,000. Equity: ₦500,000.","check":"The equation balances: ₦600,000 = ₦100,000 + ₦500,000."}},{"id":"act_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Bookkeeping and accounting are the same thing.","why_wrong":"Bookkeeping is recording transactions. Accounting goes further — it analyzes, interprets, and reports financial information for decision-making.","correct_model":"Bookkeeping = recording. Accounting = recording + analyzing + reporting + decision-making."}},{"id":"act_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests accounting equation, types of accounts, and accounting principles.","trap":"JAMB may ask about the difference between capital expenditure and revenue expenditure. Capital = long-term assets. Revenue = day-to-day expenses.","tip":"Memorize the accounting equation and practice applying it to different transactions.","related_topics":["Double-entry bookkeeping","Financial statements","Types of accounts"]}},{"id":"act_memory_01","type":"memory_hook","order":8,"content":{"text":"Accounting equation: Assets = Liabilities + Equity. Double entry: every debit has a credit. Users: internal (management) and external (investors, government). Principles: going concern, consistency, accrual, prudence.","hook_type":"mnemonic"}},{"id":"act_reflection_01","type":"reflection","order":9,"content":{"question":"Why is accounting important for a small business owner?","expected_understanding":"It helps track income and expenses, calculate profit/loss, make informed decisions, pay correct taxes, and attract investors."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The accounting equation is:","options":[{"label":"A","text":"Assets = Revenue − Expenses"},{"label":"B","text":"Assets = Liabilities + Equity"},{"label":"C","text":"Assets = Capital − Drawings"},{"label":"D","text":"Assets = Income + Liabilities"}],"answer":"B","explanation":"Assets = Liabilities + Owner''s Equity is the fundamental accounting equation.","hints":["The most basic equation in accounting"]},{"difficulty":"medium","question":"A business has assets of ₦1,000,000 and liabilities of ₦400,000. The owner''s equity is:","options":[{"label":"A","text":"₦1,400,000"},{"label":"B","text":"₦600,000"},{"label":"C","text":"₦400,000"},{"label":"D","text":"₦1,000,000"}],"answer":"B","explanation":"Equity = Assets − Liabilities = ₦1,000,000 − ₦400,000 = ₦600,000.","hints":["Rearrange the accounting equation"]},{"difficulty":"jamb","question":"Which of the following is an accounting principle?","options":[{"label":"A","text":"Profit maximization"},{"label":"B","text":"Going concern"},{"label":"C","text":"Cash basis"},{"label":"D","text":"Cost minimization"}],"answer":"B","explanation":"Going concern assumes the business will continue operating indefinitely.","hints":["Which is a fundamental accounting assumption?"]}]'::jsonb, '{"min_score":80,"required_sections":["act_hook_01","act_intuitive_01","act_formal_01","act_formula_01","act_practice_01"]}'::jsonb, '1')
