INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('accounting', 'Double Entry Bookkeeping', 'Recording Transactions', 'Double Entry — Every Debit Has a Credit', '["Explain the double entry principle","Identify types of accounts (Real, Personal, Nominal)","Apply debit and credit rules","Record transactions using journals and ledgers"]'::jsonb, 'medium', '20', '[{"id":"dbl_hook_01","type":"hook","order":1,"content":{"text":"Imagine lending your friend ₦1,000. In your mind, you''ve lost ₦1,000 cash but gained a ₦1,000 IOU. That''s double entry — every transaction has two sides. This principle, invented 500 years ago, is the backbone of all modern accounting.","prediction_prompt":"When you buy something with cash, what changes? Think about what you gain and what you lose."}},{"id":"dbl_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Double entry means every transaction affects at least TWO accounts. When you buy goods for cash: goods increase (debit), cash decreases (credit). When you receive money from a debtor: cash increases (debit), debtor decreases (credit). Debits and credits must always be equal.","analogy":"Think of double entry like a seesaw. For every push up on one side (debit), there must be an equal push down on the other side (credit). The seesaw must always stay balanced."}},{"id":"dbl_formal_01","type":"formal_explanation","order":3,"content":{"text":"Three types of accounts: (1) Personal — people and entities (Debtors, Creditors, Bank). (2) Real — assets (Cash, Equipment, Inventory). (3) Nominal — income and expenses (Sales, Rent, Salary). Rules: Personal & Real accounts: Debit the receiver, Credit the giver. Nominal accounts: Debit expenses/losses, Credit incomes/gains.","key_terms":[{"term":"Debit (Dr)","definition":"Left side of an account. Increases assets, expenses; decreases liabilities, equity, income"},{"term":"Credit (Cr)","definition":"Right side of an account. Increases liabilities, equity, income; decreases assets, expenses"},{"term":"Journal","definition":"Book of original entry where transactions are recorded chronologically"},{"term":"Ledger","definition":"Book of final entry where transactions are posted by account"}]}},{"id":"dbl_formula_01","type":"formula","order":4,"content":{"formula":"For every transaction: Total Debits = Total Credits","variables":[{"name":"Personal Account","description":"Debit receiver, Credit giver"},{"name":"Real Account","description":"Debit what comes in, Credit what goes out"},{"name":"Nominal Account","description":"Debit expenses/losses, Credit incomes/gains"}],"when_to_use":"When recording any business transaction in the books.","common_traps":["Debiting the wrong account type","Forgetting that drawing reduces equity (credit drawings, debit capital)","Confusing when to use personal vs nominal rules"],"units_note":"Every journal entry must have equal debits and credits."}},{"id":"dbl_practice_01","type":"worked_example","order":5,"content":{"scenario":"Record these transactions: (1) Owner invests ₦100,000 cash. (2) Buys equipment for ₦30,000 cash. (3) Buys goods on credit from Ali ₦20,000. (4) Sells goods for cash ₦50,000.","given":["Four transactions to record"],"required":"Journal entries for each transaction","principle":"Apply debit and credit rules for each account type.","steps":[{"explanation":"Owner invests cash","calculation":"Debit Cash ₦100,000 (asset increases), Credit Capital ₦100,000 (equity increases)"},{"explanation":"Buys equipment","calculation":"Debit Equipment ₦30,000 (asset increases), Credit Cash ₦30,000 (asset decreases)"},{"explanation":"Buys on credit","calculation":"Debit Purchases ₦20,000 (expense increases), Credit Ali (Creditor) ₦20,000 (liability increases)"},{"explanation":"Sells goods","calculation":"Debit Cash ₦50,000 (asset increases), Credit Sales ₦50,000 (income increases)"}],"answer":"All entries balanced. Total debits = Total credits for each transaction.","check":"Each entry has equal debits and credits."}},{"id":"dbl_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Debit always means increase.","why_wrong":"Debit increases assets and expenses but DECREASES liabilities, equity, and income. The effect depends on the account type.","correct_model":"Debit = left side. Effect depends on account type: increases assets/expenses, decreases liabilities/equity/income."}},{"id":"dbl_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests journal entries, ledger posting, and trial balance.","trap":"JAMB may give transactions and ask for the trial balance. Make sure total debits = total credits.","tip":"Practice journalizing common transactions: sales, purchases, expenses, capital introduction.","related_topics":["Trial balance","Financial statements","Accounting cycle"]}},{"id":"dbl_memory_01","type":"memory_hook","order":8,"content":{"text":"Personal: Debit receiver, Credit giver. Real: Debit what comes in, Credit what goes out. Nominal: Debit expenses, Credit incomes. Total debits = Total credits.","hook_type":"mnemonic"}},{"id":"dbl_reflection_01","type":"reflection","order":9,"content":{"question":"Why must every transaction have two entries?","expected_understanding":"Because every transaction has two effects — you gain something and give up something. Double entry ensures the accounting equation always balances."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"When a business receives cash from sales, which account is debited?","options":[{"label":"A","text":"Sales (credit)"},{"label":"B","text":"Cash (debit)"},{"label":"C","text":"Capital (debit)"},{"label":"D","text":"Expenses (credit)"}],"answer":"B","explanation":"Cash is debited because cash (asset) increases. Sales is credited because income increases.","hints":["What account type is cash?"]},{"difficulty":"medium","question":"The owner withdraws ₦5,000 for personal use. The journal entry is:","options":[{"label":"A","text":"Debit Cash, Credit Drawings"},{"label":"B","text":"Debit Drawings, Credit Cash"},{"label":"C","text":"Debit Capital, Credit Cash"},{"label":"D","text":"Debit Expenses, Credit Cash"}],"answer":"B","explanation":"Drawings (nominal) is debited, Cash (real) is credited because cash goes out.","hints":["Drawings reduce equity — what side increases drawings?"]},{"difficulty":"jamb","question":"A trial balance will not agree if:","options":[{"label":"A","text":"A correct entry is posted to the wrong account"},{"label":"B","text":"A debit entry is posted as a credit"},{"label":"C","text":"A transaction is completely omitted"},{"label":"D","text":"The same amount is debited and credited"}],"answer":"B","explanation":"Posting a debit as a credit will cause the trial balance to disagree. Wrong account or omission won''t affect the balance.","hints":["Which error affects the trial balance totals?"]}]'::jsonb, '{"min_score":80,"required_sections":["dbl_hook_01","dbl_intuitive_01","dbl_formal_01","dbl_formula_01","dbl_practice_01"]}'::jsonb, '1')
