INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('accounting', 'Financial Statements', 'Income Statement and Balance Sheet', 'Financial Statements — The Business Report Card', '["Prepare an income statement (profit and loss account)","Prepare a balance sheet (statement of financial position)","Understand the relationship between the two statements","Calculate net profit or loss"]'::jsonb, 'medium', '20', '[{"id":"fin_hook_01","type":"hook","order":1,"content":{"text":"At the end of every year, companies release their financial results. Is the company making money? Is it growing? Financial statements tell the story. Two main statements: Income Statement (profit or loss) and Balance Sheet (what you own and owe at a point in time).","prediction_prompt":"How would you know if a business is doing well just by looking at its numbers?"}},{"id":"fin_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Income Statement = Revenue minus Expenses = Profit or Loss (over a period). Balance Sheet = Assets, Liabilities, and Equity (at a specific date). The profit from the Income Statement flows into the Balance Sheet as retained earnings, increasing equity.","analogy":"Think of the Income Statement like your monthly salary slip — how much you earned vs how much you spent. The Balance Sheet is like a snapshot of your bank account, debts, and possessions on a specific day."}},{"id":"fin_formal_01","type":"formal_explanation","order":3,"content":{"text":"Income Statement structure: Sales Revenue − Cost of Sales = Gross Profit. Gross Profit − Operating Expenses = Net Profit. Balance Sheet structure: Non-current Assets + Current Assets = Total Assets. Current Liabilities + Non-current Liabilities + Equity = Total Liabilities + Equity. The two sides must be equal.","key_terms":[{"term":"Gross Profit","definition":"Sales minus cost of goods sold"},{"term":"Net Profit","definition":"Gross profit minus all operating expenses"},{"term":"Current Assets","definition":"Assets that can be converted to cash within one year (cash, inventory, debtors)"},{"term":"Non-current Assets","definition":"Long-term assets (equipment, buildings, vehicles)"},{"term":"Current Liabilities","definition":"Debts due within one year (creditors, short-term loans)"}]}},{"id":"fin_formula_01","type":"formula","order":4,"content":{"formula":"Net Profit = Revenue − Cost of Goods Sold − Expenses. Total Assets = Total Liabilities + Equity","variables":[{"name":"Revenue","description":"Total income from sales"},{"name":"COGS","description":"Direct cost of producing goods sold"},{"name":"Expenses","description":"Operating costs (rent, salary, utilities)"},{"name":"Current Assets","description":"Cash + Inventory + Debtors + Prepayments"},{"name":"Non-current Assets","description":"Equipment + Buildings − Depreciation"}],"when_to_use":"When preparing financial statements at year-end.","common_traps":["Confusing gross profit with net profit","Forgetting to include all expenses (depreciation, interest)","Mixing up current and non-current items"],"units_note":"Income Statement covers a period (e.g., year ended Dec 31). Balance Sheet is at a specific date."}},{"id":"fin_practice_01","type":"worked_example","order":5,"content":{"scenario":"Prepare an income statement: Sales ₦500,000; Cost of Sales ₦300,000; Rent ₦50,000; Salary ₦80,000; Utilities ₦20,000.","given":["Revenue and expenses for the year"],"required":"Calculate net profit","principle":"Subtract all expenses from revenue.","steps":[{"explanation":"Gross Profit","calculation":"₦500,000 − ₦300,000 = ₦200,000"},{"explanation":"Total Expenses","calculation":"₦50,000 + ₦80,000 + ₦20,000 = ₦150,000"},{"explanation":"Net Profit","calculation":"₦200,000 − ₦150,000 = ₦50,000"}],"answer":"Net Profit = ₦50,000.","check":"₦500,000 − ₦300,000 − ₦50,000 − ₦80,000 − ₦20,000 = ₦50,000."}},{"id":"fin_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The balance sheet shows profit.","why_wrong":"The Income Statement shows profit or loss. The Balance Sheet shows assets, liabilities, and equity at a point in time.","correct_model":"Income Statement = profit/loss. Balance Sheet = financial position (assets = liabilities + equity)."}},{"id":"fin_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests preparation of income statement and balance sheet from given data.","trap":"JAMB may give trial balance data and ask you to prepare both statements. Don''t forget depreciation and closing stock.","tip":"Always check: Net profit goes to balance sheet equity. Trial balance totals must agree before preparing statements.","related_topics":["Trial balance","Adjustments","Depreciation"]}},{"id":"fin_memory_01","type":"memory_hook","order":8,"content":{"text":"Income Statement: Revenue − Expenses = Profit. Balance Sheet: Assets = Liabilities + Equity. Gross Profit = Sales − COGS. Net Profit = Gross Profit − Operating Expenses.","hook_type":"mnemonic"}},{"id":"fin_reflection_01","type":"reflection","order":9,"content":{"question":"Why must the balance sheet balance?","expected_understanding":"Because of the accounting equation: every asset is funded either by borrowing (liabilities) or by the owner''s investment (equity). The two sides must always be equal."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Net profit is calculated as:","options":[{"label":"A","text":"Revenue + Expenses"},{"label":"B","text":"Revenue − Expenses"},{"label":"C","text":"Assets − Liabilities"},{"label":"D","text":"Sales − Capital"}],"answer":"B","explanation":"Net profit = Revenue − Expenses.","hints":["What''s left after paying all costs?"]},{"difficulty":"medium","question":"Which item appears on the balance sheet, not the income statement?","options":[{"label":"A","text":"Sales revenue"},{"label":"B","text":"Rent expense"},{"label":"C","text":"Inventory"},{"label":"D","text":"Salary expense"}],"answer":"C","explanation":"Inventory is a current asset on the balance sheet. Sales, rent, and salary are on the income statement.","hints":["Which is an asset, not an income or expense?"]},{"difficulty":"jamb","question":"Closing stock appears in the balance sheet as:","options":[{"label":"A","text":"A liability"},{"label":"B","text":"An expense"},{"label":"C","text":"A current asset"},{"label":"D","text":"Income"}],"answer":"C","explanation":"Closing stock (inventory) is a current asset on the balance sheet.","hints":["Stock is something the business owns"]}]'::jsonb, '{"min_score":80,"required_sections":["fin_hook_01","fin_intuitive_01","fin_formal_01","fin_formula_01","fin_practice_01"]}'::jsonb, '1')
