INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('accounting', 'Cost and Management Accounting', 'Costing Methods', 'Cost Accounting — Knowing What Things Really Cost', '["Classify costs (fixed, variable, direct, indirect)","Calculate total cost and unit cost","Understand cost-volume-profit analysis","Apply break-even analysis"]'::jsonb, 'medium', '20', '[{"id":"cost_hook_01","type":"hook","order":1,"content":{"text":"A shoe maker sells each pair for ₦5,000. But how much does it actually cost to make one pair? Materials, labour, rent — how do you calculate the real cost? If you don''t know your costs, you can''t set the right price, and you might be selling at a loss without knowing it.","prediction_prompt":"If you run a business, how would you figure out if you''re making a profit on each item you sell?"}},{"id":"cost_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Costs can be classified in different ways: Fixed costs stay the same regardless of output (rent, insurance). Variable costs change with output (materials, direct labour). Direct costs can be traced to a specific product (shoe leather). Indirect costs (overheads) support the business but aren''t directly tied to one product (factory rent). Total cost = Fixed + Variable.","analogy":"Think of fixed costs like your phone bill — you pay the same amount whether you make 1 call or 1000. Variable costs are like data charges — the more you use, the more you pay."}},{"id":"cost_formal_01","type":"formal_explanation","order":3,"content":{"text":"Cost classifications: (1) Fixed — constant regardless of output (rent, salary). (2) Variable — changes with output (materials, direct labour). (3) Semi-variable — partly fixed, partly variable (electricity with standing charge). Break-even analysis: the point where total revenue = total cost (no profit, no loss). Contribution = Selling price − Variable cost per unit.","key_terms":[{"term":"Fixed Cost","definition":"Cost that doesn''t change with output level"},{"term":"Variable Cost","definition":"Cost that changes directly with output level"},{"term":"Break-even Point","definition":"Output level where total revenue = total cost"},{"term":"Contribution","definition":"Selling price minus variable cost per unit"},{"term":"Margin of Safety","definition":"Actual sales minus break-even sales"}]}},{"id":"cost_formula_01","type":"formula","order":4,"content":{"formula":"Break-even Point (units) = Fixed Costs / (Selling Price − Variable Cost per unit)","variables":[{"name":"Fixed Costs","description":"Total fixed costs for the period"},{"name":"Selling Price","description":"Price per unit"},{"name":"Variable Cost/unit","description":"Variable cost per unit produced"},{"name":"Contribution","description":"Selling Price − Variable Cost per unit"}],"when_to_use":"When determining how many units must be sold to cover all costs.","common_traps":["Confusing fixed and variable costs","Forgetting to include ALL fixed costs","Using total costs instead of per-unit variable costs in break-even formula"],"units_note":"Break-even can be calculated in units or in revenue (₦)."}},{"id":"cost_practice_01","type":"worked_example","order":5,"content":{"scenario":"A business has fixed costs of ₦200,000 per month. Each unit sells for ₦10,000 and costs ₦6,000 in variable costs. Calculate the break-even point.","given":["Fixed costs: ₦200,000","Selling price: ₦10,000","Variable cost: ₦6,000"],"required":"Calculate break-even point in units","principle":"Break-even = Fixed Costs ÷ (Selling Price − Variable Cost per unit)","steps":[{"explanation":"Calculate contribution","calculation":"₦10,000 − ₦6,000 = ₦4,000 per unit"},{"explanation":"Calculate break-even","calculation":"₦200,000 ÷ ₦4,000 = 50 units"}],"answer":"The business must sell 50 units to break even.","check":"At 50 units: Revenue = 50 × ₦10,000 = ₦500,000. Total cost = ₦200,000 + (50 × ₦6,000) = ₦500,000. Profit = ₦0."}},{"id":"cost_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Fixed costs increase when production increases.","why_wrong":"Fixed costs stay the same regardless of output (within relevant range). Rent doesn''t change if you produce 1 or 1000 units.","correct_model":"Fixed costs are constant. Variable costs increase with output. Total cost = Fixed + Variable."}},{"id":"cost_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests cost classification, break-even analysis, and cost-volume-profit.","trap":"JAMB may give semi-variable costs and ask you to separate them into fixed and variable components using high-low method.","tip":"Practice break-even diagrams — know how to plot fixed costs, total costs, and total revenue lines.","related_topics":["Budgeting","Variance analysis","Decision making"]}},{"id":"cost_memory_01","type":"memory_hook","order":8,"content":{"text":"Fixed = constant (rent). Variable = changes with output (materials). Contribution = Price − Variable cost. Break-even = Fixed Costs ÷ Contribution per unit.","hook_type":"mnemonic"}},{"id":"cost_reflection_01","type":"reflection","order":9,"content":{"question":"Why is break-even analysis important for a business owner?","expected_understanding":"It helps determine how many units must be sold to cover costs. Below break-even, the business loses money. Above, it makes profit. It guides pricing and production decisions."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Rent paid for a factory is an example of:","options":[{"label":"A","text":"Variable cost"},{"label":"B","text":"Fixed cost"},{"label":"C","text":"Direct cost"},{"label":"D","text":"Selling cost"}],"answer":"B","explanation":"Rent is a fixed cost — it doesn''t change with the level of output.","hints":["Does the cost change with production?"]},{"difficulty":"medium","question":"The break-even point is where:","options":[{"label":"A","text":"Revenue is maximum"},{"label":"B","text":"Total revenue equals total cost"},{"label":"C","text":"Variable costs equal fixed costs"},{"label":"D","text":"Profit is maximum"}],"answer":"B","explanation":"Break-even is where total revenue = total cost — no profit, no loss.","hints":["What does ''break even'' mean?"]},{"difficulty":"jamb","question":"If fixed costs are ₦150,000, selling price is ₦12,000, and variable cost per unit is ₦8,000, the break-even point is:","options":[{"label":"A","text":"12.5 units"},{"label":"B","text":"19 units"},{"label":"C","text":"38 units"},{"label":"D","text":"50 units"}],"answer":"C","explanation":"Break-even = ₦150,000 ÷ (₦12,000 − ₦8,000) = ₦150,000 ÷ ₦4,000 = 37.5 ≈ 38 units.","hints":["Use the formula: FC ÷ (SP − VC)"]}]'::jsonb, '{"min_score":80,"required_sections":["cost_hook_01","cost_intuitive_01","cost_formal_01","cost_formula_01","cost_practice_01"]}'::jsonb, '1')
