INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('accounting', 'Accounting Ratio Analysis', 'Performance Measurement', 'Ratio Analysis — Measuring Business Health', '["Calculate key accounting ratios","Interpret profitability, liquidity, and efficiency ratios","Use ratios to evaluate business performance","Compare ratios across different periods"]'::jsonb, 'hard', '20', '[{"id":"rat_hook_01","type":"hook","order":1,"content":{"text":"Two companies both make ₦10 million profit. But one has ₦50 million in assets, and the other has ₦200 million. Which is doing better? You can''t just look at profit — you need ratios. Ratios are like vital signs for a business: they tell you how healthy it really is.","prediction_prompt":"If two students both score 80%, but one studied for 2 hours and the other for 10 hours, who performed better? How would you measure this?"}},{"id":"rat_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Ratios compare two numbers to give meaning. Gross profit margin = how much profit you make on each sale before expenses. Net profit margin = how much you keep after ALL expenses. Current ratio = can you pay short-term debts? Return on investment = how well is the owner''s money working?","analogy":"Think of ratios like a doctor''s checkup. Blood pressure, heart rate, temperature — each number alone means little, but together they tell the story of your health. Business ratios do the same for a company."}},{"id":"rat_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key ratios: (1) Gross Profit Margin = Gross Profit/Revenue × 100. (2) Net Profit Margin = Net Profit/Revenue × 100. (3) Current Ratio = Current Assets/Current Liabilities. (4) Quick Ratio = (Current Assets − Inventory)/Current Liabilities. (5) Return on Capital Employed (ROCE) = Net Profit/Capital Employed × 100.","key_terms":[{"term":"Gross Profit Margin","definition":"Percentage of revenue remaining after cost of goods sold"},{"term":"Current Ratio","definition":"Ability to pay short-term debts (ideal: 2:1)"},{"term":"ROCE","definition":"Return on the total capital invested in the business"},{"term":"Inventory Turnover","definition":"How many times inventory is sold and replaced in a period"}]}},{"id":"rat_formula_01","type":"formula","order":4,"content":{"formula":"Gross Profit Margin = (Gross Profit / Revenue) × 100. Current Ratio = Current Assets : Current Liabilities. ROCE = (Net Profit / Capital Employed) × 100","variables":[{"name":"Gross Profit Margin","description":"Higher = better cost control on production"},{"name":"Net Profit Margin","description":"Higher = more efficient overall operations"},{"name":"Current Ratio","description":"Ideal is 2:1. Below 1 = liquidity problems"},{"name":"ROCE","description":"Higher = better use of invested capital"}],"when_to_use":"When evaluating business performance, comparing companies, or making investment decisions.","common_traps":["Using book value instead of market value for ROCE","Not interpreting ratios in context (industry matters)","Confusing current ratio with quick ratio"],"units_note":"Most ratios are expressed as percentages or ratios (e.g., 2:1)."}},{"id":"rat_practice_01","type":"worked_example","order":5,"content":{"scenario":"Company A: Revenue ₦1,000,000. Gross Profit ₦400,000. Net Profit ₦150,000. Current Assets ₦300,000. Current Liabilities ₦200,000. Calculate key ratios.","given":["Financial data for Company A"],"required":"Calculate gross margin, net margin, and current ratio","principle":"Apply the ratio formulas.","steps":[{"explanation":"Gross Profit Margin","calculation":"₦400,000 / ₦1,000,000 × 100 = 40%"},{"explanation":"Net Profit Margin","calculation":"₦150,000 / ₦1,000,000 × 100 = 15%"},{"explanation":"Current Ratio","calculation":"₦300,000 / ₦200,000 = 1.5:1"}],"answer":"Gross margin: 40%. Net margin: 15%. Current ratio: 1.5:1.","check":"The current ratio of 1.5:1 means the company has ₦1.50 in current assets for every ₦1 of current liabilities."}},{"id":"rat_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A high current ratio is always good.","why_wrong":"A very high current ratio (e.g., 5:1) may mean the business has too much idle cash or unsold inventory — inefficient use of resources.","correct_model":"The ideal current ratio is around 2:1. Too high = inefficiency. Too low = liquidity risk."}},{"id":"rat_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests ratio calculations and interpretation.","trap":"JAMB may ask you to compare two companies and explain which is more efficient. Don''t just calculate — INTERPRET.","tip":"Memorize the key ratios and their ideal values. Practice interpreting what each ratio tells you about the business.","related_topics":["Financial analysis","Business performance","Investment decisions"]}},{"id":"rat_memory_01","type":"memory_hook","order":8,"content":{"text":"Gross margin = GP/Revenue. Net margin = NP/Revenue. Current ratio = CA:CL (ideal 2:1). ROCE = NP/Capital Employed. Higher profitability ratios = better. Current ratio too high = inefficiency.","hook_type":"mnemonic"}},{"id":"rat_reflection_01","type":"reflection","order":9,"content":{"question":"Why is it important to compare ratios over multiple years rather than just one year?","expected_understanding":"Trends over time reveal whether the business is improving or declining. A single year''s ratio doesn''t show direction. Ratios also need to be compared with industry averages for meaningful analysis."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Gross profit margin is calculated as:","options":[{"label":"A","text":"Net Profit / Revenue × 100"},{"label":"B","text":"Gross Profit / Revenue × 100"},{"label":"C","text":"Revenue / Gross Profit × 100"},{"label":"D","text":"Revenue / Net Profit × 100"}],"answer":"B","explanation":"Gross profit margin = (Gross Profit / Revenue) × 100.","hints":["Which profit and which figure?"]},{"difficulty":"medium","question":"A current ratio of 0.8:1 indicates:","options":[{"label":"A","text":"The company is very profitable"},{"label":"B","text":"The company may struggle to pay short-term debts"},{"label":"C","text":"The company has too much inventory"},{"label":"D","text":"The company has high sales"}],"answer":"B","explanation":"A current ratio below 1:1 means current liabilities exceed current assets — liquidity problems.","hints":["What does the current ratio measure?"]},{"difficulty":"jamb","question":"Company A has a net profit margin of 12% and Company B has 8%. This means:","options":[{"label":"A","text":"Company A is larger"},{"label":"B","text":"Company A keeps more profit from each ₦ of sales"},{"label":"C","text":"Company B has more revenue"},{"label":"D","text":"Company A has lower costs"}],"answer":"B","explanation":"Net profit margin shows how much profit is kept from each ₦ of revenue. Higher = more efficient.","hints":["What does the net margin percentage tell you?"]}]'::jsonb, '{"min_score":80,"required_sections":["rat_hook_01","rat_intuitive_01","rat_formal_01","rat_formula_01","rat_practice_01"]}'::jsonb, '1')
