INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('agricultural_science', 'Introduction to Agriculture', 'Branches and Importance', 'Agriculture — The Foundation of Civilization', '["Define agriculture and its branches","Explain the importance of agriculture to national development","Identify types of farming systems","Understand the role of agriculture in food security"]'::jsonb, 'medium', '20', '[{"id":"ag_hook_01","type":"hook","order":1,"content":{"text":"Without agriculture, there would be no food, no clothes (cotton), no furniture (timber), no medicines (herbs). Agriculture is the oldest and most important human activity. It feeds us, clothes us, and powers economies. Yet many people look down on farming.","prediction_prompt":"Can you go through a single day without using anything that comes from agriculture?"}},{"id":"ag_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Agriculture = cultivation of crops and rearing of animals for human use. Branches: Crop science (arable farming — yam, cassava, rice). Animal science (livestock — cattle, poultry, fish). Agricultural economics (business side). Agricultural engineering (machines and tools). It provides food, raw materials, employment, and export revenue.","analogy":"Think of agriculture as the root of a tree. The trunk is industry, the branches are services, and the leaves are technology. Without strong roots (agriculture), the whole tree collapses."}},{"id":"ag_formal_01","type":"formal_explanation","order":3,"content":{"text":"Importance of agriculture: (1) Food security — provides food for the population. (2) Employment — employs ~35% of Nigeria''s workforce. (3) Foreign exchange — cocoa, rubber, palm oil are major exports. (4) Raw materials — cotton, rubber, timber for industries. (5) Revenue — government earns from agricultural exports. Types of farming: subsistence (small-scale, family labour), commercial (large-scale, mechanized).","key_terms":[{"term":"Agriculture","definition":"The science and practice of cultivating crops and rearing animals for food, fibre, and other products"},{"term":"Subsistence Farming","definition":"Small-scale farming mainly to feed the family"},{"term":"Commercial Farming","definition":"Large-scale farming for sale and profit"},{"term":"Arable Farming","definition":"Farming that involves ploughing land and growing crops"},{"term":"Pastoral Farming","definition":"Farming that involves rearing livestock"}]}},{"id":"ag_formula_01","type":"formula","order":4,"content":{"formula":"Agricultural Output = f(Land, Labour, Capital, Technology, Management)","variables":[{"name":"Land","description":"Fertile soil, adequate rainfall, proper drainage"},{"name":"Labour","description":"Human effort — unskilled, semi-skilled, skilled"},{"name":"Capital","description":"Money for inputs — seeds, fertilizers, equipment"},{"name":"Technology","description":"Improved methods — irrigation, mechanization, improved seeds"},{"name":"Management","description":"Planning, organizing, and controlling farm activities"}],"when_to_use":"When analyzing factors affecting agricultural productivity.","common_traps":["Focusing only on land — labour, capital, and technology are equally important","Not knowing the difference between subsistence and commercial farming","Forgetting that management (planning) is crucial"],"units_note":"Agriculture contributes about 24% of Nigeria''s GDP but employs ~35% of the workforce."}},{"id":"ag_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain why agriculture is important to Nigeria''s economy.","given":["Nigeria''s agricultural sector"],"required":"Discuss the importance of agriculture","principle":"Use the five key areas: food, employment, exports, raw materials, revenue.","steps":[{"explanation":"Food security","calculation":"Agriculture provides food for 200+ million Nigerians"},{"explanation":"Employment","calculation":"~35% of the workforce depends on agriculture"},{"explanation":"Foreign exchange","calculation":"Cocoa, rubber, palm oil earn billions in exports"},{"explanation":"Raw materials","calculation":"Cotton, rubber, timber supply local industries"},{"explanation":"Government revenue","calculation":"Export duties and taxes from agriculture"}],"answer":"Agriculture provides food, employment (35% of workforce), foreign exchange, raw materials, and government revenue.","check":"Without agriculture, Nigeria would depend entirely on food imports."}},{"id":"ag_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Agriculture is only for uneducated people.","why_wrong":"Modern agriculture requires knowledge of biology, chemistry, economics, and technology. Agricultural scientists, engineers, and economists are highly educated professionals.","correct_model":"Agriculture is a science that requires education, technology, and management skills."}},{"id":"ag_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests branches of agriculture, importance, and farming types.","trap":"JAMB may ask about specific agricultural programmes: Operation Feed the Nation (OFN), Green Revolution, Anchor Borrowers'' Programme.","tip":"Know the branches of agriculture and Nigeria''s agricultural history. Use specific examples.","related_topics":["Food security","Agricultural development","Rural economy"]}},{"id":"ag_memory_01","type":"memory_hook","order":8,"content":{"text":"Agriculture = crops + animals. Branches: crop science, animal science, agricultural economics, agricultural engineering. Types: subsistence (family) + commercial (profit). Importance: food, jobs, exports, materials, revenue.","hook_type":"mnemonic"}},{"id":"ag_reflection_01","type":"reflection","order":9,"content":{"question":"How can agriculture be made attractive to young Nigerians?","expected_understanding":"Modernize farming with technology, make it profitable through better prices and processing, provide credit, and change the perception that farming is backward."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Farming mainly to feed one''s family is called:","options":[{"label":"A","text":"Commercial farming"},{"label":"B","text":"Subsistence farming"},{"label":"C","text":"Plantation farming"},{"label":"D","text":"Industrial farming"}],"answer":"B","explanation":"Subsistence farming is small-scale farming to feed the family.","hints":["Growing food to eat, not sell"]},{"difficulty":"medium","question":"Which of the following is NOT a branch of agriculture?","options":[{"label":"A","text":"Crop science"},{"label":"B","text":"Animal science"},{"label":"C","text":"Computer science"},{"label":"D","text":"Agricultural economics"}],"answer":"C","explanation":"Computer science is not a branch of agriculture. The branches include crop science, animal science, agricultural economics, and agricultural engineering.","hints":["Which is unrelated to farming?"]},{"difficulty":"jamb","question":"Agriculture contributes to national development by:","options":[{"label":"A","text":"Only providing food"},{"label":"B","text":"Providing food, employment, raw materials, and export revenue"},{"label":"C","text":"Only employing people"},{"label":"D","text":"Only earning foreign exchange"}],"answer":"B","explanation":"Agriculture contributes in multiple ways: food, jobs, raw materials, exports, and government revenue.","hints":["What are ALL the contributions?"]}]'::jsonb, '{"min_score":80,"required_sections":["ag_hook_01","ag_intuitive_01","ag_formal_01","ag_formula_01","ag_practice_01"]}'::jsonb, '1')
