INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('agricultural_science', 'Crop Production', 'Soil and Tillage', 'Crop Production — Growing the Food We Eat', '["Describe the composition and properties of soil","Explain soil conservation methods","Understand tillage operations and their purposes","Identify factors affecting crop growth"]'::jsonb, 'medium', '20', '[{"id":"crp_hook_01","type":"hook","order":1,"content":{"text":"All food comes from the soil. Rice grows in flooded fields, yam grows in mounds, cassava grows in ridges. The soil provides water, nutrients, and support for plant roots. Without healthy soil, there''s no food. Yet soil is being lost to erosion, pollution, and poor farming practices every day.","prediction_prompt":"Why do farmers sometimes get lower yields from the same land year after year?"}},{"id":"crp_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Soil is made of minerals, organic matter (decayed plants/animals), water, air, and living organisms. Healthy soil has the right balance of these. Tillage = preparing the land for planting: ploughing (turning the soil), harrowing (breaking clumps), ridging (making mounds). Different crops need different soil preparation.","analogy":"Think of soil like a cake recipe. Minerals = flour. Organic matter = sugar. Water and air = eggs and butter. Living organisms = the oven that makes it all work. If you leave out any ingredient, the cake (crop) won''t turn out well."}},{"id":"crp_formal_01","type":"formal_explanation","order":3,"content":{"text":"Soil components: mineral particles (sand, silt, clay), organic matter, water, air, microorganisms. Soil types: sandy (drains fast, low nutrients), clay (retains water, compact), loam (balanced — best for farming). Soil conservation: crop rotation, mulching, contour ploughing, terracing, cover cropping, avoiding overgrazing.","key_terms":[{"term":"Soil","definition":"The top layer of earth''s surface where plants grow"},{"term":"Loam","definition":"A balanced soil type with sand, silt, and clay — ideal for farming"},{"term":"Tillage","definition":"Preparing land for planting by ploughing, harrowing, and ridging"},{"term":"Crop Rotation","definition":"Growing different crops on the same land in successive seasons"},{"term":"Erosion","definition":"The wearing away of topsoil by wind, water, or farming activities"}]}},{"id":"crp_formula_01","type":"formula","order":4,"content":{"formula":"Soil Health = f(Organic matter, pH, Nutrients, Structure, Moisture)","variables":[{"name":"Organic Matter","description":"Decayed plant and animal material — improves soil structure and nutrients"},{"name":"pH","description":"Acidity or alkalinity — most crops prefer 6.0-7.0"},{"name":"Nutrients","description":"Nitrogen (N), Phosphorus (P), Potassium (K) — the big three"},{"name":"Structure","description":"How particles are arranged — affects root growth and water movement"},{"name":"Moisture","description":"Water content — too much or too little is bad"}],"when_to_use":"When diagnosing soil problems or planning crop production.","common_traps":["Not testing soil before applying fertilizer","Ignoring organic matter — it''s the key to healthy soil","Over-tilling which destroys soil structure"],"units_note":"Soil pH is measured on a scale of 0-14. Below 7 = acidic, above 7 = alkaline, 7 = neutral."}},{"id":"crp_practice_01","type":"worked_example","order":5,"content":{"scenario":"A farmer notices low crop yields despite using fertilizers. Suggest possible causes and solutions.","given":["Low yields despite fertilizer use"],"required":"Diagnose and solve the problem","principle":"Fertilizer alone doesn''t guarantee good yields — other factors matter.","steps":[{"explanation":"Check soil pH","calculation":"If pH is too low (acidic) or too high (alkaline), plants can''t absorb nutrients. Solution: apply lime (if acidic) or gypsum (if alkaline)"},{"explanation":"Check organic matter","calculation":"Low organic matter means poor soil structure. Solution: add compost or manure"},{"explanation":"Check water","calculation":"Too little or too much water affects nutrient uptake. Solution: improve drainage or irrigation"},{"explanation":"Check nutrients","calculation":"NPK fertilizer may not address all deficiencies. Solution: do soil test and apply specific nutrients"}],"answer":"Possible causes: wrong pH, low organic matter, poor drainage, nutrient imbalance. Solution: soil testing, organic matter addition, proper drainage, targeted fertilization.","check":"Fertilizer is only one part of soil management — pH, organic matter, and water are equally important."}},{"id":"crp_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Adding more fertilizer always increases yields.","why_wrong":"Excessive fertilizer can damage crops (burn roots), pollute water, and harm soil organisms. The right amount depends on soil test results.","correct_model":"Fertilizer should be applied based on soil test results, not just ''more is better''."}},{"id":"crp_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests soil types, conservation methods, and tillage operations.","trap":"JAMB may ask about specific soil properties: texture vs structure, or types of erosion (gully, sheet, rill).","tip":"Know soil types (sand, clay, loam) and their properties. Know conservation methods and when to use each.","related_topics":["Soil conservation","Fertilizer types","Crop management"]}},{"id":"crp_memory_01","type":"memory_hook","order":8,"content":{"text":"Soil = minerals + organic matter + water + air + organisms. Loam = best (sand + silt + clay). Conservation: rotation, mulching, terracing, cover crops. Tillage: plough, harrow, ridge.","hook_type":"mnemonic"}},{"id":"crp_reflection_01","type":"reflection","order":9,"content":{"question":"Why is soil conservation important for future food security?","expected_understanding":"Topsoil takes hundreds of years to form. If we lose it to erosion or degradation, future generations won''t be able to grow food. Conservation ensures the land remains productive."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The best soil type for farming is:","options":[{"label":"A","text":"Sandy soil"},{"label":"B","text":"Clay soil"},{"label":"C","text":"Loam soil"},{"label":"D","text":"Rocky soil"}],"answer":"C","explanation":"Loam soil has a balanced mix of sand, silt, and clay — ideal for most crops.","hints":["Which soil has the best balance?"]},{"difficulty":"medium","question":"Crop rotation helps to:","options":[{"label":"A","text":"Increase soil erosion"},{"label":"B","text":"Maintain soil fertility and break pest cycles"},{"label":"C","text":"Reduce crop variety"},{"label":"D","text":"Increase the need for pesticides"}],"answer":"B","explanation":"Crop rotation maintains soil fertility (different crops use different nutrients) and breaks pest and disease cycles.","hints":["Why grow different crops on the same land?"]},{"difficulty":"jamb","question":"Mulching helps to:","options":[{"label":"A","text":"Increase evaporation"},{"label":"B","text":"Conserve soil moisture and reduce erosion"},{"label":"C","text":"Kill beneficial organisms"},{"label":"D","text":"Increase soil temperature"}],"answer":"B","explanation":"Mulching covers the soil surface, reducing evaporation and protecting against erosion.","hints":["What does covering the soil do?"]}]'::jsonb, '{"min_score":80,"required_sections":["crp_hook_01","crp_intuitive_01","crp_formal_01","crp_formula_01","crp_practice_01"]}'::jsonb, '1')
