INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('agricultural_science', 'Livestock Production', 'Animal Husbandry', 'Livestock — Raising Animals for Food and Profit', '["Identify major livestock in Nigeria","Explain livestock management practices","Understand animal nutrition and feeding","Identify common livestock diseases and prevention"]'::jsonb, 'medium', '20', '[{"id":"live_hook_01","type":"hook","order":1,"content":{"text":"Nigeria has over 20 million cattle, 70 million goats, 40 million sheep, and millions of poultry. Livestock provides meat, milk, eggs, leather, and manure. But raising animals isn''t just putting them in a field — it requires knowledge of nutrition, health, breeding, and housing.","prediction_prompt":"What are the challenges of raising cattle in northern Nigeria?"}},{"id":"live_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Livestock management includes: housing (shelter from weather and predators), feeding (balanced diet for growth and production), breeding (selecting the best animals), health care (vaccination, deworming), and record keeping. Different animals have different needs: cattle need pasture, poultry need feed and water, fish need ponds.","analogy":"Think of raising livestock like raising children. They need proper shelter, nutritious food, regular health check-ups, and a safe environment. Neglect any of these, and they''ll get sick or die."}},{"id":"live_formal_01","type":"formal_explanation","order":3,"content":{"text":"Major livestock in Nigeria: (1) Cattle — beef and dairy. (2) Poultry — eggs and meat. (3) Goats — meat and milk. (4) Sheep — meat and wool. (5) Fish — aquaculture. Management practices: housing (types: zero-grazing, free-range, semi-intensive), feeding (concentrates, roughages, supplements), breeding (natural and artificial insemination), disease control (vaccination, quarantine).","key_terms":[{"term":"Livestock","definition":"Domesticated animals raised for food, fibre, or other products"},{"term":"Zero-grazing","definition":"Keeping animals in confined areas and bringing food to them"},{"term":"Free-range","definition":"Allowing animals to roam freely and forage"},{"term":"Concentrates","definition":"High-energy feed like maize, groundnut cake, soybean"},{"term":"Roughage","definition":"Fibrous feed like grass, hay, and crop residues"}]}},{"id":"live_formula_01","type":"formula","order":4,"content":{"formula":"Animal Nutrition: Energy + Protein + Vitamins + Minerals + Water = Balanced Diet","variables":[{"name":"Energy","description":"From carbohydrates (maize, cassava) — for body functions and growth"},{"name":"Protein","description":"From groundnut, soybean, fish meal — for muscle and milk production"},{"name":"Vitamins","description":"From green vegetables, sunlight — for health and disease resistance"},{"name":"Minerals","description":"From salt licks, bone meal — for bone development and milk production"},{"name":"Water","description":"Essential for all body functions — animals need clean water daily"}],"when_to_use":"When formulating animal feed or diagnosing nutritional problems.","common_traps":["Feeding only one type of feed — animals need balanced nutrition","Not providing clean water — water is the most important nutrient","Ignoring minerals — deficiency causes poor growth and diseases"],"units_note":"A dairy cow needs 50-100 litres of water per day. Poultry need 200-300ml per day."}},{"id":"live_practice_01","type":"worked_example","order":5,"content":{"scenario":"A poultry farmer notices that chickens are not laying eggs as expected. Suggest possible causes and solutions.","given":["Low egg production in poultry"],"required":"Diagnose and solve the problem","principle":"Egg production depends on nutrition, lighting, health, and stress management.","steps":[{"explanation":"Check nutrition","calculation":"Hens need 16-18% protein, calcium for eggshells. Solution: provide balanced poultry feed with calcium supplement"},{"explanation":"Check lighting","calculation":"Hens need 14-16 hours of light per day for egg production. Solution: provide artificial lighting in the coop"},{"explanation":"Check health","calculation":"Diseases like Newcastle reduce production. Solution: vaccinate regularly"},{"explanation":"Check stress","calculation":"Overcrowding, heat, and predators cause stress. Solution: reduce density, provide shade, secure the coop"}],"answer":"Causes: poor nutrition, insufficient light, disease, stress. Solutions: balanced feed, 14-16 hours light, vaccination, proper housing.","check":"All four factors (nutrition, light, health, stress) affect egg production."}},{"id":"live_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Animals can eat anything — they''re not picky.","why_wrong":"Animals need specific nutrients in specific amounts. Feeding them random food can cause malnutrition, diseases, and death.","correct_model":"Livestock need balanced nutrition. Different animals have different dietary needs."}},{"id":"live_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests livestock management, nutrition, and disease control.","trap":"JAMB may ask about specific diseases: Newcastle (poultry), anthrax (cattle), trypanosomiasis (tsetse fly disease).","tip":"Know the major livestock diseases and their control methods. Know the nutritional requirements of different animals.","related_topics":["Animal health","Feed formulation","Livestock economics"]}},{"id":"live_memory_01","type":"memory_hook","order":8,"content":{"text":"Livestock = cattle, poultry, goats, sheep, fish. Needs: housing, feeding, breeding, health care. Feed: energy + protein + vitamins + minerals + water. Diseases: Newcastle, anthrax, trypanosomiasis.","hook_type":"mnemonic"}},{"id":"live_reflection_01","type":"reflection","order":9,"content":{"question":"What are the challenges of livestock farming in Nigeria?","expected_understanding":"Inadequate feed, disease outbreaks, poor infrastructure, insecurity (rustling), climate change, and limited access to credit and modern technology."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Keeping animals in confined areas and bringing food to them is called:","options":[{"label":"A","text":"Free-range system"},{"label":"B","text":"Zero-grazing"},{"label":"C","text":"Nomadic farming"},{"label":"D","text":"Subsistence farming"}],"answer":"B","explanation":"Zero-grazing confines animals in one area and feeds them there.","hints":["Animals stay in one place"]},{"difficulty":"medium","question":"The most important nutrient for livestock is:","options":[{"label":"A","text":"Protein"},{"label":"B","text":"Carbohydrates"},{"label":"C","text":"Water"},{"label":"D","text":"Vitamins"}],"answer":"C","explanation":"Water is essential for all body functions. Animals can die faster from dehydration than from lack of food.","hints":["What do animals need most urgently?"]},{"difficulty":"jamb","question":"Trypanosomiasis in cattle is caused by:","options":[{"label":"A","text":"Bacteria"},{"label":"B","text":"Virus"},{"label":"C","text":"Tsetse fly bite"},{"label":"D","text":"Poor nutrition"}],"answer":"C","explanation":"Trypanosomiasis (nagana) is transmitted by the tsetse fly and causes weight loss and death in cattle.","hints":["Which insect transmits this disease?"]}]'::jsonb, '{"min_score":80,"required_sections":["live_hook_01","live_intuitive_01","live_formal_01","live_formula_01","live_practice_01"]}'::jsonb, '1')
