INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('agricultural_science', 'Agricultural Economics', 'Farm Management', 'Farm Management — Running Agriculture as a Business', '["Explain the principles of farm management","Understand farm records and their importance","Calculate farm costs and returns","Apply budgeting to farm planning"]'::jsonb, 'medium', '20', '[{"id":"econ_hook_01","type":"hook","order":1,"content":{"text":"A farmer harvests 50 bags of maize. Each bag costs ₦5,000 to produce and sells for ₦8,000. Total revenue: ₦400,000. Total cost: ₦250,000. Profit: ₦150,000. But wait — did the farmer account for the value of their own labour? What about the land they could have rented out? Farm management isn''t just growing — it''s calculating.","prediction_prompt":"If a farmer spends all day working on the farm but doesn''t record anything, how will they know if they made a profit?"}},{"id":"econ_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Farm management = planning, organizing, and controlling farm resources to achieve goals. Key principles: (1) Principle of substitution — use more of what''s cheap, less of what''s expensive. (2) Principle of diminishing returns — adding more input eventually gives less output. (3) Principle of opportunity cost — the value of the next best alternative given up.","analogy":"Think of farm management like running a shop. You need to know your costs, set your prices, keep records, and plan ahead. A shop that doesn''t keep records will eventually run out of money — and so will a farm."}},{"id":"econ_formal_01","type":"formal_explanation","order":3,"content":{"text":"Farm records needed: (1) Production records — crops planted, yields, livestock numbers. (2) Financial records — income, expenses, profits. (3) Labour records — workers, hours, wages. (4) Inventory records — inputs, outputs, stock. Farm budgeting: estimated income and expenses for a planning period. Helps allocate resources and plan ahead.","key_terms":[{"term":"Farm Management","definition":"The process of planning, organizing, and controlling farm activities for maximum profit"},{"term":"Opportunity Cost","definition":"The value of the next best alternative given up when making a choice"},{"term":"Diminishing Returns","definition":"Adding more of one input while keeping others constant eventually gives less additional output"},{"term":"Farm Budget","definition":"A financial plan showing estimated income and expenses for a farming period"}]}},{"id":"econ_formula_01","type":"formula","order":4,"content":{"formula":"Farm Profit = Total Revenue − Total Cost. Total Cost = Fixed Costs + Variable Costs. Return on Investment = (Net Profit / Total Cost) × 100","variables":[{"name":"Total Revenue","description":"Quantity sold × Selling price"},{"name":"Fixed Costs","description":"Costs that don''t change with output (land rent, equipment)"},{"name":"Variable Cost","description":"Costs that change with output (seeds, fertilizers, labour)"},{"name":"Net Profit","description":"Total revenue minus all costs (including opportunity costs)"}],"when_to_use":"When evaluating farm profitability or planning farm activities.","common_traps":["Forgetting to include opportunity costs (farmer''s own labour)","Not separating fixed and variable costs","Confusing revenue with profit"],"units_note":"Farm profit should include the opportunity cost of the farmer''s labour and land."}},{"id":"econ_practice_01","type":"worked_example","order":5,"content":{"scenario":"A farmer plants yam on 1 hectare. Costs: land rent ₦50,000, seed yam ₦30,000, fertilizer ₦40,000, labour ₦60,000. Harvest: 100 bags. Selling price: ₦3,000/bag. Calculate profit and return on investment.","given":["Total costs: ₦50,000 + ₦30,000 + ₦40,000 + ₦60,000 = ₦180,000","Harvest: 100 bags × ₦3,000 = ₦300,000"],"required":"Calculate profit and ROI","principle":"Profit = Revenue − Costs. ROI = (Profit / Cost) × 100","steps":[{"explanation":"Calculate total cost","calculation":"₦50,000 + ₦30,000 + ₦40,000 + ₦60,000 = ₦180,000"},{"explanation":"Calculate total revenue","calculation":"100 bags × ₦3,000 = ₦300,000"},{"explanation":"Calculate profit","calculation":"₦300,000 − ₦180,000 = ₦120,000"},{"explanation":"Calculate ROI","calculation":"(₦120,000 / ₦180,000) × 100 = 66.7%"}],"answer":"Profit: ₦120,000. ROI: 66.7%.","check":"₦300,000 − ₦180,000 = ₦120,000. ₦120,000/₦180,000 = 66.7%."}},{"id":"econ_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Revenue is the same as profit.","why_wrong":"Revenue is total money received. Profit is what''s left after subtracting ALL costs. A farmer can have high revenue but low profit if costs are high.","correct_model":"Revenue − Costs = Profit. High revenue doesn''t always mean high profit."}},{"id":"econ_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests farm management principles, record keeping, and cost calculations.","trap":"JAMB may ask about opportunity cost — always consider what the farmer gives up (e.g., renting out the land instead of farming it).","tip":"Practice calculating farm profit and ROI. Know the difference between fixed and variable costs.","related_topics":["Farm budgeting","Agricultural marketing","Risk management"]}},{"id":"econ_memory_01","type":"memory_hook","order":8,"content":{"text":"Farm management = planning + organizing + controlling. Profit = Revenue − Costs. ROI = Profit/Cost × 100. Records: production, financial, labour, inventory. Opportunity cost = what you give up.","hook_type":"mnemonic"}},{"id":"econ_reflection_01","type":"reflection","order":9,"content":{"question":"Why do many small-scale farmers in Nigeria not keep farm records?","expected_unexpected":"Lack of education, belief that farming is ''simple'', no access to record-keeping tools, and cultural attitudes. Yet records are essential for profitability."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Farm profit is calculated as:","options":[{"label":"A","text":"Revenue + Costs"},{"label":"B","text":"Revenue − Costs"},{"label":"C","text":"Costs − Revenue"},{"label":"D","text":"Revenue × Costs"}],"answer":"B","explanation":"Profit = Total Revenue − Total Costs.","hints":["What''s left after paying all expenses?"]},{"difficulty":"medium","question":"The opportunity cost of a farmer using their own land is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"The rent they could have earned by leasing it out"},{"label":"C","text":"The cost of buying the land"},{"label":"D","text":"The cost of fertilizers"}],"answer":"B","explanation":"Opportunity cost is the value of the next best alternative. If the farmer could rent out the land, that''s what they give up by farming it themselves.","hints":["What else could the farmer do with the land?"]},{"difficulty":"jamb","question":"The principle of diminishing returns states that:","options":[{"label":"A","text":"More input always gives more output"},{"label":"B","text":"Adding more of one input eventually gives less additional output"},{"label":"C","text":"Farmers should always use more fertilizer"},{"label":"D","text":"Output decreases immediately with more input"}],"answer":"B","explanation":"Diminishing returns: adding more of one input (while others are constant) eventually gives less and less additional output.","hints":["At some point, more fertilizer stops helping as much"]}]'::jsonb, '{"min_score":80,"required_sections":["econ_hook_01","econ_intuitive_01","econ_formal_01","econ_formula_01","econ_practice_01"]}'::jsonb, '1')
