INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('agricultural_science', 'Pest and Disease Control', 'Crop and Livestock Protection', 'Pest and Disease Control — Protecting Our Harvest', '["Identify common crop and livestock pests","Classify diseases affecting crops and animals","Explain methods of pest and disease control","Understand the integrated pest management approach"]'::jsonb, 'medium', '20', '[{"id":"pest_hook_01","type":"hook","order":1,"content":{"text":"Armyworms can destroy an entire maize field in days. Newcastle disease can wipe out a poultry flock. Locusts have caused famines throughout history. Pests and diseases are the biggest threats to food production. Controlling them is essential for food security.","prediction_prompt":"What would happen to farmers if there were no ways to control pests and diseases?"}},{"id":"pest_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Pests: insects (armyworm, borer, aphids), rodents (rats, mice), birds (quelea). Diseases: fungal (blight, rust), bacterial (wilt), viral (mosaic), parasitic (nematodes). Livestock diseases: Newcastle (poultry), anthrax (cattle), rinderpest. Control methods: cultural (crop rotation), biological (natural enemies), chemical (pesticides), mechanical (traps).","analogy":"Think of pest control like your immune system. Your body has multiple defences: physical (skin), chemical (stomach acid), biological (white blood cells). Similarly, farmers use multiple methods — no single method is enough."}},{"id":"pest_formal_01","type":"formal_explanation","order":3,"content":{"text":"Control methods: (1) Cultural — crop rotation, early planting, resistant varieties, field sanitation. (2) Biological — using natural enemies (ladybugs eat aphids, ducks eat snails). (3) Chemical — pesticides (insecticides, fungicides, herbicides). (4) Mechanical — hand-picking, traps, barriers. Integrated Pest Management (IPM) combines all methods for sustainable control.","key_terms":[{"term":"Pest","definition":"Any organism that damages crops or spreads disease"},{"term":"Pathogen","definition":"A disease-causing organism (bacteria, virus, fungus)"},{"term":"Pesticide","definition":"A chemical used to kill or control pests"},{"term":"IPM","definition":"Integrated Pest Management — combining multiple control methods"},{"term":"Biological Control","definition":"Using natural enemies to control pests"}]}},{"id":"pest_formula_01","type":"formula","order":4,"content":{"formula":"IPM = Cultural + Biological + Chemical + Mechanical Control. Economic Threshold = pest level where control cost < expected damage","variables":[{"name":"Cultural Control","description":"Changing farming practices to reduce pest problems"},{"name":"Biological Control","description":"Using natural enemies (predators, parasites)"},{"name":"Chemical Control","description":"Using pesticides (last resort in IPM)"},{"name":"Mechanical Control","description":"Physical removal or barriers (traps, hand-picking)"}],"when_to_use":"When deciding how to control pests and diseases on the farm.","common_traps":["Over-reliance on chemical pesticides — they kill beneficial organisms too","Not scouting fields regularly to detect problems early","Ignoring cultural control methods — prevention is better than cure"],"units_note":"IPM aims to minimize chemical use while maintaining crop health."}},{"id":"pest_practice_01","type":"worked_example","order":5,"content":{"scenario":"A maize farmer notices armyworms attacking the crop. Design an IPM strategy to control them.","given":["Armyworm infestation in maize"],"required":"Design an integrated pest management plan","principle":"Combine multiple control methods for sustainable, effective control.","steps":[{"explanation":"Cultural control","calculation":"Plant early to avoid peak pest season. Use resistant varieties. Rotate with non-cereal crops."},{"explanation":"Biological control","calculation":"Encourage natural enemies: birds, spiders, parasitic wasps. Avoid broad-spectrum pesticides that kill them."},{"explanation":"Mechanical control","calculation":"Hand-pick caterpillars in the evening. Use pheromone traps to monitor and reduce populations."},{"explanation":"Chemical control (last resort)","calculation":"If infestation exceeds economic threshold, apply targeted insecticide (e.g., Bt-based) to minimize environmental harm."}],"answer":"IPM strategy: (1) Cultural — early planting, resistant varieties, rotation. (2) Biological — encourage natural enemies. (3) Mechanical — hand-picking, traps. (4) Chemical — only when necessary, use targeted pesticides.","check":"IPM minimizes chemical use while effectively controlling pests."}},{"id":"pest_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Pesticides are always the best solution to pest problems.","why_wrong":"Pesticides can kill beneficial organisms, contaminate water, poison food, and pests can develop resistance. They should be a last resort.","correct_model":"IPM is the best approach: combine cultural, biological, and mechanical methods. Use pesticides only when necessary."}},{"id":"pest_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests pest identification, disease types, and control methods.","trap":"JAMB may ask about specific pests: armyworm (maize), borer (cassava), aphids (various crops). Know the major pests and their crops.","tip":"For essay questions, always recommend IPM — it shows understanding of integrated, sustainable approaches.","related_topics":["Food security","Environmental protection","Sustainable agriculture"]}},{"id":"pest_memory_01","type":"memory_hook","order":8,"content":{"text":"Pests: insects, rodents, birds. Diseases: fungal, bacterial, viral. Control: Cultural, Biological, Chemical, Mechanical = IPM. Prevention > cure. Economic threshold = when to spray.","hook_type":"mnemonic"}},{"id":"pest_reflection_01","type":"reflection","order":9,"content":{"question":"Why is overuse of chemical pesticides harmful to agriculture?","expected_understanding":"Pesticides kill beneficial insects, contaminate soil and water, harm human health, and pests develop resistance over time. IPM provides a more sustainable alternative."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The use of natural enemies to control pests is called:","options":[{"label":"A","text":"Chemical control"},{"label":"B","text":"Biological control"},{"label":"C","text":"Cultural control"},{"label":"D","text":"Mechanical control"}],"answer":"B","explanation":"Biological control uses natural enemies (predators, parasites) to control pest populations.","hints":["Using nature against pests"]},{"difficulty":"medium","question":"Integrated Pest Management (IPM) involves:","options":[{"label":"A","text":"Using only chemical pesticides"},{"label":"B","text":"Combining cultural, biological, chemical, and mechanical methods"},{"label":"C","text":"Ignoring pests until they cause damage"},{"label":"D","text":"Using only biological methods"}],"answer":"B","explanation":"IPM combines all available control methods for sustainable, effective pest management.","hints":["What does ''integrated'' mean?"]},{"difficulty":"jamb","question":"The economic threshold for pest control is:","options":[{"label":"A","text":"When all crops are destroyed"},{"label":"B","text":"When the cost of control is less than the expected damage"},{"label":"C","text":"When the first pest is seen"},{"label":"D","text":"At harvest time"}],"answer":"B","explanation":"The economic threshold is the pest level where the cost of control is justified by the damage prevented.","hints":["When is it worth spending money on control?"]}]'::jsonb, '{"min_score":80,"required_sections":["pest_hook_01","pest_intuitive_01","pest_formal_01","pest_formula_01","pest_practice_01"]}'::jsonb, '1')
