INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Cell Structure and Organization', 'Basic Concepts', 'Cell Structure and Organization — The Unit of Life', '["Describe the structure of plant and animal cells","Distinguish between plant and animal cells","Explain the functions of cell organelles","Describe cell division (mitosis and meiosis)"]'::jsonb, 'medium', '20', '[{"id":"cell_hook_01","type":"hook","order":1,"content":{"text":"Every living thing — from bacteria to blue whales — is made of cells. Your body has about 37 trillion cells, each one a tiny factory with specialized parts doing specific jobs. A cell is the smallest unit of life. Understanding cells is like understanding the building blocks of everything alive.","prediction_prompt":"Why do you think plant cells have a rigid cell wall while animal cells don''t? What would happen if animal cells had cell walls?"}},{"id":"cell_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Think of a cell like a city. The cell membrane is the city wall — it controls what comes in and out. The nucleus is city hall — it contains the DNA (the master plans). Mitochondria are power stations — they make energy. The endoplasmic reticulum is a highway system for moving materials. The Golgi apparatus is the post office — packaging and sending proteins.","analogy":"A cell is like a busy factory. The manager (nucleus) gives orders. Workers (ribosomes) build products (proteins). Power generators (mitochondria) supply energy. The warehouse (ER) stores materials. Delivery trucks (Golgi) send products to where they''re needed. The security gate (cell membrane) decides what enters and exits."}},{"id":"cell_formal_01","type":"formal_explanation","order":3,"content":{"text":"All cells have: cell membrane, cytoplasm, ribosomes, and DNA. Plant cells additionally have: cell wall, chloroplasts, and a large central vacuole. Animal cells may have lysosomes and centrioles. Eukaryotic cells have a membrane-bound nucleus; prokaryotic cells don''t.","key_terms":[{"term":"Cell Membrane","definition":"Semi-permeable phospholipid bilayer that controls movement of substances in and out"},{"term":"Nucleus","definition":"Contains DNA; controls cell activities and reproduction"},{"term":"Mitochondria","definition":"Site of aerobic respiration; produces ATP (energy currency)"},{"term":"Chloroplast","definition":"Site of photosynthesis; contains chlorophyll (plant cells only)"}]}},{"id":"cell_formula_01","type":"formula","order":4,"content":{"formula":"Plant cell = Animal cell + Cell wall + Chloroplasts + Large central vacuole","variables":[{"name":"Cell wall","description":"Rigid cellulose layer outside cell membrane","unit":"none"},{"name":"Chloroplasts","description":"Organelles for photosynthesis","unit":"count varies"},{"name":"Large central vacuole","description":"Stores water; maintains turgor pressure","unit":"none"}],"when_to_use":"Use this comparison to distinguish between plant and animal cells in exams.","common_traps":["Forgetting that plant cells ALSO have mitochondria (not just chloroplasts)","Confusing the cell wall (plant) with the cell membrane (both)","Not knowing that animal cells have lysosomes but plant cells usually don''t"],"units_note":"Cell organelles are microscopic — measured in micrometres (μm)."}},{"id":"cell_worked_example_01","type":"worked_example","order":5,"content":{"problem":"List 5 differences between plant and animal cells.","steps":["Plant cells have a cell wall; animal cells don''t","Plant cells have chloroplasts; animal cells don''t","Plant cells have a large central vacuole; animal cells have small temporary vacuoles","Plant cells are usually rectangular/fixed shape; animal cells are irregular","Animal cells have centrioles and lysosomes; plant cells usually don''t"],"answer":"See the 5 differences above. Plant cells are more rigid and specialized for photosynthesis.","explanation":"These differences reflect the different lifestyles of plants (sessile, photosynthetic) vs animals (mobile, heterotrophic)."}},{"id":"cell_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — cell biology is fundamental to JAMB Biology","typical_question":"Name 3 organelles found in plant cells but not in animal cells. State the function of each.","common_mistakes":["Forgetting that both plant and animal cells have mitochondria","Confusing lysosomes (animal) with peroxisomes (both)","Not mentioning the function of each organelle"],"exam_tip":"For organelle questions: always state the name, location, and function. JAMB awards marks for each part."}},{"id":"cell_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"Which organelle is the ''powerhouse of the cell''?","options":["Nucleus","Ribosome","Mitochondria","Golgi apparatus"],"correct_index":2,"explanation":"Mitochondria carry out aerobic respiration, producing ATP (energy) for the cell."},{"question":"Which structure is found in plant cells but NOT animal cells?","options":["Cell membrane","Nucleus","Chloroplast","Ribosome"],"correct_index":2,"explanation":"Chloroplasts are unique to plant cells (and some protists). They carry out photosynthesis."},{"question":"What is the function of the cell membrane?","options":["Support and protection","Controls what enters and exits","Contains DNA","Makes proteins"],"correct_index":1,"explanation":"The cell membrane is semi-permeable — it selectively controls the movement of substances."}]}},{"id":"cell_summary_01","type":"summary","order":8,"content":{"key_takeaways":["All cells: membrane, cytoplasm, ribosomes, DNA","Plant cells + cell wall, chloroplasts, large vacuole","Mitochondria = energy (ATP), Nucleus = control centre","Mitosis = growth, Meiosis = gametes"],"connections":["Leads to: Tissues, organs, and organ systems","Leads to: Cell division and genetics","Builds on: Basic biology concepts"]}},{"id":"cell_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Cell Structure and Organization","min_score":80,"required_sections":["cell_hook_01","cell_intuitive_01","cell_formal_01","cell_formula_01","cell_worked_example_01"]}}]'::jsonb, 'published', '1')
