INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Transport in Plants', 'Basic Concepts', 'Transport in Plants — How Water and Nutrients Move', '["Explain the structure and function of xylem and phloem","Describe the mechanisms of water transport (transpiration pull, root pressure)","Explain translocation in the phloem","Describe the factors affecting transpiration rate"]'::jsonb, 'medium', '20', '[{"id":"transport_hook_01","type":"hook","order":1,"content":{"text":"How does water get from the roots of a 100-metre tall tree all the way to the leaves? There''s no pump — trees don''t have hearts. The answer involves physics (evaporation, cohesion, tension) working together with biology. It''s one of the most elegant systems in nature.","prediction_prompt":"If a tree''s leaves are cut off, what do you think happens to water transport? Why?"}},{"id":"transport_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Plants have two transport systems: xylem (one-way, from roots to leaves) carries water and dissolved minerals. Phloem (two-way) carries sugars from leaves to other parts. Water moves up the xylem mainly by transpiration pull — evaporation from leaves creates a suction force that pulls water up, like drinking through a straw.","analogy":"Think of the xylem as a drinking straw. When you suck on a straw, you create negative pressure that pulls liquid up. Trees do the same thing — evaporation from leaves (transpiration) creates a pull that draws water up from the roots. The water molecules stick together (cohesion), so the whole column moves as one."}},{"id":"transport_formal_01","type":"formal_explanation","order":3,"content":{"text":"Xylem transports water and minerals unidirectionally from roots to shoots. It consists of dead cells with thickened lignified walls. Phloem transports sugars bidirectionally (source to sink). It consists of living sieve tube elements and companion cells. Transpiration is the loss of water vapour from leaves through stomata.","key_terms":[{"term":"Xylem","definition":"Vascular tissue that transports water and minerals upwards. Dead cells."},{"term":"Phloem","definition":"Vascular tissue that transports sugars (translocation). Living cells."},{"term":"Transpiration","definition":"Loss of water vapour from aerial parts of the plant through stomata"},{"term":"Translocation","definition":"Movement of dissolved sugars in phloem from source to sink"}]}},{"id":"transport_formula_01","type":"formula","order":4,"content":{"formula":"Water potential (Ψ) = Ψs + Ψp","variables":[{"name":"Ψ","description":"Water potential","unit":"MPa"},{"name":"Ψs","description":"Solute potential (always negative)","unit":"MPa"},{"name":"Ψp","description":"Pressure potential (usually positive)","unit":"MPa"}],"when_to_use":"Water always moves from high water potential to low water potential. Use this to predict water movement in plant tissues.","common_traps":["Water potential is always negative or zero — never positive","Forgetting that pure water has Ψ = 0 (reference point)","Confusing water potential with osmotic pressure"],"units_note":"Water potential is measured in megapascals (MPa). Pure water at atmospheric pressure = 0 MPa."}},{"id":"transport_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Cell A has Ψ = −1.2 MPa. Cell B has Ψ = −0.8 MPa. In which direction will water move?","steps":["Water moves from HIGH Ψ to LOW Ψ","Cell B (−0.8) has higher Ψ than Cell A (−1.2)","Water moves from Cell B to Cell A"],"answer":"Water moves from Cell B to Cell A (from −0.8 to −1.2 MPa).","explanation":"Remember: less negative = higher water potential. −0.8 is higher than −1.2. Water always moves down the water potential gradient."}},{"id":"transport_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — transport in plants is a regular JAMB Biology topic","typical_question":"Describe the process of transpiration and explain 3 factors that affect its rate.","common_mistakes":["Confusing transpiration (water loss) with translocation (sugar transport)","Forgetting that xylem transport requires no energy (passive)","Not mentioning that phloem transport requires energy (active)"],"exam_tip":"For transpiration: mention stomata, guard cells, and the cohesion-tension theory. For factors: temperature, humidity, wind speed, light intensity."}},{"id":"transport_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"Which tissue transports water in plants?","options":["Phloem","Xylem","Cambium","Epidermis"],"correct_index":1,"explanation":"Xylem transports water and dissolved minerals from roots to leaves."},{"question":"Transpiration is mainly through which structures?","options":["Root hairs","Stomata","Xylem vessels","Phloem sieve tubes"],"correct_index":1,"explanation":"Stomata (pores on leaf surface) are the main sites of transpiration. Guard cells control their opening/closing."},{"question":"Which condition would INCREASE transpiration rate?","options":["High humidity","Low temperature","Still air","Bright light"],"correct_index":3,"explanation":"Bright light opens stomata, increasing transpiration. High humidity, low temperature, and still air all decrease it."}]}},{"id":"transport_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Xylem = water up (dead cells, passive), Phloem = sugars (living, active)","Transpiration pull is the main force for water transport","Water moves from high Ψ to low Ψ","Transpiration rate affected by: light, temperature, humidity, wind"],"connections":["Leads to: Photosynthesis (water is a reactant)","Leads to: Plant nutrition and mineral uptake","Builds on: Cell structure and osmosis"]}},{"id":"transport_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Transport in Plants","min_score":80,"required_sections":["transport_hook_01","transport_intuitive_01","transport_formal_01","transport_formula_01","transport_worked_example_01"]}}]'::jsonb, 'published', '1')
