INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Nutrition', 'Basic Concepts', 'Nutrition — How Living Things Get Food', '["Distinguish between autotrophic and heterotrophic nutrition","Describe the structure and function of the human alimentary canal","Explain the process of digestion and absorption","Describe deficiency diseases and balanced diet"]'::jsonb, 'medium', '20', '[{"id":"nutrition_hook_01","type":"hook","order":1,"content":{"text":"You eat food every day, but do you know what happens after you swallow? Your body breaks down a sandwich into molecules small enough to absorb — and this process involves mechanical churning, chemical digestion, and absorption across 6+ metres of intestines. Understanding nutrition helps you know why balanced diets matter and why some foods are essential.","prediction_prompt":"Why do we need to eat both carbohydrates AND proteins? Can''t one replace the other?"}},{"id":"nutrition_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Autotrophs (plants) make their own food through photosynthesis. Heterotrophs (animals, fungi) must consume other organisms for food. In humans, food travels through the alimentary canal: mouth (mechanical + chemical digestion) → oesophagus → stomach (protein digestion) → small intestine (complete digestion + absorption) → large intestine (water absorption) → rectum.","analogy":"Think of digestion like a recycling plant. Food goes in as complex materials (big molecules). It''s broken down step by step: teeth chop it up (mechanical), enzymes dissolve it (chemical), and the useful parts are absorbed (like sorting recyclables). Waste is discarded."}},{"id":"nutrition_formal_01","type":"formal_explanation","order":3,"content":{"text":"Carbohydrates provide energy (4 kcal/g). Proteins provide amino acids for growth and repair (4 kcal/g). Fats provide concentrated energy and insulation (9 kcal/g). Vitamins and minerals are needed in small amounts for metabolic functions. Fibre aids digestion. Water is essential for all body processes.","key_terms":[{"term":"Carbohydrates","definition":"Energy source. Simple (glucose) and complex (starch). 4 kcal/g"},{"term":"Proteins","definition":"Growth and repair. Made of amino acids. 4 kcal/g"},{"term":"Fats","definition":"Energy storage, insulation. Most concentrated energy source. 9 kcal/g"},{"term":"Vitamins","definition":"Organic compounds needed in small amounts for metabolic processes"}]}},{"id":"nutrition_formula_01","type":"formula","order":4,"content":{"formula":"Enzyme + Substrate → Enzyme-Substrate Complex → Enzyme + Products","variables":[{"name":"Enzyme","description":"Biological catalyst (protein)","unit":"none"},{"name":"Substrate","description":"Molecule the enzyme acts on","unit":"none"},{"name":"Products","description":"Molecules produced by the reaction","unit":"none"}],"when_to_use":"This describes how enzymes work in digestion. Each enzyme is specific to one substrate (lock and key model).","common_traps":["Confusing mechanical digestion (physical breakdown) with chemical digestion (enzyme action)","Forgetting that enzymes are specific — amylase only works on starch, pepsin only on protein","Not knowing that enzymes have optimal temperatures and pH values"],"units_note":"Enzyme activity is often measured in units per minute (U/min). Optimal temperature ≈ 37°C for human enzymes."}},{"id":"nutrition_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Trace the path of a piece of bread from mouth to absorption.","steps":["Mouth: teeth chew (mechanical), salivary amylase breaks starch → maltose (chemical)","Oesophagus: peristalsis moves bolus to stomach","Stomach: pepsin digests proteins; HCl kills bacteria; no carbohydrate digestion","Small intestine: pancreatic amylase continues starch digestion; maltase breaks maltose → glucose; lipase digests fats; bile emulsifies fats","Ileum: glucose, amino acids, fatty acids absorbed through villi into blood"],"answer":"Mouth → Oesophagus → Stomach → Duodenum → Jejunum → Ileum (absorption). Bread''s starch is broken down to glucose and absorbed in the ileum.","explanation":"Digestion is sequential — each organ has specific roles. Starch digestion begins in the mouth and completes in the small intestine."}},{"id":"nutrition_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — nutrition and digestion are core JAMB Biology topics","typical_question":"Describe the role of bile in fat digestion. Why is bile not an enzyme?","common_mistakes":["Saying bile ''digests'' fat — it only emulsifies (breaks into small droplets)","Forgetting that the small intestine is the main site of absorption","Confusing villi (absorption) with microvilli (increased surface area on cells)"],"exam_tip":"For digestion questions: mention the organ, the enzyme, the substrate, and the product. Example: ''In the small intestine, lipase digests fats into fatty acids and glycerol.''"}},{"id":"nutrition_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"Which enzyme begins protein digestion?","options":["Amylase","Pepsin","Lipase","Maltase"],"correct_index":1,"explanation":"Pepsin (in the stomach) begins protein digestion, breaking proteins into peptides."},{"question":"What is the main function of the large intestine?","options":["Digest food","Absorb glucose","Absorb water","Produce enzymes"],"correct_index":2,"explanation":"The large intestine absorbs water and salts from undigested food, forming faeces."},{"question":"Which nutrient provides the most energy per gram?","options":["Carbohydrates","Proteins","Fats","Vitamins"],"correct_index":2,"explanation":"Fats provide 9 kcal/g, compared to 4 kcal/g for carbohydrates and proteins."}]}},{"id":"nutrition_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Autotrophs make food; heterotrophs consume food","Digestion: mechanical (teeth) + chemical (enzymes)","Small intestine: main site of digestion and absorption","Enzymes are specific biological catalysts"],"connections":["Leads to: Enzyme kinetics and control","Leads to: Nutritional diseases and deficiency","Builds on: Cell biology and membrane transport"]}},{"id":"nutrition_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Nutrition","min_score":80,"required_sections":["nutrition_hook_01","nutrition_intuitive_01","nutrition_formal_01","nutrition_formula_01","nutrition_worked_example_01"]}}]'::jsonb, 'published', '1')
