INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Respiration', 'Basic Concepts', 'Respiration — How Cells Get Energy', '["Distinguish between breathing and cellular respiration","Explain the structure of the human respiratory system","Describe aerobic and anaerobic respiration","Explain the mechanism of breathing (inhalation and exhalation)"]'::jsonb, 'medium', '20', '[{"id":"respiration_hook_01","type":"hook","order":1,"content":{"text":"You breathe about 20,000 times a day without thinking about it. But respiration isn''t just breathing — it''s what happens inside your cells. Every cell in your body needs energy to function, and cellular respiration is how that energy is released from food. Breathing is just the first step — getting oxygen in and carbon dioxide out.","prediction_prompt":"Why do you breathe faster when you exercise? What''s happening inside your cells that demands more oxygen?"}},{"id":"respiration_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Breathing (ventilation) is the physical process of moving air in and out of lungs. Cellular respiration is the chemical process of breaking down glucose to release energy (ATP). They''re connected: breathing provides the oxygen needed for cellular respiration and removes the carbon dioxide produced. Think of breathing as the delivery truck and respiration as the factory.","analogy":"Breathing is like opening the windows of a factory (letting air in). Respiration is like the factory''s machines using that air to burn fuel and make products (energy). You need both — the windows AND the machines — for the factory to work."}},{"id":"respiration_formal_01","type":"formal_explanation","order":3,"content":{"text":"Aerobic respiration: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + 38 ATP. Anaerobic respiration (in animals): C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ + 2 ATP. The respiratory system: nasal cavity → pharynx → larynx → trachea → bronchi → bronchioles → alveoli. Gas exchange occurs in alveoli by diffusion.","key_terms":[{"term":"Aerobic Respiration","definition":"Complete oxidation of glucose using oxygen. Produces 38 ATP"},{"term":"Anaerobic Respiration","definition":"Incomplete oxidation without oxygen. Produces 2 ATP (in animals: ethanol + CO₂)"},{"term":"Alveoli","definition":"Tiny air sacs in lungs where gas exchange occurs"},{"term":"Diaphragm","definition":"Muscle below lungs that contracts during inhalation"}]}},{"id":"respiration_formula_01","type":"formula","order":4,"content":{"formula":"C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + Energy (ATP)","variables":[{"name":"C₆H₁₂O₆","description":"Glucose (fuel)","unit":"none"},{"name":"O₂","description":"Oxygen (from breathing)","unit":"none"},{"name":"CO₂","description":"Carbon dioxide (waste, exhaled)","unit":"none"},{"name":"ATP","description":"Adenosine triphosphate (energy currency)","unit":"none"}],"when_to_use":"This is the overall equation for aerobic respiration. It occurs in mitochondria.","common_traps":["Confusing respiration with breathing — respiration is cellular, breathing is physical","Forgetting that anaerobic respiration produces much less ATP (2 vs 38)","Confusing anaerobic respiration in animals (ethanol) with fermentation in yeast (also ethanol but different pathway)"],"units_note":"ATP is measured in moles or molecules. 1 mole of glucose yields approximately 38 moles of ATP."}},{"id":"respiration_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Compare aerobic and anaerobic respiration in terms of oxygen use, ATP yield, and products.","steps":["Aerobic: requires O₂, produces 38 ATP, products are CO₂ + H₂O","Anaerobic (animals): no O₂, produces 2 ATP, products are ethanol + CO₂","Anaerobic (plants/yeast): no O₂, produces 2 ATP, products are ethanol + CO₂"],"answer":"Aerobic: O₂ needed, 38 ATP, CO₂ + H₂O. Anaerobic: no O₂, 2 ATP, ethanol + CO₂.","explanation":"Aerobic respiration is 19× more efficient than anaerobic. This is why we breathe — to supply oxygen for efficient energy production."}},{"id":"respiration_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — respiration is a core JAMB Biology topic","typical_question":"Describe the mechanism of inhalation in humans.","common_mistakes":["Forgetting that the diaphragm contracts (flattens) during inhalation","Confusing internal intercostal muscles (exhalation) with external (inhalation)","Not mentioning that the thoracic volume increases and pressure decreases"],"exam_tip":"For breathing mechanism: mention diaphragm, intercostal muscles, thoracic volume, and pressure changes. Always explain the pressure gradient (air moves from high to low pressure)."}},{"id":"respiration_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"Where does cellular respiration primarily occur?","options":["Nucleus","Ribosome","Mitochondria","Cell membrane"],"correct_index":2,"explanation":"Mitochondria are the site of aerobic respiration, where ATP is produced."},{"question":"How many ATP molecules are produced by anaerobic respiration?","options":["2","4","38","76"],"correct_index":0,"explanation":"Anaerobic respiration produces only 2 ATP per glucose molecule (vs 38 for aerobic)."},{"question":"During inhalation, the diaphragm:","options":["Relaxes and domes upward","Contracts and flattens","Does not move","Contracts and moves upward"],"correct_index":1,"explanation":"The diaphragm contracts and flattens, increasing thoracic volume and decreasing pressure, so air rushes in."}]}},{"id":"respiration_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Breathing = physical; Respiration = cellular","Aerobic: 38 ATP (efficient), Anaerobic: 2 ATP (inefficient)","Inhalation: diaphragm contracts, volume↑, pressure↓","Gas exchange in alveoli by diffusion"],"connections":["Leads to: Circulatory system (transport of gases)","Leads to: Exercise physiology","Builds on: Cell biology and enzyme kinetics"]}},{"id":"respiration_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Respiration","min_score":80,"required_sections":["respiration_hook_01","respiration_intuitive_01","respiration_formal_01","respiration_formula_01","respiration_worked_example_01"]}}]'::jsonb, 'published', '1')
