INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Excretion', 'Basic Concepts', 'Excretion — Removing Metabolic Wastes', '["Define excretion and distinguish it from egestion","Describe the structure and function of the human excretory system","Explain the process of urine formation (filtration, reabsorption, secretion)","Describe the role of the liver in excretion"]'::jsonb, 'medium', '20', '[{"id":"excretion_hook_01","type":"hook","order":1,"content":{"text":"Your kidneys filter about 180 litres of blood every day, but you only pee about 1.5 litres. That means 99% of what''s filtered is reabsorbed! Excretion isn''t just about urine — your lungs excrete CO₂, your skin excretes sweat, and your liver processes toxins. It''s your body''s waste management system.","prediction_prompt":"Why do you think the body reabsorbs 99% of the filtered water? What would happen if it didn''t?"}},{"id":"excretion_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Excretion is the removal of metabolic waste products (produced by cells) from the body. This is different from egestion (removal of undigested food). The main excretory organs are: kidneys (urea, excess water, salts), lungs (CO₂, water vapour), skin (sweat: water, salts, urea), and liver (breaks down toxins, produces urea).","analogy":"Think of your body like a city. The kidneys are the water treatment plant — they filter waste from the blood. The lungs are the ventilation system — they remove gaseous waste (CO₂). The liver is the detox centre — it neutralizes poisons before sending them to the kidneys."}},{"id":"excretion_formal_01","type":"formal_explanation","order":3,"content":{"text":"The excretory system: kidneys (filter blood, produce urine) → ureters (transport urine) → urinary bladder (stores urine) → urethra (expels urine). Nephron is the functional unit of the kidney. Urine formation: (1) Glomerular filtration (blood pressure forces fluid into Bowman''s capsule), (2) Tubular reabsorption (useful substances returned to blood), (3) Tubular secretion (additional waste removed from blood).","key_terms":[{"term":"Excretion","definition":"Removal of metabolic waste products from the body"},{"term":"Nephron","definition":"Functional unit of the kidney; filters blood and forms urine"},{"term":"Glomerulus","definition":"Network of capillaries in Bowman''s capsule; site of filtration"},{"term":"Urea","definition":"Nitrogenous waste from deamination of amino acids in the liver"}]}},{"id":"excretion_formula_01","type":"formula","order":4,"content":{"formula":"Urine = Filtrate − Reabsorbed + Secreted","variables":[{"name":"Filtrate","description":"Fluid filtered from blood at glomerulus","unit":"180 L/day"},{"name":"Reabsorbed","description":"Useful substances returned to blood","unit":"~178.5 L/day"},{"name":"Secreted","description":"Additional waste from blood into tubule","unit":"varies"},{"name":"Urine","description":"Final waste product excreted","unit":"~1.5 L/day"}],"when_to_use":"Use this equation to understand why urine volume is much less than the filtrate volume.","common_traps":["Confusing excretion (metabolic waste) with egestion (undigested food)","Forgetting that the liver produces urea (from deamination), which the kidneys excrete","Not understanding that the nephron reabsorbs 99% of water"],"units_note":"Glomerular filtration rate (GFR) ≈ 125 mL/min = 180 L/day. Urine output ≈ 1.5 L/day."}},{"id":"excretion_worked_example_01","type":"worked_example","order":5,"content":{"problem":"If the glomerular filtration rate is 125 mL/min, and a person produces 1.5 L of urine per day, what percentage of the filtrate is reabsorbed?","steps":["Filtrate per day: 125 mL/min × 60 min × 24 h = 180,000 mL = 180 L","Urine produced: 1.5 L","Reabsorbed: 180 − 1.5 = 178.5 L","Percentage reabsorbed: (178.5 / 180) × 100 = 99.17%"],"answer":"99.17% of the filtrate is reabsorbed.","explanation":"This demonstrates how efficiently the kidneys conserve water. Only about 0.83% of the filtrate becomes urine."}},{"id":"excretion_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — excretion and the excretory system are regular JAMB Biology topics","typical_question":"Describe the three stages of urine formation in the nephron.","common_mistakes":["Confusing the three stages (filtration, reabsorption, secretion)","Forgetting that the liver produces urea from amino acid deamination","Not mentioning that the loop of Henle concentrates urine"],"exam_tip":"For nephron questions: know the parts (Bowman''s capsule, proximal convoluted tubule, loop of Henle, distal convoluted tubule, collecting duct) and what happens at each part."}},{"id":"excretion_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"Which organ produces urea?","options":["Kidney","Liver","Lung","Skin"],"correct_index":1,"explanation":"The liver produces urea through deamination of amino acids. The kidneys then excrete it in urine."},{"question":"What is the functional unit of the kidney?","options":["Alveolus","Nephron","Villus","Neuron"],"correct_index":1,"explanation":"The nephron is the functional unit of the kidney. Each kidney has about 1 million nephrons."},{"question":"CO₂ is excreted through the:","options":["Kidneys","Lungs","Skin","Liver"],"correct_index":1,"explanation":"CO₂ (a waste product of respiration) is excreted through the lungs during exhalation."}]}},{"id":"excretion_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Excretion = metabolic waste removal (not egestion)","Main organs: kidneys, lungs, skin, liver","Nephron: filtration → reabsorption → secretion → urine","99% of filtrate is reabsorbed"],"connections":["Leads to: Osmoregulation and water balance","Leads to: Kidney disorders and dialysis","Builds on: Circulatory system and blood filtration"]}},{"id":"excretion_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Excretion","min_score":80,"required_sections":["excretion_hook_01","excretion_intuitive_01","excretion_formal_01","excretion_formula_01","excretion_worked_example_01"]}}]'::jsonb, 'published', '1')
