INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Reproduction', 'Basic Concepts', 'Reproduction — Ensuring Species Survival', '["Distinguish between sexual and asexual reproduction","Describe human male and female reproductive systems","Explain the menstrual cycle and hormonal control","Describe fertilization and early embryonic development"]'::jsonb, 'medium', '22', '[{"id":"repro_hook_01","type":"hook","order":1,"content":{"text":"Reproduction is the reason life exists. Without it, every species would go extinct within a single lifetime. Nature has invented two main strategies: asexual (one parent, identical copies) and sexual (two parents, genetic variation). Understanding reproduction helps you know how life perpetuates and why genetic diversity matters.","prediction_prompt":"If asexual reproduction is faster and easier, why did sexual reproduction evolve? What advantage does it provide?"}},{"id":"repro_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Asexual reproduction: one parent, no gametes, offspring are clones (genetically identical). Fast and efficient but no genetic variation. Sexual reproduction: two parents, gametes fuse (fertilization), offspring are genetically unique. Slower but creates variation — which helps species adapt to changing environments.","analogy":"Think of asexual reproduction like photocopying — every copy is identical. Sexual reproduction is like mixing paints — every combination is slightly different. In a stable environment, photocopying works great. But if the environment changes, having varied copies (sexual reproduction) gives some offspring a better chance of survival."}},{"id":"repro_formal_01","type":"formal_explanation","order":3,"content":{"text":"Male reproductive system: testes (produce sperm + testosterone), epididymis (sperm maturation), vas deferens (sperm transport), prostate/seminal vesicles (seminal fluid), penis. Female reproductive system: ovaries (produce eggs + oestrogen/progesterone), fallopian tubes (site of fertilization), uterus (embryo development), vagina (birth canal).","key_terms":[{"term":"Gametes","definition":"Sex cells: sperm (male) and ovum (female)"},{"term":"Fertilization","definition":"Fusion of sperm and ovum to form a zygote"},{"term":"Menstrual Cycle","definition":"Monthly hormonal cycle preparing the uterus for pregnancy (~28 days)"},{"term":"Ovulation","definition":"Release of a mature ovum from the ovary (day 14)"}]}},{"id":"repro_formula_01","type":"formula","order":4,"content":{"formula":"Menstrual cycle: FSH → Oestrogen → LH surge → Ovulation → Progesterone → Menstruation","variables":[{"name":"FSH","description":"Follicle-stimulating hormone — stimulates follicle growth","unit":"none"},{"name":"LH","description":"Luteinizing hormone — triggers ovulation","unit":"none"},{"name":"Oestrogen","description":"Thickens endometrium; inhibits FSH","unit":"none"},{"name":"Progesterone","description":"Maintains endometrium; inhibits LH and FSH","unit":"none"}],"when_to_use":"Use this sequence to trace hormonal changes through the menstrual cycle.","common_traps":["Confusing the hormones: FSH (follicle), LH (ovulation), Oestrogen (thickening), Progesterone (maintaining)","Forgetting that menstruation occurs when progesterone drops (no pregnancy)","Not knowing that negative feedback prevents multiple ovulations"],"units_note":"Hormones are measured in IU/L or pg/mL. The cycle averages 28 days but normal range is 21-35 days."}},{"id":"repro_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Trace the hormonal events from day 1 to day 28 of the menstrual cycle.","steps":["Days 1-5: Menstruation (progesterone drops, endometrium sheds)","Days 1-13: FSH stimulates follicle growth; follicle produces oestrogen","Day 13: High oestrogen triggers LH surge","Day 14: LH surge triggers ovulation (ovum released)","Days 15-28: Corpus luteum produces progesterone; endometrium thickens","Day 28: No fertilization → corpus luteum degenerates → progesterone drops → menstruation begins"],"answer":"FSH (1-13) → Oestrogen (rising) → LH surge (13) → Ovulation (14) → Progesterone (15-28) → Menstruation (28/1)","explanation":"The cycle is controlled by feedback loops. Oestrogen initially inhibits FSH (negative feedback) but at high levels triggers LH (positive feedback). Progesterone inhibits both FSH and LH."}},{"id":"repro_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — reproduction is a major JAMB Biology topic","typical_question":"Describe the role of FSH and LH in the menstrual cycle.","common_mistakes":["Confusing FSH and LH roles","Forgetting that oestrogen has both negative and positive feedback effects","Not mentioning that the corpus luteum produces progesterone"],"exam_tip":"For hormonal control: name the hormone, where it''s produced, its target, and its effect. JAMB loves asking about feedback mechanisms."}},{"id":"repro_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What is the main advantage of sexual reproduction?","options":["Faster reproduction","No need for a mate","Genetic variation","Identical offspring"],"correct_index":2,"explanation":"Sexual reproduction creates genetic variation, which helps species adapt to changing environments."},{"question":"Where does fertilization normally occur?","options":["Ovary","Uterus","Fallopian tube","Vagina"],"correct_index":2,"explanation":"Fertilization normally occurs in the fallopian tube (oviduct), about 12-24 hours after ovulation."},{"question":"Which hormone triggers ovulation?","options":["FSH","Oestrogen","LH","Progesterone"],"correct_index":2,"explanation":"The LH surge (sharp increase in LH) triggers the release of the ovum from the ovary."}]}},{"id":"repro_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Asexual: one parent, clones, fast. Sexual: two parents, variation, slow","Fertilization: sperm + ovum → zygote (in fallopian tube)","Menstrual cycle: FSH → Oestrogen → LH → Ovulation → Progesterone","Negative feedback controls hormone levels"],"connections":["Leads to: Genetics and inheritance","Leads to: Development of the embryo","Builds on: Cell biology and hormones"]}},{"id":"repro_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Reproduction","min_score":80,"required_sections":["repro_hook_01","repro_intuitive_01","repro_formal_01","repro_formula_01","repro_worked_example_01"]}}]'::jsonb, 'published', '1')
