INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Genetics', 'Basic Concepts', 'Genetics — The Science of Heredity', '["Define genotype and phenotype","Explain Mendel''s laws of inheritance","Perform monohybrid and dihybrid crosses","Describe patterns of inheritance (codominance, sex-linkage)"]'::jsonb, 'hard', '25', '[{"id":"genetics_hook_01","type":"hook","order":1,"content":{"text":"Why do you have your mother''s eyes but your father''s nose? Why do some families have a history of sickle cell anaemia? Genetics is the code of life — written in DNA, passed from parents to offspring. Mendel discovered the basic rules with pea plants in the 1860s, and his work laid the foundation for modern genetics, forensics, and medicine.","prediction_prompt":"If both parents are carriers of the sickle cell gene (HbA HbS), what are the chances their child will have sickle cell disease?"}},{"id":"genetics_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Every trait is controlled by genes, which come in pairs (one from each parent). Dominant genes (capital letters, e.g., B) mask recessive genes (lowercase, e.g., b). Genotype is the genetic makeup (BB, Bb, bb). Phenotype is the physical appearance (brown eyes, blue eyes). If B is dominant for brown eyes: BB = brown, Bb = brown, bb = blue.","analogy":"Think of genes like light switches. Dominant genes are ''on'' switches — they override recessive ''off'' switches. If you have at least one ''on'' switch (BB or Bb), the light is on (brown eyes). Only if both switches are ''off'' (bb) is the light off (blue eyes)."}},{"id":"genetics_formal_01","type":"formal_explanation","order":3,"content":{"text":"Mendel''s Law of Segregation: each gamete receives one allele from each gene pair. Law of Independent Assortment: genes for different traits are inherited independently. Monohybrid cross: one trait (e.g., Bb × Bb → 3:1 ratio). Dihybrid cross: two traits (e.g., BbRr × BbRr → 9:3:3:1 ratio).","key_terms":[{"term":"Allele","definition":"Alternative form of a gene (e.g., B and b are alleles)"},{"term":"Homozygous","definition":"Two identical alleles (BB or bb)"},{"term":"Heterozygous","definition":"Two different alleles (Bb)"},{"term":"Dominant","definition":"Allele that masks the recessive allele when present"}]}},{"id":"genetics_formula_01","type":"formula","order":4,"content":{"formula":"Bb × Bb → 1 BB : 2 Bb : 1 bb (genotype) → 3:1 (phenotype)","variables":[{"name":"B","description":"Dominant allele","unit":"none"},{"name":"b","description":"Recessive allele","unit":"none"},{"name":"BB","description":"Homozygous dominant","unit":"none"},{"name":"Bb","description":"Heterozygous","unit":"none"},{"name":"bb","description":"Homozygous recessive","unit":"none"}],"when_to_use":"Use Punnett squares for monohybrid crosses to predict offspring genotypes and phenotypes.","common_traps":["Confusing genotype (genetic makeup) with phenotype (physical appearance)","Forgetting that carriers are heterozygous (Bb) — they have the recessive allele but don''t show it","Not understanding that the 3:1 ratio applies to phenotype, not genotype"],"units_note":"Ratios are always expressed in simplest form. 1:2:1 is genotype, 3:1 is phenotype."}},{"id":"genetics_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Both parents are carriers of sickle cell anaemia (HbA HbS). What is the probability of their child having sickle cell disease?","steps":["Sickle cell is autosomal recessive: HbS HbS = disease, HbA HbS = carrier (normal), HbA HbA = normal","Cross: HbA HbS × HbA HbS","Punnett square: 1/4 HbA HbA (normal), 1/2 HbA HbS (carrier), 1/4 HbS HbS (disease)"],"answer":"25% chance of sickle cell disease, 50% chance of being a carrier, 25% chance of being completely normal.","explanation":"Both parents must be carriers for a child to have sickle cell disease. Each child has a 1/4 chance of inheriting both recessive alleles."}},{"id":"genetics_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — genetics and inheritance are core JAMB Biology topics","typical_question":"A cross between two heterozygous tall plants (Tt × Tt) produces 200 offspring. How many would be expected to be short?","common_mistakes":["Confusing the genotypic ratio (1:2:1) with phenotypic ratio (3:1)","Forgetting that ''short'' is recessive and only appears in tt genotype","Not converting the ratio to actual numbers (1/4 of 200 = 50)"],"exam_tip":"For cross questions: draw the Punnett square, identify dominant/recessive, then calculate ratios. JAMB often asks for expected numbers from a given total."}},{"id":"genetics_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"In a cross BB × Bb, what percentage of offspring will show the dominant phenotype?","options":["25%","50%","75%","100%"],"correct_index":3,"explanation":"All offspring (BB or Bb) have at least one dominant allele, so 100% show the dominant phenotype."},{"question":"What is the genotype of a carrier of a recessive disorder?","options":["Homozygous dominant","Homozygous recessive","Heterozygous","Cannot determine"],"correct_index":2,"explanation":"A carrier has one dominant and one recessive allele (heterozygous) — they don''t show the disorder but can pass it on."},{"question":"Mendel''s Law of Segregation states that:","options":["Genes are on chromosomes","Each gamete receives one allele from each pair","Traits are inherited independently","Dominant genes are more common"],"correct_index":1,"explanation":"The Law of Segregation: during gamete formation, the two alleles of a gene separate so each gamete gets only one."}]}},{"id":"genetics_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Genotype = genes (BB, Bb, bb). Phenotype = appearance","Dominant masks recessive. Carrier = heterozygous","Monohybrid cross: 3:1 phenotype ratio","Mendel''s laws: Segregation and Independent Assortment"],"connections":["Leads to: Genetic disorders and screening","Leads to: DNA and molecular genetics","Builds on: Cell division (meiosis)"]}},{"id":"genetics_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Genetics","min_score":80,"required_sections":["genetics_hook_01","genetics_intuitive_01","genetics_formal_01","genetics_formula_01","genetics_worked_example_01"]}}]'::jsonb, 'published', '1')
