INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Ecology', 'Basic Concepts', 'Ecology — How Organisms Interact with Their Environment', '["Define ecology and levels of ecological organization","Describe biotic and abiotic factors in ecosystems","Explain food chains, food webs, and energy flow","Describe the carbon and nitrogen cycles"]'::jsonb, 'medium', '22', '[{"id":"ecology_hook_01","type":"hook","order":1,"content":{"text":"Every organism on Earth is connected. The plants you see, the insects you swat, the birds you hear — they''re all part of an intricate web of relationships called an ecosystem. Ecology studies how organisms interact with each other and their environment. Understanding ecology helps us know why biodiversity matters and how human actions affect the planet.","prediction_prompt":"What would happen to an ecosystem if all the predators were removed? Can you think of a real example?"}},{"id":"ecology_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Ecology has levels: individual → population → community → ecosystem → biome → biosphere. Biotic factors are living (predation, competition, symbiosis). Abiotic factors are non-living (temperature, water, soil, sunlight). Energy flows through ecosystems via food chains: producers → primary consumers → secondary consumers → decomposers.","analogy":"Think of an ecosystem like a giant economy. Producers (plants) are the factories making food. Consumers (animals) are the businesses buying and selling. Decomposers (fungi, bacteria) are the recyclers. Remove any group and the whole economy suffers."}},{"id":"ecology_formal_01","type":"formal_explanation","order":3,"content":{"text":"Producers (autotrophs) convert solar energy to chemical energy (photosynthesis). Consumers eat other organisms: primary (herbivores), secondary (carnivores), tertiary (top predators). Decomposers break down dead matter, recycling nutrients. Only 10% of energy transfers between trophic levels (10% rule).","key_terms":[{"term":"Ecosystem","definition":"Community of living organisms + their physical environment"},{"term":"Food Chain","definition":"Linear sequence of organisms through which energy and nutrients pass"},{"term":"Trophic Level","definition":"Position in a food chain (producer = level 1)"},{"term":"Decomposer","definition":"Organism that breaks down dead organic matter (fungi, bacteria)"}]}},{"id":"ecology_formula_01","type":"formula","order":4,"content":{"formula":"Energy at level n+1 = 10% × Energy at level n","variables":[{"name":"Level 1","description":"Producers (100% of solar energy captured)","unit":"kJ/m²/year"},{"name":"Level 2","description":"Primary consumers (10% of level 1)","unit":"kJ/m²/year"},{"name":"Level 3","description":"Secondary consumers (10% of level 2)","unit":"kJ/m²/year"}],"when_to_use":"Use the 10% rule to calculate energy available at each trophic level.","common_traps":["Confusing energy flow (unidirectional) with nutrient cycling (circular)","Forgetting that energy is lost as heat at each level","Not understanding why food chains are rarely longer than 4-5 levels"],"units_note":"Energy is measured in kJ/m²/year. Only about 1% of solar energy is captured by producers."}},{"id":"ecology_worked_example_01","type":"worked_example","order":5,"content":{"problem":"If producers capture 10,000 kJ/m²/year of energy, how much is available to secondary consumers?","steps":["Level 1 (Producers): 10,000 kJ/m²/year","Level 2 (Primary consumers): 10,000 × 0.10 = 1,000 kJ/m²/year","Level 3 (Secondary consumers): 1,000 × 0.10 = 100 kJ/m²/year"],"answer":"100 kJ/m²/year is available to secondary consumers.","explanation":"Only 10% of energy transfers between levels. This is why there are fewer top predators than herbivores — there''s simply less energy available at higher trophic levels."}},{"id":"ecology_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — ecology and environmental biology are regular JAMB topics","typical_question":"Describe the carbon cycle and explain how human activities disrupt it.","common_mistakes":["Confusing the carbon cycle with the nitrogen cycle","Forgetting that combustion of fossil fuels releases stored carbon","Not mentioning the role of decomposers in nutrient cycling"],"exam_tip":"For cycle diagrams: show all reservoirs (atmosphere, ocean, soil, organisms) and all processes (photosynthesis, respiration, combustion, decomposition)."}},{"id":"ecology_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What percentage of energy transfers between trophic levels?","options":["1%","10%","50%","100%"],"correct_index":1,"explanation":"Only about 10% of energy transfers between trophic levels. The rest is lost as heat."},{"question":"Which organism is a decomposer?","options":["Grass","Rabbit","Fungi","Eagle"],"correct_index":2,"explanation":"Fungi break down dead organic matter, recycling nutrients back into the ecosystem."},{"question":"The nitrogen cycle involves which process?","options":["Photosynthesis","Nitrogen fixation","Transpiration","Fermentation"],"correct_index":1,"explanation":"Nitrogen fixation converts atmospheric N₂ into usable forms (NH₃) by bacteria in root nodules."}]}},{"id":"ecology_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Levels: individual → population → community → ecosystem","10% rule: only 10% of energy transfers between levels","Biotic = living factors, Abiotic = non-living factors","Nutrients cycle; energy flows one way"],"connections":["Leads to: Environmental issues and conservation","Leads to: Human impact on ecosystems","Builds on: Photosynthesis and respiration"]}},{"id":"ecology_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Ecology","min_score":80,"required_sections":["ecology_hook_01","ecology_intuitive_01","ecology_formal_01","ecology_formula_01","ecology_worked_example_01"]}}]'::jsonb, 'published', '1')
