INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Evolution', 'Basic Concepts', 'Evolution — How Species Change Over Time', '["Define evolution and natural selection","Explain Darwin''s theory of evolution by natural selection","Describe evidence for evolution (fossils, anatomy, molecular)","Distinguish between artificial and natural selection"]'::jsonb, 'medium', '20', '[{"id":"evolution_hook_01","type":"hook","order":1,"content":{"text":"There are over 8 million species on Earth, and they all share a common ancestor. How did one simple cell become everything from bacteria to blue whales? Darwin''s answer: natural selection. It''s beautifully simple — those with traits that help them survive and reproduce pass those traits on. Over millions of years, this creates new species.","prediction_prompt":"If a population of beetles lives on green leaves, and some are green while others are brown, which colour do you think would become more common over time? Why?"}},{"id":"evolution_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Natural selection has four conditions: (1) Variation exists in a population. (2) Some variation is heritable. (3) More offspring are produced than can survive. (4) Those with favourable traits survive and reproduce more. Over time, the population changes. This is evolution — change in allele frequencies in a population over generations.","analogy":"Imagine a job interview with 100 candidates but only 1 opening. Some candidates are better qualified (variation). The employer picks the best (selection). If the successful candidate has children and trains them similarly, the next generation of applicants will be better qualified on average. Over many generations, the ''pool'' of applicants improves."}},{"id":"evolution_formal_01","type":"formal_explanation","order":3,"content":{"text":"Evidence for evolution: (1) Fossil record shows gradual changes. (2) Comparative anatomy (homologous structures suggest common ancestry). (3) Molecular biology (DNA similarities between species). (4) Biogeography (island species resemble nearby mainland species). Artificial selection: humans breed organisms for desired traits (dog breeds, crop varieties).","key_terms":[{"term":"Natural Selection","definition":"Differential survival and reproduction of individuals due to differences in phenotype"},{"term":"Adaptation","definition":"Trait that increases an organism''s fitness in its environment"},{"term":"Speciation","definition":"Formation of new species through evolution"},{"term":"Fossil","definition":"Preserved remains or traces of ancient organisms"}]}},{"id":"evolution_formula_01","type":"formula","order":4,"content":{"formula":"Variation + Inheritance + Selection + Time = Evolution","variables":[{"name":"Variation","description":"Differences between individuals","unit":"none"},{"name":"Inheritance","description":"Traits passed from parents to offspring","unit":"none"},{"name":"Selection","description":"Differential survival and reproduction","unit":"none"},{"name":"Time","description":"Many generations required for significant change","unit":"generations"}],"when_to_use":"Use these four conditions to explain how natural selection leads to evolution.","common_traps":["Evolution is not about individuals — populations evolve over generations","Natural selection doesn''t create variation — it acts on existing variation","Evolution doesn''t have a ''goal'' — it''s not directed toward perfection"],"units_note":"Evolution is measured in changes of allele frequencies over generations."}},{"id":"evolution_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Explain how antibiotic resistance in bacteria demonstrates natural selection.","steps":["Variation: some bacteria have genes that make them resistant to antibiotics","Selection: when antibiotics are used, non-resistant bacteria die","Inheritance: surviving resistant bacteria reproduce and pass on resistance genes","Time: over many generations, the population becomes mostly resistant"],"answer":"Antibiotics create a selection pressure. Resistant bacteria survive and reproduce, leading to a resistant population.","explanation":"This is natural selection in real-time. It''s why we need to complete full courses of antibiotics — stopping early allows resistant bacteria to survive and multiply."}},{"id":"evolution_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — evolution and natural selection are regular JAMB Biology topics","typical_question":"Explain Darwin''s theory of evolution by natural selection with a suitable example.","common_mistakes":["Saying ''survival of the fittest'' means the strongest — it means best adapted","Confusing artificial selection with natural selection","Forgetting that evolution requires heritable variation"],"exam_tip":"For evolution questions: always mention the four conditions (variation, inheritance, selection, time) and give a specific example."}},{"id":"evolution_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What is the main mechanism of evolution according to Darwin?","options":["Genetic drift","Natural selection","Mutation","Gene flow"],"correct_index":1,"explanation":"Natural selection is the primary mechanism of evolution — differential survival and reproduction based on fitness."},{"question":"Antibiotic resistance in bacteria is an example of:","options":["Artificial selection","Natural selection","Genetic drift","Mutation"],"correct_index":1,"explanation":"Antibiotics create a selection pressure. Resistant bacteria survive (natural selection), not humans choosing which bacteria survive (artificial selection)."},{"question":"Which is evidence for evolution?","options":["Fossils","Photosynthesis","Respiration","Digestion"],"correct_index":0,"explanation":"Fossils show how organisms have changed over millions of years, providing direct evidence for evolution."}]}},{"id":"evolution_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Natural selection: variation + inheritance + selection + time","Populations evolve, not individuals","Evidence: fossils, anatomy, molecular, biogeography","Artificial selection = humans choosing traits"],"connections":["Leads to: Genetic drift and speciation","Leads to: Human evolution","Builds on: Genetics and Mendel''s laws"]}},{"id":"evolution_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Evolution","min_score":80,"required_sections":["evolution_hook_01","evolution_intuitive_01","evolution_formal_01","evolution_formula_01","evolution_worked_example_01"]}}]'::jsonb, 'published', '1')
