INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('biology', 'Homeostasis', 'Basic Concepts', 'Homeostasis — Maintaining Internal Balance', '["Define homeostasis and its importance","Explain the role of receptors, coordination centres, and effectors","Describe thermoregulation and osmoregulation","Explain feedback mechanisms (negative and positive)"]'::jsonb, 'medium', '20', '[{"id":"homeostasis_hook_01","type":"hook","order":1,"content":{"text":"Your body temperature stays around 37°C whether it''s 5°C outside or 40°C. Your blood sugar stays stable even after eating a sugary meal. This isn''t magic — it''s homeostasis, the body''s ability to maintain a stable internal environment despite external changes. Every system in your body works together to keep things balanced.","prediction_prompt":"If your body temperature rises to 40°C, what mechanisms do you think your body uses to cool down?"}},{"id":"homeostasis_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Homeostasis works like a thermostat. (1) Receptors detect changes (stimuli). (2) Coordination centres (brain, spinal cord, pancreas) process information. (3) Effectors (muscles, glands) respond to restore balance. This is a negative feedback loop — the response opposes the change. Example: if temperature rises → sweat → cool down → temperature returns to normal.","analogy":"Think of homeostasis like a thermostat in your house. If the room gets too hot, the AC turns on. If it gets too cold, the heater turns on. The thermostat (receptor) detects the change, the control unit (brain) decides what to do, and the AC/heater (effectors) respond. The goal is always to return to the set temperature."}},{"id":"homeostasis_formal_01","type":"formal_explanation","order":3,"content":{"text":"Homeostasis maintains: body temperature (37°C), blood pH (7.4), blood glucose (3.9-5.6 mmol/L), water balance. Negative feedback: opposes the change (most common). Positive feedback: amplifies the change (less common, e.g., blood clotting, childbirth). Thermoregulation: hypothalamus detects temperature changes and triggers sweating/shivering.","key_terms":[{"term":"Homeostasis","definition":"Maintenance of a stable internal environment despite external changes"},{"term":"Negative Feedback","definition":"Response that opposes the change, restoring the set point"},{"term":"Positive Feedback","definition":"Response that amplifies the change (rare in biology)"},{"term":"Receptor","definition":"Detects changes in the environment (stimuli)"}]}},{"id":"homeostasis_formula_01","type":"formula","order":4,"content":{"formula":"Stimulus → Receptor → Coordination Centre → Effector → Response (opposes stimulus)","variables":[{"name":"Stimulus","description":"Change in the environment","unit":"none"},{"name":"Receptor","description":"Detects the change","unit":"none"},{"name":"Coordination Centre","description":"Processes information (brain/pancreas)","unit":"none"},{"name":"Effector","description":"Carries out the response (muscle/gland)","unit":"none"},{"name":"Response","description":"Opposes the original change","unit":"none"}],"when_to_use":"Use this pathway to describe any homeostatic mechanism (temperature, glucose, water balance).","common_traps":["Confusing negative feedback (opposes change) with positive feedback (amplifies change)","Forgetting that homeostasis involves all three components: receptor, coordinator, effector","Not specifying the stimulus, receptor, coordinator, effector, and response in answers"],"units_note":"Homeostatic set points are ranges, not exact values (e.g., body temperature 36.5-37.5°C)."}},{"id":"homeostasis_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Describe how the body maintains blood glucose levels after a meal.","steps":["Stimulus: blood glucose rises after eating","Receptor: beta cells in pancreas detect high glucose","Coordination centre: pancreas processes the information","Effector: pancreas secretes insulin","Response: insulin promotes glucose uptake by cells; blood glucose falls to normal"],"answer":"High glucose → pancreas (receptor) → insulin (effector) → cells take up glucose → glucose falls to normal.","explanation":"This is negative feedback. When glucose is too low, the pancreas releases glucagon instead, which promotes glycogen breakdown to raise glucose levels."}},{"id":"homeostasis_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — homeostasis is a regular JAMB Biology topic","typical_question":"Explain how the body responds to a sudden drop in body temperature (cold exposure).","common_mistakes":["Forgetting to mention all components: receptor, coordinator, effector","Not specifying that the response is negative feedback","Confusing thermoregulation with osmoregulation"],"exam_tip":"For homeostasis questions: always follow the pathway: Stimulus → Receptor → Coordination centre → Effector → Response. State clearly that it''s negative feedback."}},{"id":"homeostasis_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What is the main role of the hypothalamus in homeostasis?","options":["Digest food","Regulate body temperature","Produce insulin","Filter blood"],"correct_index":1,"explanation":"The hypothalamus is the body''s thermostat — it detects temperature changes and coordinates responses."},{"question":"Negative feedback means the response:","options":["Amplifies the change","Opposes the change","Has no effect","Creates a new set point"],"correct_index":1,"explanation":"Negative feedback opposes the original change, restoring the set point. It''s the most common homeostatic mechanism."},{"question":"Which hormone raises blood glucose levels?","options":["Insulin","Glucagon","Adrenaline","Thyroxine"],"correct_index":1,"explanation":"Glucagon (from pancreas) promotes glycogen breakdown into glucose, raising blood sugar levels."}]}},{"id":"homeostasis_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Homeostasis = stable internal environment","Pathway: Stimulus → Receptor → Coordinator → Effector → Response","Negative feedback opposes change; positive feedback amplifies it","Key examples: temperature, glucose, water balance"],"connections":["Leads to: Nervous and hormonal control","Leads to: Kidney function and osmoregulation","Builds on: Cell biology and enzyme kinetics"]}},{"id":"homeostasis_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Homeostasis","min_score":80,"required_sections":["homeostasis_hook_01","homeostasis_intuitive_01","homeostasis_formal_01","homeostasis_formula_01","homeostasis_worked_example_01"]}}]'::jsonb, 'published', '1')
