INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Atomic Structure', 'Basic Concepts', 'Atomic Structure — The Building Blocks of Matter', '["Describe the structure of an atom (protons, neutrons, electrons)","Define atomic number and mass number","Explain electron configuration and energy levels","Distinguish between isotopes and their applications"]'::jsonb, 'medium', '20', '[{"id":"atomic_hook_01","type":"hook","order":1,"content":{"text":"Everything you see — your phone, the air, your body — is made of atoms. But atoms aren''t solid balls. They have a tiny nucleus with protons and neutrons, and electrons flying around it. Here''s the wild part: if an atom were the size of a football stadium, the nucleus would be the size of a marble in the centre. Most of the atom is empty space!","prediction_prompt":"If two atoms have the same number of protons but different numbers of neutrons, are they the same element? What do we call them?"}},{"id":"atomic_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Think of an atom like a solar system. The nucleus (protons + neutrons) is the sun at the centre. Electrons are planets orbiting around it — but unlike real planets, electrons exist in specific energy levels (shells), not just anywhere. The number of protons determines WHAT the element is. Carbon always has 6 protons. Oxygen always has 8.","analogy":"Imagine a school with classrooms (energy levels). The first classroom holds 2 students, the second holds 8, the third holds 18. Students (electrons) fill the closest classrooms first. The number of students in the outermost classroom determines how the atom behaves chemically."}},{"id":"atomic_formal_01","type":"formal_explanation","order":3,"content":{"text":"An atom consists of a nucleus containing protons (positive charge, mass ≈ 1 amu) and neutrons (no charge, mass ≈ 1 amu). Electrons (negative charge, mass ≈ 0 amu) occupy energy levels outside the nucleus. The atomic number (Z) = number of protons. The mass number (A) = protons + neutrons. Number of neutrons = A − Z.","key_terms":[{"term":"Atomic Number (Z)","definition":"Number of protons in the nucleus. Defines the element."},{"term":"Mass Number (A)","definition":"Total number of protons and neutrons in the nucleus."},{"term":"Isotopes","definition":"Atoms of the same element with different mass numbers (different neutrons)."},{"term":"Electron Configuration","definition":"Distribution of electrons among energy levels and sub-levels."}]}},{"id":"atomic_formula_01","type":"formula","order":4,"content":{"formula":"A = Z + N","variables":[{"name":"A","description":"Mass number","unit":"none"},{"name":"Z","description":"Atomic number (protons)","unit":"none"},{"name":"N","description":"Number of neutrons","unit":"none"}],"when_to_use":"When you need to find the number of neutrons, or given neutrons and atomic number, find the mass number.","common_traps":["Confusing atomic number with mass number. Atomic number = protons only.","Forgetting that isotopes of the same element have the same Z but different A.","Writing electron configuration incorrectly — remember 2, 8, 18, 32 maximum per shell."],"units_note":"Atomic number and mass number are counts — they have no units."}},{"id":"atomic_worked_example_01","type":"worked_example","order":5,"content":{"problem":"An element X has atomic number 17 and mass number 35. Determine the number of protons, neutrons, and electrons in a neutral atom of X. Write its electron configuration.","steps":["Protons = Atomic number = 17","Neutrons = Mass number − Atomic number = 35 − 17 = 18","Electrons = Protons (for neutral atom) = 17","Electron configuration: 2, 8, 7 (first shell: 2, second: 8, third: 7)"],"answer":"Protons = 17, Neutrons = 18, Electrons = 17. Configuration: 2, 8, 7. Element is Chlorine (Cl).","explanation":"The atomic number tells you everything about the element''s identity. With 17 electrons filling shells as 2, 8, 7, we can predict it will gain 1 electron to complete its outer shell — which is exactly what chlorine does."}},{"id":"atomic_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — appears in nearly every JAMB Chemistry paper","typical_question":"Calculate the number of neutrons in an atom of ²³₅U. [Answer: 235 − 92 = 143 neutrons]","common_mistakes":["Using mass number as the atomic number","Forgetting that electrons = protons only in neutral atoms (ions have different electron counts)"],"exam_tip":"When you see notation like ¹⁴₆C, the top number is mass number (A) and bottom is atomic number (Z). Always remember: N = A − Z."}},{"id":"atomic_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"How many neutrons are in an atom of Carbon-14?","options":["6","8","14","10"],"correct_index":1,"explanation":"Carbon has atomic number 6. Neutrons = 14 − 6 = 8."},{"question":"Which particle determines the chemical properties of an atom?","options":["Protons","Neutrons","Electrons","Nucleus"],"correct_index":2,"explanation":"Chemical properties are determined by the number and arrangement of electrons, especially the outermost (valence) electrons."},{"question":"Two atoms have the same atomic number but different mass numbers. They are:","options":["Isotopes","Isomers","Ions","Allotropes"],"correct_index":0,"explanation":"Same atomic number = same element. Different mass number = different number of neutrons. These are isotopes."}]}},{"id":"atomic_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Atomic number = protons = electrons (in neutral atoms)","Mass number = protons + neutrons","Isotopes: same element, different neutrons","Electron configuration: 2, 8, 18, 32 max per shell"],"connections":["Leads to: Chemical Bonding (how atoms combine)","Leads to: Periodic Table (arrangement by atomic number)","Builds on: Basic Chemistry concepts"]}},{"id":"atomic_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Atomic Structure","min_score":80,"required_sections":["atomic_hook_01","atomic_intuitive_01","atomic_formal_01","atomic_formula_01","atomic_worked_example_01"]}}]'::jsonb, 'published', '1')
