INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Chemical Bonding', 'Basic Concepts', 'Chemical Bonding — How Atoms Join Together', '["Explain the three types of chemical bonding (ionic, covalent, metallic)","Predict the type of bond formed between elements","Draw Lewis dot structures for simple molecules","Relate bonding to physical properties (melting point, conductivity)"]'::jsonb, 'medium', '22', '[{"id":"bonding_hook_01","type":"hook","order":1,"content":{"text":"Why does salt (NaCl) dissolve in water but not conduct electricity as a solid? Why is diamond the hardest natural material but graphite (also pure carbon) is soft enough to write with? The answer lies in how atoms are bonded together. Chemical bonding is the reason materials behave the way they do.","prediction_prompt":"If sodium (Na) has 1 valence electron and chlorine (Cl) has 7, what do you think happens when they meet?"}},{"id":"bonding_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Atoms bond because they want to be stable — specifically, they want a full outer shell (usually 8 electrons, the octet rule). They achieve this in three main ways: (1) Transfer electrons completely (ionic), (2) Share electrons (covalent), (3) Delocalize electrons across a sea (metallic). Think of it like three different ways people solve problems — each method works differently.","analogy":"Imagine you have 1 apple and your friend has 7. You need 8 to be happy. Option 1: Give your 1 apple away — now you have 0 but you''ve ''completed'' someone else''s set (ionic bonding). Option 2: Pool your apples together and share — you both have access to 8 (covalent bonding). Option 3: Put all your apples in a community basket everyone can access (metallic bonding)."}},{"id":"bonding_formal_01","type":"formal_explanation","order":3,"content":{"text":"Ionic bonding involves transfer of electrons from a metal to a non-metal, forming positive and negative ions held by electrostatic attraction. Covalent bonding involves sharing of electron pairs between non-metal atoms. Metallic bonding involves metal cations in a ''sea'' of delocalized electrons.","key_terms":[{"term":"Ionic Bond","definition":"Electrostatic attraction between oppositelyely charged ions formed by electron transfer"},{"term":"Covalent Bond","definition":"A shared pair of electrons between two non-metal atoms"},{"term":"Metallic Bond","definition":"Attraction between metal cations and delocalized valence electrons"},{"term":"Octet Rule","definition":"Atoms tend to gain, lose, or share electrons to achieve 8 electrons in their outer shell"}]}},{"id":"bonding_formula_01","type":"formula","order":4,"content":{"formula":"Lewis dot structures show valence electrons as dots around element symbols","variables":[{"name":"Valence electrons","description":"Electrons in the outermost shell","unit":"count"},{"name":"Bonding pairs","description":"Electrons shared between atoms","unit":"count"},{"name":"Lone pairs","description":"Non-bonding electrons on an atom","unit":"count"}],"when_to_use":"Use Lewis structures to visualize how atoms share or transfer electrons in molecules and ionic compounds.","common_traps":["Forgetting that ionic compounds form crystal lattices, not discrete molecules","Drawing covalent bonds as ionic (or vice versa)","Not counting all valence electrons in the structure"],"units_note":"Lewis structures are diagrams — no units, but they represent electron counts."}},{"id":"bonding_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Draw the Lewis structure for water (H₂O) and identify the number of bonding pairs and lone pairs on oxygen.","steps":["H has 1 valence electron, O has 6. Total = 2(1) + 6 = 8 valence electrons","O is the central atom. Connect each H with a single bond (2 electrons used)","Place remaining 6 electrons as lone pairs on O: 3 pairs","Check: O has 2 bonding pairs + 2 lone pairs = 8 electrons (octet satisfied)"],"answer":"Oxygen has 2 bonding pairs (O-H bonds) and 2 lone pairs. Total: 4 electron pairs around oxygen.","explanation":"Water''s bent shape comes from the 2 lone pairs repelling the bonding pairs. This is why water is polar — a key property for its role as a solvent."}},{"id":"bonding_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — bonding questions appear in almost every paper","typical_question":"State the type of bonding in: (a) NaCl, (b) H₂O, (c) Fe. Explain why NaCl conducts electricity when molten but not as a solid.","common_mistakes":["Saying ionic compounds have ''molecules'' — they have formula units in a lattice","Forgetting that metallic bonding explains electrical conductivity in metals","Confusing polar covalent with ionic bonding"],"exam_tip":"When asked to identify bonding, look at the elements: Metal + Non-metal → Ionic. Non-metal + Non-metal → Covalent. Metal + Metal → Metallic."}},{"id":"bonding_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What type of bond is formed between Sodium (Na) and Chlorine (Cl)?","options":["Covalent","Ionic","Metallic","Hydrogen"],"correct_index":1,"explanation":"Na is a metal, Cl is a non-metal. Na transfers 1 electron to Cl, forming Na⁺ and Cl⁻ ions held by ionic bonding."},{"question":"Which substance does NOT conduct electricity?","options":["Copper metal","Molten NaCl","Diamond","Graphite"],"correct_index":2,"explanation":"Diamond has all electrons locked in covalent bonds with no free carriers. Copper has delocalized electrons. Molten NaCl has free ions. Graphite has delocalized electrons between layers."},{"question":"How many lone pairs are on the central atom in NH₃?","options":["0","1","2","3"],"correct_index":1,"explanation":"N has 5 valence electrons. 3 are used in N-H bonds. 2 remain = 1 lone pair. NH₃ has 3 bonding pairs and 1 lone pair."}]}},{"id":"bonding_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Ionic: metal + non-metal, electron transfer, high melting point, conducts when molten/dissolved","Covalent: non-metal + non-metal, electron sharing, low melting point, poor conductor","Metallic: metal + metal, delocalized electrons, conducts in solid state","Octet rule drives most bonding behaviour"],"connections":["Leads to: Molecular Geometry (VSEPR theory)","Leads to: Properties of Materials","Builds on: Atomic Structure (electron configuration)"]}},{"id":"bonding_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Chemical Bonding","min_score":80,"required_sections":["bonding_hook_01","bonding_intuitive_01","bonding_formal_01","bonding_formula_01","bonding_worked_example_01"]}}]'::jsonb, 'published', '1')
