INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Acids, Bases and Salts', 'Basic Concepts', 'Acids, Bases and Salts — The Chemistry of Everyday Life', '["Define acids, bases, and salts with examples","Explain the pH scale and its significance","Describe neutralization reactions and their applications","Perform calculations involving concentration and dilution"]'::jsonb, 'medium', '20', '[{"id":"acids_hook_01","type":"hook","order":1,"content":{"text":"Lemon juice tastes sour because of citric acid. Soap feels slippery because it''s a base. Table salt is a neutral compound. These everyday experiences are all about acids, bases, and salts. Understanding them helps you know why antacids work, why soil pH matters for farming, and why some chemicals are dangerous while others are harmless.","prediction_prompt":"If you mix an acid with a base, what do you think happens? Can you guess the products?"}},{"id":"acids_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Acids donate hydrogen ions (H⁺) in solution. They taste sour, turn blue litmus red, and react with metals to produce hydrogen gas. Bases accept H⁺ ions (or donate OH⁻ ions). They taste bitter, feel slippery, and turn red litmus blue. When you mix an acid with a base, they neutralize each other — producing a salt and water.","analogy":"Think of acids and bases as opposites. Acid is like adding heat to a room; base is like adding cold. When you add equal amounts, the temperature balances out (neutral). The ''balance point'' is pH 7."}},{"id":"acids_formal_01","type":"formal_explanation","order":3,"content":{"text":"An acid is a substance that donates H⁺ ions (proton donor). A base is a substance that accepts H⁺ ions (proton acceptor). An alkali is a soluble base. Salts are ionic compounds formed from the reaction of an acid with a base, metal, or metal carbonate. The pH scale ranges from 0 (strongly acidic) to 14 (strongly alkaline), with 7 being neutral.","key_terms":[{"term":"Acid","definition":"Proton (H⁺) donor. Turns blue litmus red. pH < 7"},{"term":"Base","definition":"Proton acceptor. Turns red litmus blue. pH > 7"},{"term":"Salt","definition":"Ionic compound from acid-base reaction. E.g., NaCl from HCl + NaOH"},{"term":"Neutralization","definition":"Acid + Base → Salt + Water"}]}},{"id":"acids_formula_01","type":"formula","order":4,"content":{"formula":"pH = −log₁₀[H⁺]","variables":[{"name":"pH","description":"Measure of acidity/alkalinity","unit":"none"},{"name":"[H⁺]","description":"Concentration of hydrogen ions","unit":"mol/dm³"}],"when_to_use":"When you need to calculate pH from ion concentration, or find concentration from pH.","common_traps":["Confusing pH with concentration — lower pH means HIGHER H⁺ concentration","Forgetting that pH is logarithmic — pH 3 is 10× more acidic than pH 4","Not converting units properly (e.g., mmol to mol)"],"units_note":"pH has no units. Concentration must be in mol/dm³ (or mol/L) for the formula."}},{"id":"acids_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Calculate the pH of a solution with [H⁺] = 0.001 mol/dm³. Is it acidic, neutral, or alkaline?","steps":["pH = −log₁₀[H⁺]","pH = −log₁₀(0.001)","0.001 = 10⁻³, so log₁₀(0.001) = −3","pH = −(−3) = 3"],"answer":"pH = 3. The solution is acidic (pH < 7).","explanation":"A pH of 3 means the solution is 1000× more acidic than pure water (pH 7). This is roughly the pH of vinegar or orange juice."}},{"id":"acids_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — acids, bases, and salts are core JAMB Chemistry topics","typical_question":"25 cm³ of 0.1 mol/dm³ HCl is neutralized by 20 cm³ of NaOH. Calculate the concentration of NaOH.","common_mistakes":["Using the wrong formula in titration calculations (n₁V₁ = n₂V₂ for 1:1 reactions)","Forgetting that strong acids completely ionize while weak acids partially ionize","Confusing indicators — methyl orange changes at pH 3.1-4.4, phenolphthalein at pH 8.2-10"],"exam_tip":"For titration: write the balanced equation first. Then use n = c × v to find moles of one reactant, then use the mole ratio to find the other."}},{"id":"acids_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What is the pH of a solution with [H⁺] = 10⁻⁴ mol/dm³?","options":["4","10","−4","14"],"correct_index":0,"explanation":"pH = −log₁₀(10⁻⁴) = 4."},{"question":"Which indicator is best for a strong acid-strong base titration?","options":["Methyl orange","Phenolphthalein","Litmus paper","Universal indicator"],"correct_index":1,"explanation":"Phenolphthalein is ideal because it changes sharply at pH 8.2-10, which is near the equivalence point of strong acid-strong base titrations."},{"question":"Which acid is found in vinegar?","options":["Hydrochloric acid","Sulphuric acid","Acetic acid","Citric acid"],"correct_index":2,"explanation":"Vinegar contains acetic acid (ethanoic acid, CH₃COOH) at about 5% concentration."}]}},{"id":"acids_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Acids donate H⁺, bases accept H⁺","pH scale: 0-14, logarithmic, 7 is neutral","Neutralization: Acid + Base → Salt + Water","pH = −log₁₀[H⁺]"],"connections":["Leads to: Electrochemistry (electrolysis of salts)","Leads to: Organic Chemistry (carboxylic acids)","Builds on: Chemical Bonding (ionic compounds)"]}},{"id":"acids_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Acids, Bases and Salts","min_score":80,"required_sections":["acids_hook_01","acids_intuitive_01","acids_formal_01","acids_formula_01","acids_worked_example_01"]}}]'::jsonb, 'published', '1')
