INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Stoichiometry', 'Basic Concepts', 'Stoichiometry — The Math of Chemical Reactions', '["Write and balance chemical equations","Calculate molar masses from atomic masses","Use the mole concept to perform calculations","Determine limiting reagents and theoretical yields"]'::jsonb, 'hard', '25', '[{"id":"stoich_hook_01","type":"hook","order":1,"content":{"text":"If you have 12 balls of flour, 8 eggs, and 200g of sugar, how many cakes can you bake? You''d run out of eggs first — that''s the limiting ingredient. Stoichiometry does the same thing but with chemicals. It tells you exactly how much of each chemical you need and how much product you''ll get.","prediction_prompt":"In the reaction 2H₂ + O₂ → 2H₂O, if you have 5 molecules of H₂ and 3 molecules of O₂, which one runs out first?"}},{"id":"stoich_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Chemical equations are like recipes. The coefficients (numbers in front) tell you the ratio of ingredients. 2H₂ + O₂ → 2H₂O means: 2 molecules of hydrogen react with 1 molecule of oxygen to make 2 molecules of water. The ratio is always fixed. If you change the amounts, one chemical runs out first — that''s the limiting reagent.","analogy":"Think of a bicycle. Each bicycle needs 2 wheels and 1 frame. If you have 10 wheels and 3 frames, you can only make 3 bicycles (you run out of frames). 4 wheels are left over (excess). The frames are the limiting reagent."}},{"id":"stoich_formal_01","type":"formal_explanation","order":3,"content":{"text":"Stoichiometry is the quantitative study of reactants and products in chemical reactions. The mole concept is central: 1 mole = 6.022 × 10²³ particles (Avogadro''s number). Molar mass = atomic/molecular mass in grams. From a balanced equation, mole ratios give the stoichiometric relationships.","key_terms":[{"term":"Mole","definition":"Amount of substance containing 6.022 × 10²³ particles (Avogadro''s number)"},{"term":"Molar Mass","definition":"Mass of 1 mole of a substance in grams (numerically equal to molecular mass)"},{"term":"Limiting Reagent","definition":"The reactant that is completely consumed first, limiting the amount of product"},{"term":"Theoretical Yield","definition":"Maximum amount of product that can be formed from given reactants"}]}},{"id":"stoich_formula_01","type":"formula","order":4,"content":{"formula":"n = m / M = N / Nₐ = c × V","variables":[{"name":"n","description":"Number of moles","unit":"mol"},{"name":"m","description":"Mass","unit":"g"},{"name":"M","description":"Molar mass","unit":"g/mol"},{"name":"N","description":"Number of particles","unit":"count"},{"name":"Nₐ","description":"Avogadro''s number","unit":"6.022 × 10²³"},{"name":"c","description":"Concentration","unit":"mol/dm³"},{"name":"V","description":"Volume","unit":"dm³"}],"when_to_use":"These formulas connect mass, moles, particles, and concentration — the four pillars of stoichiometry.","common_traps":["Using atomic mass instead of molar mass (should be in grams, not amu)","Forgetting to balance the equation before doing calculations","Not converting volume from cm³ to dm³ (divide by 1000)"],"units_note":"Always work in moles, grams, and dm³ for consistency. Convert cm³ to dm³ by dividing by 1000."}},{"id":"stoich_worked_example_01","type":"worked_example","order":5,"content":{"problem":"How many grams of water are produced when 4 g of hydrogen reacts completely with excess oxygen? (H = 1, O = 16)","steps":["Write the balanced equation: 2H₂ + O₂ → 2H₂O","Calculate moles of H₂: n = m/M = 4/2 = 2 mol","From equation: 2 mol H₂ produces 2 mol H₂O (ratio 1:1)","Moles of H₂O = 2 mol","Mass of H₂O = n × M = 2 × 18 = 36 g"],"answer":"36 g of water is produced.","explanation":"The key step is using the mole ratio from the balanced equation. Since 2 mol H₂ gives 2 mol H₂O, the ratio is 1:1. Then convert moles back to mass using the molar mass of water (18 g/mol)."}},{"id":"stoich_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — stoichiometry calculations appear in every JAMB Chemistry paper","typical_question":"10 g of calcium carbonate (CaCO₃) is heated. Calculate the volume of CO₂ produced at RTP. [Ca = 40, C = 12, O = 16, Molar gas volume = 24 dm³/mol]","common_mistakes":["Forgetting to use the balanced equation to get the mole ratio","Using molar gas volume (24 dm³) instead of converting to moles first","Arithmetic errors when calculating molar masses"],"exam_tip":"For gas volume questions: find moles of gas from the equation, then multiply by 24 dm³/mol (at RTP). For mass questions: moles × molar mass."}},{"id":"stoich_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"How many moles are in 36 g of water? (H = 1, O = 16)","options":["1 mol","2 mol","3 mol","18 mol"],"correct_index":1,"explanation":"Molar mass of H₂O = 18 g/mol. n = 36/18 = 2 mol."},{"question":"In 2H₂ + O₂ → 2H₂O, if you have 3 mol H₂ and 2 mol O₂, which is the limiting reagent?","options":["H₂","O₂","Neither","Cannot determine"],"correct_index":1,"explanation":"3 mol H₂ requires 1.5 mol O₂ (ratio 2:1). You have 2 mol O₂, so H₂ runs out first. H₂ is limiting."},{"question":"What is the volume of 2 mol of gas at RTP?","options":["12 dm³","24 dm³","48 dm³","22.4 dm³"],"correct_index":2,"explanation":"At RTP, 1 mol of gas occupies 24 dm³. 2 mol = 2 × 24 = 48 dm³."}]}},{"id":"stoich_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Always balance the equation first","n = m/M = N/Nₐ = c × V","Mole ratio from equation connects reactants to products","Limiting reagent determines theoretical yield"],"connections":["Leads to: Concentration calculations","Leads to: Gas volume calculations","Builds on: Atomic Structure and Molar Mass"]}},{"id":"stoich_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Stoichiometry","min_score":80,"required_sections":["stoich_hook_01","stoich_intuitive_01","stoich_formal_01","stoich_formula_01","stoich_worked_example_01"]}}]'::jsonb, 'published', '1')
