INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Chemical Equilibrium', 'Basic Concepts', 'Chemical Equilibrium — When Reactions Balance', '["Define dynamic equilibrium and its conditions","State and apply Le Chatelier''s Principle","Write equilibrium constant expressions (Kc and Kp)","Predict the effect of changes on equilibrium position"]'::jsonb, 'hard', '22', '[{"id":"equil_hook_01","type":"hook","order":1,"content":{"text":"Imagine a busy highway where cars are going both ways at the same rate. The traffic looks still, but cars are constantly moving. That''s dynamic equilibrium — forward and reverse reactions happen at equal rates. Understanding this helps chemists maximize product yield in industrial processes like the Haber process for ammonia.","prediction_prompt":"If you add more reactant to a system at equilibrium, which direction will the reaction shift to restore balance?"}},{"id":"equil_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Chemical equilibrium occurs when the rate of the forward reaction equals the rate of the reverse reaction. The concentrations of reactants and products remain constant (but not necessarily equal). Le Chatelier''s Principle says: if you disturb a system at equilibrium, it will shift to counteract the disturbance. It''s nature''s way of maintaining balance.","analogy":"Think of a crowded room with people constantly entering and leaving at the same rate. The total number of people stays the same (equilibrium). If you open more doors to let people in (add reactant), more people will also leave (forward reaction increases) until a new balance is reached."}},{"id":"equil_formal_01","type":"formal_explanation","order":3,"content":{"text":"For a reaction aA + bB ⇌ cC + dD, the equilibrium constant Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ. Kp uses partial pressures instead of concentrations. Le Chatelier''s Principle: increasing concentration, pressure, or temperature shifts equilibrium to counteract the change. Catalysts speed up both forward and reverse reactions equally — they don''t shift equilibrium.","key_terms":[{"term":"Dynamic Equilibrium","definition":"Forward and reverse reactions occur at equal rates; concentrations are constant"},{"term":"Le Chatelier''s Principle","definition":"A system at equilibrium counteracts any imposed change"},{"term":"Kc","definition":"Equilibrium constant in terms of concentration"},{"term":"Kp","definition":"Equilibrium constant in terms of partial pressures"}]}},{"id":"equil_formula_01","type":"formula","order":4,"content":{"formula":"Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ","variables":[{"name":"Kc","description":"Equilibrium constant (concentration)","unit":"varies"},{"name":"[A], [B]","description":"Equilibrium concentrations of reactants","unit":"mol/dm³"},{"name":"[C], [D]","description":"Equilibrium concentrations of products","unit":"mol/dm³"},{"name":"a, b, c, d","description":"Stoichiometric coefficients from balanced equation","unit":"none"}],"when_to_use":"When you know equilibrium concentrations and need to calculate Kc, or know Kc and need to find concentrations.","common_traps":["Using initial concentrations instead of equilibrium concentrations","Forgetting to raise concentrations to the power of their coefficients","Not including pure solids or liquids in the expression"],"units_note":"Kc may have units depending on the reaction. Kp uses partial pressures (usually in atm or Pa)."}},{"id":"equil_worked_example_01","type":"worked_example","order":5,"content":{"problem":"For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), at equilibrium: [N₂] = 0.5, [H₂] = 1.5, [NH₃] = 0.8 mol/dm³. Calculate Kc.","steps":["Write the Kc expression: Kc = [NH₃]² / ([N₂][H₂]³)","Substitute values: Kc = (0.8)² / ((0.5)(1.5)³)","Calculate numerator: 0.8² = 0.64","Calculate denominator: 0.5 × 3.375 = 1.6875","Kc = 0.64 / 1.6875 ≈ 0.379"],"answer":"Kc ≈ 0.38 (no units in this case)","explanation":"A small Kc (< 1) means reactants are favoured at equilibrium. To make more NH₃ industrially, you need high pressure and low temperature (Le Chatelier''s Principle)."}},{"id":"equil_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — equilibrium and Le Chatelier''s Principle are frequent JAMB topics","typical_question":"Explain the effect of increasing pressure on the equilibrium: N₂(g) + 3H₂(g) ⇌ 2NH₃(g)","common_mistakes":["Thinking increasing pressure always shifts to the side with fewer moles (only for gaseous species)","Forgetting that catalysts don''t affect equilibrium position","Confusing the effect of temperature on exothermic vs endothermic reactions"],"exam_tip":"For pressure: count moles of gas on each side. More moles → shift away. For temperature: treat heat as a product (exothermic) or reactant (endothermic)."}},{"id":"equil_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"At equilibrium, forward and reverse reaction rates are:","options":["Zero","Equal","Different","Maximum"],"correct_index":1,"explanation":"Dynamic equilibrium means forward rate = reverse rate. Both reactions continue, but there''s no net change."},{"question":"Adding a catalyst to a system at equilibrium will:","options":["Shift equilibrium to products","Shift equilibrium to reactants","Have no effect on equilibrium","Increase Kc"],"correct_index":2,"explanation":"A catalyst speeds up both forward and reverse reactions equally. It doesn''t change the equilibrium position or Kc."},{"question":"For the Haber process, which condition favours NH₃ production?","options":["Low pressure, high temperature","High pressure, low temperature","Low pressure, low temperature","High pressure, high temperature"],"correct_index":1,"explanation":"High pressure shifts equilibrium to the side with fewer moles (products). Low temperature favours the exothermic forward reaction."}]}},{"id":"equil_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Equilibrium: forward rate = reverse rate, concentrations constant","Le Chatelier''s: system counteracts disturbances","Kc = products/reactants (raised to coefficients)","Catalysts speed up both directions equally — no shift"],"connections":["Leads to: Industrial processes (Haber, Contact process)","Leads to: pH and buffer calculations","Builds on: Chemical Bonding and Reaction Rates"]}},{"id":"equil_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Chemical Equilibrium","min_score":80,"required_sections":["equil_hook_01","equil_intuitive_01","equil_formal_01","equil_formula_01","equil_worked_example_01"]}}]'::jsonb, 'published', '1')
