INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Electrochemistry', 'Basic Concepts', 'Electrochemistry — Electricity from Chemical Reactions', '["Distinguish between galvanic and electrolytic cells","Identify anode, cathode, and direction of electron flow","Calculate electrode potentials and cell EMF","Explain electrolysis and its applications"]'::jsonb, 'hard', '22', '[{"id":"electrochem_hook_01","type":"hook","order":1,"content":{"text":"Your phone battery, the corrosion of iron, electroplating of jewellery, and even how your body transmits nerve impulses — all involve electrochemistry. It''s the bridge between chemistry and electricity. Understanding it helps you know why batteries die, how rust forms, and why we can extract metals from ores using electricity.","prediction_prompt":"If you connect a zinc rod to a copper rod and dip them in a salt bridge, what do you think happens? Which rod dissolves?"}},{"id":"electrochem_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Some chemical reactions produce electricity (galvanic/voltaic cells — like batteries). Others use electricity to drive non-spontaneous reactions (electrolytic cells — like electroplating). In both cases, oxidation happens at the anode and reduction at the cathode. Electrons always flow from anode to cathode through the external circuit.","analogy":"Think of a galvanic cell like a waterfall — water (electrons) flows downhill naturally, releasing energy. An electrolytic cell is like pumping water uphill — you need to put energy in (from a battery) to make it happen."}},{"id":"electrochem_formal_01","type":"formal_explanation","order":3,"content":{"text":"A galvanic cell converts chemical energy to electrical energy using spontaneous redox reactions. An electrolytic cell uses electrical energy to drive non-spontaneous reactions. The anode is where oxidation occurs (loss of electrons). The cathode is where reduction occurs (gain of electrons). Electrons flow from anode to cathode externally. Current flows from cathode to anode.","key_terms":[{"term":"Anode","definition":"Electrode where oxidation occurs. Negative in galvanic, positive in electrolytic"},{"term":"Cathode","definition":"Electrode where reduction occurs. Positive in galvanic, negative in electrolytic"},{"term":"EMF","definition":"Electromotive force — the potential difference of a cell at equilibrium"},{"term":"Electrolysis","definition":"Using electricity to decompose an electrolyte"}]}},{"id":"electrochem_formula_01","type":"formula","order":4,"content":{"formula":"E°cell = E°cathode − E°anode","variables":[{"name":"E°cell","description":"Standard cell EMF","unit":"V"},{"name":"E°cathode","description":"Standard reduction potential of cathode","unit":"V"},{"name":"E°anode","description":"Standard reduction potential of anode","unit":"V"}],"when_to_use":"When you need to calculate the EMF of a galvanic cell from standard electrode potentials.","common_traps":["Swapping anode and cathode — remember: oxidation at anode, reduction at cathode","Forgetting the negative sign: E°cell = E°cathode − E°anode (not plus)","Confusing which electrode is which in electrolytic vs galvanic cells"],"units_note":"Electrode potentials are measured in volts (V) under standard conditions (298 K, 1 mol/dm³, 1 atm)."}},{"id":"electrochem_interactive_electrolysis_01","type":"interactive","order":5,"content":{"component":"electrolysis_simulator","config":{},"instruction":"Change the electrolyte and the electrode materials. Identify which ions are oxidised at the anode and which are reduced at the cathode.","prediction_prompt":"At the anode, oxidation happens — so should mass be lost or gained there? Predict, then check the electrode masses."}},{"id":"electrochem_worked_example_01","type":"worked_example","order":6,"content":{"problem":"Calculate the EMF of a Daniell cell: Zn | Zn²⁺ || Cu²⁺ | Cu. Given E°(Zn²⁺/Zn) = −0.76 V and E°(Cu²⁺/Cu) = +0.34 V.","steps":["Identify: Zn is oxidized (anode), Cu²⁺ is reduced (cathode)","E°cell = E°cathode − E°anode","E°cell = (+0.34) − (−0.76)","E°cell = 0.34 + 0.76 = 1.10 V"],"answer":"E°cell = 1.10 V","explanation":"The positive EMF confirms the reaction is spontaneous. Zinc dissolves at the anode (oxidized) while copper plates out at the cathode (reduced). This is the principle behind Daniell cells."}},{"id":"electrochem_jamb_focus_01","type":"jamb_focus","order":7,"content":{"frequency":"Common — electrochemistry and electrolysis are regular JAMB topics","typical_question":"Describe the electrolysis of molten NaCl. What is produced at each electrode?","common_mistakes":["Confusing molten NaCl with aqueous NaCl (different products)","Forgetting that in electrolysis, anode is positive (connected to positive terminal)","Not writing the half-equations for electrode reactions"],"exam_tip":"For electrolysis: always check if the electrolyte is molten or aqueous. Molten = only the cation and anion. Aqueous = water may also be discharged."}},{"id":"electrochem_practice_01","type":"practice","order":8,"content":{"questions":[{"question":"In a galvanic cell, electrons flow from:","options":["Cathode to anode","Anode to cathode","Positive to negative","Nowhere (no flow)"],"correct_index":1,"explanation":"Electrons always flow from anode (where oxidation releases electrons) to cathode (where reduction consumes electrons) through the external circuit."},{"question":"During electrolysis of CuSO₄ solution with copper electrodes, what happens at the anode?","options":["Cu²⁺ is deposited","Cu dissolves","O₂ is produced","H₂ is produced"],"correct_index":1,"explanation":"With copper electrodes, the copper anode dissolves: Cu → Cu²⁺ + 2e⁻. This is used in copper refining."},{"question":"Which reaction occurs at the cathode?","options":["Oxidation","Reduction","Both","Neither"],"correct_index":1,"explanation":"Reduction (gain of electrons) always occurs at the cathode. Remember: ''Red Cat'' (Reduction at Cathode)."}]}},{"id":"electrochem_summary_01","type":"summary","order":9,"content":{"key_takeaways":["Anode = oxidation, Cathode = reduction","Electrons: anode → cathode (external circuit)","E°cell = E°cathode − E°anode","Electrolysis: molten vs aqueous produces different products"],"connections":["Leads to: Corrosion and prevention","Leads to: Batteries and fuel cells","Builds on: Redox reactions and Chemical Bonding"]}},{"id":"electrochem_mastery_01","type":"mastery_check","order":10,"content":{"description":"Demonstrate mastery of Electrochemistry","min_score":80,"required_sections":["electrochem_hook_01","electrochem_intuitive_01","electrochem_formal_01","electrochem_formula_01","electrochem_worked_example_01"]}}]'::jsonb, 'published', '1')
