INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Organic Chemistry', 'Basic Concepts', 'Organic Chemistry — Carbon''s Amazing Compounds', '["Classify organic compounds by functional groups","Name simple organic compounds using IUPAC nomenclature","Explain the properties of homologous series","Predict products of organic reactions"]'::jsonb, 'hard', '25', '[{"id":"organic_hook_01","type":"hook","order":1,"content":{"text":"Every living thing on Earth is made of organic compounds — proteins, carbohydrates, fats, DNA. Your body is a walking chemistry lab with thousands of organic reactions happening every second. Organic chemistry is the study of carbon compounds, and it''s the foundation of medicine, food science, plastics, and even the fuel in your car.","prediction_prompt":"Why do you think carbon is special enough to have its own branch of chemistry? What makes it different from other elements?"}},{"id":"organic_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Carbon is unique because it can form 4 bonds, bond to itself to make long chains, and form double/triple bonds. This gives rise to millions of different compounds. Organic compounds are grouped by functional groups — specific atom arrangements that determine how they react. Think of functional groups as the ''personality'' of the molecule.","analogy":"Imagine Lego bricks. Carbon is like a special brick that can connect to 4 other bricks in any direction. You can build straight chains, branches, rings, and complex 3D structures. The functional group is like adding a special piece (wheels, wings, lights) that changes what the structure can do."}},{"id":"organic_formal_01","type":"formal_explanation","order":3,"content":{"text":"Organic compounds are classified by functional groups: alkanes (C-C single bonds), alkenes (C=C double bonds), alcohols (-OH), carboxylic acids (-COOH), esters (-COO-), amines (-NH₂). A homologous series is a family of compounds with the same functional group but differing by CH₂ units. IUPAC nomenclature provides systematic naming.","key_terms":[{"term":"Functional Group","definition":"An atom or group of atoms that determines the chemical properties of an organic compound"},{"term":"Homologous Series","definition":"A series of compounds with the same functional group, differing by CH₂ units"},{"term":"IUPAC Name","definition":"Systematic international name for organic compounds"},{"term":"Saturated","definition":"Contains only C-C single bonds (alkanes). Unsaturated has double/triple bonds"}]}},{"id":"organic_formula_01","type":"formula","order":4,"content":{"formula":"CₙH₂ₙ₊₂ (alkanes), CₙH₂ₙ (alkenes)","variables":[{"name":"n","description":"Number of carbon atoms","unit":"count"},{"name":"2n+2","description":"Number of hydrogen atoms in alkanes","unit":"count"},{"name":"2n","description":"Number of hydrogen atoms in alkenes","unit":"count"}],"when_to_use":"Use these general formulas to determine the molecular formula of alkanes and alkenes.","common_traps":["Forgetting that alkanes are saturated (single bonds only) and alkenes are unsaturated","Using the wrong general formula for cyclic compounds (CₙH₂ₙ for cycloalkanes)","Not recognizing functional groups in complex molecules"],"units_note":"n must be a positive integer (1, 2, 3...). For alkanes, n ≥ 1. For alkenes, n ≥ 2."}},{"id":"organic_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Name the following compound: CH₃-CH₂-CH₂-OH","steps":["Identify the functional group: -OH (alcohol)","Count the carbon chain: 3 carbons (prop-)","Number from the end nearest the -OH: C1-C2-C3-OH","Add suffix for alcohol: -ol","Name: propan-1-ol (the -OH is on carbon 1)"],"answer":"Propan-1-ol (or 1-propanol)","explanation":"The IUPAC system identifies the longest carbon chain containing the functional group, numbers it to give the functional group the lowest number, and adds the appropriate suffix (-ol for alcohols)."}},{"id":"organic_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Very common — organic chemistry is a major JAMB topic","typical_question":"Name the products of the reaction between ethanol and ethanoic acid. What type of reaction is this?","common_mistakes":["Confusing esterification with neutralization","Not recognizing that alkenes undergo addition reactions while alkanes undergo substitution","Forgetting that carboxylic acids are weak acids"],"exam_tip":"For naming: identify the functional group first, count the carbon chain, then add prefix + root + suffix. For reactions: know that alkenes decolourise bromine water (test for unsaturation)."}},{"id":"organic_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What is the general formula for alkanes?","options":["CₙH₂ₙ","CₙH₂ₙ₊₂","CₙH₂ₙ₋₂","CₙHₙ"],"correct_index":1,"explanation":"Alkanes are saturated hydrocarbons with the general formula CₙH₂ₙ₊₂ (e.g., methane CH₄, ethane C₂H₆)."},{"question":"Which test distinguishes alkenes from alkanes?","options":["Litmus test","Bromine water test","Flame test","pH test"],"correct_index":1,"explanation":"Alkenes decolourise bromine water (orange → colourless) due to addition across the double bond. Alkanes don''t react."},{"question":"What is the product of ethanol + ethanoic acid?","options":["Sodium ethanoate","Ethyl ethanoate","Ethanol","Ethanoic acid"],"correct_index":1,"explanation":"This is esterification: CH₃COOH + C₂H₅OH → CH₃COOC₂H₅ + H₂O. The product is ethyl ethanoate (an ester)."}]}},{"id":"organic_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Carbon forms 4 bonds, enabling complex structures","Functional groups determine chemical behaviour","Alkanes: CₙH₂ₙ₊₂ (saturated), Alkenes: CₙH₂ₙ (unsaturated)","IUPAC naming: prefix + root + suffix"],"connections":["Leads to: Biochemistry (carbohydrates, proteins, lipids)","Leads to: Industrial organic chemistry","Builds on: Chemical Bonding (covalent bonds)"]}},{"id":"organic_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Organic Chemistry","min_score":80,"required_sections":["organic_hook_01","organic_intuitive_01","organic_formal_01","organic_formula_01","organic_worked_example_01"]}}]'::jsonb, 'published', '1')
