INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Chemical Kinetics', 'Basic Concepts', 'Chemical Kinetics — Why Some Reactions Are Fast', '["Define reaction rate and factors affecting it","Explain collision theory and activation energy","Describe the effect of concentration, temperature, and catalysts on rate","Draw and interpret reaction rate graphs"]'::jsonb, 'medium', '20', '[{"id":"kinetics_hook_01","type":"hook","order":1,"content":{"text":"Why does food spoil faster at room temperature than in a fridge? Why do we use catalysts in car exhausts? Why does burning paper ignite instantly while rusting iron takes months? All these questions are about reaction rates — how fast or slow chemical reactions happen. Kinetics explains the ''how fast'' while equilibrium explains ''how far.''","prediction_prompt":"If you increase the temperature of a reaction, does it always speed up? By how much?"}},{"id":"kinetics_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"For a reaction to happen, particles must collide with enough energy (activation energy) and in the right orientation. Increasing concentration means more particles in the same space → more collisions. Increasing temperature means particles move faster → more collisions AND more energy per collision. Catalysts lower the activation energy barrier, making it easier for collisions to succeed.","analogy":"Think of a locked door. Activation energy is the key. Particles need to hit the door with the right key (energy + orientation). Increasing concentration = more people trying. Increasing temperature = people running faster. A catalyst = making the lock easier to pick."}},{"id":"kinetics_formal_01","type":"formal_explanation","order":3,"content":{"text":"Reaction rate is the change in concentration of reactants or products per unit time. Factors affecting rate: concentration (more particles → more collisions), temperature (higher T → more energy, more successful collisions), surface area (more exposed area → more collisions), catalysts (lower activation energy), and nature of reactants.","key_terms":[{"term":"Reaction Rate","definition":"Change in concentration per unit time. Usually mol/dm³/s"},{"term":"Activation Energy (Ea)","definition":"Minimum energy required for a collision to be successful"},{"term":"Catalyst","definition":"A substance that speeds up a reaction without being consumed"},{"term":"Collision Theory","definition":"Reactions occur when particles collide with sufficient energy and correct orientation"}]}},{"id":"kinetics_formula_01","type":"formula","order":4,"content":{"formula":"Rate = k[A]ⁿ[B]ᵐ","variables":[{"name":"Rate","description":"Reaction rate","unit":"mol/dm³/s"},{"name":"k","description":"Rate constant","unit":"varies"},{"name":"[A], [B]","description":"Concentrations of reactants","unit":"mol/dm³"},{"name":"n, m","description":"Orders of reaction (determined experimentally)","unit":"none"}],"when_to_use":"Use the rate equation to calculate rate from concentrations and determine the order of reaction from experimental data.","common_traps":["Orders of reaction (n, m) are NOT the same as stoichiometric coefficients","A zero-order reaction means rate is independent of that reactant''s concentration","First-order: doubling concentration doubles rate. Second-order: doubling concentration quadruples rate"],"units_note":"The units of k depend on the overall order. For first order: s⁻¹. For second order: dm³/mol/s."}},{"id":"kinetics_worked_example_01","type":"worked_example","order":5,"content":{"problem":"For the reaction A + B → products, the rate equation is Rate = k[A][B]². If [A] = 0.1 mol/dm³ and [B] = 0.2 mol/dm³, and k = 5.0 × 10³ dm⁶/mol²/s, calculate the rate.","steps":["Write the rate equation: Rate = k[A][B]²","Substitute values: Rate = (5.0 × 10³)(0.1)(0.2)²","Calculate [B]²: (0.2)² = 0.04","Rate = 5000 × 0.1 × 0.04 = 20 mol/dm³/s"],"answer":"Rate = 20 mol/dm³/s","explanation":"The reaction is third-order overall (first-order in A, second-order in B). This means the rate is most sensitive to changes in [B]. Doubling [B] would quadruple the rate."}},{"id":"kinetics_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — kinetics and rate factors are regular JAMB topics","typical_question":"Explain why increasing temperature has a greater effect on reaction rate than increasing concentration.","common_mistakes":["Forgetting that temperature affects both collision frequency AND the fraction of successful collisions","Confusing catalysts with reactants (catalysts are not consumed)","Not understanding that activation energy is a minimum threshold"],"exam_tip":"For rate graphs: reactant concentration decreases over time (curve down), product concentration increases (curve up). The gradient at any point = instantaneous rate."}},{"id":"kinetics_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"What does a catalyst do to a reaction?","options":["Increases activation energy","Decreases activation energy","Changes the products","Increases the temperature"],"correct_index":1,"explanation":"A catalyst provides an alternative reaction pathway with a lower activation energy, making more collisions successful."},{"question":"If doubling [A] quadruples the rate, what is the order with respect to A?","options":["Zero order","First order","Second order","Third order"],"correct_index":2,"explanation":"Second-order: rate ∝ [A]². Doubling [A] gives 2² = 4× the rate."},{"question":"Which factor does NOT affect reaction rate?","options":["Temperature","Concentration","Catalyst","Equilibrium constant"],"correct_index":3,"explanation":"The equilibrium constant (Kc) determines how far a reaction goes, not how fast. Rate depends on concentration, temperature, surface area, and catalysts."}]}},{"id":"kinetics_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Reaction rate depends on collision frequency and energy","Factors: concentration, temperature, surface area, catalysts","Catalysts lower activation energy without being consumed","Rate = k[A]ⁿ[B]ᵐ — orders determined experimentally"],"connections":["Leads to: Industrial processes and optimization","Leads to: Enzyme kinetics in biology","Builds on: Collision theory and Thermodynamics"]}},{"id":"kinetics_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of Chemical Kinetics","min_score":80,"required_sections":["kinetics_hook_01","kinetics_intuitive_01","kinetics_formal_01","kinetics_formula_01","kinetics_worked_example_01"]}}]'::jsonb, 'published', '1')
