INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'States of Matter', 'Basic Concepts', 'States of Matter — Solids, Liquids, and Gases', '["Describe the three states of matter and their properties","Explain the kinetic molecular theory","Describe phase changes and their energy requirements","Apply the gas laws (Boyle''s, Charles''s, Ideal Gas)"]'::jsonb, 'medium', '20', '[{"id":"states_hook_01","type":"hook","order":1,"content":{"text":"Water can be ice, liquid water, or steam — same molecule, completely different behaviours. Why does ice float while most solids sink? Why does steam burn more than boiling water? The answers lie in how molecules are arranged and how much energy they have in each state.","prediction_prompt":"If you heat a gas in a sealed container, what happens to the pressure? Why do you think tyres can burst in hot weather?"}},{"id":"states_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"In solids, molecules are tightly packed and vibrate in fixed positions. In liquids, molecules can slide past each other — they''re close but free to move. In gases, molecules are far apart and move randomly at high speed. The key difference is the amount of kinetic energy: solids (least) → liquids → gases (most).","analogy":"Think of a crowded room. Solid = everyone standing still, shoulder to shoulder, vibrating. Liquid = people walking slowly, bumping into each other. Gas = people running around wildly with lots of space between them."}},{"id":"states_formal_01","type":"formal_explanation","order":3,"content":{"text":"Solids have fixed shape and volume (incompressible). Liquids have fixed volume but take the shape of their container (slightly compressible). Gases have neither fixed shape nor volume (highly compressible). Phase changes: melting (solid→liquid), boiling (liquid→gas), condensation (gas→liquid), freezing (liquid→solid), sublimation (solid→gas), deposition (gas→solid).","key_terms":[{"term":"Melting Point","definition":"Temperature at which solid turns to liquid at 1 atm"},{"term":"Boiling Point","definition":"Temperature at which liquid turns to gas at 1 atm"},{"term":"Sublimation","definition":"Direct transition from solid to gas (e.g., dry ice)"},{"term":"Latent Heat","definition":"Energy absorbed/released during phase change without temperature change"}]}},{"id":"states_formula_01","type":"formula","order":4,"content":{"formula":"PV = nRT","variables":[{"name":"P","description":"Pressure","unit":"Pa or atm"},{"name":"V","description":"Volume","unit":"m³ or dm³"},{"name":"n","description":"Number of moles","unit":"mol"},{"name":"R","description":"Gas constant","unit":"8.314 J/mol/K"},{"name":"T","description":"Temperature","unit":"K (Kelvin)"}],"when_to_use":"The ideal gas law relates pressure, volume, temperature, and amount of gas. Use it when other gas laws don''t directly apply.","common_traps":["Using temperature in °C instead of K (always convert: K = °C + 273)","Confusing Boyle''s Law (P ∝ 1/V at constant T) with Charles''s Law (V ∝ T at constant P)","Forgetting to convert volume to m³ or dm³"],"units_note":"Always use SI units: Pa for pressure, m³ for volume, K for temperature. R = 8.314 J/mol/K."}},{"id":"states_worked_example_01","type":"worked_example","order":5,"content":{"problem":"A gas occupies 5.0 dm³ at 25°C and 100 kPa. What volume will it occupy at 100°C and the same pressure?","steps":["This is Charles''s Law (constant pressure): V₁/T₁ = V₂/T₂","Convert temperatures to Kelvin: T₁ = 25 + 273 = 298 K, T₂ = 100 + 273 = 373 K","Rearrange: V₂ = V₁ × T₂/T₁","V₂ = 5.0 × 373/298 = 5.0 × 1.252 = 6.26 dm³"],"answer":"V₂ ≈ 6.26 dm³","explanation":"When temperature increases at constant pressure, volume increases proportionally (Charles''s Law). The gas expands because molecules move faster and push harder against the container walls."}},{"id":"states_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — gas laws and states of matter are regular JAMB topics","typical_question":"A gas at 27°C has a volume of 200 cm³. What is its volume at 127°C at constant pressure?","common_mistakes":["Using °C instead of K in gas law calculations","Forgetting to convert cm³ to dm³ when using with pressure in kPa","Not specifying which gas law applies (Boyle''s vs Charles''s vs Combined)"],"exam_tip":"For gas law questions: always convert to Kelvin first. Identify which variable is constant to choose the right law."}},{"id":"states_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"At what temperature does water boil at 1 atm?","options":["0°C","100°C","373°C","273 K"],"correct_index":1,"explanation":"Water boils at 100°C (373 K) at standard atmospheric pressure (1 atm)."},{"question":"Which state has the highest kinetic energy per molecule?","options":["Solid","Liquid","Gas","All equal"],"correct_index":2,"explanation":"Gas molecules have the most kinetic energy — they move freely at high speeds."},{"question":"If pressure is doubled at constant temperature, what happens to volume?","options":["Doubles","Halves","Stays the same","Quadruples"],"correct_index":1,"explanation":"Boyle''s Law: P₁V₁ = P₂V₂. If P doubles, V must halve to keep PV constant."}]}},{"id":"states_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Solid (fixed shape) → Liquid (fixed volume) → Gas (no fixed shape/volume)","Phase changes require energy (latent heat) without temperature change","PV = nRT — always use Kelvin for temperature","Boyle''s: P ∝ 1/V. Charles''s: V ∝ T"],"connections":["Leads to: Gas stoichiometry calculations","Leads to: Thermochemistry and enthalpy","Builds on: Kinetic molecular theory"]}},{"id":"states_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of States of Matter","min_score":80,"required_sections":["states_hook_01","states_intuitive_01","states_formal_01","states_formula_01","states_worked_example_01"]}}]'::jsonb, 'published', '1')
