INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "version")
VALUES ('chemistry', 'Periodic Table', 'Basic Concepts', 'Periodic Table — Organizing the Elements', '["Explain the organization of the periodic table","Describe trends in atomic radius, ionization energy, and electronegativity","Classify elements as metals, non-metals, or metalloids","Predict element properties from their position"]'::jsonb, 'medium', '20', '[{"id":"periodic_hook_01","type":"hook","order":1,"content":{"text":"The periodic table isn''t just a chart on a classroom wall — it''s a map of everything that exists. Mendeleev arranged elements by mass and noticed patterns: elements with similar properties appeared at regular (periodic) intervals. Today, we arrange them by atomic number, and the table predicts how elements behave just by their position.","prediction_prompt":"If Lithium (Li) and Sodium (Na) are in the same column, what do you think they have in common?"}},{"id":"periodic_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The periodic table is arranged in rows (periods) and columns (groups). Elements in the same group have the same number of valence electrons, which gives them similar chemical properties. Moving left to right across a period, atoms get smaller and lose electrons more easily. Moving down a group, atoms get larger and gain electrons more easily.","analogy":"Think of the periodic table like a sports team roster. Groups are positions (goalkeeper, defender, striker). Players in the same position have similar skills (chemical properties). Periods are like experience levels — more experience (periods) means more ''layers'' (electron shells)."}},{"id":"periodic_formal_01","type":"formal_explanation","order":3,"content":{"text":"The periodic table organizes elements by increasing atomic number. Groups (columns) contain elements with similar valence electron configurations. Periods (rows) represent the highest energy level occupied. Trends across a period: atomic radius decreases, ionization energy increases, electronegativity increases. Trends down a group: atomic radius increases, ionization energy decreases, electronegativity decreases.","key_terms":[{"term":"Group","definition":"Vertical column. Elements in same group have similar chemical properties"},{"term":"Period","definition":"Horizontal row. Represents the highest occupied energy level"},{"term":"Ionization Energy","definition":"Energy required to remove one electron from a gaseous atom"},{"term":"Electronegativity","definition":"Ability of an atom to attract bonding electrons"}]}},{"id":"periodic_formula_01","type":"formula","order":4,"content":{"formula":"Trends: Left→Right: radius↓, IE↑, EN↑. Top→Bottom: radius↑, IE↓, EN↓","variables":[{"name":"IE","description":"Ionization energy","unit":"kJ/mol"},{"name":"EN","description":"Electronegativity (Pauling scale)","unit":"none"}],"when_to_use":"Use these trends to predict relative atomic sizes, reactivity, and bonding behaviour of elements.","common_traps":["Forgetting that noble gases have very high ionization energy (full outer shell)","Not recognizing that metalloids (Si, Ge, As) have intermediate properties","Confusing electronegativity trend with electron affinity trend"],"units_note":"Ionization energy is measured in kJ/mol. Electronegativity is on the Pauling scale (no units)."}},{"id":"periodic_worked_example_01","type":"worked_example","order":5,"content":{"problem":"Arrange the following in order of increasing atomic radius: Li, Na, K, Rb.","steps":["All are in Group 1 (alkali metals)","Going down the group: atomic radius increases","Order from smallest to largest: Li < Na < K < Rb","Each element has one more electron shell than the one above"],"answer":"Li < Na < K < Rb (increasing atomic radius)","explanation":"As you go down Group 1, each element has an additional electron shell, making the atom larger. The outermost electron is also further from the nucleus, which is why reactivity increases down the group."}},{"id":"periodic_jamb_focus_01","type":"jamb_focus","order":6,"content":{"frequency":"Common — periodic trends and element properties are regular JAMB topics","typical_question":"Explain why sodium is more reactive than lithium, even though lithium has a higher ionization energy.","common_mistakes":["Confusing ionization energy with reactivity — they''re inversely related for metals","Forgetting that atomic radius increases down a group","Not connecting periodic position to chemical behaviour"],"exam_tip":"For trend questions: remember the mnemonic ''Tiny Tom Eats Eggs Regularly'' — across a period: radius decreases, IE increases, EN increases."}},{"id":"periodic_practice_01","type":"practice","order":7,"content":{"questions":[{"question":"Which element has the highest ionization energy in Period 3?","options":["Na","Mg","Al","Ar"],"correct_index":3,"explanation":"Noble gases have the highest IE because they have a full outer shell. Ar (Period 3 noble gas) has the highest IE in that period."},{"question":"Which group contains the halogens?","options":["Group 1","Group 2","Group 17","Group 18"],"correct_index":2,"explanation":"Halogens are in Group 17: F, Cl, Br, I. They have 7 valence electrons and are highly reactive non-metals."},{"question":"Going down Group 1, ionization energy:","options":["Increases","Decreases","Stays the same","Fluctuates"],"correct_index":1,"explanation":"Down a group, atomic radius increases and the outer electron is further from the nucleus, making it easier to remove (lower IE)."}]}},{"id":"periodic_summary_01","type":"summary","order":8,"content":{"key_takeaways":["Groups = same valence electrons = similar properties","Periods = same energy level = similar atomic size","Left→Right: radius↓, IE↑, EN↑","Top→Bottom: radius↑, IE↓, EN↓"],"connections":["Leads to: Chemical Bonding (predicting bond type)","Leads to: Periodic Chemistry (reactions of elements)","Builds on: Atomic Structure (electron configuration)"]}},{"id":"periodic_mastery_01","type":"mastery_check","order":9,"content":{"description":"Demonstrate mastery of the Periodic Table","min_score":80,"required_sections":["periodic_hook_01","periodic_intuitive_01","periodic_formal_01","periodic_formula_01","periodic_worked_example_01"]}}]'::jsonb, 'published', '1')
