INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('commerce', 'Basis of Commerce', 'Introduction', 'Commerce — Buying, Selling, and Everything in Between', '["Define commerce and its scope","Distinguish between trade and aid to trade","Explain the importance of commerce to economic development","Identify the branches of commerce"]'::jsonb, 'medium', '20', '[{"id":"com_hook_01","type":"hook","order":1,"content":{"text":"Every time you buy airtime, pay school fees, or buy groceries, you''re participating in commerce. Commerce is the engine that moves goods from producers to consumers. Without it, farmers couldn''t sell their crops, and you couldn''t buy the things you need.","prediction_prompt":"What would happen if there were no shops, banks, or transport companies?"}},{"id":"com_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Commerce = Trade + Aids to Trade. Trade is the actual buying and selling. Aids to trade are the services that help trade happen: banking (finance), insurance (risk protection), transport (moving goods), warehousing (storing goods), advertising (informing buyers), and communication (connecting people).","analogy":"Think of commerce like a football team. Trade is the players scoring goals. Aids to trade are the goalkeeper, coach, referee, and supporters — they make the game possible but aren''t the main event."}},{"id":"com_formal_01","type":"formal_explanation","order":3,"content":{"text":"Branches of commerce: (1) Trade — buying and selling. Domestic trade (within country). International trade (between countries). (2) Aids to trade — banking, insurance, transport, warehousing, advertising, communication. Commerce promotes specialization, creates employment, raises living standards, and generates government revenue.","key_terms":[{"term":"Commerce","definition":"All activities involved in buying, selling, and distributing goods and services"},{"term":"Trade","definition":"The buying and selling of goods and services"},{"term":"Aids to Trade","definition":"Services that facilitate trade: banking, insurance, transport, etc."},{"term":"Middleman","definition":"An intermediary between producer and consumer (wholesaler, retailer)"}]}},{"id":"com_formula_01","type":"formula","order":4,"content":{"formula":"Commerce = Trade (Buying + Selling) + Aids to Trade (Banking + Insurance + Transport + Warehousing + Advertising + Communication)","variables":[{"name":"Domestic Trade","description":"Trade within a country (wholesale and retail)"},{"name":"International Trade","description":"Trade between countries (import and export)"},{"name":"Aids to Trade","description":"Services that support trade activities"}],"when_to_use":"When classifying commercial activities or understanding the scope of commerce.","common_traps":["Confusing trade with commerce — commerce is broader, includes aids to trade","Not knowing all six aids to trade","Confusing domestic and international trade"],"units_note":"Commerce accounts for a significant portion of GDP in most economies."}},{"id":"com_practice_01","type":"worked_example","order":5,"content":{"scenario":"A farmer grows tomatoes in Kano. A wholesaler buys them, a truck transports them to Lagos, a warehouse stores them, a retailer sells them to consumers, and a bank finances the transaction. Identify the commercial activities involved.","given":["A supply chain from farmer to consumer"],"required":"Identify trade and aids to trade","principle":"Trade = buying/selling. Aids = services that help trade happen.","steps":[{"explanation":"Trade","calculation":"Farmer sells to wholesaler (buying). Wholesaler sells to retailer (selling). Retailer sells to consumer (selling)."},{"explanation":"Aids to Trade","calculation":"Transport (truck moves goods), Warehousing (storing tomatoes), Banking (financing the transaction)"}],"answer":"Trade: farmer → wholesaler → retailer → consumer. Aids: transport, warehousing, banking.","check":"Each step in the chain involves both trade and aids to trade."}},{"id":"com_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Commerce is the same as trade.","why_wrong":"Commerce is broader. Trade is just buying and selling. Commerce includes all the services that make trade possible (banking, transport, insurance, etc.).","correct_model":"Commerce = Trade + Aids to Trade. Trade is a subset of commerce."}},{"id":"com_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the definition and branches of commerce, and the role of aids to trade.","trap":"JAMB may list activities and ask which is an aid to trade vs. which is trade. Know the difference.","tip":"Remember: Trade = direct buying/selling. Aids to trade = everything else that helps trade happen.","related_topics":["International trade","Banking","Insurance","Transport"]}},{"id":"com_memory_01","type":"memory_hook","order":8,"content":{"text":"Commerce = Trade + Aids. Trade = buying + selling. Aids = BANKIT: Banking, Advertising, Navigation (transport), Communication, Insurance, Transport, Warehousing.","hook_type":"mnemonic"}},{"id":"com_reflection_01","type":"reflection","order":9,"content":{"question":"How does commerce contribute to national development?","expected_understanding":"Commerce creates jobs, generates tax revenue, connects producers with consumers, improves living standards, and promotes economic growth."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Commerce includes:","options":[{"label":"A","text":"Only buying and selling"},{"label":"B","text":"Trade and aids to trade"},{"label":"C","text":"Only banking"},{"label":"D","text":"Only transport"}],"answer":"B","explanation":"Commerce = Trade + Aids to Trade (banking, insurance, transport, etc.).","hints":["Commerce is broader than just trade"]},{"difficulty":"medium","question":"Which of the following is an aid to trade?","options":[{"label":"A","text":"Selling goods"},{"label":"B","text":"Buying goods"},{"label":"C","text":"Warehousing"},{"label":"D","text":"Manufacturing"}],"answer":"C","explanation":"Warehousing stores goods until they''re needed — it aids trade but isn''t trade itself.","hints":["Which helps trade happen without being buying/selling?"]},{"difficulty":"jamb","question":"The intermediary between the producer and the final consumer is called:","options":[{"label":"A","text":"Producer"},{"label":"B","text":"Middleman"},{"label":"C","text":"Consumer"},{"label":"D","text":"Manufacturer"}],"answer":"B","explanation":"A middleman (wholesaler or retailer) sits between the producer and consumer.","hints":["Who is in the middle of the supply chain?"]}]'::jsonb, '{"min_score":80,"required_sections":["com_hook_01","com_intuitive_01","com_formal_01","com_formula_01","com_practice_01"]}'::jsonb, '1')
