INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('commerce', 'Trade — Domestic and International', 'Exchange of Goods', 'Trade — How Goods Move Across Borders', '["Distinguish between domestic and international trade","Explain the balance of trade and balance of payments","Identify types of international trade barriers","Understand the role of ECOWAS and AU in African trade"]'::jsonb, 'medium', '20', '[{"id":"trd_hook_01","type":"hook","order":1,"content":{"text":"Nigeria imports cars from Japan, rice from India, and electronics from China. It exports crude oil to Europe and cocoa to the Americas. International trade connects every country to the global economy. But what happens when a country imports more than it exports?","prediction_prompt":"If Nigeria stopped importing rice, what would happen to the price of rice locally?"}},{"id":"trd_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Domestic trade = buying and selling within a country. International trade = buying and selling between countries. Balance of trade = value of exports minus imports. Surplus = exports > imports. Deficit = imports > exports. Nigeria has a trade deficit in most goods but a surplus in oil.","analogy":"Think of international trade like a family budget. If you earn ₦100 and spend ₦120, you''re in deficit — you need to borrow or sell something. Countries face the same problem when they import more than they export."}},{"id":"trd_formal_01","type":"formal_explanation","order":3,"content":{"text":"International trade barriers: (1) Tariffs — taxes on imports. (2) Quotas — limits on import quantities. (3) Embargoes — complete bans on trade. (4) Exchange controls — restrictions on currency conversion. Regional trade: ECOWAS (Economic Community of West African States) promotes free trade in West Africa. AU (African Union) promotes continental trade through AfCFTA.","key_terms":[{"term":"Balance of Trade","definition":"Value of exports minus value of imports"},{"term":"Tariff","definition":"Tax imposed on imported goods"},{"term":"Embargo","definition":"Complete ban on trade with a country"},{"term":"ECOWAS","definition":"Economic Community of West African States — promotes regional trade"},{"term":"AfCFTA","definition":"African Continental Free Trade Area — world''s largest free trade area by number of countries"}]}},{"id":"trd_formula_01","type":"formula","order":4,"content":{"formula":"Balance of Trade = Total Exports − Total Imports. Trade Surplus: Exports > Imports. Trade Deficit: Imports > Exports","variables":[{"name":"Exports","description":"Goods sold to other countries"},{"name":"Imports","description":"Goods bought from other countries"},{"name":"Visible Trade","description":"Trade in physical goods (oil, rice, cars)"},{"name":"Invisible Trade","description":"Trade in services (banking, tourism, consulting)"}],"when_to_use":"When analyzing a country''s trade position or the effect of trade policies.","common_traps":["Confusing balance of trade with balance of payments","Not knowing the difference between visible and invisible trade","Forgetting that tariffs make imports more expensive"],"units_note":"Trade balance is usually measured in USD or the country''s currency."}},{"id":"trd_practice_01","type":"worked_example","order":5,"content":{"scenario":"Nigeria''s total exports in a year are $50 billion and total imports are $65 billion. Calculate the balance of trade and state whether it''s a surplus or deficit.","given":["Exports: $50 billion","Imports: $65 billion"],"required":"Calculate balance of trade","principle":"Balance of Trade = Exports − Imports","steps":[{"explanation":"Calculate","calculation":"$50B − $65B = −$15B"},{"explanation":"Interpret","calculation":"Negative result means imports exceed exports = trade deficit"}],"answer":"Balance of trade is −$15 billion (trade deficit of $15 billion).","check":"Imports ($65B) exceed exports ($50B) by $15B."}},{"id":"trd_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A trade deficit is always bad.","why_wrong":"A deficit means the country is buying more than it sells. This can be financed by borrowing or foreign investment. Some deficits are necessary for development (importing machinery).","correct_model":"A trade deficit isn''t always bad — it depends on what''s being imported and how it''s financed."}},{"id":"trd_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests trade balance, trade barriers, and regional trade organizations.","trap":"JAMB may give trade data and ask you to calculate the balance and explain whether it''s a surplus or deficit.","tip":"Know ECOWAS and AU trade policies. Know the difference between tariffs, quotas, and embargoes.","related_topics":["Exchange rates","Balance of payments","Economic integration"]}},{"id":"trd_memory_01","type":"memory_hook","order":8,"content":{"text":"Domestic = within country. International = between countries. Balance = Exports − Imports. Surplus = good (earn more). Deficit = bad (spend more). Barriers: tariffs, quotas, embargoes.","hook_type":"mnemonic"}},{"id":"trd_reflection_01","type":"reflection","order":9,"content":{"question":"How can Nigeria reduce its trade deficit?","expected_understanding":"Export more (diversify beyond oil), import less (produce locally), invest in manufacturing, and support agricultural exports."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"When a country''s exports exceed its imports, it has:","options":[{"label":"A","text":"Trade deficit"},{"label":"B","text":"Trade surplus"},{"label":"C","text":"Balance of payments deficit"},{"label":"D","text":"Inflation"}],"answer":"B","explanation":"Trade surplus = exports > imports.","hints":["More going out (earning) than coming in (spending)"]},{"difficulty":"medium","question":"A tariff on imported goods will:","options":[{"label":"A","text":"Make imports cheaper"},{"label":"B","text":"Make imports more expensive"},{"label":"C","text":"Increase imports"},{"label":"D","text":"Have no effect"}],"answer":"B","explanation":"A tariff is a tax on imports, making them more expensive and reducing demand.","hints":["What does a tax do to price?"]},{"difficulty":"jamb","question":"ECOWAS promotes:","options":[{"label":"A","text":"Trade barriers between member states"},{"label":"B","text":"Free movement of goods and people in West Africa"},{"label":"C","text":"Increased tariffs"},{"label":"D","text":"Trade restriction"}],"answer":"B","explanation":"ECOWAS aims to promote free trade and free movement of persons in West Africa.","hints":["What does ECOWAS stand for and what does it do?"]}]'::jsonb, '{"min_score":80,"required_sections":["trd_hook_01","trd_intuitive_01","trd_formal_01","trd_formula_01","trd_practice_01"]}'::jsonb, '1')
