INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('commerce', 'Business Finance', 'Sources and Use of Funds', 'Business Finance — Where Money Comes From and Where It Goes', '["Identify sources of business finance (short-term and long-term)","Explain the difference between debt and equity financing","Understand the role of banks in business financing","Evaluate the advantages and disadvantages of different financing methods"]'::jsonb, 'medium', '20', '[{"id":"fin_hook_01","type":"hook","order":1,"content":{"text":"You want to start a phone accessories business. You need ₦500,000 for stock, rent, and equipment. Where will you get the money? Your savings? A bank loan? A friend? Each option has pros and cons. This is the challenge every business owner faces — finding the right finance.","prediction_prompt":"If you needed money to start a business, would you borrow from a bank or use your own savings? Why?"}},{"id":"fin_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Sources of finance: Short-term (under 1 year): trade credit, bank overdraft, short-term loans. Long-term (over 1 year): bank loans, shares (equity), debentures, retained profits, government grants. Debt = borrowing money (must repay with interest). Equity = selling ownership (must share profits).","analogy":"Think of financing like building a house. You can borrow money from the bank (debt) — you must pay it back with interest. Or you can invite someone to co-own the house (equity) — they share in the profits and losses. Each has trade-offs."}},{"id":"fin_formal_01","type":"formal_explanation","order":3,"content":{"text":"Debt financing: bank loans, overdrafts, debentures, bonds. Advantages: don''t give up ownership, interest is tax-deductible. Disadvantages: must repay with interest, collateral may be required. Equity financing: shares, retained profits, venture capital. Advantages: no repayment obligation, shared risk. Disadvantages: dilute ownership, must share profits.","key_terms":[{"term":"Debt Finance","definition":"Borrowing money that must be repaid with interest"},{"term":"Equity Finance","definition":"Raising money by selling ownership shares in the business"},{"term":"Debenture","definition":"A long-term loan certificate, usually with fixed interest"},{"term":"Retained Profits","definition":"Net profit kept in the business rather than distributed as dividends"},{"term":"Overdraft","definition":"A bank facility allowing you to withdraw more than your account balance (short-term)"}]}},{"id":"fin_formula_01","type":"formula","order":4,"content":{"formula":"Total Capital = Debt + Equity. Cost of Debt = Interest rate × (1 − Tax rate). Cost of Equity = Dividends / Share price","variables":[{"name":"Debt","description":"Borrowed funds (loans, debentures, bonds)"},{"name":"Equity","description":"Owner''s funds (shares, retained profits)"},{"name":"Interest Rate","description":"Annual cost of borrowing"},{"name":"Dividends","description":"Share of profit paid to shareholders"}],"when_to_use":"When deciding how to finance a business or investment.","common_traps":["Not considering the cost of each financing method","Forgetting that debt requires collateral","Confusing short-term and long-term finance"],"units_note":"Debt interest is tax-deductible; dividends are not."}},{"id":"fin_practice_01","type":"worked_example","order":5,"content":{"scenario":"A business needs ₦2,000,000. It can borrow at 15% interest or sell 40% ownership to an investor. The business expects ₦500,000 profit. Which option is better?","given":["Capital needed: ₦2,000,000","Bank loan: 15% interest","Investor: 40% ownership","Expected profit: ₦500,000"],"required":"Compare the two financing options","principle":"Calculate the cost of each option.","steps":[{"explanation":"Bank loan cost","calculation":"₦2,000,000 × 15% = ₦300,000 interest per year"},{"explanation":"Investor cost","calculation":"₦500,000 × 40% = ₦200,000 share of profit"},{"explanation":"Compare","calculation":"Bank: ₦300,000 (must pay regardless of profit). Investor: ₦200,000 (only if profitable), but gives up 40% ownership permanently."}],"answer":"Bank loan costs ₦300,000/year. Investor costs ₦200,000/year but dilutes ownership. Bank loan is simpler if business can afford payments.","check":"The investor option is cheaper but you lose 40% of future profits."}},{"id":"fin_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Debt financing is always better than equity.","why_wrong":"Debt must be repaid with interest regardless of profit. Equity doesn''t require repayment but dilutes ownership. The best choice depends on the business situation.","correct_model":"Neither is always better. Debt = cheaper but riskier (must repay). Equity = safer but more expensive long-term (sharing profits)."}},{"id":"fin_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests sources of finance, advantages/disadvantages of debt vs equity.","trap":"JAMB may ask about specific Nigerian financing: Bank of Industry loans, SMEDAN, CBN intervention funds.","tip":"Know the advantages and disadvantages of each financing method. Practice comparing options.","related_topics":["Banking","Investment","Business planning"]}},{"id":"fin_memory_01","type":"memory_hook","order":8,"content":{"text":"Debt = borrow (must repay with interest). Equity = sell ownership (share profits). Short-term: overdraft, trade credit. Long-term: loans, shares, retained profits.","hook_type":"mnemonic"}},{"id":"fin_reflection_01","type":"reflection","order":9,"content":{"question":"A friend asks you to invest in their business. What factors would you consider before deciding?","expected_understanding":"Profitability, risk, expected return, ownership share, exit strategy, and trust in the friend''s ability to run the business."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Raising money by selling shares is called:","options":[{"label":"A","text":"Debt financing"},{"label":"B","text":"Equity financing"},{"label":"C","text":"Trade credit"},{"label":"D","text":"Overdraft"}],"answer":"B","explanation":"Selling shares = equity financing. You''re selling ownership in the business.","hints":["Shares represent ownership"]},{"difficulty":"medium","question":"An advantage of debt financing over equity is:","options":[{"label":"A","text":"No need to repay"},{"label":"B","text":"The owner retains full ownership"},{"label":"C","text":"Interest is not tax-deductible"},{"label":"D","text":"There is no risk"}],"answer":"B","explanation":"With debt, you don''t give up ownership. With equity, you share ownership with shareholders.","hints":["What does the owner keep with debt?"]},{"difficulty":"jamb","question":"A bank overdraft is a source of:","options":[{"label":"A","text":"Long-term finance"},{"label":"B","text":"Short-term finance"},{"label":"C","text":"Equity finance"},{"label":"D","text":"Government grants"}],"answer":"B","explanation":"An overdraft is a short-term facility allowing you to withdraw more than your balance.","hints":["How long does an overdraft last?"]}]'::jsonb, '{"min_score":80,"required_sections":["fin_hook_01","fin_intuitive_01","fin_formal_01","fin_formula_01","fin_practice_01"]}'::jsonb, '1')
