INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('commerce', 'Marketing', 'The 4 Ps of Marketing', 'Marketing — Getting the Right Product to the Right People', '["Define marketing and its importance","Explain the marketing mix (4 Ps)","Distinguish between marketing and selling","Understand market research and its methods"]'::jsonb, 'medium', '20', '[{"id":"mkt_hook_01","type":"hook","order":1,"content":{"text":"Why do you prefer Coke to Pepsi, or iPhone to Samsung? Is it the taste, the price, the adverts, or the brand image? That''s marketing at work. Marketing isn''t just advertising — it''s everything that makes a product desirable, from design to price to distribution.","prediction_prompt":"What makes you choose one brand over another, even when they''re similar?"}},{"id":"mkt_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Marketing = identifying customer needs and satisfying them profitably. The 4 Ps: Product (what you sell), Price (how much you charge), Place (where customers buy it), Promotion (how you inform and persuade). Marketing starts before the product is made — it identifies what people want.","analogy":"Think of marketing like planning a party. You need the right food (product), at the right price, in the right location, and you need to invite people and make them excited to come (promotion). If any element is wrong, the party fails."}},{"id":"mkt_formal_01","type":"formal_explanation","order":3,"content":{"text":"Marketing mix (4 Ps): (1) Product — design, quality, features, packaging, branding. (2) Price — pricing strategies (penetration, skimming, competitive). (3) Place — distribution channels (direct, wholesale, retail, online). (4) Promotion — advertising, sales promotion, personal selling, public relations. Market research: gathering information about customers, competitors, and market trends.","key_terms":[{"term":"Marketing","definition":"The process of identifying, anticipating, and satisfying customer needs profitably"},{"term":"Marketing Mix","definition":"The 4 Ps: Product, Price, Place, Promotion"},{"term":"Market Research","definition":"Systematic collection and analysis of data about a market"},{"term":"Target Market","definition":"The specific group of customers a business aims to serve"}]}},{"id":"mkt_formula_01","type":"formula","order":4,"content":{"formula":"Marketing = Product + Price + Place + Promotion. Revenue = Price × Quantity Sold. Marketing ROI = (Revenue from Marketing − Marketing Cost) / Marketing Cost × 100","variables":[{"name":"Product","description":"What you sell — must meet customer needs"},{"name":"Price","description":"Must be acceptable to customers and profitable for the business"},{"name":"Place","description":"Where and how customers access the product"},{"name":"Promotion","description":"How you communicate with and persuade customers"}],"when_to_use":"When developing a marketing strategy or evaluating a product launch.","common_traps":["Confusing marketing with advertising — marketing is broader","Setting price without considering costs and competition","Ignoring the ''Place'' element — distribution matters"],"units_note":"Marketing budgets typically range from 5-15% of revenue, depending on industry."}},{"id":"mkt_practice_01","type":"worked_example","order":5,"content":{"scenario":"A company is launching a new energy drink in Nigeria. Apply the 4 Ps to develop a marketing strategy.","given":["Product: energy drink","Target: young adults aged 18-35"],"required":"Apply the marketing mix","principle":"Each P must be designed to meet the target market''s needs.","steps":[{"explanation":"Product","calculation":"Tropical flavours (zobo, ginger), energy-boosting, attractive can design, 500ml size"},{"explanation":"Price","calculation":"₦300-₦500 (competitive with existing brands, affordable for students)"},{"explanation":"Place","calculation":"Universaries, gyms, filling stations, supermarkets, online delivery"},{"explanation":"Promotion","calculation":"Social media influencers, campus events, sponsorship of football matches, radio jingles"}],"answer":"Product: locally-flavoured energy drink. Price: ₦300-₦500. Place: universities, gyms, online. Promotion: influencers, campus events, radio.","check":"All 4 Ps align with the target market of young adults."}},{"id":"mkt_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Marketing is the same as advertising.","why_wrong":"Advertising is just one part of promotion, which is just one part of the marketing mix. Marketing includes product design, pricing, distribution, AND promotion.","correct_model":"Marketing = Product + Price + Place + Promotion. Advertising is a subset of Promotion."}},{"id":"mkt_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the 4 Ps, market research methods, and marketing strategies.","trap":"JAMB may give a scenario and ask you to apply the marketing mix. Be specific — use Nigerian examples.","tip":"For essay questions, always apply the 4 Ps to the specific product/service. Don''t just define them.","related_topics":["Consumer behaviour","Branding","Distribution channels"]}},{"id":"mkt_memory_01","type":"memory_hook","order":8,"content":{"text":"Marketing Mix = 4 Ps: Product (what), Price (how much), Place (where), Promotion (how to tell). Marketing ≠ advertising — it''s everything from design to distribution.","hook_type":"mnemonic"}},{"id":"mkt_reflection_01","type":"reflection","order":9,"content":{"question":"Why is market research important before launching a new product?","expected_understanding":"It helps understand customer needs, identify competitors, set the right price, and choose the best distribution channels. Without research, you risk launching a product nobody wants."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The marketing mix consists of:","options":[{"label":"A","text":"Product, Price, Place, Promotion"},{"label":"B","text":"People, Process, Physical evidence"},{"label":"C","text":"Sales, Advertising, PR"},{"label":"D","text":"Production, Distribution, Consumption"}],"answer":"A","explanation":"The 4 Ps are Product, Price, Place, and Promotion.","hints":["The classic marketing framework"]},{"difficulty":"medium","question":"Penetration pricing means:","options":[{"label":"A","text":"Setting a high initial price"},{"label":"B","text":"Setting a low price to enter the market"},{"label":"C","text":"Setting price based on costs"},{"label":"D","text":"Matching competitors'' prices"}],"answer":"B","explanation":"Penetration pricing = low initial price to attract customers and gain market share quickly.","hints":["How do you ''penetrate'' a new market?"]},{"difficulty":"jamb","question":"Market research is important because it helps a business:","options":[{"label":"A","text":"Avoid paying taxes"},{"label":"B","text":"Understand customer needs and make better decisions"},{"label":"C","text":"Reduce production costs"},{"label":"D","text":"Increase the number of employees"}],"answer":"B","explanation":"Market research provides information about customers, competitors, and trends to guide business decisions.","hints":["What does research help you know?"]}]'::jsonb, '{"min_score":80,"required_sections":["mkt_hook_01","mkt_intuitive_01","mkt_formal_01","mkt_formula_01","mkt_practice_01"]}'::jsonb, '1')
