INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('commerce', 'Insurance', 'Principles and Types', 'Insurance — Spreading the Risk', '["Define insurance and its purpose","Explain the principles of insurance","Identify types of insurance","Calculate basic insurance premiums"]'::jsonb, 'medium', '20', '[{"id":"ins_hook_01","type":"hook","order":1,"content":{"text":"Your phone worth ₦200,000 falls and cracks the screen. Repair costs ₦50,000. If you had phone insurance for ₦5,000/year, the insurance company would pay the repair. Insurance is paying a small amount regularly to protect against a large unexpected loss.","prediction_prompt":"Would you pay ₦5,000 per year to protect your ₦200,000 phone? Why or why not?"}},{"id":"ins_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Insurance is a contract where one party (insurer) promises to compensate another party (insured) for a specified loss, in exchange for a premium. The principle: many people pay small premiums into a pool. When one person suffers a loss, they''re compensated from the pool. This spreads the risk.","analogy":"Think of insurance like an umbrella shared by many people on a rainy day. Everyone contributes a little to buy the umbrella. When it rains, anyone under the umbrella is protected. If it doesn''t rain, you''ve lost your small contribution — but you''re safe."}},{"id":"ins_formal_01","type":"formal_explanation","order":3,"content":{"text":"Principles of insurance: (1) Utmost good faith — both parties must be honest. (2) Insurable interest — you must suffer financially from the loss. (3) Indemnity — compensation restores you to your pre-loss position (no profit). (4) Proximate cause — the nearest cause of loss must be covered. (5) Contribution — if multiple policies, each pays its share.","key_terms":[{"term":"Premium","definition":"The amount paid by the insured to the insurer for coverage"},{"term":"Indemnity","definition":"Compensation that restores the insured to their pre-loss position"},{"term":"Policy","definition":"The insurance contract"},{"term":"Claim","definition":"A request for compensation when a loss occurs"},{"term":"Underwriting","definition":"The process of evaluating risk and setting premium rates"}]}},{"id":"ins_formula_01","type":"formula","order":4,"content":{"formula":"Premium = Sum Insured × Rate. Claim Settlement = Loss Amount (up to sum insured)","variables":[{"name":"Sum Insured","description":"Maximum amount the insurer will pay"},{"name":"Premium Rate","description":"Percentage of sum insured charged as premium"},{"name":"Deductible","description":"Amount the insured must pay before the insurer pays"}],"when_to_use":"When calculating insurance costs or understanding claim settlements.","common_traps":["Expecting to profit from insurance — indemnity means no profit","Not reading the policy exclusions","Underinsuring to save on premiums — you''ll be undercompensated"],"units_note":"Premium is usually paid monthly, quarterly, or annually."}},{"id":"ins_practice_01","type":"worked_example","order":5,"content":{"scenario":"A shop owner insures goods worth ₦1,000,000 at a premium rate of 2%. Halfway through the year, goods worth ₦200,000 are destroyed by fire. How much will the insurance company pay?","given":["Sum insured: ₦1,000,000","Premium rate: 2%","Loss: ₦200,000"],"required":"Calculate premium and claim amount","principle":"Premium = Sum Insured × Rate. Claim = Loss amount (up to sum insured).","steps":[{"explanation":"Calculate premium","calculation":"₦1,000,000 × 2% = ₦20,000 per year"},{"explanation":"Calculate claim","calculation":"₦200,000 loss — insurer pays ₦200,000 (up to sum insured)"}],"answer":"Premium: ₦20,000/year. Claim: ₦200,000 paid by insurer.","check":"The claim (₦200,000) is within the sum insured (₦1,000,000), so the full loss is covered."}},{"id":"ins_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Insurance is a savings account — you get back what you pay.","why_wrong":"Insurance is not savings. If you don''t suffer a loss, you don''t get your premiums back. You''re paying for protection, not saving money.","correct_model":"Insurance = protection against loss, not a savings plan. You pay premiums for peace of mind. If no loss, you''ve paid for nothing — but you were protected."}},{"id":"ins_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests principles of insurance, types of insurance, and premium calculations.","trap":"JAMB may ask about utmost good faith, insurable interest, or indemnity. Know all the principles.","tip":"For calculations: Premium = Sum Insured × Rate. For essay questions: explain principles with examples.","related_topics":["Risk management","Banking","Investment"]}},{"id":"ins_memory_01","type":"memory_hook","order":8,"content":{"text":"Insurance = spread risk. Principles: good faith, insurable interest, indemnity, proximate cause, contribution. Premium = Sum Insured × Rate. No profit from insurance.","hook_type":"mnemonic"}},{"id":"ins_reflection_01","type":"reflection","order":9,"content":{"question":"Why do many Nigerians not buy insurance?","expected_understanding":"Lack of trust, low awareness, religious/cultural beliefs (''it won''t happen to me''), cost, and poor claim settlement history by insurance companies."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The amount paid by the insured to the insurer is called:","options":[{"label":"A","text":"Claim"},{"label":"B","text":"Premium"},{"label":"C","text":"Sum insured"},{"label":"D","text":"Deductible"}],"answer":"B","explanation":"The premium is the regular payment made by the insured for insurance coverage.","hints":["What do you pay to keep insurance active?"]},{"difficulty":"medium","question":"The principle of indemnity means:","options":[{"label":"A","text":"The insured profits from a claim"},{"label":"B","text":"The insured is restored to pre-loss position"},{"label":"C","text":"The insurer pays regardless of loss"},{"label":"D","text":"Premiums are refunded"}],"answer":"B","explanation":"Indemnity means compensation restores you to your pre-loss position — you don''t profit from insurance.","hints":["What does ''restore to pre-loss'' mean?"]},{"difficulty":"jamb","question":"A person has insurable interest in a property if:","options":[{"label":"A","text":"They own it"},{"label":"B","text":"They would suffer financially from its loss"},{"label":"C","text":"They live near it"},{"label":"D","text":"They admire it"}],"answer":"B","explanation":"Insurable interest means you must suffer a financial loss if the property is damaged or destroyed.","hints":["What must you lose for insurance to pay?"]}]'::jsonb, '{"min_score":80,"required_sections":["ins_hook_01","ins_intuitive_01","ins_formal_01","ins_formula_01","ins_practice_01"]}'::jsonb, '1')
