INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('crs', 'The Creation Account', 'God''s Creation and Purpose', 'Creation — How Everything Began', '["Narrate the biblical account of creation in Genesis 1-2","Explain the purpose of creation and humanity''s role","Identify key themes in the creation narrative","Apply lessons from creation to environmental stewardship"]'::jsonb, 'medium', '20', '[{"id":"crs_hook_01","type":"hook","order":1,"content":{"text":"In the beginning, God created the heavens and the earth. The Bible opens with this powerful declaration. But creation is not just about how the world started — it''s about WHY it was made. The creation account reveals God''s power, purpose, and plan for humanity.","prediction_prompt":"Why do you think the Bible begins with creation? What does this tell us about God''s nature?"}},{"id":"crs_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Genesis 1-2 describes God creating the world in six days and resting on the seventh. Each day, God creates something: light, sky, land, plants, animals, and finally humans. The climax is humanity — created in God''s image, given dominion over all creation. This shows humans are special in God''s plan.","analogy":"Think of creation like an artist building a masterpiece. Day by day, God adds elements — the sky as a canvas, mountains as texture, animals as colour. The final touch is humanity — the viewer who appreciates and cares for the artwork."}},{"id":"crs_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key elements of the creation account: (1) God created everything from nothing (ex nihilo). (2) Creation was orderly and progressive (days 1-6). (3) Humanity was created in God''s image (imago Dei) — with reason, morality, and creativity. (4) Humanity was given dominion — responsibility to care for creation. (5) God declared creation ''very good'' (Genesis 1:31). (6) The Sabbath rest (Genesis 2:1-3) established a pattern of work and rest.","key_terms":[{"term":"Imago Dei","definition":"The image of God in humanity — reason, morality, creativity, relationship"},{"term":"Dominion","definition":"The God-given responsibility to care for and steward creation"},{"term":"Ex Nihilo","definition":"Creation from nothing — only God can create from nothing"},{"term":"Sabbath","definition":"The seventh day of rest, establishing a rhythm of work and worship"}]}},{"id":"crs_formula_01","type":"formula","order":4,"content":{"formula":"Creation Account: Days 1-6 (Creation) → Day 7 (Rest) → Humanity as Stewards","variables":[{"name":"Day 1","description":"Light and darkness (Day and Night)"},{"name":"Day 2","description":"Sky and waters (Firmament)"},{"name":"Day 3","description":"Land, seas, and plants"},{"name":"Day 4","description":"Sun, moon, and stars"},{"name":"Day 5","description":"Birds and sea creatures"},{"name":"Day 6","description":"Land animals and humanity"},{"name":"Day 7","description":"God rested — Sabbath"}],"when_to_use":"When asked about the order of creation, the purpose of humanity, or the significance of the Sabbath.","common_traps":["Confusing Genesis 1 and Genesis 2 — they tell the same story from different perspectives","Thinking ''dominion'' means exploitation — it means responsible stewardship","Forgetting that rest is part of God''s design — not laziness but renewal"],"units_note":"The ''days'' of creation are interpreted differently: literal 24-hour days, or long periods (day-age theory)."}},{"id":"crs_practice_01","type":"worked_example","order":5,"content":{"scenario":"A company wants to clear a forest to build a factory. How would the creation account inform a Christian perspective on this decision?","given":["An environmental decision with economic implications"],"required":"Apply biblical principles from the creation account","principle":"Humanity has dominion (stewardship) over creation, not exploitation.","steps":[{"explanation":"Identify the principle","calculation":"Genesis 2:15 — ''The LORD God took the man and put him in the Garden of Eden to work it and take care of it''"},{"explanation":"Apply to the situation","calculation":"Dominion means stewardship, not destruction. We are caretakers, not owners."},{"explanation":"Consider the balance","calculation":"Economic development vs environmental care — Christians should seek sustainable solutions"},{"explanation":"Practical application","calculation":"Can the factory be built without destroying the forest? Can reforestation offset the damage?"}],"answer":"A Christian perspective would emphasize responsible stewardship — balancing economic needs with environmental care. Complete destruction of the forest would violate the creation mandate.","check":"The creation account establishes humanity as caretakers, not destroyers, of God''s creation."}},{"id":"crs_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The Bible and science contradict each other on creation.","why_wrong":"Many Christians see science and the Bible as complementary — science explains ''how'' while the Bible explains ''why.'' They address different questions.","correct_model":"The creation account is primarily theological (revealing God''s nature and purpose), not scientific. It answers ''why'' more than ''how.''"}},{"id":"crs_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the creation narrative, key verses, themes, and practical applications.","trap":"JAMB may ask about specific verses (Genesis 1:26-28, Genesis 2:15). Know these passages and their significance.","tip":"For essay questions, structure: Introduction (context) → Account (what happened) → Themes (what it teaches) → Application (relevance today).","related_topics":["The Fall","Environmental stewardship","Human dignity"]}},{"id":"crs_memory_01","type":"memory_hook","order":8,"content":{"text":"Genesis 1: God created everything in 6 days, rested on 7th. Genesis 2: Humanity placed in Garden to tend it. Key verse: Genesis 1:26 — ''Let us make mankind in our image.'' Theme: God''s power, purpose, and plan.","hook_type":"mnemonic"}},{"id":"crs_reflection_01","type":"reflection","order":9,"content":{"question":"What does it mean to be created in the ''image of God''? How should this affect how we treat other people?","expected_understanding":"Being in God''s image means we have dignity, reason, morality, and the capacity for relationships. This is why every human life has value — regardless of race, gender, status, or ability."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"According to Genesis 1, God created humanity on which day?","options":[{"label":"A","text":"Fifth day"},{"label":"B","text":"Sixth day"},{"label":"C","text":"Seventh day"},{"label":"D","text":"Third day"}],"answer":"B","explanation":"God created land animals and humanity on the sixth day (Genesis 1:24-31).","hints":["The climax of creation"]},{"difficulty":"medium","question":"The phrase ''imago Dei'' refers to:","options":[{"label":"A","text":"God''s creation of the world"},{"label":"B","text":"Humanity being created in God''s image"},{"label":"C","text":"The Sabbath rest"},{"label":"D","text":"The fall of man"}],"answer":"B","explanation":"''Imago Dei'' (image of God) refers to humanity being created in God''s likeness — with reason, morality, and creativity.","hints":["Image of God = ?"]},{"difficulty":"jamb","question":"Genesis 2:15 states that God placed man in the garden ''to work it and take care of it.'' This establishes the principle of:","options":[{"label":"A","text":"Exploitation of nature"},{"label":"B","text":"Environmental stewardship"},{"label":"C","text":"Agricultural dominance"},{"label":"D","text":"Retirement from work"}],"answer":"B","explanation":"This verse establishes humanity''s role as caretakers (stewards) of God''s creation, not exploiters.","hints":["Work AND take care = ?"]}]'::jsonb, '{"min_score":80,"required_sections":["crs_hook_01","crs_intuitive_01","crs_formal_01","crs_formula_01","crs_practice_01"]}'::jsonb, '1')
