INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('crs', 'The Fall of Man', 'Sin and Its Consequences', 'The Fall — When Everything Changed', '["Narrate the Genesis 3 account of the fall","Explain the consequences of disobedience","Understand the concept of original sin","Apply lessons from the fall to moral decisions"]'::jsonb, 'medium', '20', '[{"id":"fall_hook_01","type":"hook","order":1,"content":{"text":"God gave Adam and Eve everything — a beautiful garden, delicious food, perfect fellowship. He gave them one rule: don''t eat from one tree. Just one. But they broke that one rule, and everything changed. Sin entered the world, and nothing has been the same since.","prediction_prompt":"Why do you think God gave a rule He knew would be broken? What does this tell us about free will?"}},{"id":"fall_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The serpent tempted Eve by questioning God''s word: ''Did God really say...?'' Eve saw the fruit was good for food, pleasing to the eye, and desirable for wisdom. She ate, and gave some to Adam. Their eyes were opened — they knew they were naked. They hid from God. The consequences were severe: pain, toil, separation from God, and death.","analogy":"Think of the fall like breaking a trust. A parent tells a child: ''Don''t touch the stove — it''s hot.'' The child touches it and gets burned. The child''s action doesn''t change the parent''s love, but it changes the relationship. The child now knows pain and loss of trust."}},{"id":"fall_formal_01","type":"formal_explanation","order":3,"content":{"text":"The Fall (Genesis 3): (1) The serpent''s temptation — questioning God''s word and character. (2) Eve''s disobedience — eating the forbidden fruit. (3) Adam''s disobedience — eating without resistance. (4) Consequences: shame (knew they were naked), hiding from God, blame (Adam blamed Eve, Eve blamed serpent). (5) God''s curses: pain in childbearing, toil for food, death. (6) The promise of redemption (Genesis 3:15) — the offspring of the woman will crush the serpent''s head.","key_terms":[{"term":"Original Sin","definition":"The inherited sinfulness of humanity, descended from Adam and Eve''s disobedience"},{"term":"The Fall","definition":"The event in Genesis 3 when Adam and Eve disobeyed God, bringing sin into the world"},{"term":"Redemption","definition":"God''s plan to rescue humanity from sin through Jesus Christ"},{"term":"Theological Significance","definition":"The Fall explains why the world is broken and why humanity needs a Savior"}]}},{"id":"fall_formula_01","type":"formula","order":4,"content":{"formula":"The Fall: Temptation → Disobedience → Shame → Hiding → Blame → Consequences → Promise of Redemption","variables":[{"name":"Temptation","description":"Serpent questions God''s word"},{"name":"Disobedience","description":"Adam and Eve eat the forbidden fruit"},{"name":"Shame","description":"They realize they are naked"},{"name":"Hiding","description":"They hide from God"},{"name":"Blame","description":"Each blames the other"},{"name":"Consequences","description":"Pain, toil, death, separation from God"},{"name":"Promise","description":"Genesis 3:15 — the offspring will crush the serpent"}],"when_to_use":"For analyzing the narrative flow and theological significance of the Fall.","common_traps":["Blaming Eve alone — Adam was equally responsible (he was with her)","Thinking the fruit was literally poisonous — the issue was disobedience, not the fruit itself","Missing the promise of redemption in Genesis 3:15"],"units_note":"The Fall is foundational to Christian theology — it explains the human condition and the need for salvation."}},{"id":"fall_practice_01","type":"worked_example","order":5,"content":{"scenario":"A friend says: ''If God is all-knowing, He knew Adam and Eve would sin. So why did He create them? Isn''t God responsible for sin?'' How would you respond?","given":["A theological question about God''s responsibility for sin"],"required":"Explain the relationship between free will and sin","principle":"God created humans with free will. Love requires choice. Without the possibility of disobedience, obedience has no meaning.","steps":[{"explanation":"Acknowledge the question","calculation":"It''s a genuine and important question"},{"explanation":"Explain free will","calculation":"God gave humans the ability to choose — including the choice to disobey"},{"explanation":"Explain love","calculation":"True love requires free choice. Robot obedience is not love."},{"explanation":"Address responsibility","calculation":"God created the possibility of sin but did not cause sin. Humans chose to disobey."}],"answer":"God created humans with free will because love requires choice. The possibility of disobedience is necessary for genuine obedience. Humans, not God, chose to sin.","check":"Genesis shows God gave a clear warning and humans freely chose to disobey."}},{"id":"fall_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Eve was solely responsible for the fall.","why_wrong":"The Bible says Adam was with her and also ate (Genesis 3:6). Both were equally responsible. Paul later attributes sin''s entry to Adam (Romans 5:12).","correct_model":"Both Adam and Eve were responsible. Adam''s failure was passive — he was present but didn''t resist."}},{"id":"fall_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the Genesis 3 narrative, consequences of the fall, and theological implications.","trap":"JAMB may ask about Genesis 3:15 as the ''protoevangelium'' (first gospel) — the promise of a redeemer. Don''t miss this!","tip":"Know the sequence: temptation → disobedience → shame → hiding → blame → consequences → promise. This is the narrative arc.","related_topics":["Original sin","Redemption","The nature of temptation"]}},{"id":"fall_memory_01","type":"memory_hook","order":8,"content":{"text":"Genesis 3: Serpent tempts, Eve eats, Adam eats, they hide, God curses, but promises redemption (3:15). The Fall explains why the world is broken. Original sin: we all inherit Adam''s sinfulness.","hook_type":"mnemonic"}},{"id":"fall_reflection_01","type":"reflection","order":9,"content":{"question":"What does Genesis 3:15 (''He will crush your head'') mean to Christians?","expected_understanding":"Christians see this as the first promise of a Savior — Jesus Christ would defeat Satan and redeem humanity. It''s called the ''protoevangelium'' (first gospel)."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What was the forbidden tree called?","options":[{"label":"A","text":"Tree of life"},{"label":"B","text":"Tree of knowledge of good and evil"},{"label":"C","text":"Tree of wisdom"},{"label":"D","text":"Tree of righteousness"}],"answer":"B","explanation":"The tree was the ''tree of the knowledge of good and evil'' (Genesis 2:17).","hints":["The tree that gave knowledge"]},{"difficulty":"medium","question":"Who tempted Eve in the garden?","options":[{"label":"A","text":"God"},{"label":"B","text":"Adam"},{"label":"C","text":"The serpent"},{"label":"D","text":"An angel"}],"answer":"C","explanation":"The serpent (identified with Satan in Christian theology) tempted Eve (Genesis 3:1-5).","hints":["The crafty creature in the garden"]},{"difficulty":"jamb","question":"Genesis 3:15 is significant because it contains:","options":[{"label":"A","text":"The first miracle"},{"label":"B","text":"The first promise of a Redeemer"},{"label":"C","text":"The Ten Commandments"},{"label":"D","text":"The Great Commission"}],"answer":"B","explanation":"Genesis 3:15 is the ''protoevangelium'' — the first gospel promise that the offspring of the woman would defeat Satan.","hints":["The first prophecy about a coming Savior"]}]'::jsonb, '{"min_score":80,"required_sections":["fall_hook_01","fall_intuitive_01","fall_formal_01","fall_formula_01","fall_practice_01"]}'::jsonb, '1')
