INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('crs', 'The Patriarchs', 'Abraham, Isaac, Jacob, Joseph', 'The Patriarchs — Faith Through the Generations', '["Narrate the call and faith of Abraham","Explain the Abrahamic covenant","Trace the stories of Isaac, Jacob, and Joseph","Identify themes of faith, obedience, and providence"]'::jsonb, 'medium', '22', '[{"id":"pat_hook_01","type":"hook","order":1,"content":{"text":"God told Abraham: ''Leave your country and go to a land I will show you.'' Abraham obeyed — without knowing where he was going. That''s faith. The patriarchs (Abraham, Isaac, Jacob, Joseph) are examples of faith through trials, failures, and God''s faithfulness.","prediction_prompt":"Would you leave everything familiar if God told you to? What would make you obey or disobey?"}},{"id":"pat_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The patriarchs are the founding fathers of Israel. Abraham was called by God to leave Ur and go to Canaan. God promised him descendants as numerous as the stars. Abraham waited decades for this promise. His grandson Jacob had 12 sons — the 12 tribes of Israel. Joseph, Jacob''s favourite son, was sold into slavery but rose to power in Egypt, saving his family from famine.","analogy":"Think of the patriarchs like a family saga. Each generation faces challenges: Abraham''s waiting, Jacob''s deception, Joseph''s suffering. But through it all, God''s plan unfolds. Like a river flowing to the sea, God''s purpose cannot be stopped."}},{"id":"pat_formal_01","type":"formal_explanation","order":3,"content":{"text":"Abraham: Called from Ur (Genesis 12). Covenant: descendants, land, blessing (Genesis 12:1-3). Tested: sacrifice of Isaac (Genesis 22). Isaac: Peaceful life, blessed Jacob over Esau. Jacob: Deceived Isaac, wrestled with God, renamed Israel. Had 12 sons. Joseph: Sold into slavery by brothers, interpreted dreams in Egypt, rose to power, saved family from famine, forgave his brothers.","key_terms":[{"term":"Covenant","definition":"A solemn agreement between God and humanity — God''s promises are unconditional"},{"term":"Faith","definition":"Trust and obedience to God even when the outcome is uncertain"},{"term":"Providence","definition":"God''s care and guidance over human events"},{"term":"Forgiveness","definition":"Joseph''s forgiveness of his brothers — a key theme of the Joseph narrative"}]}},{"id":"pat_formula_01","type":"formula","order":4,"content":{"formula":"Patriarchal Narrative: Call → Promise → Test → Faith → Fulfilment","variables":[{"name":"Abraham","description":"Called → Promised descendants → Tested (Isaac) → Faith rewarded"},{"name":"Isaac","description":"Born of promise → Blessed → Chose Jacob over Esau"},{"name":"Jacob","description":"Deceived → Wrestled with God → Renamed Israel → 12 sons"},{"name":"Joseph","description":"Sold into slavery → Rose to power → Saved family → Forgave"}],"when_to_use":"For tracing the narrative arc of the patriarchal stories.","common_traps":["Thinking the patriarchs were perfect — they all had flaws (Abraham lied, Jacob deceived)","Missing the covenant promises — they connect all the patriarchal stories","Forgetting Joseph''s forgiveness — the emotional climax of the narrative"],"units_note":"The patriarchal narratives span Genesis 12-50."}},{"id":"pat_practice_01","type":"worked_example","order":5,"content":{"scenario":"When Joseph''s brothers came to Egypt seeking food, Joseph recognized them but they didn''t recognize him. Why didn''t Joseph immediately reveal himself?","given":["The reunion scene in Genesis 42-45"],"required":"Explain Joseph''s motives and the themes revealed","principle":"Joseph was testing his brothers'' character — had they changed since selling him into slavery?","steps":[{"explanation":"Joseph''s position","calculation":"He was vizier of Egypt — powerful enough to punish his brothers"},{"explanation":"The test","calculation":"He accused them of being spies, kept Benjamin, demanded they bring Jacob"},{"explanation":"Purpose of the test","calculation":"He wanted to see if they had repented — would they abandon Benjamin like they abandoned him?"},{"explanation":"The reveal","calculation":"When Judah offered himself for Benjamin (Genesis 44:33), Joseph knew they had changed"}],"answer":"Joseph tested his brothers to see if they had changed. When Judah offered himself for Benjamin — showing self-sacrifice — Joseph knew they had repented and revealed himself.","check":"Joseph''s famous words: ''You intended to harm me, but God intended it for good'' (Genesis 50:20)."}},{"id":"pat_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The patriarchs were perfect examples of faith.","why_wrong":"Abraham lied about Sarah being his sister. Jacob deceived his father. Joseph''s brothers were jealous and violent. They were flawed people who God used despite their failures.","correct_model":"The patriarchs were ordinary people with extraordinary faith — and serious flaws. God works through imperfect people."}},{"id":"pat_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of key patriarchal events, covenants, and themes.","trap":"JAMB may ask about the Abrahamic covenant''s three promises: descendants, land, blessing. These are the backbone of the patriarchal narratives.","tip":"For each patriarch, know: the call/challenge, the response, the outcome. This gives you a framework for any question.","related_topics":["The Exodus","The Twelve Tribes","Covenant theology"]}},{"id":"pat_memory_01","type":"memory_hook","order":8,"content":{"text":"Abraham: called, covenant, faith. Isaac: peaceful, blessed Jacob. Jacob: deceived, wrestled, 12 sons. Joseph: slavery, power, forgiveness. Key verse: Genesis 50:20 — ''God meant it for good.''","hook_type":"mnemonic"}},{"id":"pat_reflection_01","type":"reflection","order":9,"content":{"question":"What does Joseph''s forgiveness of his brothers teach us about dealing with people who have wronged us?","expected_understanding":"Joseph chose forgiveness over revenge. He recognized God''s sovereignty in his suffering and chose to bless those who harmed him. This is a model for Christian forgiveness."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Who is considered the father of faith in Christianity?","options":[{"label":"A","text":"Isaac"},{"label":"B","text":"Jacob"},{"label":"C","text":"Abraham"},{"label":"D","text":"Joseph"}],"answer":"C","explanation":"Abraham is called the ''father of faith'' because of his extraordinary trust and obedience to God.","hints":["The one who left Ur and was promised descendants"]},{"difficulty":"medium","question":"Joseph was sold into slavery by his:","options":[{"label":"A","text":"Father"},{"label":"B","text":"Brothers"},{"label":"C","text":"Uncles"},{"label":"D","text":"Friends"}],"answer":"B","explanation":"Joseph''s brothers were jealous of him and sold him into slavery (Genesis 37:27-28).","hints":["They were jealous of his special coat and dreams"]},{"difficulty":"jamb","question":"The Abrahamic covenant includes all these promises EXCEPT:","options":[{"label":"A","text":"Descendants as numerous as the stars"},{"label":"B","text":"The land of Canaan"},{"label":"C","text":"That Abraham would never face trials"},{"label":"D","text":"All nations would be blessed through him"}],"answer":"C","explanation":"God promised descendants, land, and blessing — not a trial-free life. Abraham faced many tests.","hints":["Which promise is NOT in Genesis 12:1-3?"]}]'::jsonb, '{"min_score":80,"required_sections":["pat_hook_01","pat_intuitive_01","pat_formal_01","pat_formula_01","pat_practice_01"]}'::jsonb, '1')
