INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('crs', 'The Mosaic Law', 'Commandments and Civil Laws', 'The Law — God''s Rules for Living', '["Identify the Ten Commandments and their significance","Explain the ceremonial and civil laws","Understand the purpose of the law in Israel","Relate the law to Christian ethics today"]'::jsonb, 'medium', '22', '[{"id":"law_hook_01","type":"hook","order":1,"content":{"text":"After escaping Egypt, the Israelites needed rules for their new nation. God gave Moses the Ten Commandments on Mount Sinai — the foundation of Israel''s law and ethics. These commandments cover relationship with God (commandments 1-4) and relationship with people (commandments 5-10).","prediction_prompt":"Which of the Ten Commandments do you think is most important? Why?"}},{"id":"law_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The Mosaic Law has three parts: The Ten Commandments (moral law), ceremonial laws (worship and sacrifice), and civil laws (daily life in Israel). The moral law reflects God''s character and never changes. The ceremonial and civil laws were specific to ancient Israel. Jesus summarized the entire law in two commands: love God and love your neighbour.","analogy":"Think of the law like a country''s constitution. The constitution establishes core principles (like human rights) that don''t change. Specific laws (like traffic regulations) can be updated for new situations. The Ten Commandments are like the constitution; the ceremonial laws are like specific regulations."}},{"id":"law_formal_01","type":"formal_explanation","order":3,"content":{"text":"The Ten Commandments (Exodus 20): (1) No other gods. (2) No idols. (3) Don''t misuse God''s name. (4) Remember the Sabbath. (5) Honour parents. (6) Don''t murder. (7) Don''t commit adultery. (8) Don''t steal. (9) Don''t lie. (10) Don''t covet. The law revealed sin, guided behaviour, and pointed to Christ (Galatians 3:24 — the law as a ''tutor'' leading to Christ).","key_terms":[{"term":"Moral Law","definition":"The Ten Commandments — reflecting God''s eternal character"},{"term":"Ceremonial Law","definition":"Laws about worship, sacrifices, and festivals — fulfilled in Christ"},{"term":"Civil Law","definition":"Laws about daily life in ancient Israel — specific to that context"},{"term":"Summary of the Law","definition":"Jesus'' summary: Love God completely, love your neighbour as yourself (Matthew 22:37-40)"}]}},{"id":"law_formula_01","type":"formula","order":4,"content":{"formula":"The Law: Ten Commandments (moral) + Ceremonial Laws (worship) + Civil Laws (daily life)","variables":[{"name":"Commandments 1-4","description":"Relationship with God (no other gods, no idols, no misuse of name, Sabbath)"},{"name":"Commandments 5-10","description":"Relationship with people (honour parents, don''t murder/adulterate/steal/lie/covet)"},{"name":"Ceremonial","description":"Sacrifices, festivals, food laws — fulfilled in Christ"},{"name":"Civil","description":"Property, justice, community life — specific to Israel"}],"when_to_use":"When asked about the purpose and structure of the Mosaic Law.","common_traps":["Confusing the three types of law — moral (eternal), ceremonial (fulfilled), civil (historical)","Thinking Christians must follow all Old Testament laws — ceremonial laws are fulfilled in Christ","Missing Jesus'' summary of the law — love God, love neighbour"],"units_note":"Christians believe the moral law still applies; ceremonial laws are fulfilled; civil laws were specific to Israel."}},{"id":"law_practice_01","type":"worked_example","order":5,"content":{"scenario":"A student says: ''The Old Testament says ''an eye for an eye,'' but Jesus says ''turn the other cheek.'' Is Jesus contradicting the Old Testament?''","given":["A common confusion about law and grace"],"required":"Explain the relationship between Old Testament law and Jesus'' teaching","principle":"The ''eye for an eye'' law limited retaliation (don''t take more than you lost). Jesus calls for a higher standard — forgiveness.","steps":[{"explanation":"Context of the Old Testament law","calculation":"''Eye for eye'' (Exodus 21:24) limited punishment — you couldn''t take more than you lost"},{"explanation":"Jesus'' teaching","calculation":"''Turn the other cheek'' (Matthew 5:38-39) calls for forgiveness, not retaliation"},{"explanation":"Relationship","calculation":"Jesus fulfills the law — not by abolishing it, but by elevating it to a higher standard"},{"explanation":"Principle","calculation":"The law says ''don''t take revenge.'' Jesus says ''actively forgive.''"}],"answer":"Jesus is not contradicting the Old Testament but elevating it. The law limited retaliation; Jesus calls for radical forgiveness and love.","check":"Matthew 5:17 — ''I have not come to abolish the law but to fulfill it.''"}},{"id":"law_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Christians must follow all Old Testament laws.","why_wrong":"Ceremonial laws (sacrifices, food restrictions, festivals) were fulfilled in Christ and are no longer binding. Moral laws (Ten Commandments) still apply.","correct_model":"Ceremonial laws = fulfilled in Christ. Civil laws = specific to ancient Israel. Moral laws = eternal principles that still guide Christian life."}},{"id":"law_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the Ten Commandments, the purpose of the law, and its relationship to Christian ethics.","trap":"JAMB may ask about the ''greatest commandment'' — Matthew 22:37-38: ''Love the Lord your God with all your heart...'' This is Jesus'' summary of the entire law.","tip":"Know the two divisions of the Ten Commandments: duties to God (1-4) and duties to others (5-10).","related_topics":["Sermon on the Mount","New Testament ethics","Christian morality"]}},{"id":"law_memory_01","type":"memory_hook","order":8,"content":{"text":"Ten Commandments: 1-4 = love God. 5-10 = love people. Jesus'' summary: Love God + Love neighbour. The law = moral (eternal) + ceremonial (fulfilled) + civil (historical).","hook_type":"mnemonic"}},{"id":"law_reflection_01","type":"reflection","order":9,"content":{"question":"Why did God give the Israelites so many specific laws about daily life (food, clothing, property)?","expected_understanding":"These laws shaped Israel into a distinct holy community. They addressed health (food laws), justice (property laws), and worship (ceremonial laws). The laws created a society that reflected God''s character."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"How many commandments are in the Mosaic Law?","options":[{"label":"A","text":"5"},{"label":"B","text":"10"},{"label":"C","text":"12"},{"label":"D","text":"613"}],"answer":"B","explanation":"The Ten Commandments (Exodus 20:1-17) are the foundation of the Mosaic Law.","hints":["Ten Commandments"]},{"difficulty":"medium","question":"Jesus summarized the entire law as:","options":[{"label":"A","text":"Follow all 613 laws perfectly"},{"label":"B","text":"Love God and love your neighbour"},{"label":"C","text":"Obey the Ten Commandments only"},{"label":"D","text":"Worship God on the Sabbath"}],"answer":"B","explanation":"Jesus said the greatest commandments are to love God completely and love your neighbour as yourself (Matthew 22:37-40).","hints":["What did Jesus say is the greatest commandment?"]},{"difficulty":"jamb","question":"The ceremonial laws in the Old Testament include laws about:","options":[{"label":"A","text":"Property and inheritance"},{"label":"B","text":"Sacrifices, festivals, and worship"},{"label":"C","text":"Criminal punishment"},{"label":"D","text":"Marriage and divorce"}],"answer":"B","explanation":"Ceremonial laws dealt with worship, sacrifices, food restrictions, and religious festivals — all fulfilled in Christ.","hints":["Which type of law deals with worship?"]}]'::jsonb, '{"min_score":80,"required_sections":["law_hook_01","law_intuitive_01","law_formal_01","law_formula_01","law_practice_01"]}'::jsonb, '1')
