INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('crs', 'The Life and Teachings of Jesus', 'Parables and Miracles', 'Jesus — His Life, Teachings, and Miracles', '["Identify key events in Jesus'' ministry","Explain the meaning of major parables","Understand the significance of Jesus'' miracles","Apply Jesus'' teachings to daily life"]'::jsonb, 'medium', '22', '[{"id":"jesus_hook_01","type":"hook","order":1,"content":{"text":"Jesus was born in Bethlehem, worked as a carpenter, then began a 3-year ministry that changed the world. He healed the sick, taught thousands through parables, challenged religious leaders, and was eventually crucified. But His story doesn''t end there.","prediction_prompt":"Why do you think Jesus used parables (stories) to teach instead of just giving rules?"}},{"id":"jesus_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Jesus taught through parables — simple stories with deep meanings. The Parable of the Sower teaches about how people respond to God''s word. The Good Samaritan teaches about loving your neighbour. His miracles (turning water to wine, healing the blind, raising Lazarus) demonstrated His power over nature, sickness, and death — proving He was who He claimed to be.","analogy":"Jesus'' parables were like seed bombs — simple on the outside but containing powerful truth inside. The listeners had to think deeply to understand. His miracles were like signposts — pointing to His divine identity."}},{"id":"jesus_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key parables: (1) Sower — different responses to God''s word. (2) Good Samaritan — love your neighbour regardless of race. (3) Prodigal Son — God''s forgiveness for repentant sinners. (4) Talents — faithfulness with what God gives. Key miracles: (1) Water to wine (John 2) — power over nature. (2) Healing blind (John 9) — power over sickness. (3) Raising Lazarus (John 11) — power over death.","key_terms":[{"term":"Parable","definition":"An earthly story with a heavenly meaning — a teaching tool used by Jesus"},{"term":"Miracle","definition":"A supernatural act demonstrating Jesus'' divine power and compassion"},{"term":"Kingdom of God","definition":"Jesus'' central teaching — God''s reign in people''s hearts and lives"},{"term":"Discipleship","definition":"Following Jesus and applying His teachings in daily life"}]}},{"id":"jesus_formula_01","type":"formula","order":4,"content":{"formula":"Jesus'' Ministry: Teaching (parables) + Healing (miracles) + Challenging (religious leaders) → Crucifixion → Resurrection","variables":[{"name":"Teaching","description":"Parables, Sermon on the Mount, discourse on bread of life"},{"name":"Healing","description":"Blind, lepers, paralytics, raised the dead"},{"name":"Challenging","description":"Pharisees, Sadducees, money changers in temple"},{"name":"Crucifixion","description":"The cross — sacrifice for sin"},{"name":"Resurrection","description":"Victory over death — proof of divine identity"}],"when_to_use":"For tracing the narrative arc of Jesus'' earthly ministry.","common_traps":["Focusing only on Jesus'' miracles — His teaching was equally important","Missing the purpose of miracles — they demonstrated His identity, not just His power","Forgetting the resurrection — it''s the foundation of Christian faith"],"units_note":"The Gospels (Matthew, Mark, Luke, John) record Jesus'' life and teachings."}},{"id":"jesus_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain the Parable of the Good Samaritan (Luke 10:25-37). What is Jesus teaching?","given":["The parable of a man beaten by robbers, ignored by a priest and Levite, helped by a Samaritan"],"required":"Explain the meaning and application","principle":"Jesus is redefining ''neighbour'' — it''s anyone in need, regardless of race or religion.","steps":[{"explanation":"Identify the context","calculation":"A lawyer asked: ''Who is my neighbour?'' Jesus told this parable"},{"explanation":"Identify the characters","calculation":"Priest and Levite (religious leaders) ignored the victim. Samaritan (despised outsider) helped."},{"explanation":"Identify the teaching","calculation":"Your neighbour is anyone in need — even someone you despise"},{"explanation":"Apply the teaching","calculation":"Love requires action, not just words. Help those in need regardless of who they are."}],"answer":"The Good Samaritan teaches that ''neighbour'' means anyone in need. Love requires action — not just feeling compassion but helping practically, even those we might despise.","check":"Jesus'' command: ''Go and do likewise'' (Luke 10:37) — love in action."}},{"id":"jesus_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Jesus only taught about love and forgiveness — He never challenged anyone.","why_wrong":"Jesus was confrontational with religious hypocrisy. He called Pharisees ''whitewashed tombs'' (Matthew 23:27) and drove money changers from the temple (John 2:15).","correct_model":"Jesus was both compassionate and confrontational — loving sinners while challenging hypocrisy and injustice."}},{"id":"jesus_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of Jesus'' parables, miracles, and their meanings.","trap":"JAMB may ask about the ''kingdom of God'' — Jesus'' central teaching. It''s not about political power but about God''s rule in people''s hearts.","tip":"For parable questions, always identify: the story, the characters, the meaning, and the application. This structure works for any parable.","related_topics":["Sermon on the Mount","Passion narrative","Resurrection"]}},{"id":"jesus_memory_01","type":"memory_hook","order":8,"content":{"text":"Key parables: Sower (response to God''s word), Good Samaritan (love your neighbour), Prodigal Son (God''s forgiveness), Talents (faithfulness). Miracles: power over nature, sickness, death.","hook_type":"mnemonic"}},{"id":"jesus_reflection_01","type":"reflection","order":9,"content":{"question":"Why did Jesus'' teaching about loving your enemies shock His audience?","expected_understanding":"The Jews expected a political Messiah who would defeat their enemies. Jesus instead taught to love enemies — a radical reversal of expectations. This shows God''s kingdom is about hearts, not politics."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Parable of the Sower teaches about:","options":[{"label":"A","text":"Farming techniques"},{"label":"B","text":"How people respond to God''s word"},{"label":"C","text":"The importance of agriculture"},{"label":"D","text":"Environmental stewardship"}],"answer":"B","explanation":"The seed represents God''s word; the different soils represent different human responses to it.","hints":["What does the seed represent?"]},{"difficulty":"medium","question":"In the Parable of the Good Samaritan, the ''neighbour'' is:","options":[{"label":"A","text":"Only people of the same race"},{"label":"B","text":"Only religious people"},{"label":"C","text":"Anyone in need"},{"label":"D","text":"Only family members"}],"answer":"C","explanation":"Jesus taught that a neighbour is anyone in need — regardless of race, religion, or social status.","hints":["Who helped the beaten man?"]},{"difficulty":"jamb","question":"Jesus'' miracles demonstrate:","options":[{"label":"A","text":"That He was a good teacher only"},{"label":"B","text":"His divine power over nature, sickness, and death"},{"label":"C","text":"That He could do magic tricks"},{"label":"D","text":"That miracles are fake"}],"answer":"B","explanation":"Jesus'' miracles demonstrated His divine authority and power — confirming His identity as the Son of God.","hints":["What do miracles prove about Jesus?"]}]'::jsonb, '{"min_score":80,"required_sections":["jesus_hook_01","jesus_intuitive_01","jesus_formal_01","jesus_formula_01","jesus_practice_01"]}'::jsonb, '1')
