INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('economics', 'Introduction to Economics', 'Basic Concepts and Scope', 'Economics — The Science of Scarcity and Choice', '["Define economics and explain its scope","Distinguish between microeconomics and macroeconomics","Explain opportunity cost and its applications","Identify the factors of production and their rewards"]'::jsonb, 'beginner', '20', '[{"id":"econ_hook_01","type":"hook","order":1,"content":{"text":"You have ₦5000. You can buy data, food, or save it. You can''t have all three. That''s economics — the study of how people make choices when resources are limited. Every decision involves a trade-off. Understanding economics helps you make better decisions.","prediction_prompt":"If you have 2 hours to study and 3 subjects to prepare for, how do you decide? What do you sacrifice?"}},{"id":"econ_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Economics studies how people, businesses, and governments allocate scarce resources to satisfy unlimited wants. The core problem: unlimited wants, limited resources. This forces choices. Every choice has a cost — the next best alternative you gave up. That''s opportunity cost.","analogy":"Imagine a student with ₦1000 who can buy a textbook or go to the movies. If they buy the textbook, the opportunity cost is the movie experience. If they go to the movies, the opportunity cost is the knowledge from the textbook. Economics is about weighing these trade-offs."}},{"id":"econ_formal_01","type":"formal_explanation","order":3,"content":{"text":"Economics is the social science that studies how individuals and societies allocate scarce resources to satisfy unlimited wants. Two branches: Microeconomics (individual decisions — consumers, firms) and Macroeconomics (economy-wide phenomena — inflation, unemployment, GDP). Factors of production: Land (natural resources), Labour (human effort), Capital (machinery, tools), Entrepreneurship (organizing the other three).","key_terms":[{"term":"Opportunity Cost","definition":"The value of the next best alternative foregone when a choice is made"},{"term":"Microeconomics","definition":"Study of individual economic agents — consumers, firms, markets"},{"term":"Macroeconomics","definition":"Study of economy-wide phenomena — inflation, growth, unemployment"},{"term":"Factors of Production","definition":"Resources used in production: land, labour, capital, entrepreneurship"}]}},{"id":"econ_formula_01","type":"formula","order":4,"content":{"formula":"Opportunity Cost = Value of next best alternative foregone","variables":[{"name":"Land","description":"Natural resources — rent"},{"name":"Labour","description":"Human effort — wages"},{"name":"Capital","description":"Man-made tools — interest"},{"name":"Entrepreneurship","description":"Risk-taking and organization — profit"}],"when_to_use":"Use opportunity cost to evaluate any decision. Ask: ''What am I giving up?''","common_traps":["Confusing opportunity cost with money cost — opportunity cost is the value of the alternative, not the price","Forgetting that time is a resource with opportunity cost","Not considering all alternatives — only the NEXT BEST counts"],"units_note":"Opportunity cost is measured in terms of what is given up, not necessarily in money."}},{"id":"econ_practice_01","type":"worked_example","order":5,"content":{"scenario":"A farmer has ₦100,000. He can invest in farming (expected return ₦30,000) or open a shop (expected return ₦25,000). What is his opportunity cost if he chooses farming?","given":["Two investment options with different returns"],"required":"Calculate the opportunity cost","principle":"Opportunity cost = the value of the next best alternative given up.","steps":[{"explanation":"Identify the choice","calculation":"The farmer chooses farming (return: ₦30,000)"},{"explanation":"Identify the alternative","calculation":"The next best alternative is the shop (return: ₦25,000)"},{"explanation":"Calculate opportunity cost","calculation":"Opportunity cost = ₦25,000 (the shop''s return)"},{"explanation":"Note","calculation":"The opportunity cost is NOT ₦100,000 — it''s the value of what he gave up"}],"answer":"The opportunity cost is ₦25,000 — the return from the shop he didn''t invest in.","check":"He gains ₦30,000 from farming but gives up ₦25,000 from the shop. Net benefit of choosing farming: ₦5,000."}},{"id":"econ_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Economics is only about money.","why_wrong":"Economics is about ALL scarce resources — time, energy, materials, and money. A student deciding how to spend their time is doing economics.","correct_model":"Economics is about choices under scarcity. Money is one resource, but time, labour, and materials are also scarce."}},{"id":"econ_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests definitions, opportunity cost, factors of production, and the difference between micro and macroeconomics.","trap":"JAMB may ask about ''opportunity cost'' in real-world scenarios. Always identify: the choice made, the alternative given up, and the value of that alternative.","tip":"For definitions, be precise. JAMB marks based on key terms. Include: scarcity, choice, allocation, satisfaction of wants.","related_topics":["Demand and supply","Production possibilities","Economic systems"]}},{"id":"econ_memory_01","type":"memory_hook","order":8,"content":{"text":"Economics = Scarcity + Choice. Opportunity cost = what you give up. Factors: Land (rent), Labour (wages), Capital (interest), Entrepreneurship (profit). Micro = individual. Macro = economy-wide.","hook_type":"mnemonic"}},{"id":"econ_reflection_01","type":"reflection","order":9,"content":{"question":"Is there such a thing as a free lunch? Why or why not?","expected_understanding":"No. Even if someone gives you a free lunch, they bear the cost. The saying ''there''s no such thing as a free lunch'' reminds us that everything has a cost — even if you don''t pay for it, someone does, or something is given up."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The study of individual consumer and firm decisions is called:","options":[{"label":"A","text":"Macroeconomics"},{"label":"B","text":"Microeconomics"},{"label":"C","text":"Development economics"},{"label":"D","text":"Agricultural economics"}],"answer":"B","explanation":"Microeconomics studies individual agents — consumers, firms, and markets.","hints":["Micro = small scale"]},{"difficulty":"medium","question":"The opportunity cost of attending a 4-year university is:","options":[{"label":"A","text":"Tuition fees only"},{"label":"B","text":"The salary you could have earned working"},{"label":"C","text":"Tuition plus books"},{"label":"D","text":"The degree you receive"}],"answer":"B","explanation":"The opportunity cost is the next best alternative — the salary you could have earned instead of studying.","hints":["What do you give up by spending 4 years in school?"]},{"difficulty":"jamb","question":"Which factor of production receives ''profit'' as its reward?","options":[{"label":"A","text":"Land"},{"label":"B","text":"Labour"},{"label":"C","text":"Capital"},{"label":"D","text":"Entrepreneurship"}],"answer":"D","explanation":"The entrepreneur organizes production and bears risk — profit is the reward for this.","hints":["Who organizes the other factors and takes risks?"]}]'::jsonb, '{"min_score":80,"required_sections":["econ_hook_01","econ_intuitive_01","econ_formal_01","econ_formula_01","econ_practice_01"]}'::jsonb, '1')
