INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('economics', 'Theory of Demand and Supply', 'Price Determination', 'Demand and Supply — How Prices Are Born', '["State the law of demand and supply","Explain factors affecting demand and supply","Analyze market equilibrium and price determination","Calculate and interpret elasticity of demand"]'::jsonb, 'medium', '22', '[{"id":"ds_hook_01","type":"hook","order":1,"content":{"text":"Why is garri cheap during harvest season but expensive during the rainy season? Why do exam materials cost more close to the exam date? The answer is demand and supply — the most powerful forces in economics. When many people want something (high demand) and there''s little of it (low supply), the price goes up.","prediction_prompt":"What happens to the price of umbrellas when it starts raining? Why?"}},{"id":"ds_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Demand is how much of a product people are willing and able to buy at a given price. Supply is how much producers are willing to sell at a given price. When demand exceeds supply, prices rise. When supply exceeds demand, prices fall. Equilibrium is where demand equals supply — the price ''settles'' there.","analogy":"Think of demand and supply like a tug-of-war. Buyers pull prices down (they want cheap goods). Sellers pull prices up (they want profit). The equilibrium price is where neither side is winning — the rope stays in the middle."}},{"id":"ds_formal_01","type":"formal_explanation","order":3,"content":{"text":"Law of Demand: as price increases, quantity demanded decreases (and vice versa), ceteris paribus. Law of Supply: as price increases, quantity supplied increases (and vice versa). Market equilibrium: where demand curve intersects supply curve. Price floor: minimum price (above equilibrium). Price ceiling: maximum price (below equilibrium).","key_terms":[{"term":"Demand","definition":"Quantity of a good consumers are willing and able to buy at various prices"},{"term":"Supply","definition":"Quantity of a good producers are willing and able to sell at various prices"},{"term":"Equilibrium","definition":"Where demand equals supply — the market-clearing price"},{"term":"Price Elasticity","definition":"Responsiveness of quantity demanded to a change in price"}]}},{"id":"ds_formula_01","type":"formula","order":4,"content":{"formula":"PED = % Change in Quantity Demanded / % Change in Price","variables":[{"name":"PED","description":"Price Elasticity of Demand"},{"name":"|PED| > 1","description":"Elastic — quantity changes more than price"},{"name":"|PED| < 1","description":"Inelastic — quantity changes less than price"},{"name":"|PED| = 1","description":"Unit elastic — proportional change"}],"when_to_use":"When analyzing how sensitive consumers are to price changes. Essential for business pricing and government taxation.","common_traps":["Confusing demand with quantity demanded — demand is the whole curve, quantity demanded is a point","Forgetting ceteris paribus — all other factors must remain constant","Not knowing that PED is usually negative (price up, demand down)"],"units_note":"Elasticity has no units — it''s a ratio of percentages."}},{"id":"ds_practice_01","type":"worked_example","order":5,"content":{"scenario":"The price of rice increases from ₦500 to ₦600 per bag. Quantity demanded falls from 1000 bags to 800 bags. Calculate the price elasticity of demand.","given":["Price change: ₦500 to ₦600","Quantity change: 1000 to 800"],"required":"Calculate PED","principle":"PED = % change in Qd / % change in P","steps":[{"explanation":"Calculate % change in quantity","calculation":"ΔQ = (800−1000)/1000 × 100 = −20%"},{"explanation":"Calculate % change in price","calculation":"ΔP = (600−500)/500 × 100 = +20%"},{"explanation":"Calculate PED","calculation":"PED = −20%/20% = −1"},{"explanation":"Interpret","calculation":"|PED| = 1, so demand is unit elastic"}],"answer":"PED = −1 (unit elastic). A 20% price increase caused a 20% decrease in quantity demanded.","check":"Unit elastic means the percentage change in quantity equals the percentage change in price."}},{"id":"ds_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"If demand increases, price always increases.","why_wrong":"Only if supply stays constant. If supply also increases, the price may stay the same or even fall.","correct_model":"Price depends on BOTH demand AND supply. An increase in demand raises price only if supply is constant."}},{"id":"ds_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests demand/supply curves, equilibrium, elasticity calculations, and effects of price controls.","trap":"JAMB may ask about the effect of a price ceiling or price floor. Price ceiling below equilibrium creates shortage. Price floor above equilibrium creates surplus.","tip":"For elasticity: remember PED is usually negative. When JAMB asks ''is demand elastic or inelastic,'' look at the absolute value.","related_topics":["Market structures","Government intervention","Taxation"]}},{"id":"ds_memory_01","type":"memory_hook","order":8,"content":{"text":"Law of Demand: Price up, quantity down. Law of Supply: Price up, quantity up. Equilibrium: demand = supply. PED > 1 = elastic. PED < 1 = inelastic.","hook_type":"mnemonic"}},{"id":"ds_reflection_01","type":"reflection","order":9,"content":{"question":"Why does the government sometimes set maximum prices for essential goods? Does this always work?","expected_understanding":"Price ceilings (maximum prices) make goods affordable for the poor. But if set below equilibrium, they create shortages — producers supply less because prices are too low. This can lead to black markets."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"According to the law of demand, as price increases:","options":[{"label":"A","text":"Quantity demanded increases"},{"label":"B","text":"Quantity demanded decreases"},{"label":"C","text":"Supply increases"},{"label":"D","text":"Supply decreases"}],"answer":"B","explanation":"The law of demand states that as price increases, quantity demanded decreases (inverse relationship).","hints":["Higher prices make people buy less"]},{"difficulty":"medium","question":"If PED = −2.5, demand is:","options":[{"label":"A","text":"Inelastic"},{"label":"B","text":"Elastic"},{"label":"C","text":"Unit elastic"},{"label":"D","text":"Perfectly inelastic"}],"answer":"B","explanation":"|PED| = 2.5 > 1, so demand is elastic — quantity responds strongly to price changes.","hints":["|PED| > 1 = elastic"]},{"difficulty":"jamb","question":"A price ceiling set below equilibrium will cause:","options":[{"label":"A","text":"Surplus"},{"label":"B","text":"Shortage"},{"label":"C","text":"Equilibrium"},{"label":"D","text":"No change"}],"answer":"B","explanation":"A price ceiling below equilibrium means demand exceeds supply — creating a shortage.","hints":["Below equilibrium, people want more than producers supply"]}]'::jsonb, '{"min_score":80,"required_sections":["ds_hook_01","ds_intuitive_01","ds_formal_01","ds_formula_01","ds_practice_01"]}'::jsonb, '1')
