INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('economics', 'Theory of Consumer Behaviour', 'Utility Analysis', 'Consumer Behaviour — Why We Buy What We Buy', '["Explain the concept of utility","State the law of diminishing marginal utility","Analyze consumer equilibrium","Understand indifference curve analysis"]'::jsonb, 'medium', '20', '[{"id":"util_hook_01","type":"hook","order":1,"content":{"text":"The first bottle of water on a hot day is heavenly. The second is nice. The third is okay. By the fifth, you don''t want any more. That''s diminishing marginal utility — the more you have of something, the less satisfaction you get from each additional unit. This explains why you don''t eat only rice every day.","prediction_prompt":"Why do you get bored of eating the same food every day? What economic principle explains this?"}},{"id":"util_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Utility is satisfaction from consuming a good or service. Total utility (TU) is the total satisfaction. Marginal utility (MU) is the extra satisfaction from one more unit. The law of diminishing marginal utility says each additional unit gives less satisfaction than the previous one. Consumers maximize satisfaction by allocating their budget where MU per naira is equal across all goods.","analogy":"Think of utility like a buffet. The first plate: everything tastes amazing (high MU). Second plate: still good but less exciting. Third plate: you''re getting full (low MU). Fourth plate: you feel sick (negative MU). You stop eating when satisfaction starts dropping."}},{"id":"util_formal_01","type":"formal_explanation","order":3,"content":{"text":"Total Utility (TU) = total satisfaction from consuming all units. Marginal Utility (MU) = ΔTU/ΔQ. Law of Diminishing MU: as consumption increases, marginal utility decreases. Consumer Equilibrium: MUₐ/Pₐ = MU_b/P_b = ... = MU_n/P_n. Indifference curves show combinations of goods giving equal satisfaction. Budget line shows affordable combinations.","key_terms":[{"term":"Utility","definition":"Satisfaction or pleasure from consuming a good or service"},{"term":"Marginal Utility","definition":"Additional satisfaction from consuming one more unit of a good"},{"term":"Consumer Equilibrium","definition":"The point where the consumer maximizes satisfaction given their budget"},{"term":"Indifference Curve","definition":"A curve showing combinations of two goods that give equal satisfaction"}]}},{"id":"util_formula_01","type":"formula","order":4,"content":{"formula":"Consumer Equilibrium: MUₐ/Pₐ = MU_b/P_b = ... = MU_n/P_n","variables":[{"name":"MUₐ","description":"Marginal utility of good A"},{"name":"Pₐ","description":"Price of good A"},{"name":"MU/P","description":"Marginal utility per naira spent"},{"name":"Rule","description":"Allocate budget so MU per naira is equal for all goods"}],"when_to_use":"When analyzing how consumers allocate their budget among different goods to maximize satisfaction.","common_traps":["Confusing total utility with marginal utility — TU can rise while MU falls","Forgetting that MU eventually becomes negative (too much of a good thing)","Not understanding that equilibrium means no incentive to change"],"units_note":"Utility is measured in ''utils'' (hypothetical units). In practice, we use ordinal ranking (1st, 2nd, 3rd preference)."}},{"id":"util_practice_01","type":"worked_example","order":5,"content":{"scenario":"A consumer has ₦20 to spend on goods X (₦4 each) and Y (₦2 each). The marginal utilities are: X: 24, 20, 16, 12. Y: 12, 10, 8, 6, 4, 2. How should the consumer spend the ₦20?","given":["Budget: ₦20, Price of X: ₦4, Price of Y: ₦2"],"required":"Find the utility-maximizing combination","principle":"Compare MU/P for each good. Allocate to the highest MU/P first.","steps":[{"explanation":"Calculate MU/P for X","calculation":"24/4=6, 20/4=5, 16/4=4, 12/4=3"},{"explanation":"Calculate MU/P for Y","calculation":"12/2=6, 10/2=5, 8/2=4, 6/2=3, 4/2=2, 2/2=1"},{"explanation":"Allocate to highest MU/P","calculation":"First naira: X (MU/P=6) or Y (MU/P=6). Buy both until equal."},{"explanation":"Find equilibrium","calculation":"Buy 2X (₦8) + 6Y (₦12) = ₦20. MU_X/P_X = 4, MU_Y/P_Y = 4. Equal!"}],"answer":"Buy 2 units of X and 6 units of Y. At this point, MUₓ/Pₓ = MUᵧ/Pᵧ = 4.","check":"Total spending: 2×₦4 + 6×₦2 = ₦8 + ₦12 = ₦20. ✓"}},{"id":"util_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"More consumption always means more satisfaction.","why_wrong":"Diminishing marginal utility means each additional unit gives less satisfaction. Eventually, more consumption reduces total satisfaction (MU becomes negative).","correct_model":"Satisfaction increases at a decreasing rate, then eventually decreases. There''s an optimal level of consumption."}},{"id":"util_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests utility maximization, consumer equilibrium, and indifference curve analysis.","trap":"JAMB may ask about the equi-marginal principle. Remember: MUₐ/Pₐ = MU_b/P_b — this is the condition for maximum satisfaction.","tip":"For indifference curve questions: higher curves = higher satisfaction. Budget line = what you can afford. Equilibrium = where budget line is tangent to highest possible indifference curve.","related_topics":["Demand curves","Price elasticity","Consumer surplus"]}},{"id":"util_memory_01","type":"memory_hook","order":8,"content":{"text":"Diminishing MU: more = less satisfaction per unit. Equilibrium: MU/Price equal for all goods. Higher indifference curve = more satisfaction. Budget line = what you can afford.","hook_type":"mnemonic"}},{"id":"util_reflection_01","type":"reflection","order":9,"content":{"question":"Why might a rich person still experience diminishing marginal utility?","expected_understanding":"Even with unlimited money, the human body and mind have limits. The 10th car gives less joy than the first. The 100th meal gives less satisfaction than the first. Diminishing utility is a human psychological reality, not just a financial one."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The law of diminishing marginal utility states that:","options":[{"label":"A","text":"Total utility always decreases"},{"label":"B","text":"Marginal utility decreases as consumption increases"},{"label":"C","text":"Price decreases as consumption increases"},{"label":"D","text":"Supply decreases as consumption increases"}],"answer":"B","explanation":"The law states that each additional unit consumed gives less additional satisfaction than the previous unit.","hints":["Each extra unit gives less satisfaction"]},{"difficulty":"medium","question":"Consumer equilibrium is reached when:","options":[{"label":"A","text":"Total utility is maximized"},{"label":"B","text":"Marginal utility is zero"},{"label":"C","text":"MU/P is equal for all goods"},{"label":"D","text":"Price equals marginal cost"}],"answer":"C","explanation":"Equilibrium: MUₐ/Pₐ = MU_b/P_b — marginal utility per naira is equal across all goods.","hints":["What condition must hold for maximum satisfaction?"]},{"difficulty":"jamb","question":"At the point of consumer saturation:","options":[{"label":"A","text":"TU is maximum and MU is zero"},{"label":"B","text":"TU is zero and MU is maximum"},{"label":"C","text":"Both TU and MU are zero"},{"label":"D","text":"Both TU and MU are maximum"}],"answer":"A","explanation":"Saturation: TU is maximum (no more satisfaction from more consumption), MU = 0 (additional unit adds nothing).","hints":["Saturation = you''ve had enough, no more satisfaction"]}]'::jsonb, '{"min_score":80,"required_sections":["util_hook_01","util_intuitive_01","util_formal_01","util_formula_01","util_practice_01"]}'::jsonb, '1')
