INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('economics', 'Theory of Production', 'Production and Costs', 'Production — How Goods Are Made', '["Explain the concept of production and production function","Understand the law of variable proportions","Distinguish between short-run and long-run costs","Analyze economies and diseconomies of scale"]'::jsonb, 'medium', '22', '[{"id":"prod_hook_01","type":"hook","order":1,"content":{"text":"A company with 10 workers produces 100 shoes per day. With 20 workers, they produce 220 shoes. With 30 workers, they produce 300 shoes. What happened? Why didn''t production triple when workers doubled? That''s the law of diminishing returns — adding more of one input eventually gives smaller increases in output.","prediction_prompt":"If you add more workers to a small kitchen, will food production always increase proportionally?"}},{"id":"prod_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Production is the process of converting inputs (raw materials, labour, capital) into outputs (goods and services). In the short run, at least one factor is fixed (like factory size). Adding more variable inputs (workers) to fixed inputs (factory) eventually leads to diminishing returns. In the long run, all factors are variable — you can build bigger factories.","analogy":"Think of a small kitchen. With 1 cook, production is slow. With 2 cooks, it doubles. With 3 cooks, it''s crowded — they bump into each other. With 10 cooks, production might actually decrease! The kitchen (fixed factor) is too small for that many cooks (variable factor)."}},{"id":"prod_formal_01","type":"formal_explanation","order":3,"content":{"text":"Production function: Q = f(L, K). Short run: at least one factor fixed. Long run: all factors variable. Law of Variable Proportions: as more units of a variable factor are added to fixed factors, marginal product eventually decreases. Stages: Increasing returns → Diminishing returns → Negative returns. Costs: Fixed (rent), Variable (materials), Total (FC + VC), Average (TC/Q), Marginal (ΔTC/ΔQ).","key_terms":[{"term":"Production Function","definition":"Relationship between inputs and maximum output"},{"term":"Marginal Product","definition":"Extra output from one more unit of variable input"},{"term":"Economies of Scale","definition":"Cost advantages from increasing scale of production"},{"term":"Diseconomies of Scale","definition":"Cost disadvantages from increasing scale too much"}]}},{"id":"prod_formula_01","type":"formula","order":4,"content":{"formula":"TC = FC + VC | AVC = VC/Q | ATC = TC/Q | MC = ΔTC/ΔQ","variables":[{"name":"TC","description":"Total Cost"},{"name":"FC","description":"Fixed Cost (doesn''t change with output)"},{"name":"VC","description":"Variable Cost (changes with output)"},{"name":"ATC","description":"Average Total Cost per unit"},{"name":"MC","description":"Marginal Cost — cost of producing one more unit"}],"when_to_use":"For analyzing production decisions: firms produce where MC = MR (marginal cost = marginal revenue).","common_traps":["Confusing fixed and variable costs — fixed costs don''t change with output","Forgetting that MC eventually rises — due to diminishing returns","Not understanding that economies of scale reduce ATC in the long run"],"units_note":"All cost figures are in naira. Output is in units."}},{"id":"prod_practice_01","type":"worked_example","order":5,"content":{"scenario":"A firm''s total cost is ₦5000 for 100 units and ₦5400 for 101 units. Calculate the marginal cost of the 101st unit.","given":["TC(100) = ₦5000, TC(101) = ₦5400"],"required":"Calculate MC","principle":"MC = ΔTC/ΔQ = change in total cost divided by change in quantity.","steps":[{"explanation":"Find change in total cost","calculation":"ΔTC = ₦5400 − ₦5000 = ₦400"},{"explanation":"Find change in quantity","calculation":"ΔQ = 101 − 100 = 1"},{"explanation":"Calculate MC","calculation":"MC = ₦400/1 = ₦400"},{"explanation":"Interpret","calculation":"The 101st unit costs ₦400 to produce"}],"answer":"The marginal cost of the 101st unit is ₦400.","check":"If the firm sells this unit for more than ₦400, it makes a profit on this unit."}},{"id":"prod_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Economies of scale always occur when a firm grows larger.","why_wrong":"Beyond a certain size, firms experience diseconomies of scale — coordination problems, bureaucracy, communication breakdowns increase costs.","correct_model":"Small firms may experience economies of scale (lower costs). Very large firms may experience diseconomies of scale (higher costs). There''s an optimal size."}},{"id":"prod_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests production concepts, cost calculations, and economies of scale.","trap":"JAMB may ask about the relationship between MC and ATC. MC crosses ATC at its minimum point.","tip":"For cost questions, draw a table: Q, FC, VC, TC, ATC, MC. Fill in what you know and calculate the rest.","related_topics":["Market structures","Profit maximization","Break-even analysis"]}},{"id":"prod_memory_01","type":"memory_hook","order":8,"content":{"text":"TC = FC + VC. MC = ΔTC/ΔQ. MC cuts ATC at minimum. Economies of scale: bigger = cheaper (up to a point). Diminishing returns: more input, less extra output.","hook_type":"mnemonic"}},{"id":"prod_reflection_01","type":"reflection","order":9,"content":{"question":"Why might a firm choose to produce at a loss in the short run rather than shut down?","expected_understanding":"If the firm covers its variable costs, it loses less by continuing to produce than by shutting down (where it still pays fixed costs). The firm only shuts down if price < average variable cost."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Total cost equals:","options":[{"label":"A","text":"Fixed cost + Variable cost"},{"label":"B","text":"Fixed cost − Variable cost"},{"label":"C","text":"Average cost × Quantity"},{"label":"D","text":"Both A and C"}],"answer":"D","explanation":"TC = FC + VC. Also, TC = ATC × Q. Both formulas give the same result.","hints":["TC can be calculated two ways"]},{"difficulty":"medium","question":"Economies of scale occur when:","options":[{"label":"A","text":"ATC increases as output increases"},{"label":"B","text":"ATC decreases as output increases"},{"label":"C","text":"MC exceeds ATC"},{"label":"D","text":"Fixed costs increase"}],"answer":"B","explanation":"Economies of scale: as output increases, average cost per unit decreases.","hints":["Scale up, costs down"]},{"difficulty":"jamb","question":"A firm should shut down in the short run if:","options":[{"label":"A","text":"It is making a loss"},{"label":"B","text":"Price is less than average variable cost"},{"label":"C","text":"Price is less than average total cost"},{"label":"D","text":"Marginal cost exceeds marginal revenue"}],"answer":"B","explanation":"If P < AVC, the firm can''t even cover variable costs — it loses more by producing than by shutting down.","hints":["What must a firm cover to stay open?"]}]'::jsonb, '{"min_score":80,"required_sections":["prod_hook_01","prod_intuitive_01","prod_formal_01","prod_formula_01","prod_practice_01"]}'::jsonb, '1')
