INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('economics', 'Market Structures', 'Perfect and Imperfect Competition', 'Market Structures — How Markets Are Organized', '["Explain the features of perfect competition","Analyze monopoly and its characteristics","Understand monopolistic competition and oligopoly","Compare different market structures"]'::jsonb, 'hard', '22', '[{"id":"mkt_hook_01","type":"hook","order":1,"content":{"text":"Why is there only one PHCN (electricity) in Nigeria but thousands of restaurants? Why are there 4 telecom companies but hundreds of phone accessory sellers? The answer lies in market structure — how many firms exist, how easy it is to enter the market, and how much control firms have over prices.","prediction_prompt":"What would happen if there was only one phone seller in Nigeria? How would prices compare to the current market?"}},{"id":"mkt_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Markets are organized by competition level. Perfect competition: many firms, identical products, no price control (like agricultural markets). Monopoly: one firm, unique product, total price control (like PHCN). Monopolistic competition: many firms, slightly different products, some price control (like restaurants). Oligopoly: few large firms, mutual interdependence (like telecoms).","analogy":"Think of market structures like a sports league. Perfect competition = local football — many teams, anyone can join, no one team dominates. Monopoly = one team controls the league. Oligopoly = 3-4 big teams dominate. Monopolistic = many teams, each with different styles."}},{"id":"mkt_formal_01","type":"formal_explanation","order":3,"content":{"text":"Perfect Competition: many firms, homogeneous product, free entry/exit, perfect information, price takers. Monopoly: single firm, unique product, blocked entry, price maker. Monopolistic Competition: many firms, differentiated products, free entry, some price control. Oligopoly: few firms, identical or differentiated, barriers to entry, mutual interdependence.","key_terms":[{"term":"Price Taker","definition":"A firm that cannot influence the market price — must accept the prevailing price"},{"term":"Price Maker","definition":"A firm that can set its own price due to market power"},{"term":"Barriers to Entry","definition":"Obstacles that prevent new firms from entering a market"},{"term":"Product Differentiation","definition":"Making products appear different from competitors (branding, quality)"}]}},{"id":"mkt_formula_01","type":"formula","order":4,"content":{"formula":"Profit Maximization: Produce where MC = MR. Profit = TR − TC = (P − ATC) × Q","variables":[{"name":"MC","description":"Marginal Cost"},{"name":"MR","description":"Marginal Revenue"},{"name":"P","description":"Price"},{"name":"ATC","description":"Average Total Cost"},{"name":"Q","description":"Quantity produced"}],"when_to_use":"For any market structure, firms maximize profit by producing where MC = MR.","common_traps":["Confusing revenue with profit — revenue is income, profit is revenue minus cost","Forgetting that in perfect competition, P = MR (price taker)","Not understanding that monopolies can set price but not quantity independently"],"units_note":"All monetary values in naira. Profit can be negative (loss)."}},{"id":"mkt_practice_01","type":"worked_example","order":5,"content":{"scenario":"Compare the long-run outcomes of perfect competition and monopoly in terms of price, output, and efficiency.","given":["Two market structures to compare"],"required":"Analyze differences in price, output, and efficiency","principle":"Perfect competition: P = MC (efficient). Monopoly: P > MC (inefficient).","steps":[{"explanation":"Perfect competition long run","calculation":"P = MC = minimum ATC. Zero economic profit. Allocatively and productively efficient."},{"explanation":"Monopoly long run","calculation":"P > MC > minimum ATC. Positive economic profit. Neither allocatively nor productively efficient."},{"explanation":"Output comparison","calculation":"Monopoly produces less output than perfect competition (restricts output to raise price)"},{"explanation":"Price comparison","calculation":"Monopoly charges higher price than perfect competition"}],"answer":"Perfect competition: lower price, higher output, efficient. Monopoly: higher price, lower output, inefficient. The monopoly''s market power leads to deadweight loss.","check":"This is why governments regulate monopolies — to protect consumers from high prices and low output."}},{"id":"mkt_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Monopolies are always bad for the economy.","why_wrong":"Natural monopolies (like utilities) can be more efficient than multiple competing firms. One pipe company serving a city is cheaper than five competing pipe companies laying parallel pipes.","correct_model":"Some monopolies are natural (high fixed costs make competition wasteful). The key is regulation — preventing abuse of monopoly power."}},{"id":"mkt_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests features of market structures, profit maximization, and efficiency comparisons.","trap":"JAMB may ask which market structure is ''most efficient.'' Perfect competition is the benchmark for efficiency, but it''s rare in reality.","tip":"For comparison questions, use a table: Feature | Perfect Competition | Monopoly | Monopolistic Competition | Oligopoly.","related_topics":["Price discrimination","Government regulation","Anti-trust policy"]}},{"id":"mkt_memory_01","type":"memory_hook","order":8,"content":{"text":"Perfect Competition: many firms, price taker, P=MC. Monopoly: one firm, price maker, P>MC. Monopolistic: many firms, differentiated products. Oligopoly: few firms, interdependent.","hook_type":"mnemonic"}},{"id":"mkt_reflection_01","type":"reflection","order":9,"content":{"question":"Why do telecom companies in Nigeria charge similar prices even though there are 4 competitors?","expected_understanding":"This is oligopolistic behavior — firms are interdependent. If one lowers prices, others follow (price war). So they maintain similar prices. This is called price leadership or tacit collusion."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A market with only one seller is called:","options":[{"label":"A","text":"Perfect competition"},{"label":"B","text":"Monopoly"},{"label":"C","text":"Oligopoly"},{"label":"D","text":"Monopolistic competition"}],"answer":"B","explanation":"A monopoly is a market structure with a single seller of a unique product.","hints":["Mono = one"]},{"difficulty":"medium","question":"In perfect competition, firms are:","options":[{"label":"A","text":"Price makers"},{"label":"B","text":"Price takers"},{"label":"C","text":"Price regulators"},{"label":"D","text":"Price leaders"}],"answer":"B","explanation":"In perfect competition, firms have no market power — they must accept the market price.","hints":["Many firms, identical products = no pricing power"]},{"difficulty":"jamb","question":"A monopolist maximizes profit by producing where:","options":[{"label":"A","text":"P = ATC"},{"label":"B","text":"MC = MR"},{"label":"C","text":"P = MC"},{"label":"D","text":"ATC = MR"}],"answer":"B","explanation":"All profit-maximizing firms produce where MC = MR, including monopolies.","hints":["This rule applies to ALL market structures"]}]'::jsonb, '{"min_score":80,"required_sections":["mkt_hook_01","mkt_intuitive_01","mkt_formal_01","mkt_formula_01","mkt_practice_01"]}'::jsonb, '1')
