INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('english', 'Reading comprehension passages', 'Comprehension and Summary', 'Reading Comprehension — How to Actually Understand What You Read', '["Apply active reading strategies to comprehension passages","Identify main ideas and supporting details in a text","Infer meaning from context clues","Answer comprehension questions accurately and efficiently"]'::jsonb, 'medium', '20', '[{"id":"comprehension_hook_01","type":"hook","order":1,"content":{"text":"JAMB gives you a passage and asks you to understand it — but most students read too fast. They skim without thinking, then panic when the questions ask about details they missed. The secret is reading with PURPOSE: know what you''re looking for before you start.","prediction_prompt":"Read this: ''The government''s new policy has been widely criticised, though some argue it represents a necessary departure from traditional approaches.'' What is the author''s attitude — positive, negative, or neutral?"}},{"id":"comprehension_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Reading comprehension is not just about understanding words — it''s about understanding what the AUTHOR means. Authors use specific words for a reason. When they say ''criticised'' instead of ''discussed,'' they''re telling you something. Active reading means questioning the text as you read.","analogy":"Think of reading comprehension like detective work. The passage is the crime scene. The questions are the case you need to solve. You don''t just glance around — you look for clues, connect evidence, and build a case. Every word is a potential clue."}},{"id":"comprehension_formal_01","type":"formal_explanation","order":3,"content":{"text":"JAMB comprehension passages test three levels: (1) Literal — what is directly stated. (2) Inferential — what can be deduced. (3) Critical — evaluating the author''s purpose, tone, and bias. Skimming gives you the general idea. Scanning finds specific details. Inferring goes beyond what is stated.","key_terms":[{"term":"Main idea","definition":"The central point or message of the passage. Usually in the topic sentence."},{"term":"Supporting details","definition":"Facts, examples, or evidence that support the main idea"},{"term":"Inference","definition":"A conclusion drawn from evidence in the text, not directly stated"},{"term":"Context clues","definition":"Surrounding words that help you understand an unfamiliar word''s meaning"},{"term":"Tone","definition":"The author''s attitude towards the subject (e.g., critical, supportive, neutral)"}]}},{"id":"comprehension_strategy_01","type":"formula","order":4,"content":{"formula":"Read the questions FIRST, Skim the passage, Scan for answers, Eliminate wrong options","variables":[{"name":"Step 1","description":"Read all questions before reading the passage","unit":""},{"name":"Step 2","description":"Skim the passage for main ideas (30 seconds)","unit":""},{"name":"Step 3","description":"Scan for specific answers to each question","unit":""},{"name":"Step 4","description":"Eliminate obviously wrong options, then choose the best answer","unit":""}],"when_to_use":"For every JAMB comprehension question. This strategy saves time and improves accuracy.","common_traps":["Reading the entire passage slowly before looking at questions — wastes time.","Choosing the first answer that seems right without checking the others.","Inferring too much — only use information actually supported by the text."],"units_note":"Time management: spend about 1 minute per question. 10 questions = 10 minutes for the passage."}},{"id":"comprehension_practice_01","type":"worked_example","order":5,"content":{"scenario":"Passage: ''The introduction of computer-based testing in Nigerian universities has generated considerable debate. Proponents argue that it eliminates manual marking errors and reduces examination malpractice. Critics point to the high cost of infrastructure and the digital divide between urban and rural institutions.'' Question: What is the main idea?","given":["A passage about computer-based testing in Nigerian universities"],"required":"Identify the main idea","principle":"The main idea is what the whole passage is about. Look at the first and last sentences for clues.","steps":[{"explanation":"Identify the topic","calculation":"The topic is computer-based testing in Nigerian universities"},{"explanation":"Look at what is said","calculation":"Both benefits and problems are discussed"},{"explanation":"Find the capturing sentence","calculation":"The passage presents both arguments for and against"}],"answer":"The main idea is that computer-based testing in Nigerian universities has both advantages and disadvantages, with a gap between benefits and available infrastructure.","check":"This captures both the debate and the evidence presented"}},{"id":"comprehension_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The answer to a comprehension question is always directly stated in the passage.","why_wrong":"Many JAMB questions require inference — you need to read between the lines. The answer may be implied but not stated directly.","correct_model":"Some questions test literal comprehension (directly stated), others test inference (implied), and others test critical thinking (evaluating). Be prepared for all three."}},{"id":"comprehension_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB comprehension tests include literal, inferential, and vocabulary-in-context questions. Passages are usually 200-400 words on social, political, or scientific topics.","trap":"JAMB often includes trap answers that use words from the passage but change the meaning. Always check that your answer matches what the passage actually says.","tip":"For vocabulary questions, look at the sentence BEFORE and AFTER the word to get context. Don''t just guess from the word alone.","related_topics":["Cloze passages","Summary writing","Vocabulary"]}},{"id":"comprehension_memory_01","type":"memory_hook","order":8,"content":{"text":"Questions FIRST, passage SECOND. Skim for main idea, scan for details. Eliminate wrong answers before choosing. When in doubt, re-read the relevant paragraph.","hook_type":"strategy"}},{"id":"comprehension_reflection_01","type":"reflection","order":9,"content":{"question":"Why is it important to read the questions before reading the passage?","expected_understanding":"Reading questions first tells you what to look for. Instead of reading passively, you read with purpose — scanning for specific information. This saves time and improves accuracy."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"In a comprehension passage, what is the ''main idea''?","options":[{"label":"A","text":"The first sentence of the passage"},{"label":"B","text":"The central point that the whole passage supports"},{"label":"C","text":"A detail mentioned in the middle"},{"label":"D","text":"The author''s name"}],"answer":"B","explanation":"The main idea is the central point or message of the entire passage.","hints":["The main idea is what everything in the passage is about"]},{"difficulty":"medium","question":"''The policy was widely condemned by experts, though the government remained defiant.'' What is the author''s tone?","options":[{"label":"A","text":"Fully supportive of the government"},{"label":"B","text":"Neutral — just reporting both sides"},{"label":"C","text":"Critical of the government"},{"label":"D","text":"Angry and emotional"}],"answer":"B","explanation":"The author reports both the condemnation and the government''s stance without expressing personal opinion.","hints":["Does the author take a side or just report?"]},{"difficulty":"jamb","question":"''The minister''s assurances did little to quell the growing unrest among workers, who had already endured three months of unpaid salaries.'' What can you infer about the workers?","options":[{"label":"A","text":"They are satisfied with the minister''s response"},{"label":"B","text":"They have been waiting for payment for a long time"},{"label":"C","text":"They are about to receive their salaries"},{"label":"D","text":"They support the government''s position"}],"answer":"B","explanation":"''Three months of unpaid salaries'' and ''growing unrest'' indicate the workers have been waiting a long time and are increasingly frustrated.","hints":["''Three months'' = a long time","''Growing unrest'' = getting worse"]}]'::jsonb, '{"min_score":80,"required_sections":["comprehension_hook_01","comprehension_intuitive_01","comprehension_formal_01","comprehension_strategy_01","comprehension_practice_01"]}'::jsonb, '1')
