INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('english', 'Cloze passages', 'Comprehension and Summary', 'Cloze Passages — Fill in the Blanks with Confidence', '["Use context clues to determine missing words in a passage","Apply grammar awareness to choose correct word forms","Recognise collocations and common word combinations","Complete cloze passages accurately under exam conditions"]'::jsonb, 'medium', '18', '[{"id":"cloze_hook_01","type":"hook","order":1,"content":{"text":"Fill-in-the-blank questions test your understanding of context. You''re not just looking for a word that sounds right — you need a word that fits the grammar, the meaning, AND the flow of the passage. The good news? The passage itself gives you all the clues you need.","prediction_prompt":"Complete this: ''The committee ____ (has/have) decided to postpone the meeting.'' Which is correct and why?"}},{"id":"cloze_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A cloze passage is a paragraph with words removed. Your job is to figure out what fits. Think of it like a jigsaw puzzle — the surrounding pieces tell you what shape and colour the missing piece should be.","analogy":"Imagine reading a recipe that says: ''Add two _____ of sugar.'' You''d know the missing word is probably ''cups'' or ''tablespoons'' — something that measures. The context tells you what kind of word fits."}},{"id":"cloze_formal_01","type":"formal_explanation","order":3,"content":{"text":"Cloze passages test three things: (1) Grammar — does the word fit grammatically? (2) Meaning — does the word make sense in context? (3) Collocation — does the word naturally go with its neighbours (e.g., ''make a decision'' not ''do a decision'')?","key_terms":[{"term":"Collocation","definition":"Words that naturally go together in English (e.g., strong coffee, heavy rain)"},{"term":"Context clue","definition":"Information from surrounding words that helps determine the missing word"},{"term":"Grammatical fit","definition":"The word must fit the grammar of the sentence"},{"term":"Semantic fit","definition":"The word must make logical sense in the passage"}]}},{"id":"cloze_strategy_01","type":"formula","order":4,"content":{"formula":"Read the full passage, Check grammar, Check meaning, Check collocations, Verify","variables":[{"name":"Step 1","description":"Read the whole passage first to understand context","unit":""},{"name":"Step 2","description":"For each blank, check what part of speech is needed","unit":""},{"name":"Step 3","description":"Check which option makes logical sense","unit":""},{"name":"Step 4","description":"Check which word naturally collocates with surrounding words","unit":""},{"name":"Step 5","description":"Read the completed passage to verify it flows","unit":""}],"when_to_use":"For every cloze passage question.","common_traps":["Choosing a word that sounds right but doesn''t fit grammatically.","Picking a word that fits one blank but creates a contradiction elsewhere.","Not reading the full passage before starting."],"units_note":"Time: about 3-4 minutes per cloze passage (5 blanks)."}},{"id":"cloze_practice_01","type":"worked_example","order":5,"content":{"scenario":"Complete: ''The new policy has been ___ by most stakeholders, though some ___ remain about its implementation.'' Options for blank 1: welcomed/welcome/welcoming/welcome. Options for blank 2: concern/concerns/concerned/concerning.","given":["A cloze passage with two blanks"],"required":"Choose the correct words for each blank","principle":"For Blank 1: past participle needed (has been + past participle). For Blank 2: noun needed (some + noun).","steps":[{"explanation":"Blank 1: grammar check","calculation":"''has been'' + past participle = welcomed"},{"explanation":"Blank 2: grammar check","calculation":"''some'' + noun = concerns (plural noun)"},{"explanation":"Read the full passage","calculation":"''The new policy has been welcomed by most stakeholders, though some concerns remain about its implementation.''"},{"explanation":"Check meaning","calculation":"Most people welcome it, but some concerns exist"}],"answer":"Blank 1: welcomed, Blank 2: concerns","check":"The grammar fits and the meaning is logical"}},{"id":"cloze_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"You can answer cloze questions just by reading the sentence with the blank.","why_wrong":"Often, the clue comes from a different sentence. You need to understand the whole passage.","correct_model":"Always read the full passage first. The clue for a blank may be several sentences away."}},{"id":"cloze_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB cloze passages test grammar (tense, subject-verb agreement), vocabulary, and collocations.","trap":"JAMB often includes options that are grammatically correct but don''t fit the context. Check BOTH grammar and meaning.","tip":"Common collocations: make a decision (not do), take place (not happen), do harm (not make), heavy rain (not strong).","related_topics":["Reading comprehension","Sentence completion","Vocabulary"]}},{"id":"cloze_memory_01","type":"memory_hook","order":8,"content":{"text":"Grammar first, meaning second, collocation third. If it doesn''t fit grammatically, it''s wrong. If it fits grammatically but makes no sense, it''s wrong.","hook_type":"strategy"}},{"id":"cloze_reflection_01","type":"reflection","order":9,"content":{"question":"Why do collocations matter in cloze passages?","expected_understanding":"Collocations are natural word combinations. ''Make a decision'' is correct; ''do a decision'' is grammatically possible but sounds wrong to native speakers."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The teacher asked the students to ___ their essays by Friday.","options":[{"label":"A","text":"submit"},{"label":"B","text":"submitting"},{"label":"C","text":"submitted"},{"label":"D","text":"submission"}],"answer":"A","explanation":"''asked someone to'' + base form of verb.","hints":["''to'' + base verb"]},{"difficulty":"medium","question":"The company has ___ a new strategy to increase sales.","options":[{"label":"A","text":"adopted"},{"label":"B","text":"adapted"},{"label":"C","text":"adept"},{"label":"D","text":"addicted"}],"answer":"A","explanation":"''Adopted'' means to accept and implement. ''Adapted'' means to modify.","hints":["Which word means ''to take on and use''?"]},{"difficulty":"jamb","question":"Despite the heavy rain, the match went ___ as planned.","options":[{"label":"A","text":"on"},{"label":"B","text":"off"},{"label":"C","text":"through"},{"label":"D","text":"ahead"}],"answer":"D","explanation":"''Went ahead'' means proceeded as planned.","hints":["Which phrase means ''proceeded despite obstacles''?"]}]'::jsonb, '{"min_score":80,"required_sections":["cloze_hook_01","cloze_intuitive_01","cloze_formal_01","cloze_strategy_01","cloze_practice_01"]}'::jsonb, '1')
