INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('english', 'Synonyms and antonyms', 'Lexis and Structure', 'Synonyms and Antonyms — Knowing What Words Mean and What They Don''t', '["Identify synonyms and antonyms from word lists","Use word roots, prefixes, and suffixes to determine meaning","Recognise common word families","Apply knowledge of Latin and Greek roots to unfamiliar words"]'::jsonb, 'medium', '18', '[{"id":"synonym_hook_01","type":"hook","order":1,"content":{"text":"JAMB loves testing whether you know what words mean — and what words mean the OPPOSITE. But here''s the thing: you don''t need to memorise every word. If you know a few roots, prefixes, and suffixes, you can figure out hundreds of words you''ve never seen before.","prediction_prompt":"If ''benevolent'' means kind, what does ''malevolent'' mean? Can you figure it out from the roots?"}},{"id":"synonym_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"English is built from pieces. Most long words come from Latin or Greek roots, with prefixes (before) and suffixes (after) that modify the meaning. If you know that ''bene'' means good and ''mal'' means bad, you can understand benevolent and malevolent without memorising them separately.","analogy":"Think of words like LEGO bricks. ''Pre-'' means before. ''Dict'' means say. ''Predict'' = say before = say what will happen. ''Dis-'' means not. ''Agree'' means agree. ''Disagree'' = not agree. Once you know the pieces, you can understand any word."}},{"id":"synonym_formal_01","type":"formal_explanation","order":3,"content":{"text":"A synonym is a word with the same or similar meaning (e.g., big/large, happy/joyful). An antonym is a word with the opposite meaning (e.g., big/small, happy/sad). JAMB tests both, but antonyms are more common.","key_terms":[{"term":"Synonym","definition":"A word with the same or similar meaning as another word"},{"term":"Antonym","definition":"A word with the opposite meaning of another word"},{"term":"Word family","definition":"A group of words derived from the same root (e.g., act, action, active, actor, react)"},{"term":"Prefix","definition":"Letters added to the beginning of a word to change its meaning (e.g., un-, re-, pre-, dis-)"},{"term":"Suffix","definition":"Letters added to the end of a word to change its meaning or part of speech"}]}},{"id":"synonym_roots_01","type":"formula","order":4,"content":{"formula":"Prefix + Root + Suffix = Word meaning","variables":[{"name":"un-","description":"not (unhappy = not happy, undo = reverse)"},{"name":"re-","description":"again (rewrite = write again, return = come back)"},{"name":"pre-","description":"before (predict = say before, preview = see before)"},{"name":"dis-","description":"not/opposite (disagree = not agree, disappear = stop being visible)"},{"name":"bene-","description":"good (benefit = good result, benevolent = kind)"},{"name":"mal-","description":"bad (malicious = harmful, malfunction = work badly)"}],"when_to_use":"When you encounter an unfamiliar word on the JAMB exam. Break it into prefix + root + suffix to guess the meaning.","common_traps":["Assuming all words with the same prefix have the same meaning — context matters.","Confusing similar prefixes: ''un-'' vs ''in-'' vs ''im-''.","Forgetting that some roots have changed form over time."],"units_note":"Common JAMB prefixes: un-, re-, pre-, dis-, in-/im-/il-/ir-, over-, under-, mis-, sub-, anti-, post-."}},{"id":"synonym_practice_01","type":"worked_example","order":5,"content":{"scenario":"Choose the word OPPOSITE in meaning to ''benevolent''. A. generous B. kind C. malevolent D. charitable","given":["A synonym/antonym question"],"required":"Choose the antonym of benevolent","principle":"Benevolent means kind/good (bene = good). The opposite would mean evil/harmful (mal = bad).","steps":[{"explanation":"Break down the word","calculation":"bene (good) + volent (wishing) = well-wishing, kind"},{"explanation":"Find the opposite root","calculation":"mal (bad) + volent (wishing) = ill-wishing, malevolent"},{"explanation":"Check other options","calculation":"A. generous (similar), B. kind (similar), D. charitable (similar)"},{"explanation":"Confirm","calculation":"C. malevolent is the only antonym"}],"answer":"C. malevolent","check":"Benevolent = kind. Malevolent = evil. They are opposites."}},{"id":"synonym_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Synonyms always have exactly the same meaning.","why_wrong":"True synonyms are rare — most synonyms have slightly different meanings or are used in different contexts.","correct_model":"Synonyms are SIMILAR in meaning, not identical. For JAMB, choose the closest match."}},{"id":"synonym_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB synonyms and antonyms test vocabulary breadth and depth. Questions give a word and ask for the closest meaning or opposite.","trap":"JAMB may include words that LOOK similar but mean different things (e.g., ''emigrate'' vs ''immigrate''). Don''t be fooled by visual similarity.","tip":"Build vocabulary systematically. Learn 5 new words a day, focusing on roots and prefixes.","related_topics":["Idioms","Sentence completion","Cloze passages"]}},{"id":"synonym_memory_01","type":"memory_hook","order":8,"content":{"text":"Know your prefixes: un- (not), re- (again), pre- (before), dis- (not/opposite), in/im/il/ir (not). Know your roots: dict (say), ject (throw), duct (lead), port (carry), script (write).","hook_type":"mnemonic"}},{"id":"synonym_reflection_01","type":"reflection","order":9,"content":{"question":"If you see the word ''incredible'' for the first time, how can you figure out its meaning using roots and prefixes?","expected_understanding":"''In-'' means not. ''Cred'' means believe. So ''incredible'' = not believable = amazing. Knowing roots lets you decode unfamiliar words."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Choose the word CLOSEST in meaning to ''abundant''.","options":[{"label":"A","text":"scarce"},{"label":"B","text":"plentiful"},{"label":"C","text":"moderate"},{"label":"D","text":"adequate"}],"answer":"B","explanation":"''Abundant'' means existing in large quantities. ''Plentiful'' means the same.","hints":["Abundant = a lot of something"]},{"difficulty":"medium","question":"Choose the word OPPOSITE in meaning to ''benevolent''.","options":[{"label":"A","text":"generous"},{"label":"B","text":"kind"},{"label":"C","text":"malevolent"},{"label":"D","text":"charitable"}],"answer":"C","explanation":"''Benevolent'' means kind/good. ''Malevolent'' means evil/harmful.","hints":["Bene- means good, mal- means bad"]},{"difficulty":"jamb","question":"Choose the word that means OPPOSITE of ''transparent''.","options":[{"label":"A","text":"clear"},{"label":"B","text":"obvious"},{"label":"C","text":"opaque"},{"label":"D","text":"visible"}],"answer":"C","explanation":"''Transparent'' means see-through. ''Opaque'' means you cannot see through it.","hints":["Transparent = can see through","Opaque = cannot see through"]}]'::jsonb, '{"min_score":80,"required_sections":["synonym_hook_01","synonym_intuitive_01","synonym_formal_01","synonym_roots_01","synonym_practice_01"]}'::jsonb, '1')
