INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('english', 'Idioms and idiomatic expressions', 'Lexis and Structure', 'Idioms — When Words Don''t Mean What You Think', '["Identify common English idioms and their meanings","Distinguish between literal and figurative language","Recognise Nigerian English idioms","Match idioms to their correct meanings in exam questions"]'::jsonb, 'medium', '18', '[{"id":"idiom_hook_01","type":"hook","order":1,"content":{"text":"It''s raining cats and dogs — no one said anything about animals. Idioms are phrases that mean something different from the literal meaning of their words. JAMB tests them because they show whether you truly understand English beyond the dictionary.","prediction_prompt":"What does ''bite the bullet'' mean? Think about it before reading on."}},{"id":"idiom_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Idioms are phrases where the whole meaning is different from the individual words. You can''t figure them out by looking at each word — you have to know the phrase as a whole. ''Break a leg'' doesn''t mean harm — it means good luck.","analogy":"Think of idioms like a secret code. If you know the code, you understand the message. If you don''t, you''ll be confused. ''Spill the beans'' doesn''t mean you dropped food — it means you revealed a secret."}},{"id":"idiom_formal_01","type":"formal_explanation","order":3,"content":{"text":"An idiom is a fixed expression whose meaning cannot be deduced from the individual words. Idioms are cultural — they develop from shared usage over time. JAMB tests common English idioms and occasionally Nigerian English expressions.","key_terms":[{"term":"Idiom","definition":"A phrase whose meaning is different from the literal meaning of its words"},{"term":"Figurative language","definition":"Language that uses words in a non-literal way to create an effect"},{"term":"Fixed expression","definition":"A phrase that must be said in a specific way — you can''t change the words"},{"term":"Nigerian English idiom","definition":"Idioms unique to or common in Nigerian English (e.g., dash = give freely)"}]}},{"id":"idiom_list_01","type":"formula","order":4,"content":{"formula":"Common idioms and their meanings","variables":[{"name":"Break the ice","description":"To initiate conversation in an awkward situation"},{"name":"Bite the bullet","description":"To endure something painful or difficult"},{"name":"Hit the nail on the head","description":"To be exactly right about something"},{"name":"Spill the beans","description":"To reveal a secret"},{"name":"Once in a blue moon","description":"Very rarely"},{"name":"Under the weather","description":"Feeling ill"},{"name":"Piece of cake","description":"Something very easy"},{"name":"Cost an arm and a leg","description":"Very expensive"},{"name":"Barking up the wrong tree","description":"Making a wrong assumption"},{"name":"Beat around the bush","description":"Avoiding the main topic"}],"when_to_use":"When JAMB asks what an expression means. You need to know the idiom, not analyse the words.","common_traps":["Taking idioms literally — ''break a leg'' does NOT mean break a bone.","Confusing similar idioms.","Using Nigerian English meanings for standard English idioms."],"units_note":"JAMB typically tests 10-15 common idioms per year."}},{"id":"idiom_practice_01","type":"worked_example","order":5,"content":{"scenario":"Choose the option that best explains: ''After much deliberation, the committee decided to bite the bullet and announce the unpopular decision.''","given":["A sentence with the idiom ''bite the bullet''"],"required":"Explain what the idiom means","principle":"Look at the context: ''after much deliberation'' and ''unpopular decision'' suggest something difficult was faced.","steps":[{"explanation":"Identify the idiom","calculation":"''Bite the bullet''"},{"explanation":"Look at the context","calculation":"They deliberated and chose to do something unpopular"},{"explanation":"Match to meaning","calculation":"''Bite the bullet'' = to endure something painful with courage"},{"explanation":"Verify","calculation":"This fits: they decided to face the difficulty"}],"answer":"To endure something painful or difficult with courage","check":"The context confirms the meaning"}},{"id":"idiom_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"You can figure out an idiom''s meaning by looking at the individual words.","why_wrong":"That''s the whole point of idioms — their meaning is NOT literal.","correct_model":"Idioms must be learned as whole units. Don''t try to analyse the words."}},{"id":"idiom_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests common English idioms in the form: ''Choose the option that best explains the underlined expression.''","trap":"JAMB may use less common idioms or Nigerian English expressions. If you don''t know the idiom, look at the context.","tip":"Create a personal list of idioms. Write each one with its meaning and an example sentence.","related_topics":["Synonyms and antonyms","Sentence completion","Reading comprehension"]}},{"id":"idiom_memory_01","type":"memory_hook","order":8,"content":{"text":"Top 10 JAMB idioms: break the ice (start talking), bite the bullet (endure), hit the nail on the head (exactly right), spill the beans (reveal secret), once in a blue moon (rarely), under the weather (ill), piece of cake (easy), cost an arm and a leg (expensive), barking up the wrong tree (wrong assumption), beat around the bush (avoid the point).","hook_type":"list"}},{"id":"idiom_reflection_01","type":"reflection","order":9,"content":{"question":"Why do idioms exist in English? Why not just say what you mean directly?","expected_understanding":"Idioms add colour, emphasis, and cultural flavour to language. They often express ideas more vividly or concisely than literal language."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What does ''piece of cake'' mean?","options":[{"label":"A","text":"A dessert"},{"label":"B","text":"Something very easy"},{"label":"C","text":"A small portion"},{"label":"D","text":"A reward"}],"answer":"B","explanation":"''Piece of cake'' is an idiom meaning something very easy to do.","hints":["It''s an idiom, not literal"]},{"difficulty":"medium","question":"Choose the option that best explains: ''The manager decided to call a spade a spade during the meeting.''","options":[{"label":"A","text":"To bring gardening tools"},{"label":"B","text":"To speak frankly and directly"},{"label":"C","text":"To avoid the topic"},{"label":"D","text":"To make a joke"}],"answer":"B","explanation":"''Call a spade a spade'' means to speak plainly and honestly.","hints":["It''s about how someone speaks"]},{"difficulty":"jamb","question":"The expression ''to kill two birds with one stone'' means to:","options":[{"label":"A","text":"Harm animals"},{"label":"B","text":"Waste time"},{"label":"C","text":"Achieve two objectives with one action"},{"label":"D","text":"Fail at everything"}],"answer":"C","explanation":"This idiom means accomplishing two things with a single effort.","hints":["One stone, two birds = one action, two results"]}]'::jsonb, '{"min_score":80,"required_sections":["idiom_hook_01","idiom_intuitive_01","idiom_formal_01","idiom_list_01","idiom_practice_01"]}'::jsonb, '1')
