INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('english', 'Sentence completion', 'Lexis and Structure', 'Sentence Completion — Choosing the Right Word Every Time', '["Choose the correct word based on meaning and grammar","Apply rules of subject-verb agreement","Maintain tense consistency within sentences","Use parallel structure in lists and comparisons"]'::jsonb, 'medium', '18', '[{"id":"sentence_hook_01","type":"hook","order":1,"content":{"text":"The sentence makes sense... until you realise the word is wrong. Sentence completion questions test whether you can spot the word that fits BOTH grammatically AND in meaning. One wrong word can change the entire meaning.","prediction_prompt":"Which is correct: ''Each of the students ___ their homework'' or ''Each of the students ___ his or her homework''?"}},{"id":"sentence_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Sentence completion is like filling in a puzzle piece. The piece must fit the shape (grammar) AND the picture (meaning). A word that fits grammatically but doesn''t make sense is wrong.","analogy":"Imagine a jigsaw puzzle. A piece might be the right shape (grammar) but the wrong colour (meaning). Or the right colour but the wrong shape. You need both."}},{"id":"sentence_formal_01","type":"formal_explanation","order":3,"content":{"text":"JAMB sentence completion tests: (1) Grammar — subject-verb agreement, tense, pronoun agreement, prepositions. (2) Meaning — which word fits the context. (3) Structure — parallel structure, comparison, word order.","key_terms":[{"term":"Subject-verb agreement","definition":"Subject and verb must agree in number"},{"term":"Tense consistency","definition":"Tense should remain consistent within a sentence"},{"term":"Parallel structure","definition":"Items in a list must have the same grammatical form"},{"term":"Pronoun agreement","definition":"A pronoun must agree with its antecedent in number and gender"}]}},{"id":"sentence_rules_01","type":"formula","order":4,"content":{"formula":"Key grammar rules for sentence completion","variables":[{"name":"Each/Every/Neither/Either","description":"Take a singular verb: ''Each has,'' not ''Each have''"},{"name":"Neither...nor / Either...or","description":"The verb agrees with the nearer subject"},{"name":"Collective nouns","description":"Usually singular in British English: ''The team is''"},{"name":"Prepositions","description":"Fixed: interested IN, depend ON, capable OF"},{"name":"Comparison","description":"Compare like with like: ''His car is faster than mine''"}],"when_to_use":"When grammar is the key to eliminating wrong options.","common_traps":["Subject-verb agreement with complex subjects.","Tense shifts within a sentence.","Comparing different things."],"units_note":"Time: about 1 minute per sentence completion question."}},{"id":"sentence_practice_01","type":"worked_example","order":5,"content":{"scenario":"Neither the teacher nor the students ___ aware of the change. A. was B. is C. were D. has been","given":["A sentence with neither...nor construction"],"required":"Choose the correct verb form","principle":"With neither...nor, the verb agrees with the nearer subject. ''Students'' is plural.","steps":[{"explanation":"Identify the rule","calculation":"Neither...nor → verb agrees with nearer subject"},{"explanation":"Identify nearer subject","calculation":"''the students'' — plural"},{"explanation":"Choose plural verb","calculation":"''were'' is past tense plural"},{"explanation":"Check other options","calculation":"A. was (singular), B. is (singular), D. has been (singular) — all wrong"}],"answer":"C. were","check":"Verb agrees with ''students'' (plural)"}},{"id":"sentence_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The verb always agrees with the first subject in a sentence.","why_wrong":"With neither...nor and either...or, the verb agrees with the NEARER subject.","correct_model":"Subject-verb agreement depends on the construction."}},{"id":"sentence_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB sentence completion tests subject-verb agreement, prepositions, conjunctions, and vocabulary.","trap":"JAMB often includes subject-verb agreement questions with complex subjects. Find the TRUE subject.","tip":"For ''The group of students ___,'' the subject is ''group'' (singular), not ''students.''","related_topics":["Cloze passages","Synonyms and antonyms"]}},{"id":"sentence_memory_01","type":"memory_hook","order":8,"content":{"text":"Each/Every/Neither/Either = singular verb. Neither...nor/Either...or = verb agrees with nearer subject. Collective nouns = usually singular.","hook_type":"mnemonic"}},{"id":"sentence_reflection_01","type":"reflection","order":9,"content":{"question":"Why does subject-verb agreement matter? Can''t people just understand what you mean anyway?","expected_understanding":"Subject-verb agreement is a rule of standard English. Breaking it makes your writing sound unprofessional and can cause confusion in formal contexts like exams."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Each of the students ___ given a textbook.","options":[{"label":"A","text":"have"},{"label":"B","text":"were"},{"label":"C","text":"was"},{"label":"D","text":"are"}],"answer":"C","explanation":"''Each'' is singular, so the verb must be singular: ''was.''","hints":["Each = singular","Singular subject → singular verb"]},{"difficulty":"medium","question":"The committee ___ divided in their opinions about the proposal.","options":[{"label":"A","text":"is"},{"label":"B","text":"was"},{"label":"C","text":"were"},{"label":"D","text":"has"}],"answer":"C","explanation":"In British English, collective nouns can take plural verbs when the members are acting individually. ''Were divided'' (plural) shows individual opinions.","hints":["Collective nouns can be singular or plural in British English","Individual actions → plural verb"]},{"difficulty":"jamb","question":"Neither the boys nor the girl ___ present at the meeting.","options":[{"label":"A","text":"were"},{"label":"B","text":"are"},{"label":"C","text":"is"},{"label":"D","text":"have been"}],"answer":"C","explanation":"With neither...nor, the verb agrees with the nearer subject. ''The girl'' is singular → ''is.''","hints":["Neither...nor → verb agrees with nearer subject","Girl = singular"]}]'::jsonb, '{"min_score":80,"required_sections":["sentence_hook_01","sentence_intuitive_01","sentence_formal_01","sentence_rules_01","sentence_practice_01"]}'::jsonb, '1')
