INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('english', 'Stress patterns', 'Oral Forms', 'Stress Patterns — Why SAY and DESERT Sound Different', '["Identify stressed syllables in words","Distinguish word stress in nouns vs verbs","Recognise compound word stress patterns","Apply stress rules to unfamiliar words"]'::jsonb, 'medium', '18', '[{"id":"stress_hook_01","type":"hook","order":1,"content":{"text":"SAY vs DESERT — same letters, different stress, different meaning. ''DEsert'' (noun) = a dry area. ''deSERT'' (verb) = to abandon. Stress changes everything. JAMB tests whether you know where the stress falls in a word.","prediction_prompt":"Say these two words out loud: PREsent (noun) and preSENT (verb). Notice where you put the emphasis?"}},{"id":"stress_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Stress is the emphasis you put on a syllable when you speak. One syllable is louder, longer, and higher-pitched than the others. In English, stress can change the meaning of a word entirely. ''REcord'' (noun) vs ''reCORD'' (verb). ''PREsent'' (gift) vs ''preSENT'' (to introduce).","analogy":"Think of stress like a spotlight on a stage. Only one actor is spotlighted at a time. In a word, only one syllable gets the spotlight (primary stress). The others are in the background. Move the spotlight, and the meaning changes."}},{"id":"stress_formal_01","type":"formal_explanation","order":3,"content":{"text":"English stress follows patterns: (1) Noun/verb pairs: stress often shifts (REcord vs reCORD). (2) Compound nouns: stress on the first element (WAter bottle, TOOTHbrush). (3) Adjective + noun: stress on the noun (blue CAR). (4) Suffixes like -tion, -sion, -ic, -ical shift stress to the syllable before the suffix.","key_terms":[{"term":"Primary stress","definition":"The strongest stress in a word, marked with an apostrophe before the syllable: comPUter"},{"term":"Secondary stress","definition":"A weaker stress, marked with a comma: COMputer (secondary on COM, primary on PU)"},{"term":"Stress shift","definition":"When stress moves from one syllable to another to avoid two stressed syllables in a row"},{"term":"Compound noun","definition":"Two words joined to make a new noun, usually stressed on the first element"}]}},{"id":"stress_rules_01","type":"formula","order":4,"content":{"formula":"Stress rules for common word patterns","variables":[{"name":"Noun/Verb pairs","description":"Noun: stress on first syllable (REcord, PREsent, CONduct). Verb: stress on second (reCORD, preSENT, conDUCT)"},{"name":"Compound nouns","description":"Stress on the first element: WAter bottle, TOOTHbrush, BLACKboard"},{"name":"-tion/-sion words","description":"Stress on the syllable before the suffix: eduCAtion, deciSION"},{"name":"-ic/-ical words","description":"Stress on the syllable before the suffix: aTOMic, hisTORical"},{"name":"-ity/-fy words","description":"Stress on the syllable before the suffix: uniVERsity,idenTIFy"}],"when_to_use":"When JAMB asks you to identify the stressed syllable or which word has different stress.","common_traps":["Assuming all words in a category have the same stress pattern — there are exceptions.","Confusing noun and verb stress in pairs like ''record'' and ''present.''","Not noticing that compound nouns stress the FIRST element, while adjective+noun phrases stress the NOUN."],"units_note":"JAMB usually tests 3-5 stress questions. Know the patterns above and you''ll get most of them right."}},{"id":"stress_practice_01","type":"worked_example","order":5,"content":{"scenario":"In which syllable is the primary stress in the word ''photograph''? A. PHO-to-graph B. pho-TO-graph C. pho-to-GRAPH D. pho-TO-graph","given":["A word stress question"],"required":"Identify the stressed syllable","principle":"Words ending in -graph, -graphy, -phonic stress the syllable before the suffix. ''Photograph'' stresses the first syllable.","steps":[{"explanation":"Say the word aloud","calculation":"PHO-to-graph"},{"explanation":"Check the pattern","calculation":"Photo (from Greek ''photos'' = light) + graph (writing)"},{"explanation":"Apply the rule","calculation":"Two-syllable nouns often stress the first syllable"},{"explanation":"Confirm","calculation":"PHO-to-graph — stress on first syllable"}],"answer":"A. PHO-to-graph","check":"Say it: PHO-to-graph. The emphasis is on PHO."}},{"id":"stress_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Stress always falls on the same syllable in a word family.","why_wrong":"Stress often shifts within a word family: PHOTOgraph (noun) vs photographIC (adjective) vs photograPHY (noun). The stress moves!","correct_model":"Stress shifts when suffixes are added. Know the suffix rules to predict where stress falls."}},{"id":"stress_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB stress questions ask you to identify which word has the stress on a particular syllable, or which word has different stress from the others.","trap":"JAMB may include words from other languages (French, Latin) where stress rules differ. Focus on the English patterns.","tip":"When in doubt, say the word aloud. Your ear will often tell you where the stress is.","related_topics":["Pronunciation","Intonation","Word formation"]}},{"id":"stress_memory_01","type":"memory_hook","order":8,"content":{"text":"Noun/verb pairs: noun = first syllable (REcord), verb = second syllable (reCORD). Compounds: first element (WAter bottle). -tion/-sion: syllable before (eduCAtion). Say it loud — your ear knows.","hook_type":"mnemonic"}},{"id":"stress_reflection_01","type":"reflection","order":9,"content":{"question":"Why does stress matter in English? Can''t people understand you even if you stress the wrong syllable?","expected_understanding":"Stress affects intelligibility. Wrong stress can make a word unrecognisable or change its meaning entirely. In formal contexts (exams, presentations), correct stress signals competence and fluency."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which syllable is stressed in ''banana''?","options":[{"label":"A","text":"BA-na-na"},{"label":"B","text":"ba-NA-na"},{"label":"C","text":"ba-na-NA"},{"label":"D","text":"BA-NA-na"}],"answer":"B","explanation":"The primary stress is on the second syllable: ba-NA-na.","hints":["Say it aloud: ba-NA-na"]},{"difficulty":"medium","question":"Which word has the stress on the SECOND syllable?","options":[{"label":"A","text":"photograph"},{"label":"B","text":"photography"},{"label":"C","C":"photographic"},{"label":"D","text":"photographer"}],"answer":"B","explanation":"PHOtograph (1st), phoTOGraphy (2nd), photoGRAPHic (3rd), phoTOGrapher (2nd). Both B and D have 2nd syllable stress, but ''photography'' is the clearest example.","hints":["Say each word and notice where the emphasis falls"]},{"difficulty":"jamb","question":"Which word has a DIFFERENT stress pattern from the others?","options":[{"label":"A","text":"record (noun)"},{"label":"B","text":"present (noun)"},{"label":"C","text":"conduct (noun)"},{"label":"D","text":"conduct (verb)"}],"answer":"D","explanation":"A, B, C are all nouns with stress on the first syllable (REcord, PREsent, CONduct). D is a verb with stress on the second syllable (conDUCT).","hints":["Nouns: stress on first syllable. Verbs: stress on second syllable."]}]'::jsonb, '{"min_score":80,"required_sections":["stress_hook_01","stress_intuitive_01","stress_formal_01","stress_rules_01","stress_practice_01"]}'::jsonb, '1')
