INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('geography', 'Map Reading and Interpretation', 'Fundamental Skills', 'Map Reading — Navigating the World on Paper', '["Identify map symbols and conventional signs","Calculate distance using map scale","Determine directions using compass and grid lines","Interpret contour lines and relief features"]'::jsonb, 'medium', '20', '[{"id":"geo_hook_01","type":"hook","order":1,"content":{"text":"Before GPS and smartphones, explorers used maps to navigate deserts, oceans, and mountains. A map is a flat representation of the Earth''s surface. Learning to read maps is not just a school subject — it''s a life skill that helps you understand the world around you.","prediction_prompt":"Can you read a map without a GPS? What information does a map give you?"}},{"id":"geo_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A map uses symbols, colors, and lines to represent real features. Contour lines show height — close together means steep, far apart means flat. Scale shows the ratio between map distance and real distance. The compass rose shows directions. Grid references help you locate exact positions.","analogy":"Think of a map like a bird''s-eye view of the Earth. You''re looking down from an airplane. Roads become lines, buildings become squares, mountains become contour patterns."}},{"id":"geo_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key map skills: (1) Scale — ratio of map distance to ground distance (1:50,000 means 1cm = 500m). (2) Symbols — conventional signs for roads, railways, churches, etc. (3) Direction — compass bearings (N, S, E, W) and grid lines. (4) Contour lines — lines of equal height; interval = difference between adjacent contours. (5) Grid references — four-figure (grid square) and six-figure (exact point).","key_terms":[{"term":"Scale","definition":"Ratio between map distance and actual ground distance"},{"term":"Contour Lines","definition":"Lines connecting points of equal height above sea level"},{"term":"Grid Reference","definition":"A system of coordinates that locates a point on a map"},{"term":"Relief","definition":"The shape of the land surface — hills, valleys, plains"}]}},{"id":"geo_formula_01","type":"formula","order":4,"content":{"formula":"Distance = Map distance × Scale denominator. E.g., 1:50,000 → 3cm on map = 3 × 50,000 = 150,000cm = 1.5km","variables":[{"name":"Scale 1:50,000","description":"1cm on map = 50,000cm = 500m = 0.5km on ground"},{"name":"Scale 1:25,000","description":"1cm on map = 250m on ground"},{"name":"Contour interval","description":"Height difference between adjacent contour lines"}],"when_to_use":"When calculating real distances from map measurements.","common_traps":["Confusing cm and km — always convert units carefully","Misreading contour intervals — check the key!","Forgetting to multiply by the scale denominator"],"units_note":"Map distances in cm; real distances convert to km."}},{"id":"geo_practice_01","type":"worked_example","order":5,"content":{"scenario":"On a 1:50,000 map, two towns are 4.5cm apart. Calculate the real distance.","given":["Scale: 1:50,000","Map distance: 4.5cm"],"required":"Calculate real distance","principle":"Multiply map distance by scale denominator.","steps":[{"explanation":"Apply scale","calculation":"4.5cm × 50,000 = 225,000cm"},{"explanation":"Convert to km","calculation":"225,000cm ÷ 100,000 = 2.25km"}],"answer":"The real distance is 2.25 km.","check":"At 1:50,000, 1cm = 500m. So 4.5cm = 2,250m = 2.25km."}},{"id":"geo_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Contour lines that are close together mean flat land.","why_wrong":"Close contours mean STEEP land (height changes quickly over short distance). Far apart means flat.","correct_model":"Close together = steep. Far apart = flat. Contours that form concentric circles = hill or valley."}},{"id":"geo_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests scale calculations, contour interpretation, grid references, and map symbols.","trap":"JAMB may give a scale in ratio form (1:50,000) or verbal form (1cm to 500m). Convert carefully.","tip":"For contour questions: draw a cross-section along a line. Mark heights where contours cross it.","related_topics":["Cross-sections","Landforms","Cartography"]}},{"id":"geo_memory_01","type":"memory_hook","order":8,"content":{"text":"Close contours = steep. Far contours = flat. Scale: map × denominator = real distance. Grid: Eastings first (along corridor), then Northings (up stairs).","hook_type":"mnemonic"}},{"id":"geo_reflection_01","type":"reflection","order":9,"content":{"question":"Why is map reading still important even though we have GPS?","expected_understanding":"GPS can fail (battery, signal). Maps give a broader overview that GPS lacks. Understanding maps helps you plan routes, understand terrain, and make spatial decisions."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"On a 1:100,000 map, 1cm represents:","options":[{"label":"A","text":"100m"},{"label":"B","text":"1km"},{"label":"C","text":"10km"},{"label":"D","text":"100km"}],"answer":"B","explanation":"1:100,000 means 1cm = 100,000cm = 1km.","hints":["Convert 100,000cm to km"]},{"difficulty":"medium","question":"Steep slopes are shown on a map by:","options":[{"label":"A","text":"Contours far apart"},{"label":"B","text":"Contours close together"},{"label":"C","text":"Flat colors"},{"label":"D","text":"Dotted lines"}],"answer":"B","explanation":"Close contour lines indicate steep slopes.","hints":["What happens to contour spacing on hillsides?"]},{"difficulty":"jamb","question":"A four-figure grid reference identifies:","options":[{"label":"A","text":"An exact point"},{"label":"B","text":"A grid square"},{"label":"C","text":"A contour line"},{"label":"D","text":"A road"}],"answer":"B","explanation":"A four-figure grid reference identifies a grid square. A six-figure reference identifies an exact point.","hints":["Four figures = ? Six figures = ?"]}]'::jsonb, '{"min_score":80,"required_sections":["geo_hook_01","geo_intuitive_01","geo_formal_01","geo_formula_01","geo_practice_01"]}'::jsonb, '1')
