INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('geography', 'Climate and Weather', 'Atmospheric Processes', 'Climate — Understanding Weather Patterns', '["Explain factors affecting climate","Distinguish between weather and climate","Identify climate types in Nigeria","Understand the causes of rainfall"]'::jsonb, 'medium', '20', '[{"id":"clim_hook_01","type":"hook","order":1,"content":{"text":"Why is Lagos rainy and Maiduguri dry? Why does Nigeria have a rainy season and a dry season? Climate determines how we dress, what we eat, and how we build our houses. Understanding climate helps us prepare for weather changes.","prediction_prompt":"How would your life be different if you lived in a place with no rainy season?"}},{"id":"clim_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Weather is what''s happening now (sunny, rainy). Climate is the average weather over 30+ years. Factors affecting climate: latitude (distance from equator), altitude (height above sea level), ocean currents, wind patterns, and vegetation. Nigeria has two main climate zones: the wet south and the dry north.","analogy":"Think of weather as your mood today, and climate as your personality. Your mood changes daily, but your personality stays relatively constant over time."}},{"id":"clim_formal_01","type":"formal_explanation","order":3,"content":{"text":"Climate factors: (1) Latitude — areas near equator are hotter. (2) Altitude — higher areas are cooler (temperature drops 6.5°C per 1000m). (3) Ocean currents — warm currents bring moisture, cold currents bring dry air. (4) Wind patterns — prevailing winds carry moisture. (5) Relief — mountains cause orographic rainfall. Nigeria''s climate: equatorial in south, tropical in central, arid in north.","key_terms":[{"term":"Climate","definition":"Average weather conditions over a long period (30+ years)"},{"term":"Rainfall Types","definition":"Convectional (heat-driven), relief/orographic (mountain-driven), frontal (warm meets cold air)"},{"term":"ITCZ","definition":"Inter-Tropical Convergence Zone — belt of low pressure near equator that moves north/south seasonally"},{"term":"Harmattan","definition":"Dry, dusty wind from the Sahara that affects Nigeria from November to March"}]}},{"id":"clim_formula_01","type":"formula","order":4,"content":{"formula":"Temperature drops 6.5°C for every 1000m increase in altitude (lapse rate)","variables":[{"name":"Latitude","description":"Equator = hottest. Poles = coldest"},{"name":"Altitude","description":"Higher = cooler (6.5°C per 1000m)"},{"name":"Rainfall","description":"Convectional (afternoon), relief (windward side), frontal (cold/warm front)"}],"when_to_use":"When explaining climate differences or rainfall patterns.","common_traps":["Confusing weather (short-term) with climate (long-term average)","Not knowing the three types of rainfall","Forgetting that altitude cools temperature"],"units_note":"Lapse rate: 6.5°C per 1000m."}},{"id":"clim_practice_01","type":"worked_example","order":5,"content":{"scenario":"The temperature at sea level is 30°C. What is the temperature at the top of a 2000m mountain?","given":["Sea level temperature: 30°C","Height: 2000m"],"required":"Calculate temperature at altitude","principle":"Temperature drops 6.5°C per 1000m.","steps":[{"explanation":"Calculate total drop","calculation":"2000m ÷ 1000 × 6.5°C = 13°C"},{"explanation":"Subtract from base","calculation":"30°C − 13°C = 17°C"}],"answer":"The temperature at 2000m is 17°C.","check":"13°C drop over 2000m is correct at 6.5°C/1000m."}},{"id":"clim_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Nigeria has the same climate everywhere.","why_wrong":"Nigeria ranges from equatorial (wet south) to semi-arid (dry north). Lagos gets 1700mm rain; Maiduguri gets 250mm.","correct_model":"Nigeria has diverse climates: equatorial south, tropical central, semi-arid north."}},{"id":"clim_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests climate factors, rainfall types, and Nigerian climate zones.","trap":"JAMB may ask about the ITCZ — its movement north/south causes Nigeria''s rainy and dry seasons.","tip":"Know the rainfall types: convectional (afternoon thunderstorms), relief (windward side of mountains), frontal (when warm and cold air meet).","related_topics":["Agriculture","Vegetation","Human-environment interaction"]}},{"id":"clim_memory_01","type":"memory_hook","order":8,"content":{"text":"Climate = weather average (30+ years). Types of rainfall: convectional, relief, frontal. Lapse rate: 6.5°C per 1000m. Nigeria: wet south, dry north.","hook_type":"mnemonic"}},{"id":"clim_reflection_01","type":"reflection","order":9,"content":{"question":"How does climate change affect agriculture in Nigeria?","expected_unexceptional":"Shifting rainfall patterns cause droughts in the north and floods in the south. Farmers can''t predict planting seasons. Food security is threatened."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The average weather conditions over 30 years is called:","options":[{"label":"A","text":"Weather"},{"label":"B","text":"Climate"},{"label":"C","text":"Season"},{"label":"D","text":"Forecast"}],"answer":"B","explanation":"Climate is the long-term average of weather conditions.","hints":["Long-term vs short-term"]},{"difficulty":"medium","question":"The Harmattan wind comes from:","options":[{"label":"A","text":"The Atlantic Ocean"},{"label":"B","text":"The Sahara Desert"},{"label":"C","text":"The Indian Ocean"},{"label":"D","text":"The Mediterranean"}],"answer":"B","explanation":"The Harmattan is a dry, dusty wind from the Sahara that affects Nigeria from November to March.","hints":["Which desert is north of Nigeria?"]},{"difficulty":"jamb","question":"Orographic rainfall occurs when:","options":[{"label":"A","text":"Warm air rises due to heat"},{"label":"B","text":"Moist air is forced to rise over mountains"},{"label":"C","text":"Warm and cold air masses meet"},{"label":"D","text":"The sun heats the ocean"}],"answer":"B","explanation":"Orographic (relief) rainfall occurs when moist air is forced to rise over mountains, cooling and condensing.","hints":["Oro = mountain"]}]'::jsonb, '{"min_score":80,"required_sections":["clim_hook_01","clim_intuitive_01","clim_formal_01","clim_formula_01","clim_practice_01"]}'::jsonb, '1')
