INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('geography', 'Population and Settlement', 'Demographics and Urbanization', 'Population — People and Where They Live', '["Explain factors affecting population distribution","Distinguish between population growth and density","Understand urbanization and its effects","Analyze migration patterns and their causes"]'::jsonb, 'medium', '20', '[{"id":"pop_hook_01","type":"hook","order":1,"content":{"text":"Lagos has over 20 million people crammed into a small area. Yobe State has far fewer people spread over a larger area. Why do people cluster in some places and avoid others? The answer lies in geography, economics, and history.","prediction_prompt":"Why do you think more people live in southern Nigeria than in the north?"}},{"id":"pop_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"People settle where conditions are favourable: good soil for farming, water availability, mild climate, economic opportunities, and safety. Population density = people per unit area. Growth rate = how fast population increases (births + immigration − deaths − emigration). Urbanization = the shift from rural to urban living.","analogy":"Think of population like water flowing downhill. People flow toward opportunities (jobs, education, healthcare) just as water flows toward lower ground. Cities are the valleys where people collect."}},{"id":"pop_formal_01","type":"formal_explanation","order":3,"content":{"text":"Population factors: (1) Physical — climate, water, soil, terrain. (2) Economic — jobs, industry, commerce. (3) Social — education, healthcare, security. (4) Historical — colonial influence, trade routes. Nigeria: 200+ million people, fastest-growing large country. Urbanization rate: 50%+ live in cities, projected to reach 60% by 2030.","key_terms":[{"term":"Population Density","definition":"Number of people per unit area (people/km²)"},{"term":"Urbanization","definition":"The process of population shift from rural to urban areas"},{"term":"Migration","definition":"Movement of people from one place to another"},{"term":"Census","definition":"Official count of a population at a specific time"}]}},{"id":"pop_formula_01","type":"formula","order":4,"content":{"formula":"Population Density = Total Population / Land Area. Growth Rate = (Births + Immigration) − (Deaths + Emigration)","variables":[{"name":"Density","description":"People per km²"},{"name":"Growth Rate","description":"% increase per year"},{"name":"Doubling Time","description":"70 / Growth Rate (%) = years to double"}],"when_to_use":"When calculating population statistics or analyzing settlement patterns.","common_traps":["Confusing growth rate with density","Not knowing doubling time formula","Forgetting that urbanization has both positive and negative effects"],"units_note":"Population density is measured in people per km²."}},{"id":"pop_practice_01","type":"worked_example","order":5,"content":{"scenario":"Nigeria''s population growth rate is 2.5%. How long will it take for the population to double?","given":["Growth rate: 2.5%"],"required":"Calculate doubling time","principle":"Doubling time = 70 / growth rate (%)","steps":[{"explanation":"Apply formula","calculation":"70 / 2.5 = 28 years"}],"answer":"Nigeria''s population will double in approximately 28 years.","check":"At 2.5% per year, population doubles in 70/2.5 = 28 years."}},{"id":"pop_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Urbanization is always good.","why_wrong":"Urbanization brings opportunities but also problems: congestion, pollution, slums, unemployment, crime.","correct_model":"Urbanization has benefits (jobs, services) and challenges (overcrowding, poverty). Balanced development is key."}},{"id":"pop_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests population concepts, urbanization effects, and migration causes.","trap":"JAMB may ask about push vs pull factors. Push = reasons to leave (poverty, conflict). Pull = reasons to move to (jobs, education).","tip":"For essay questions, use examples from Nigeria: Lagos as a mega-city, rural-urban migration, IDP camps.","related_topics":["Urban planning","Housing","Migration"]}},{"id":"pop_memory_01","type":"memory_hook","order":8,"content":{"text":"Density = population/area. Growth = births + immigration − deaths − emigration. Doubling time = 70/growth rate. Urbanization = rural to urban shift.","hook_type":"mnemonic"}},{"id":"pop_reflection_01","type":"reflection","order":9,"content":{"question":"What challenges does rapid urbanization pose for Nigerian cities?","expected_unexpected":"Congestion, inadequate housing (slums), pressure on infrastructure, unemployment, environmental degradation."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Population density is calculated as:","options":[{"label":"A","text":"Births minus deaths"},{"label":"B","text":"Population divided by land area"},{"label":"C","text":"Number of cities"},{"label":"D","text":"Immigration rate"}],"answer":"B","explanation":"Population density = total population / land area.","hints":["How many people per unit area?"]},{"difficulty":"medium","question":"A push factor for migration is:","options":[{"label":"A","text":"Better job opportunities"},{"label":"B","text":"Good schools"},{"label":"C","text":"Poverty and lack of jobs"},{"label":"D","text":"Modern hospitals"}],"answer":"C","explanation":"Push factors drive people away (poverty, conflict). Pull factors attract people (jobs, education).","hints":["What pushes people to leave?"]},{"difficulty":"jamb","question":"Urbanization in Nigeria has led to:","options":[{"label":"A","text":"Only positive effects"},{"label":"B","text":"Growth of slums and congestion"},{"label":"C","text":"Empty cities"},{"label":"D","text":"Reduced population"}],"answer":"B","explanation":"Rapid urbanization has caused slums, congestion, unemployment, and infrastructure pressure.","hints":["What are the negative effects of rapid city growth?"]}]'::jsonb, '{"min_score":80,"required_sections":["pop_hook_01","pop_intuitive_01","pop_formal_01","pop_formula_01","pop_practice_01"]}'::jsonb, '1')
