INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('geography', 'Natural Resources and Conservation', 'Resource Management', 'Natural Resources — Using and Protecting What We Have', '["Classify natural resources (renewable and non-renewable)","Explain the importance of natural resources to Nigeria","Understand environmental conservation methods","Evaluate the impact of resource extraction on the environment"]'::jsonb, 'medium', '20', '[{"id":"res_hook_01","type":"hook","order":1,"content":{"text":"Nigeria is one of the world''s largest oil producers, yet many Nigerians live in poverty. The Niger Delta — where oil comes from — is one of the most polluted places on Earth. Natural resources can be a blessing or a curse. How we manage them determines our future.","prediction_prompt":"If Nigeria had no oil, what other resources could the country rely on?"}},{"id":"res_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Natural resources are materials from nature that humans use. Renewable resources can be replenished (water, solar, forests). Non-renewable resources take millions of years to form (oil, gas, minerals). Nigeria''s resources include oil, gas, tin, coal, limestone, timber, and fertile farmland. Resource management means balancing exploitation with conservation.","analogy":"Think of non-renewable resources like money in a bank account. Once you withdraw it, it''s gone. Renewable resources are like interest — they keep generating if you don''t overdraw."}},{"id":"res_formal_01","type":"formal_explanation","order":3,"content":{"text":"Nigeria''s resources: (1) Petroleum — 90% of export earnings, found mainly in Niger Delta. (2) Natural gas — largest reserves in Africa. (3) Solid minerals — tin, columbite, coal, limestone. (4) Agriculture — cocoa, rubber, palm oil, groundnut. (5) Water resources — rivers, lakes, groundwater. Conservation: sustainable use, recycling, pollution control, protected areas.","key_terms":[{"term":"Renewable Resources","definition":"Resources that can be replenished naturally (water, solar, wind, forests)"},{"term":"Non-renewable Resources","definition":"Resources that take millions of years to form and cannot be replaced once used (oil, gas, minerals)"},{"term":"Conservation","definition":"Protecting and managing natural resources to prevent waste and destruction"},{"term":"Sustainable Development","definition":"Meeting present needs without compromising future generations'' ability to meet their needs"}]}},{"id":"res_formula_01","type":"formula","order":4,"content":{"formula":"Resource Management: Extract + Process + Use + Conserve + Recycle","variables":[{"name":"Extract","description":"Mining, drilling, harvesting"},{"name":"Process","description":"Refining, manufacturing"},{"name":"Use","description":"Consumption by people and industry"},{"name":"Conserve","description":"Protecting resources for future use"},{"name":"Recycle","description":"Reusing materials to reduce waste"}],"when_to_use":"When analyzing resource management challenges or sustainability.","common_traps":["Confusing renewable and non-renewable resources","Not knowing Nigeria''s main exports","Forgetting that conservation doesn''t mean not using resources — it means using them wisely"],"units_note":"Oil accounts for ~90% of Nigeria''s export earnings."}},{"id":"res_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain the ''resource curse'' — why do oil-rich countries like Nigeria often have high poverty?","given":["The paradox of resource wealth and poverty"],"required":"Explain the resource curse concept","principle":"Resource wealth can create economic, social, and political problems.","steps":[{"explanation":"Economic problem","calculation":"Oil wealth causes ''Dutch Disease'' — other sectors (agriculture, manufacturing) are neglected"},{"explanation":"Political problem","calculation":"Corruption — leaders steal oil revenue instead of developing the country"},{"explanation":"Social problem","calculation":"Environmental pollution in Niger Delta destroys farming and fishing"},{"explanation":"Solution","calculation":"Diversify economy, fight corruption, invest in people and infrastructure"}],"answer":"The resource curse: oil wealth leads to neglect of other sectors, corruption, environmental damage, and inequality.","check":"Nigeria earns billions from oil but has high poverty — the wealth doesn''t reach ordinary people."}},{"id":"res_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Natural resources will last forever.","why_wrong":"Non-renewable resources (oil, gas) take millions of years to form. Once used, they''re gone for human history.","correct_model":"Non-renewable resources are finite. We must use them wisely and invest in renewable alternatives."}},{"id":"res_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests resource types, Nigeria''s resources, and conservation methods.","trap":"JAMB may ask about the Niger Delta environmental crisis — oil spills, gas flaring, and their effects on communities.","tip":"For essay questions, balance: economic benefits of oil vs environmental and social costs.","related_topics":["Environmental pollution","Sustainable development","Economic diversification"]}},{"id":"res_memory_01","type":"memory_hook","order":8,"content":{"text":"Renewable = replenishes (water, solar). Non-renewable = finite (oil, gas). Nigeria: oil = 90% exports. Resource curse = wealth + poverty. Conservation = wise use.","hook_type":"mnemonic"}},{"id":"res_reflection_01","type":"reflection","order":9,"content":{"question":"What steps should Nigeria take to reduce dependence on oil?","expected_understanding":"Invest in agriculture, manufacturing, tourism, and technology. Fight corruption. Develop renewable energy. Educate the workforce."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which of the following is a non-renewable resource?","options":[{"label":"A","text":"Solar energy"},{"label":"B","text":"Petroleum"},{"label":"C","text":"Water"},{"label":"D","text":"Wind"}],"answer":"B","explanation":"Petroleum is non-renewable — it takes millions of years to form.","hints":["Which resource cannot be replenished?"]},{"difficulty":"medium","question":"The Niger Delta environmental crisis is mainly caused by:","options":[{"label":"A","text":"Farming activities"},{"label":"B","text":"Oil exploration and production"},{"label":"C","text":"Deforestation"},{"label":"D","text":"Urbanization"}],"answer":"B","explanation":"Oil spills, gas flaring, and pipeline vandalism have devastated the Niger Delta environment.","hints":["What industry dominates the Niger Delta?"]},{"difficulty":"jamb","question":"Sustainable development means:","options":[{"label":"A","text":"Using all resources now"},{"label":"B","text":"Meeting present needs without compromising future generations"},{"label":"C","text":"Stopping all development"},{"label":"D","text":"Only using renewable resources"}],"answer":"B","explanation":"Sustainable development balances current needs with protecting resources for the future.","hints":["The Brundtland definition"]}]'::jsonb, '{"min_score":80,"required_sections":["res_hook_01","res_intuitive_01","res_formal_01","res_formula_01","res_practice_01"]}'::jsonb, '1')
