INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('geography', 'Agriculture and Food Production', 'Farming Systems', 'Agriculture — Feeding the Nation', '["Identify types of farming in Nigeria","Explain factors affecting agricultural production","Understand the problems facing Nigerian agriculture","Evaluate solutions to food insecurity"]'::jsonb, 'medium', '20', '[{"id":"agr_hook_01","type":"hook","order":1,"content":{"text":"Nigeria was once a major exporter of groundnuts, cocoa, and palm oil. Today, it imports food worth billions of dollars. What went wrong? Agriculture — the backbone of the Nigerian economy — declined due to neglect, insecurity, and poor infrastructure. Reviving agriculture is key to Nigeria''s future.","prediction_prompt":"Why would a country with fertile land import food?"}},{"id":"agr_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Agriculture in Nigeria ranges from subsistence farming (growing food for family) to commercial farming (growing for sale). Major crops: cassava, yam, maize, rice, sorghum (food crops); cocoa, rubber, palm oil, groundnut (cash crops). Factors affecting agriculture: climate, soil, water, labour, technology, government policy.","analogy":"Think of agriculture like a chain. Each link — land, seed, water, labour, market — must be strong. If any link breaks (no rain, no market, no road), the whole chain fails and food production suffers."}},{"id":"agr_formal_01","type":"formal_explanation","order":3,"content":{"text":"Nigerian farming systems: (1) Shifting cultivation — clearing and burning vegetation, farming for few years, then moving. (2) Subsistence farming — small plots, family labour, minimal inputs. (3) Commercial farming — large-scale, mechanized, for export. Problems: poor infrastructure, insecurity (herder-farmer conflicts), climate change, land tenure issues, limited access to credit.","key_terms":[{"term":"Subsistence Farming","definition":"Farming mainly to feed the family, with small surpluses for sale"},{"term":"Cash Crops","definition":"Crops grown primarily for sale (cocoa, rubber, palm oil)"},{"term":"Food Crops","definition":"Crops grown mainly for consumption (cassava, yam, rice)"},{"term":"Agricultural Extension","definition":"Government services that educate farmers on modern techniques"}]}},{"id":"agr_formula_01","type":"formula","order":4,"content":{"formula":"Agricultural Productivity = f(Land, Labour, Capital, Technology, Policy)","variables":[{"name":"Land","description":"Fertile soil, adequate rainfall, irrigation"},{"name":"Labour","description":"Available workers, training, health"},{"name":"Capital","description":"Credit, equipment, infrastructure"},{"name":"Technology","description":"Improved seeds, fertilizers, mechanization"},{"name":"Policy","description":"Government support, subsidies, security"}],"when_to_use":"When analyzing factors affecting agricultural production.","common_traps":["Focusing only on climate — infrastructure and policy are equally important","Not knowing the difference between subsistence and commercial farming","Forgetting that insecurity (herder-farmer conflicts) is a major problem"],"units_note":"Agriculture employs ~35% of Nigeria''s workforce but contributes only ~24% of GDP — showing low productivity."}},{"id":"agr_practice_01","type":"worked_example","order":5,"content":{"scenario":"Suggest five ways to improve agricultural production in Nigeria.","given":["Nigerian agriculture faces multiple challenges"],"required":"Propose solutions","principle":"Solutions must address the key constraints: infrastructure, technology, security, finance, and policy.","steps":[{"explanation":"Infrastructure","calculation":"Build rural roads to connect farms to markets"},{"explanation":"Technology","calculation":"Provide improved seeds, fertilizers, and mechanization"},{"explanation":"Security","calculation":"Address herder-farmer conflicts and banditry"},{"explanation":"Finance","calculation":"Provide low-interest loans and insurance for farmers"},{"explanation":"Policy","calculation":"Government should support agriculture with subsidies and research"}],"answer":"Solutions: (1) Build rural roads, (2) Provide improved inputs, (3) Address insecurity, (4) Provide credit, (5) Government investment in research and extension.","check":"These address the five key constraints: infrastructure, technology, security, finance, and policy."}},{"id":"agr_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Nigeria has no agricultural potential.","why_wrong":"Nigeria has vast arable land, diverse climates, and a large workforce. The potential is enormous — but untapped due to poor infrastructure and policy.","correct_model":"Nigeria has huge agricultural potential — it just needs investment, infrastructure, and security."}},{"id":"agr_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests farming types, agricultural problems, and solutions.","trap":"JAMB may ask about the ''Green Revolution'' or government agricultural policies. Know specific programmes.","tip":"For essay questions, use specific examples: Anchor Borrowers'' Programme, CBN agricultural loans, Lake Rice project.","related_topics":["Food security","Rural development","Climate change impacts"]}},{"id":"agr_memory_01","type":"memory_hook","order":8,"content":{"text":"Nigeria agriculture: subsistence (food) + commercial (cash). Problems: roads, security, credit, climate, policy. Potential: vast land, diverse climate, large workforce.","hook_type":"mnemonic"}},{"id":"agr_reflection_01","type":"reflection","order":9,"content":{"question":"How can young Nigerians be encouraged to take up agriculture?","expected_understanding":"Make farming profitable (better prices, processing), modernize agriculture (technology, mechanization), provide credit, and change the perception that farming is ''dirty'' work."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Farming mainly to feed one''s family is called:","options":[{"label":"A","text":"Commercial farming"},{"label":"B","text":"Subsistence farming"},{"label":"C","text":"Plantation farming"},{"label":"D","text":"Industrial farming"}],"answer":"B","explanation":"Subsistence farming is growing food mainly for family consumption.","hints":["Growing food to eat, not to sell"]},{"difficulty":"medium","question":"Which of the following is NOT a cash crop in Nigeria?","options":[{"label":"A","text":"Cocoa"},{"label":"B","text":"Cassava"},{"label":"C","text":"Rubber"},{"label":"D","text":"Palm oil"}],"answer":"B","explanation":"Cassava is a food crop (grown for consumption). Cocoa, rubber, and palm oil are cash crops (grown for sale).","hints":["Which crop is mainly eaten, not sold?"]},{"difficulty":"jamb","question":"A major problem facing Nigerian agriculture is:","options":[{"label":"A","text":"Too much rainfall"},{"label":"B","text":"Insecurity and herder-farmer conflicts"},{"label":"C","text":"Over-mechanization"},{"label":"D","text":"Too many farmers"}],"answer":"B","explanation":"Insecurity — including banditry and herder-farmer conflicts — is a major threat to agricultural production.","hints":["What prevents farmers from working safely?"]}]'::jsonb, '{"min_score":80,"required_sections":["agr_hook_01","agr_intuitive_01","agr_formal_01","agr_formula_01","agr_practice_01"]}'::jsonb, '1')
