INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('government', 'Basic Concepts of Government', 'Fundamental Terms and Definitions', 'Government — Power, Authority, and the State', '["Define government and distinguish it from the state","Explain concepts of power, authority, and legitimacy","Identify the features of a state","Understand sovereignty and its types"]'::jsonb, 'medium', '20', '[{"id":"govt_hook_01","type":"hook","order":1,"content":{"text":"Why do people obey the law? Is it because the government has guns, or because people believe it has the right to rule? The difference between force and authority is the difference between a government and a gang. Understanding this is the foundation of political science.","prediction_prompt":"What makes a government different from a group of people with weapons?"}},{"id":"govt_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Government is the machinery through which a state is ruled. The state is the territory, people, and sovereignty. Government is the people and institutions that make and enforce rules. Power is the ability to influence others. Authority is power that is accepted as legitimate. A armed robber has power; a president has authority.","analogy":"Think of the state as a car. Government is the driver. Power is the engine that makes the car move. Authority is the driving license that makes the driver合法. Without authority, the driver is just someone who stole the car."}},{"id":"govt_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key concepts: (1) State — population, territory, government, sovereignty. (2) Government — the political machinery that runs the state. (3) Power — ability to influence behaviour. (4) Authority — legitimate power, accepted by the people. (5) Legitimacy — the right to rule, derived from consent, tradition, or law. (6) Sovereignty — supreme power within a territory (internal) and independence from other states (external).","key_terms":[{"term":"State","definition":"An independent political community with a permanent population, defined territory, government, and sovereignty"},{"term":"Government","definition":"The political machinery through which the state is governed"},{"term":"Sovereignty","definition":"Supreme and absolute power within a territory"},{"term":"Legitimacy","definition":"The popular acceptance of a government''s authority"}]}},{"id":"govt_formula_01","type":"formula","order":4,"content":{"formula":"State = Population + Territory + Government + Sovereignty","variables":[{"name":"Population","description":"People living within the territory"},{"name":"Territory","description":"Defined land area with boundaries"},{"name":"Government","description":"Institutions that rule the state"},{"name":"Sovereignty","description":"Supreme authority — internal and external"}],"when_to_use":"When asked to define or identify a state. All four elements must be present.","common_traps":["Confusing state with government — the state is permanent, government changes","Confusing power with authority — power can be illegitimate","Forgetting external sovereignty — a state must be independent"],"units_note":"A government in exile may have legitimacy but no territory. A occupied country may have territory but no sovereignty."}},{"id":"govt_practice_01","type":"worked_example","order":5,"content":{"scenario":"A military junta takes power through a coup. Is this government legitimate?","given":["A government that came to power by force"],"required":"Analyze the legitimacy of this government","principle":"Legitimacy comes from the consent of the governed, not from force.","steps":[{"explanation":"Check source of power","calculation":"Power came from military force (coup), not elections"},{"explanation":"Check popular acceptance","calculation":"People may obey out of fear, not belief in the government''s right"},{"explanation":"Apply Weber''s types","calculation":"This is coercive power, not legitimate authority"},{"explanation":"Consider practical reality","calculation":"Over time, the junta may gain legitimacy through effective governance (de facto legitimacy)"}],"answer":"Initially, the junta lacks democratic legitimacy. However, over time it may gain de facto legitimacy if it governs effectively and the people accept its authority.","check":"Legitimacy is not binary — it exists on a spectrum and can change over time."}},{"id":"govt_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Government and state are the same thing.","why_wrong":"The state is permanent (territory, people, sovereignty). Government changes — it''s the people and institutions currently in charge.","correct_model":"State = the country (permanent). Government = who is currently ruling (temporary). A new government doesn''t create a new state."}},{"id":"govt_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests basic political concepts, definitions, and the features of a state.","trap":"JAMB may ask about ''de jure'' vs ''de facto'' legitimacy. De jure = by law. De facto = in practice (whether recognized or not).","tip":"For definitions, be precise. JAMB marks based on key terms. Include: population, territory, government, sovereignty when defining a state.","related_topics":["Forms of government","Sovereignty","Political legitimacy"]}},{"id":"govt_memory_01","type":"memory_hook","order":8,"content":{"text":"State needs 4 things: People, Land, Government, Sovereignty. Power = ability. Authority = legitimate power. Government runs the state. State is permanent, government changes.","hook_type":"mnemonic"}},{"id":"govt_reflection_01","type":"reflection","order":9,"content":{"question":"Can a government exist without legitimacy? What happens when people stop believing in a government''s right to rule?","expected_understanding":"Yes, through coercion — but it''s unstable. When people withdraw consent, governments collapse. The Arab Spring showed how quickly governments can fall when legitimacy evaporates."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which of the following is NOT a feature of a state?","options":[{"label":"A","text":"Population"},{"label":"B","text":"Territory"},{"label":"C","text":"Army"},{"label":"D","text":"Sovereignty"}],"answer":"C","explanation":"A state needs population, territory, government, and sovereignty. An army is not a defining feature.","hints":["What are the four essential elements of a state?"]},{"difficulty":"medium","question":"Power that is accepted as rightful and proper is called:","options":[{"label":"A","text":"Force"},{"label":"B","text":"Authority"},{"label":"C","text":"Coercion"},{"label":"D","text":"Influence"}],"answer":"B","explanation":"Authority is power that is accepted as legitimate — the right to rule.","hints":["What makes people obey willingly, not out of fear?"]},{"difficulty":"jamb","question":"A state that has lost control of its territory but maintains its government in exile is said to have:","options":[{"label":"A","text":"Lost its sovereignty completely"},{"label":"B","text":"Maintained de jure sovereignty"},{"label":"C","text":"Become a failed state"},{"label":"D","text":"Both B and C"}],"answer":"D","explanation":"The government retains legal (de jure) sovereignty but has lost effective (de facto) control — making it a failed state.","hints":["De jure = by law. De facto = in practice"]}]'::jsonb, '{"min_score":80,"required_sections":["govt_hook_01","govt_intuitive_01","govt_formal_01","govt_formula_01","govt_practice_01"]}'::jsonb, '1')
