INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('government', 'Forms of Government', 'Types and Systems', 'Forms of Government — Democracy, Monarchy, and More', '["Distinguish between democracy, monarchy, and authoritarianism","Compare presidential and parliamentary systems","Analyze unitary, federal, and confederal systems","Evaluate the separation of powers"]'::jsonb, 'medium', '22', '[{"id":"forms_hook_01","type":"hook","order":1,"content":{"text":"Nigeria has a presidential system, the UK has a parliamentary system, Saudi Arabia has an absolute monarchy. Why do different countries choose different systems? The answer lies in history, culture, and the values a society prioritizes — efficiency, representation, or stability.","prediction_prompt":"If you were designing a new country''s government, would you choose a presidential or parliamentary system? Why?"}},{"id":"forms_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Governments can be classified by who rules (democracy = people, monarchy = one ruler, oligarchy = few) and how power is organized (presidential = separate executive, parliamentary = executive from legislature). The presidential system (like Nigeria) has a president who is both head of state and government. The parliamentary system (like UK) has a prime minister who leads the legislature.","analogy":"Think of presidential vs parliamentary like a company. Presidential = CEO (president) is separate from the board of directors (legislature). Parliamentary = CEO (PM) is chosen from and accountable to the board. If the board loses confidence, the CEO is replaced."}},{"id":"forms_formal_01","type":"formal_explanation","order":3,"content":{"text":"By participation: Democracy (direct or representative), Autocracy, Oligarchy, Theocracy. By structure: Unitary (power centralized), Federal (power divided), Confederal (loose alliance). By executive-legislative relationship: Presidential (separation of powers), Parliamentary (fusion of powers). Key principle: Separation of powers — legislature makes law, executive implements, judiciary interprets.","key_terms":[{"term":"Presidential System","definition":"Executive president separate from legislature, fixed term, cannot be removed by legislature"},{"term":"Parliamentary System","definition":"PM is part of legislature, government accountable to parliament, vote of no confidence can remove PM"},{"term":"Federal System","definition":"Power divided between central and state/regional governments by constitution"},{"term":"Separation of Powers","definition":"Division of government functions among legislature, executive, and judiciary"}]}},{"id":"forms_formula_01","type":"formula","order":4,"content":{"formula":"Presidential vs Parliamentary: President = separate, fixed term, both head of state and government. PM = from legislature, removable, head of government only.","variables":[{"name":"Presidential","description":"Separate executive, fixed term, direct mandate"},{"name":"Parliamentary","description":"Executive from legislature, accountable to parliament"},{"name":"Unitary","description":"All power at center, local govts are delegates"},{"name":"Federal","description":"Power shared by constitution, both levels autonomous"}],"when_to_use":"When asked to compare or classify government systems.","common_traps":["Confusing presidential with authoritarian — presidential can be democratic","Forgetting that Nigeria adopted presidential system in 1979","Not understanding that parliamentary systems can be more flexible (vote of no confidence)"],"units_note":"JAMB may compare Nigeria''s system with the UK or USA."}},{"id":"forms_practice_01","type":"worked_example","order":5,"content":{"scenario":"Compare the presidential system (Nigeria/USA) with the parliamentary system (UK).","given":["Two government systems to compare"],"required":"Identify key differences","principle":"Compare: source of executive power, accountability, relationship between executive and legislature.","steps":[{"explanation":"Source of executive power","calculation":"Presidential: President elected directly by people. Parliamentary: PM chosen by parliament"},{"explanation":"Accountability","calculation":"Presidential: President accountable to electorate (fixed term). Parliamentary: PM accountable to parliament (can be removed)"},{"explanation":"Relationship","calculation":"Presidential: Separation — president cannot sit in legislature. Parliamentary: Fusion — PM is member of parliament"},{"explanation":"Head of state","calculation":"Presidential: President is both head of state and government. Parliamentary: Head of state (monarch/president) separate from head of government (PM)"}],"answer":"Presidential: separate executive, fixed term, direct mandate. Parliamentary: executive from legislature, flexible term, parliament accountability.","check":"Nigeria chose the presidential system to prevent the instability of parliamentary systems in West Africa."}},{"id":"forms_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"In a parliamentary system, the monarch/ruler has real political power.","why_wrong":"In constitutional monarchies (UK, Japan), the monarch is a ceremonial head of state. Real power lies with the PM and parliament.","correct_model":"Constitutional monarchy = monarch is ceremonial. Absolute monarchy = monarch has real power. Know the difference."}},{"id":"forms_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests comparison of government systems and the principle of separation of powers.","trap":"JAMB may ask about ''checks and balances'' vs ''separation of powers.'' Separation = different branches. Checks = each branch can limit the others.","tip":"For comparison questions, use a table format: feature | presidential | parliamentary. This helps organize your answer clearly.","related_topics":["Constitution","Nigerian government","Electoral systems"]}},{"id":"forms_memory_01","type":"memory_hook","order":8,"content":{"text":"Presidential: President separate, fixed term, both heads. Parliamentary: PM from parliament, removable, separate head of state. Federal: shared power. Unitary: central power.","hook_type":"mnemonic"}},{"id":"forms_reflection_01","type":"reflection","order":9,"content":{"question":"Why did Nigeria choose a presidential system instead of the parliamentary system it inherited from Britain?","expected_understanding":"Nigeria''s ethnic diversity made parliamentary systems unstable — coalition governments collapsed easily. A strong president was seen as more stable. However, the presidential system has its own challenges: executive dominance and corruption."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"In a parliamentary system, the head of government is the:","options":[{"label":"A","text":"President"},{"label":"B","text":"Prime Minister"},{"label":"C","text":"Monarch"},{"label":"D","text":"Speaker"}],"answer":"B","explanation":"In a parliamentary system, the Prime Minister is the head of government. The monarch/president is usually head of state.","hints":["Who runs the day-to-day government?"]},{"difficulty":"medium","question":"Which system has a strict separation between the executive and legislature?","options":[{"label":"A","text":"Parliamentary"},{"label":"B","text":"Presidential"},{"label":"C","text":"Confederal"},{"label":"D","text":"Unitary"}],"answer":"B","explanation":"In a presidential system, the president and cabinet are separate from the legislature.","hints":["Which system keeps the executive out of the legislature?"]},{"difficulty":"jamb","question":"The principle that each branch of government can limit the powers of the other branches is called:","options":[{"label":"A","text":"Separation of powers"},{"label":"B","text":"Checks and balances"},{"label":"C","text":"Federalism"},{"label":"D","text":"Rule of law"}],"answer":"B","explanation":"Checks and balances allow each branch to limit the others. Separation of powers divides the branches.","hints":["Separation = dividing. Checks = limiting each other"]}]'::jsonb, '{"min_score":80,"required_sections":["forms_hook_01","forms_intuitive_01","forms_formal_01","forms_formula_01","forms_practice_01"]}'::jsonb, '1')
