INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('government', 'Arms of Government', 'Legislature, Executive, Judiciary', 'Arms of Government — Who Does What', '["Explain the functions of the legislature, executive, and judiciary","Understand the principle of checks and balances","Analyze the independence of the judiciary","Evaluate the relationship between the three arms"]'::jsonb, 'medium', '22', '[{"id":"arms_hook_01","type":"hook","order":1,"content":{"text":"Imagine a world where the person who makes the law also enforces it AND judges you when you break it. That''s tyranny. The separation of government into three arms — legislature, executive, judiciary — exists to prevent any one person or group from having too much power.","prediction_prompt":"Why is it dangerous for one person to make laws, enforce them, AND judge offenders?"}},{"id":"arms_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The legislature makes laws. The executive implements laws. The judiciary interprets laws. Think of it like a restaurant: the legislature writes the menu (laws), the executive kitchen staff prepares the food (implements), and the judiciary is the food inspector (ensures rules are followed). Each arm checks the others to prevent abuse.","analogy":"In football: the legislature is the rule-making body (FIFA). The executive is the referee (enforces rules). The judiciary is the appeals panel (interprets rules when disputed). Without separation, the team owner would make rules, referee matches, and judge disputes — obviously unfair."}},{"id":"arms_formal_01","type":"formal_explanation","order":3,"content":{"text":"Legislature: Makes laws, approves budgets, oversight of executive, represents people. Can be unicameral (one house) or bicameral (two houses). Executive: Implements laws, runs government, foreign policy, defense. Headed by President/PM. Judiciary: Interprets laws, settles disputes, protects rights, reviews constitutionality. Courts: Supreme, Appeal, High, Magistrate.","key_terms":[{"term":"Legislature","definition":"The law-making body of government (National Assembly in Nigeria)"},{"term":"Executive","definition":"The arm that implements and enforces laws (President and Ministers)"},{"term":"Judiciary","definition":"The arm that interprets laws and adjudicates disputes (Courts)"},{"term":"Judicial Independence","definition":"The principle that courts should be free from interference by other branches"}]}},{"id":"arms_formula_01","type":"formula","order":4,"content":{"formula":"Legislature makes → Executive implements → Judiciary interprets → Each checks the others","variables":[{"name":"Legislature","description":"Makes laws, approves budget, oversight"},{"name":"Executive","description":"Implements laws, runs government, commands armed forces"},{"name":"Judiciary","description":"Interprets laws, protects rights, reviews constitutionality"},{"name":"Checks","description":"Each arm can limit the others (e.g., veto, judicial review, impeachment)"}],"when_to_use":"For questions about government structure, separation of powers, or specific arm functions.","common_traps":["Confusing the roles — legislature makes, executive implements, judiciary interprets","Forgetting that checks and balances allow each arm to limit the others","Not knowing that the judiciary can declare laws unconstitutional (judicial review)"],"units_note":"Nigeria''s National Assembly has two chambers: Senate (109 members) and House of Representatives (360 members)."}},{"id":"arms_practice_01","type":"worked_example","order":5,"content":{"scenario":"The President refuses to sign a bill passed by the National Assembly. What power is the President exercising, and how can the legislature respond?","given":["Executive refusal to sign legislation"],"required":"Identify the constitutional power and legislative response","principle":"The president has veto power. The legislature can override with a two-thirds majority.","steps":[{"explanation":"Identify the President''s power","calculation":"Presidential veto — the power to reject a bill"},{"explanation":"Check the legislative response","calculation":"The National Assembly can override with 2/3 majority in both chambers"},{"explanation":"Apply checks and balances","calculation":"This is the legislature checking the executive''s veto power"},{"explanation":"Practical outcome","calculation":"If 2/3 of both houses vote to override, the bill becomes law without presidential assent"}],"answer":"The President is exercising veto power. The National Assembly can override with a two-thirds majority in both chambers.","check":"This is a key check and balance — the executive can reject laws, but the legislature can override."}},{"id":"arms_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The judiciary only settles disputes between citizens.","why_wrong":"The judiciary also reviews the constitutionality of laws and government actions (judicial review). It can strike down laws that violate the constitution.","correct_model":"The judiciary interprets the constitution, not just settles private disputes. Judicial review is a powerful check on the legislature and executive."}},{"id":"arms_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the functions of each arm, checks and balances, and judicial independence.","trap":"JAMB may ask about specific Nigerian institutions: NASS (legislature), President/ministers (executive), courts (judiciary). Know the structures.","tip":"For essay questions, always mention specific examples: ''The National Assembly exercises legislative power by...'' This shows practical understanding.","related_topics":["Constitution","Federalism","Rule of law"]}},{"id":"arms_memory_01","type":"memory_hook","order":8,"content":{"text":"Legislature = Laws. Executive = Execution. Judiciary = Justice. Each arm checks the others. Veto, override, judicial review, impeachment — these are the checks.","hook_type":"mnemonic"}},{"id":"arms_reflection_01","type":"reflection","order":9,"content":{"question":"Why is judicial independence important? What happens if the executive controls the courts?","expected_understanding":"If the executive controls courts, there''s no impartial judge of government actions. Citizens lose their protection against tyranny. Judicial independence ensures the law applies equally to everyone, including those in power."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which arm of government makes laws?","options":[{"label":"A","text":"Executive"},{"label":"B","text":"Judiciary"},{"label":"C","text":"Legislature"},{"label":"D","text":"Military"}],"answer":"C","explanation":"The legislature is the law-making body.","hints":["Legislative = law-making"]},{"difficulty":"medium","question":"The power of the judiciary to declare a law unconstitutional is called:","options":[{"label":"A","text":"Veto power"},{"label":"B","text":"Judicial review"},{"label":"C","text":"Impeachment"},{"label":"D","text":"Prerogative"}],"answer":"B","explanation":"Judicial review allows courts to strike down laws that violate the constitution.","hints":["The judiciary ''reviews'' the law against the constitution"]},{"difficulty":"jamb","question":"In Nigeria, which institution can override a presidential veto?","options":[{"label":"A","text":"The Supreme Court"},{"label":"B","text":"The National Assembly"},{"label":"C","text":"The State Governors"},{"label":"D","text":"The Electoral Commission"}],"answer":"B","explanation":"The National Assembly (both chambers) can override a presidential veto with a two-thirds majority.","hints":["Who has the power to make laws?"]}]'::jsonb, '{"min_score":80,"required_sections":["arms_hook_01","arms_intuitive_01","arms_formal_01","arms_formula_01","arms_practice_01"]}'::jsonb, '1')
