INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('government', 'Nigerian Government: Colonial Era', 'British Colonial Administration', 'Colonial Nigeria — How Britain Ruled', '["Trace the process of British colonization of Nigeria","Explain the system of indirect rule","Analyze the effects of amalgamation (1914)","Understand constitutional development during colonial rule"]'::jsonb, 'hard', '25', '[{"id":"col_hook_01","type":"hook","order":1,"content":{"text":"In 1914, Lord Lugard merged the Northern and Southern Protectorates into one country called Nigeria. He did this to save money — the North was losing revenue. But this ''merger'' created a country with over 250 ethnic groups, diverse religions, and different political systems. The consequences of this decision are still felt today.","prediction_prompt":"Why would merging two separate colonies into one country cause problems? What might go wrong?"}},{"id":"col_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Britain colonized Nigeria through three main phases: Lagos Colony (1861), Northern Protectorate (1900), Southern Protectorate (1900). In 1914, they merged all three into one country. The British used ''indirect rule'' — they didn''t govern directly but used traditional rulers (emirs, obas, chiefs) as intermediaries. This worked in the North but caused problems in the South.","analogy":"Think of indirect rule like a franchise system. The British were the head office. Traditional rulers were the franchisees — they ran local affairs according to British rules. But in the South, where traditional authority was weaker (especially among the Igbo), the ''franchise'' model didn''t work well."}},{"id":"col_formal_01","type":"formal_explanation","order":3,"content":{"text":"Colonial administration: (1) Indirect Rule — governing through existing traditional institutions. Worked in North (emirate system), failed in parts of South (acephalous Igbo society). (2) Amalgamation (1914) — merging North and Southern Protectorates. Lord Lugard''s wife named the country ''Nigeria.'' (3) Constitutional development: Clifford (1922), Richards (1946), Macpherson (1951), Lyttleton (1954). Each gave more Nigerian participation.","key_terms":[{"term":"Indirect Rule","definition":"British system of governing through existing traditional rulers and institutions"},{"term":"Amalgamation","definition":"The 1914 merging of Northern and Southern Protectorates into one Nigeria"},{"term":"Protectorate","definition":"A territory under British protection but not a colony"},{"term":"Clifford Constitution","definition":"1922 constitution that introduced legislative councils and elective principle"}]}},{"id":"col_formula_01","type":"formula","order":4,"content":{"formula":"Indirect Rule: British → Traditional Rulers → People. Worked where traditional authority was strong (North). Failed where it was weak (Igbo areas).","variables":[{"name":"North","description":"Emirate system with strong centralized authority — indirect rule worked well"},{"name":"South-West","description":"Oba system with structured hierarchy — indirect rule adapted"},{"name":"South-East","description":"Igbo acephalous system (no central ruler) — indirect rule failed, created warrant chiefs"},{"name":"Lagos","description":"Direct rule initially, then indirect rule after 1914"}],"when_to_use":"When asked about colonial administration or why different regions responded differently to colonial rule.","common_traps":["Forgetting that indirect rule was cheaper than direct rule — that''s why the British chose it","Not understanding why indirect rule failed in Igbo areas — no centralized authority","Confusing indirect rule with direct rule"],"units_note":"JAMB loves asking about indirect rule — its features, successes, and failures."}},{"id":"col_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain why indirect rule succeeded in Northern Nigeria but failed in parts of Southern Nigeria.","given":["Different responses to indirect rule in North and South"],"required":"Compare the two regions and explain the difference","principle":"Indirect rule works where traditional authority is centralized and accepted.","steps":[{"explanation":"Analyze the North","calculation":"Northern Nigeria had the emirate system — centralized, hierarchical, with the Emir as supreme authority. British used Emirs as intermediaries."},{"explanation":"Analyze the South","calculation":"Southern Nigeria (especially Igbo areas) had decentralized, acephalous societies. No single ruler to use as intermediary."},{"explanation":"Identify the problem","calculation":"The British created ''warrant chiefs'' in Igbo areas — people with no traditional authority. This caused resentment and resistance (Women''s War of 1929)."},{"explanation":"Conclusion","calculation":"Indirect rule depended on existing traditional structures. Where these structures were weak, the system failed."}],"answer":"Indirect rule succeeded in the North because of the centralized emirate system. It failed in Igbo areas because there was no centralized authority — the British-created warrant chiefs were resented.","check":"The Women''s War of 1929 (Aba Women''s Riot) was a direct response to indirect rule failure in the South."}},{"id":"col_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The British colonized Nigeria for the benefit of Nigerians.","why_wrong":"Colonialism was driven by British economic interests — raw materials, markets, and strategic advantage. Any benefits to Nigerians were incidental.","correct_model":"Colonialism was exploitative. The British extracted resources and labor while imposing foreign political and economic systems."}},{"id":"col_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests indirect rule, amalgamation, constitutional development, and the impact of colonialism.","trap":"JAMB may ask about specific constitutions (Clifford, Richards, etc.). Know: Clifford (1922) = elective principle. Richards (1946) = regional representation.","tip":"For essay questions on colonialism, structure your answer: Introduction → Indirect rule → Amalgamation → Constitutional development → Impact/Effects.","related_topics":["Pre-colonial government","Independence movement","Constitution"]}},{"id":"col_memory_01","type":"memory_hook","order":8,"content":{"text":"1914: Lugard amalgamates Nigeria. Indirect rule = British through traditional rulers. Worked in North (emirates), failed in Igbo areas (no central authority). Clifford (1922) = first elections.","hook_type":"mnemonic"}},{"id":"col_reflection_01","type":"reflection","order":9,"content":{"question":"How did the amalgamation of 1914 contribute to Nigeria''s political challenges today?","expected_understanding":"Forcing diverse ethnic groups with different political systems into one country created tensions that persist today: North-South divide, ethnic conflicts, resource control disputes, and debates about federalism."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Who was responsible for the amalgamation of Nigeria in 1914?","options":[{"label":"A","text":"Clifford"},{"label":"B","text":"Lord Lugard"},{"label":"C","text":"Macpherson"},{"label":"D","text":"Richards"}],"answer":"B","explanation":"Lord Lugard, the Governor-General, amalgamated the Northern and Southern Protectorates in 1914.","hints":["The last British colonial governor-general"]},{"difficulty":"medium","question":"Indirect rule failed in Igbo areas because:","options":[{"label":"A","text":"Igbo people were hostile"},{"label":"B","text":"There was no centralized authority to use as intermediary"},{"label":"C","text":"The British preferred direct rule there"},{"label":"D","text":"The Igbo had their own written laws"}],"answer":"B","explanation":"Igbo society was acephalous (no central ruler), so there was no one to serve as intermediary under indirect rule.","hints":["What was the key requirement for indirect rule to work?"]},{"difficulty":"jamb","question":"The 1922 Clifford Constitution is significant because it:","options":[{"label":"A","text":"Granted independence to Nigeria"},{"label":"B","text":"Introduced the elective principle"},{"label":"C","text":"Created the three regions"},{"label":"D","text":"Abolished indirect rule"}],"answer":"B","explanation":"The Clifford Constitution (1922) introduced elections — Nigerians could now vote for representatives in the legislative council.","hints":["What was new about this constitution?"]}]'::jsonb, '{"min_score":80,"required_sections":["col_hook_01","col_intuitive_01","col_formal_01","col_formula_01","col_practice_01"]}'::jsonb, '1')
