INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('government', 'Federalism in Nigeria', 'Structure and Practice', 'Federalism — Sharing Power in Nigeria', '["Define federalism and its features","Analyze the structure of Nigerian federalism","Evaluate revenue allocation and fiscal federalism","Identify challenges of federalism in Nigeria"]'::jsonb, 'hard', '25', '[{"id":"fed_hook_01","type":"hook","order":1,"content":{"text":"Nigeria has 36 states and a Federal Capital Territory. Each state has its own governor, house of assembly, and laws. But there''s also a federal government that controls the military, police, and foreign affairs. Why split power this way? Because in a diverse country, no single level of government can handle everything.","prediction_prompt":"If Nigeria were a unitary state (all power at the center), what problems might arise in a country with 250+ ethnic groups?"}},{"id":"fed_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Federalism is a system where power is divided between a central government and regional/state governments by a constitution. Neither level can abolish the other. Each level has its own responsibilities. This is ideal for diverse countries because it allows different groups to have some autonomy while remaining part of a larger nation.","analogy":"Think of federalism like a family compound. The family head (federal government) handles major decisions — family reputation, major investments. Each household (state government) manages its own affairs — cooking, cleaning, daily routines. Neither can interfere with the other''s responsibilities, but they share common goals."}},{"id":"fed_formal_01","type":"formal_explanation","order":3,"content":{"text":"Features of Nigerian federalism: (1) Division of powers — Exclusive list (federal only), Concurrent list (shared), Residual list (states). (2) Written constitution. (3) Independent judiciary (Supreme Court). (4) Bicameral legislature. (5) 36 states + FCT. Revenue allocation: Based on population, equality of states, internal revenue effort, land mass, and derivation (13% to oil-producing states).","key_terms":[{"term":"Federalism","definition":"A system of government where power is divided between central and regional governments by a constitution"},{"term":"Exclusive List","definition":"Matters only the federal government can legislate on (defense, foreign affairs, currency)"},{"term":"Concurrent List","definition":"Matters both federal and state governments can legislate on (education, health)"},{"term":"Residual List","definition":"Matters only state governments can legislate on (local government, traditional institutions)"}]}},{"id":"fed_formula_01","type":"formula","order":4,"content":{"formula":"Federal Structure: Federal Govt (defense, currency, foreign affairs) + State Govts (education, health, agriculture) + Local Govts (basic services)","variables":[{"name":"Exclusive List","description":"16 items — federal only (police, military, immigration, currency)"},{"name":"Concurrent List","description":"30 items — both levels (education, health, labor, roads)"},{"name":"Residual List","description":"Items not in other lists — states only (local govt, land matters)"},{"name":"Revenue","description":"Federal Account shared: 52.68% federal, 26.72% states, 20.60% LGAs"}],"when_to_use":"When asked about the structure of Nigerian federalism, division of powers, or revenue allocation.","common_traps":["Confusing exclusive and concurrent lists — exclusive = federal only, concurrent = both","Forgetting that local governments are the third tier of government","Not knowing the revenue allocation formula"],"units_note":"Nigeria practices ''fiscal federalism'' — the federal government controls most revenue and shares it with states."}},{"id":"fed_practice_01","type":"worked_example","order":5,"content":{"scenario":"A state government wants to build a new university. Can the federal government stop it? Can the state government establish its own police force?","given":["Two questions about federal-state relations"],"required":"Determine which level has authority in each case","principle":"Check which list each matter falls under.","steps":[{"explanation":"University (education)","calculation":"Education is on the Concurrent List — both federal and state can establish universities"},{"explanation":"Can federal stop it?","calculation":"No — states have the right to establish universities under concurrent jurisdiction"},{"explanation":"State police","calculation":"Police is on the Exclusive List — only the federal government can establish police"},{"explanation":"Conclusion","calculation":"States can build universities but cannot create their own police force"}],"answer":"States can establish universities (concurrent list). States cannot create police forces (exclusive list — federal only).","check":"This is why Nigeria has state universities but only one Nigeria Police Force."}},{"id":"fed_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"In a federation, the federal government is superior to state governments.","why_wrong":"In a true federation, neither level is superior — they are co-equal, each sovereign within its own sphere of authority.","correct_model":"Federal and state governments are co-equal. The constitution defines their respective powers. Neither can abolish the other."}},{"id":"fed_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the features of federalism, division of powers, and challenges of Nigerian federalism.","trap":"JAMB may ask about ''true federalism'' vs what Nigeria practices. Nigeria''s federalism is often called ''unitary federalism'' because the federal government dominates.","tip":"For questions on challenges, mention: state creation demands, revenue allocation disputes, local government autonomy, and ethnic tensions.","related_topics":["Revenue allocation","State creation","Constitution"]}},{"id":"fed_memory_01","type":"memory_hook","order":8,"content":{"text":"Federalism = shared power. Exclusive = federal only (police, army). Concurrent = both (education). Residual = states only. Revenue: 52.68% federal, 26.72% states, 20.60% LGAs.","hook_type":"mnemonic"}},{"id":"fed_reflection_01","type":"reflection","order":9,"content":{"question":"Is Nigeria''s federalism truly federal? What would ''true federalism'' look like?","expected_understanding":"Nigeria''s federalism is often criticized as too centralized — the federal government controls most revenue and powers. True federalism would give states more autonomy, control over resources, and genuine self-governance."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which of the following is on Nigeria''s Exclusive Legislative List?","options":[{"label":"A","text":"Education"},{"label":"B","text":"Police"},{"label":"C","text":"Agriculture"},{"label":"D","text":"Health"}],"answer":"B","explanation":"Police is on the Exclusive List — only the federal government can legislate on it.","hints":["Which of these is controlled only by the federal government?"]},{"difficulty":"medium","question":"The 13% derivation principle applies to revenue from:","options":[{"label":"A","text":"All states equally"},{"label":"B","text":"Oil-producing states"},{"label":"C","text":"The federal government"},{"label":"D","text":"Local governments"}],"answer":"B","explanation":"The 13% derivation principle ensures that 13% of revenue from natural resources goes to the producing states.","hints":["What states produce the resources?"]},{"difficulty":"jamb","question":"A major challenge of federalism in Nigeria is:","options":[{"label":"A","text":"Too many political parties"},{"label":"B","text":"Revenue allocation disputes between federal and state governments"},{"label":"C","text":"Too few states"},{"label":"D","text":"Lack of a written constitution"}],"answer":"B","explanation":"Revenue allocation — how to share oil revenue — is one of Nigeria''s most contentious federal issues.","hints":["What is the biggest source of conflict between federal and state governments?"]}]'::jsonb, '{"min_score":80,"required_sections":["fed_hook_01","fed_intuitive_01","fed_formal_01","fed_formula_01","fed_practice_01"]}'::jsonb, '1')
