INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'Introduction to History', 'Historical Methods and Sources', 'Introduction to History — Studying the Human Past', '["Define history and explain why the subject is studied","Distinguish between primary and secondary sources","Identify the main branches of history","Apply basic dating and periodisation to an event"]'::jsonb, 'easy', '18', '[{"id":"his_int_hook_01","type":"hook","order":1,"content":{"text":"Everything around you is a product of the past: the building you live in, the language you speak, the borders on a map, even the food you eat. History is the study of that past — not a list of names and dates, but an attempt to explain why the world looks the way it does today.","prediction_prompt":"If you could ask one person from 200 years ago only three questions, what would you ask and why?"}},{"id":"his_int_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Historians are detectives working with a long time gap and incomplete evidence. They gather evidence (sources), test it against other evidence, and build the most likely explanation. A source is anything that carries information about the past: an object dug from the ground, a document, a building, or the recorded memory of an eyewitness.","analogy":"Think of a historian as a detective at a crime scene a hundred years later. The ''scene'' is the past, the ''evidence'' is the sources, and the ''detective work'' is weighing how reliable each source is."}},{"id":"his_int_formal_01","type":"formal_explanation","order":3,"content":{"text":"Branches of history: (1) Political — rulers, wars, states and administration. (2) Economic — trade, agriculture, industry. (3) Social — class, family, gender, migration. (4) Cultural — religion, art, language, material and non-material culture. (5) Military — the conduct of war. Types of source: PRIMARY (created at the time of the event — oral traditions, artefacts, inscriptions, archives, eyewitness accounts) and SECONDARY (produced afterwards from primary evidence — textbooks, encyclopaedias, research papers). Key dating terms: BCE/AD (before/after the birth of Christ) and BP (before present, measured from 1950).","key_terms":[{"term":"History","definition":"The study of past human events and their causes and consequences"},{"term":"Primary Source","definition":"Evidence created during the period under study, e.g. a 1914 letter or a manila rope"},{"term":"Secondary Source","definition":"Evidence written after the event, e.g. a modern textbook"},{"term":"Chronology","definition":"The arrangement of events in order of time"},{"term":"Periodisation","definition":"Dividing history into named periods or eras"}]}},{"id":"his_int_formula_01","type":"formula","order":4,"content":{"formula":"Elapse of time = Later year − Earlier year. Explanation of a historical change = Long-term causes + Short-term triggers + Catalyst","variables":[{"name":"Long-term causes","description":"Deep, slow conditions that prepared the ground (e.g. colonial taxation, poverty)"},{"name":"Short-term triggers","description":"Events that brought tensions to a head (e.g. the 1929 Aba tax protests)"},{"name":"Catalyst","description":"The immediate spark that set events off (e.g. the arrest of women during the census)"}],"when_to_use":"When a JAMB question asks for the cause of a historical event, or when you must state how long an event lasted.","common_traps":["Listing only the trigger and forgetting long-term causes","Subtracting dates in the wrong order","Answering with causes of a different event because the names sound similar"],"units_note":"Years, counted AD; add or subtract once, never both."}},{"id":"his_int_practice_01","type":"worked_example","order":5,"content":{"scenario":"A student says the Asante Empire resisted British incursions in 1900 and fell in 1902. How long did the resistance last, and how would you classify the two pieces of evidence behind this claim?","given":["Evidence A: the 1900 Constitution (secondary source)","Evidence B: the looting and burning of the Asante palace at Kumasi, recorded by a British soldier (primary source)"],"required":"Calculate the duration and classify each source","principle":"Duration is the difference between the end and start years; classification depends on when the evidence was produced.","steps":[{"explanation":"Subtract to get the duration","calculation":"1902 − 1900 = 2 years"},{"explanation":"Classify Evidence A","calculation":"Written after the events → secondary source"},{"explanation":"Classify Evidence B","calculation":"Recorded by an eyewitness at the time → primary source"}],"answer":"The resistance lasted 2 years; the Constitution is a secondary source and the soldier''s account is a primary source.","check":"Always ask: who created this, and when?"}},{"id":"his_int_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"History is only the memorisation of names, dates and events.","why_wrong":"Events are the raw material, not the finished product. History is an explanation of cause, change and consequence — a list of dates answers what happened but never why.","correct_model":"History = evidence (sources) + explanation (causes and consequences) + judgement. Examiners award marks for reasons and effects, not only for dates."}},{"id":"his_int_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB introduction-to-history questions test the meaning of primary and secondary sources, the branches of history, and the difference between chronology and causation.","trap":"Do not call a written primary source ''secondary'' because it is in books. Written laws, treaties and letters written at the time are primary; a textbook commenting on them is secondary.","tip":"Answer with the sequence: evidence → why it is reliable → what it proves. Examiners reward ''source + reasoning'' pairs.","related_topics":["Primary and secondary sources","Branches of history","Periodisation"]}},{"id":"his_int_memory_01","type":"memory_hook","order":8,"content":{"text":"Primary = at the time (I saw it). Secondary = after the event (I read about it). Causes = long-term + short-term + catalyst. Duration = end year − start year.","hook_type":"mnemonic"}},{"id":"his_int_reflection_01","type":"reflection","order":9,"content":{"question":"Why do historians disagree about the same period, even when they use the same sources?","expected_understanding":"Because interpretation depends on which sources are emphasised, the historian''s own context and assumptions, and how much weight each source is given. Agreement improves when historians compare independent primary sources and state the limits of their evidence."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A treaty signed by a ruler in 1895 is best classified as:","options":[{"label":"A","text":"A primary source"},{"label":"B","text":"A secondary source"},{"label":"C","text":"An oral tradition"},{"label":"D","text":"Archaeological evidence"}],"answer":"A","explanation":"It was created at the time of the events it records, so it is a primary source.","hints":["Ask: created during the period, or after it?"]},{"difficulty":"medium","question":"Which of the following belongs to the economic branch of history?","options":[{"label":"A","text":"The life and times of a king"},{"label":"B","text":"The growth of the cocoa trade"},{"label":"C","text":"The spread of a language"},{"label":"D","text":"The conduct of a war"}],"answer":"B","explanation":"Economic history studies trade, production and distribution — such as the cocoa trade.","hints":["Which branch studies trade, production and markets?"]},{"difficulty":"jamb","question":"The study of material evidence such as pottery, tools and buildings belongs to:","options":[{"label":"A","text":"Oral history"},{"label":"B","text":"Archaeology"},{"label":"C","text":"Genealogy"},{"label":"D","text":"Chronology"}],"answer":"B","explanation":"Archaeology excavates and interprets physical (material) evidence of the past.","hints":["Which field digs things up?"]}]'::jsonb, '{"min_score":80,"required_sections":["his_int_hook_01","his_int_intuitive_01","his_int_formal_01","his_int_formula_01","his_int_practice_01"]}'::jsonb, '1')
