INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'Pre-Colonial Nigerian Societies', 'Early Civilizations and Kingdoms', 'Early Kingdoms of Nigeria — Societies Before Colonialism', '["Identify the major pre-colonial states and empires in Nigeria","Explain the role of trade in the growth of Nigerian states","Describe the social and political organisation of these societies","Compare the Nok, Kanem-Bornu, Oyo, Benin and Asante societies"]'::jsonb, 'medium', '22', '[{"id":"his_pre_hook_01","type":"hook","order":1,"content":{"text":"Long before European flags appeared on the coast, West Africa contained cities, courts, market systems and iron forges that impressed visitors such as Leo Africanus. Nigeria''s history did not begin in 1914 — it began with societies that built, governed, traded and wrote long before the Atlantic touched their shores.","prediction_prompt":"What do you think a society needs before it can build a large city? Name three things."}},{"id":"his_pre_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Pre-colonial states grew where three things came together: control of resources (gold, kola, salt, farmland), control of trade routes (river crossings, desert passes, ports), and the ability to command labour and tribute. Kingdoms such as Oyo, Benin and Asante were fiscal states as much as military ones — they grew wealthy by regulating trade rather than only by conquering.","analogy":"Imagine a market town sitting on the only paved road for miles around. Whoever controls the toll gate controls the wealth of every trader who passes. Many African kingdoms were built on exactly that kind of location."}},{"id":"his_pre_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key societies: (1) NOK (c. 1500 BCE – 2000 CE, Nok Plateau) — among the earliest West African iron smelters, famous for terracotta sculpture; a people, not a kingdom, with little political centralisation. (2) KANEM-BORNU (c. 700 – 1893, Lake Chad) — founded by the Sayfawa, who introduced the title Mai; the kingdom shifted from Kanem to Bornu as the Kanem region dried up. (3) OYO EMPIRE (c. 1300 – 1896, Yoruba) — ruled by an Alaafin, expanded into the Dahomey gap after the 17th-century Oyo civil wars, and produced slave caravans to the coast. (4) BENIN EMPIRE (1440 – 1897, Edo) — ruled by an Oba, famous for coral regalia, brass plaques and a highly organised guild system; destroyed in the 1897 punitive expedition. (5) ASANTE EMPIRE (1701 – 1902, Akan) — founded by Osei Tutu I around the Golden Stool, built on gold and slave trade, resisted the British at the Battle of Asantewaa (1900). (6) SOKOTO and KANO — Hausa city-states that grew from the 11th–14th centuries, later absorbed into the Sokoto Caliphate (see lesson 3).","key_terms":[{"term":"Alaafin","definition":"Title of the ruler of the Oyo Empire"},{"term":"Oba","definition":"Title of the ruler of Benin (Edo) state"},{"term":"Mai","definition":"Title of the ruler of Kanem-Bornu"},{"term":"Kola Nut","definition":"Hausa crop exchanged with southern Nigeria and the coast for goods; a major trade item"},{"term":"Tribute","definition":"Goods or labour sent to a ruler as a sign of allegiance"}]}},{"id":"his_pre_formula_01","type":"formula","order":4,"content":{"formula":"Growth of a pre-colonial state = Strategic location + Control of a trade item + Military or trading power + A legitimate title of succession","variables":[{"name":"Strategic location","description":"Rivers, passes or ports that force trade through the state"},{"name":"Trade item","description":"Kola nut, salt, gold, textile, horses, books"},{"name":"Legitimate title","description":"Ritual or constitutional basis of rule, e.g. the Golden Stool, the Ogboni, divine kingship"}],"when_to_use":"When asked why a particular kingdom grew powerful.","common_traps":["Confusing the Nok culture (a people) with a kingdom","Giving Oyo the Benin title Oba — Oyo''s ruler was the Alaafin","Placing Asante in Yorubaland — Asante is Akan"],"units_note":"Dates are approximate; say ''c.'' or ''about'' when a range is quoted."}},{"id":"his_pre_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain why the Hausa states of Kano, Katsina and Zazzau became wealthy, and identify the ruler title of one of them.","given":["Position: on the southern edge of the Sahara","Trade item: kola nut from the south; horses and textiles from the north"],"required":"Give a causal explanation and a title","principle":"States on trade routes between ecological zones grow rich because they tax and supply both ends of the trade.","steps":[{"explanation":"Location","calculation":"Kano and Katsina sat where desert routes met savanna markets"},{"explanation":"Trade control","calculation":"They collected kola and slaves from the south and exchanged them for horses, cloth, salt and books from the north"},{"explanation":"Political growth","calculation":"Wealth funded armies and paid officials, turning merchants'' cities into states"},{"explanation":"Title","calculation":"Sarki = ruler of a Hausa state, as in Sarkin Kano"}],"answer":"Their wealth came from controlling the trans-Saharan trade in kola nuts, horses and cloth; their rulers were called Sarki.","check":"Wealth first, political power second — trade usually funded the state."}},{"id":"his_pre_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Pre-colonial African states were primitive, shapeless and without law or government.","why_wrong":"Benin had an elaborate guild system, written laws and a professional military; Asante ran a confederacy with a council of states; the Hausa states had established dynasties and judicial systems. Complexity is not modernity — these were organised polities on their own terms.","correct_model":"Pre-colonial West Africa contained kingdoms, confederacies, trade networks and urban centres with their own institutions, laws and diplomatic customs."}},{"id":"his_pre_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB often asks you to match a state to its ruler title, capital, or a defining achievement.","trap":"Watch the near-misses: Oyo → Alaafin; Benin → Oba; Asante → Golden Stool; Kanem-Bornu → Mai; Sokoto → Caliph; Hausa states → Sarki.","tip":"For ''state and capital'' questions, memorise one pair a day: Oyo–Oyo-Ile, Benin–Benin-City, Asante–Kumasi, Sokoto–Sokoto, Kano–Kano.","related_topics":["Trans-Saharan trade","Islamic states","Coastal states"]}},{"id":"his_pre_memory_01","type":"memory_hook","order":8,"content":{"text":"Nok = terracotta and early iron. Kanem-Bornu = Mai, Lake Chad. Oyo = Alaafin, Yoruba. Benin = Oba, brass plaques. Asante = Osei Tutu, Golden Stool. Hausa states = Sarki.","hook_type":"mnemonic"}},{"id":"his_pre_reflection_01","type":"reflection","order":9,"content":{"question":"If trade built these states, how did the slave trade distort them by the 19th century?","expected_understanding":"Economies tilted towards capturing and exporting people rather than producing goods, which deepened violence between communities, starved farms of labour, enriched coastal middlemen and rulers, and weakened the institutions that had managed trade through recognised rules."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The title of the ruler of the Oyo Empire was:","options":[{"label":"A","text":"Oba"},{"label":"B","text":"Alaafin"},{"label":"C","text":"Mai"},{"label":"D","text":"Sarki"}],"answer":"B","explanation":"Oyo was ruled by an Alaafin; the Oba was the title in Benin.","hints":["Oba is Benin. Which title belongs to Oyo?"]},{"difficulty":"medium","question":"The Nok culture is best known for:","options":[{"label":"A","text":"The Golden Stool"},{"label":"B","text":"Terracotta sculpture and early iron working"},{"label":"C","text":"The trans-Saharan salt trade"},{"label":"D","text":"Brass casting in Benin"}],"answer":"B","explanation":"The Nok culture of the Jos Plateau is famous for terracotta heads and some of the earliest iron smelting in West Africa.","hints":["Where in Nigeria do terracotta heads come from?"]},{"difficulty":"jamb","question":"The Asante Empire was founded around the sacred symbol of the:","options":[{"label":"A","text":"Coral beads"},{"label":"B","text":"Golden Stool"},{"label":"C","text":"Kola nut"},{"label":"D","text":"Manila rope"}],"answer":"B","explanation":"Osei Tutu I founded the Asante Confederacy around the Golden Stool, which remains its royal seat of unity.","hints":["It is made of gold and is the seat of Asante unity."]}]'::jsonb, '{"min_score":80,"required_sections":["his_pre_hook_01","his_pre_intuitive_01","his_pre_formal_01","his_pre_formula_01","his_pre_practice_01"]}'::jsonb, '1')
