INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'The Sokoto Caliphate', 'The Jihad and its Impact', 'The Sokoto Caliphate — The Jihad and Its Impact', '["Explain how the Sokoto Caliphate was founded","List the states and peoples brought under Caliphate authority","Describe the administrative and legal changes the Caliphate introduced","Assess the impact of the jihad on West African societies"]'::jsonb, 'medium', '22', '[{"id":"his_sok_hook_01","type":"hook","order":1,"content":{"text":"In the early 1800s, thousands of Hausa families picked up their belongings and walked north. They were leaving Gobir, where the ruler had imposed harsh taxes, seized cattle and seized their daughters in place of tribute. Their destination was a small town called Sokoto, where a preacher named Usman dan Fodio had built a following. This migration, and the holy war that grew from it, created Africa''s largest 19th-century state.","prediction_prompt":"If a ruler taxes people into ruin and takes their children, what options do ordinary families have?"}},{"id":"his_sok_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Two separate things are often called ''the jihad''. First, the preaching of Usman dan Fodio, who argued that rulers who drank wine, taxed unjustly and oppressed the faithful must be replaced. Second, the military campaigns (futawa) that followed. When the Gobir king Yunfa died in 1808, the Caliphate was formally declared. Fulani jihad leaders then carried the movement beyond Hausaland: Modibo Adama into Adamawa, Omar Saidu into Borno, and the jihad into Yorubaland, where Ilorin was founded as a base in the 1820s.","analogy":"It is like a movement that starts as a sermon in a market and ends as a new constitution for half a continent — the preaching and the political project grew together."}},{"id":"his_sok_formal_01","type":"formal_explanation","order":3,"content":{"text":"FOUNDING: Usman dan Fodio''s migration from Gobir (c. 1804) to Sokoto; the death of Gobir''s Yunfa (1808) and the proclamation of the Caliphate; capital Sokoto. CALIPHS: Usman dan Fodio (1804–1817), Muhammad Bello (1817–1837), Sa''adu Abubakar (1837–1849), Ahmadu Rufai'' (1849–1862), Umaru Mudi (1862–1864), Ahmadu dan Fodio (1864–1866), Turbi (1866–1868), Ahmadu Bello (1868), Buba Jatau (1887–1893), Aliyu (1893–1902), Siddiq Abubakar III (1903–1906). TERRITORY: absorbed Gobir, Katsina, Daura, Zazzau, Nupe and Ilorin (nominally), extending into Adamawa and Borno. GOVERNMENT: the Caliph appoints emirs over the former Hausa states (an emir such as the Sarkin Shagari or the Emir of Katsina rules in the Caliph''s name); qadis administer Islamic law; provinces pay tribute (usually a tenth, zakata). SOCIETY: Islamic courts (qadi) replaced or sat alongside traditional courts; the kola trade continued but was now taxed by Caliphate officials.","key_terms":[{"term":"Jihad","definition":"Literally ''struggle''; in this context, holy war to purify and expand Islamic rule"},{"term":"Futawa","definition":"A military expedition or jihad campaign"},{"term":"Emir","definition":"A Muslim ruler installed by the Caliph to govern a province"},{"term":"Qadi","definition":"An Islamic judge"},{"term":"Zakata","definition":"Islamic almsgiving, a 2.5% wealth tax; used here as the main tribute"},{"term":"Caliph","definition":"Supreme leader of a Muslim state"}]}},{"id":"his_sok_formula_01","type":"formula","order":4,"content":{"formula":"Impact = Changed institutions + Changed economy + Changed society. Duration of an empire = Fall year − Foundation year","variables":[{"name":"Institution","description":"Emirs, qadi courts, centralised provinces replacing independent dynasties"},{"name":"Economy","description":"Taxed kola and caravan trade; tribute flowed to Sokoto"},{"name":"Society","description":"Scholar lineages (Saraq), new brotherhoods (Tijaniyya, Qadiriyya), more uniform Islamic law"}],"when_to_use":"When asked why the Caliphate lasted so long (it governed through local rulers rather than replacing them) or what it changed.","common_traps":["Saying the Caliphate created the Hausa states — they existed for centuries before 1804","Calling Sokoto the capital of a ''jihad state'' when the answer needed is the founding figure, Usman dan Fodio","Listing the wrong caliphs in an order question"],"units_note":"Sokoto fell to the British in 1903, about 95 years after 1808."}},{"id":"his_sok_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain how the Sokoto Caliphate could govern a territory larger than Nigeria from a single capital.","given":["Territory: Kano, Katsina, Zazzau, Nupe, Ilorin and parts of Adamawa","Population: many millions, many different communities"],"required":"Give an administrative explanation","principle":"Empires last by delegating power to local intermediaries who already command respect.","steps":[{"explanation":"Delegate","calculation":"The Caliph appointed emirs who were already accepted leaders"},{"explanation":"Legitimise","calculation":"Emirs ruled by the sharia, so the system was presented as God''s order, not conquest"},{"explanation":"Tax","calculation":"Provinces paid zakata to Sokoto, funding the army and courts"},{"explanation":"Trade","calculation":"The Caliphate protected the kola and caravan routes, so rulers grew rich"}],"answer":"It ruled indirectly through emirs and Islamic law, collected taxes, and protected the trade that made its provinces prosperous.","check":"Indirect rule through respected local rulers = long life."}},{"id":"his_sok_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The Sokoto Caliphate was a small state founded by one man in 1804 and destroyed within a generation.","why_wrong":"It grew into one of the largest states in 19th-century Africa, spanning from the Hausa states through Nupe to parts of Yorubaland and Adamawa, and lasted until the British conquest of 1903. Its founder, Usman dan Fodio, also wrote extensively and shaped Islamic scholarship.","correct_model":"Sokoto (1804–1903) was a long-lived Caliphate that delegated power to emirs, standardised Islamic law and taxed a vast trading region."}},{"id":"his_sok_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB asks about the founder, capital, caliphs, the spread of the jihad and the reasons Britain conquered it.","trap":"Do not confuse the Sokoto Caliphate with the Bornu Empire: both are Islamic, but Bornu''s ruler was the Mai, and Bornu was not conquered by the jihad.","tip":"For ''reasons for the British conquest of Sokoto in 1903'', answer: the Caliphate''s military and administrative strength after the Anglo-French agreement of 1898 fixed borders, and Britain needed to end the emirates'' independence and slave trading.","related_topics":["Kanem-Bornu","Islamic law in Nigeria","Anglo-French partition"]}},{"id":"his_sok_memory_01","type":"memory_hook","order":8,"content":{"text":"Sokoto: Usman dan Fodio, 1804 migration, 1808 Caliphate, capital Sokoto. Fell 1903. Ruled through emirs, taxed with zakata, spread via futawa to Ilorin, Nupe, Adamawa.","hook_type":"mnemonic"}},{"id":"his_sok_reflection_01","type":"reflection","order":9,"content":{"question":"If the Caliphate ruled through existing local rulers, was it a form of colonialism?","expected_understanding":"It resembles colonialism in mechanism — outsiders ruling through local intermediaries and extracting tribute — but differs in aim and legitimacy: Sokoto aimed to establish Islamic law and saw local rulers as illegitimate, whereas colonialism aimed at resource extraction. The comparison helps students analyse rather than judge."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Sokoto Caliphate was founded by:","options":[{"label":"A","text":"Modibo Adama"},{"label":"B","text":"Usman dan Fodio"},{"label":"C","text":"Omar Saidu"},{"label":"D","text":"Usman dan Katsina"}],"answer":"B","explanation":"Usman dan Fodio founded the Caliphate, migrating from Gobir to Sokoto and proclaiming it in 1808.","hints":["He also wrote a famous letter to the Sultan of Bornu."]},{"difficulty":"medium","question":"How did the Caliphate govern the former Hausa states?","options":[{"label":"A","text":"By destroying their rulers"},{"label":"B","text":"By appointing emirs to rule under Islamic law"},{"label":"C","text":"By selling the states to merchants"},{"label":"D","text":"By leaving them completely untouched"}],"answer":"B","explanation":"The Caliph appointed emirs who administered the provinces according to Islamic law and paid tribute to Sokoto.","hints":["The Caliph used local respected figures — what were they called?"]},{"difficulty":"jamb","question":"One major effect of the Sokoto Caliphate was:","options":[{"label":"A","text":"The spread of Islamic law and the appointment of emirs across Hausaland"},{"label":"B","text":"The introduction of Christianity"},{"label":"C","text":"The end of all trade"},{"label":"D","text":"The creation of Nigeria as a country"}],"answer":"A","explanation":"The Caliphate standardised Islamic law, appointed emirs, taxed the kola trade and extended Islamic authority to Nupe, Ilorin and Adamawa.","hints":["Think institutions, not geography — Nigeria as a country came much later."]}]'::jsonb, '{"min_score":80,"required_sections":["his_sok_hook_01","his_sok_intuitive_01","his_sok_formal_01","his_sok_formula_01","his_sok_practice_01"]}'::jsonb, '1')
