INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'European Contact and Slave Trade', 'The Atlantic Slave Trade and Its Effects', 'The Atlantic Slave Trade — Contact, Trade and Consequences', '["Outline how Europeans first made contact with West Africa","Explain how the slave trade operated (including the triangular trade)","Assess the economic, social and political effects on West Africa","State when the trade was abolished and by whom"]'::jsonb, 'medium', '24', '[{"id":"his_slave_hook_01","type":"hook","order":1,"content":{"text":"In 1485, an ambassador from the Oba of Benin arrived in Portugal bearing gifts of ivory and leopard skin. Benin was not a passive victim of Europe — it was an active diplomatic power trading on its own terms. Yet over the next three centuries, the Atlantic slave trade would reshape both societies, leaving wealth for some and ruin for millions.","prediction_prompt":"Why would Europeans sail thousands of kilometres to West Africa when there were no gold mines here to take home?"}},{"id":"his_slave_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Europeans wanted gold, ivory, pepper and slaves, but African states had strong armies and controlled their own trade. Early contact was therefore often diplomatic or parasitic: Europeans built forts (factories) at Badagry, Elmina and Ouidah, supplied guns and cloth, and paid for captives in goods rather than cash. Europeans rarely conquered the interior early on — they bought their way in, and African states competed to supply them.","analogy":"Imagine a shopkeeper who cannot take what he wants by force, so he pays a neighbour to bring it. For centuries, European traders did the same — turning African rivals into suppliers of captives."}},{"id":"his_slave_formal_01","type":"formal_explanation","order":3,"content":{"text":"CONTACT: Portuguese voyages from 1415 (Ceuta); Gil Eanes rounded Cape Bojador in 1444; the island of Arguin off Mauritania (1445); Benin sent an embassy to Portugal in 1485; the Portuguese ''factory'' (fort) at Badagry (c. 1485, Badagry Slave Castle); later Dutch, English, Danish and French forts at Elmina, Ouidah, Bonny and Calabar. THE TRIANGULAR TRADE: European manufactured goods (guns, cloth, rum, tobacco, ceramics) to West Africa; enslaved Africans across the Atlantic (Middle Passage); American commodities (sugar, tobacco, cotton, coffee) to Europe. Palm oil and groundnuts were African exports that went straight to Europe and so never crossed the Atlantic. NUMBERS: roughly 12.5 million Africans embarked on the Atlantic crossing from the 16th to the 19th century, and around 10.7 million arrived in the Americas; conditions on the Middle Passage made mortality appalling. AGENTS: African rulers and merchants supplied captives; European and African ''factors'' traded; victims were branded, shackled and marched to barracoons on the coast. ABOLITION: Britain abolished the slave trade in 1807 (Slave Trade Act), banned slavery in its empire in 1833, and ended the apprenticeship system in 1838; the trade continued illegally until the 1860s–70s.","key_terms":[{"term":"Middle Passage","definition":"The sea journey of enslaved Africans across the Atlantic"},{"term":"Barracoon","definition":"A coastal enclosure where captives were held before shipping"},{"term":"Triangle Trade","definition":"Three-legged trade linking Europe, Africa and the Americas"},{"term":"Legitimate Trade","definition":"19th-century coastal trade in commodities like palm oil and groundnuts, promoted as an alternative to the slave trade"},{"term":"Abolition","definition":"The legal end of the slave trade and of slavery"}]}},{"id":"his_slave_formula_01","type":"formula","order":4,"content":{"formula":"Trade flow = guns and cloth from Europe → captives from Africa → sugar, tobacco and cotton from the Americas to Europe. Not part of the triangle: palm oil and groundnuts went directly from Africa to Europe. Abolition chain = 1807 (British slave trade) → 1833 (Slavery Abolition Act) → 1838 (apprenticeship ends)","variables":[{"name":"Captive source","description":"Wars, raids, kidnapping, judicial sentences, and state-licensed slave markets"},{"name":"Coastal middlemen","description":"European factors and African merchants who bought and sold captives"},{"name":"Legitimate trade","description":"Palm oil, groundnuts, cotton, cocoa — the commodity trade promoted after 1807"}],"when_to_use":"When a question asks about the phases of the slave trade, or asks why the trade continued after abolition.","common_traps":["Believing Europeans raided the interior from the start — they bought from African suppliers","Confusing the 1807 abolition of the trade with 1833 abolition of slavery","Forgetting that the trade continued illegally after 1807"],"units_note":"Roughly 2 million Africans died during the Middle Passage alone; most captives came from West and Central Africa."}},{"id":"his_slave_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain why the slave trade was a ''trade'' rather than a European conquest, and state two consequences for West Africa.","given":["European powers built only a handful of coastal forts","West African states maintained strong armies"],"required":"Explain the mechanism and give two effects","principle":"When buyers cannot conquer sellers, they pay suppliers who compete with each other.","steps":[{"explanation":"Mechanism","calculation":"Europeans supplied guns, cloth and rum to African rulers and merchants who captured and sold captives"},{"explanation":"Consequence 1 — human","calculation":"Population loss, kidnapping, wars and instability, especially in the interior (e.g. Oyo''s civil wars and the wars of the 19th century)"},{"explanation":"Consequence 2 — economic","calculation":"Farm labour drained, production fell, and trade shifted towards slave commodities instead of manufactures"},{"explanation":"Consequence 3 — political","calculation":"Warfare was encouraged; rulers who captured more captives were richer and more secure"}],"answer":"It was a trade because Europeans paid African suppliers rather than conquering them; consequences included depopulation, violence and a distorted economy.","check":"Buyers bargaining with sellers = trade. Violence and depopulation = consequences."}},{"id":"his_slave_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The slave trade ended in 1807 when Britain abolished it.","why_wrong":"1807 ended the legal British trade, but the trade continued for decades illegally and under other flags, and slavery itself continued in the British Empire until the 1833 Slavery Abolition Act, with many victims kept in apprenticeship until 1838.","correct_model":"Treat abolition as a process with stages: 1807 (trade, British), 1833 (slavery, British Empire), 1838 (apprenticeship ends), and gradual suppression elsewhere into the late 19th century."}},{"id":"his_slave_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the triangular trade, the roles of African suppliers, abolition dates and the social/economic effects on West Africa.","trap":"Never answer that Europeans alone captured all captives. Examiners expect you to name African suppliers, coastal middlemen and the role of guns, and to acknowledge African states'' own economic motives.","tip":"For ''effects of the slave trade on Nigeria'', give at least two: depopulation and warfare; and two more: economic distortion (shift from subsistence and manufactured goods to slave and later palm oil exports) and social disruption (families separated, new diasporas in Brazil, Cuba and America).","related_topics":["Oyo civil wars","Legitimate trade and palm oil","Diaspora"]}},{"id":"his_slave_memory_01","type":"memory_hook","order":8,"content":{"text":"Portugal 1415 Ceuta, 1444 Bojador, 1485 Benin embassy. Forts: Badagry, Elmina, Ouidah, Bonny. Triangle = goods → captives → commodities. Abolition: 1807 trade, 1833 slavery, 1838 apprenticeship ends.","hook_type":"mnemonic"}},{"id":"his_slave_reflection_01","type":"reflection","order":9,"content":{"question":"Why is it important that African states participated in the slave trade, not only as victims?","expected_understanding":"Because it reveals how the trade worked through African political economies: rulers and merchants gained from captives, protected trade and faced strong incentives. It also keeps analysis honest — blaming Europe alone hides the internal conflicts and choices of the period, and hides how contemporaries understood their own options."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Britain abolished the slave trade in:","options":[{"label":"A","text":"1807"},{"label":"B","text":"1833"},{"label":"C","text":"1861"},{"label":"D","text":"1889"}],"answer":"A","explanation":"The Slave Trade Act of 1807 abolished the British slave trade; slavery itself was abolished in 1833.","hints":["The two dates are 1807 and 1833 — one is trade, one is slavery."]},{"difficulty":"medium","question":"In the triangular trade, what was sent from Europe to West Africa?","options":[{"label":"A","text":"Sugar and tobacco"},{"label":"B","text":"Manufactured goods such as guns, cloth and rum"},{"label":"C","text":"Captives"},{"label":"D","text":"Palm oil"}],"answer":"B","explanation":"Europeans exchanged manufactured goods and weapons for captives, who were then sent to the Americas, where sugar, tobacco and cotton were shipped back to Europe.","hints":["Think of the three corners: Europe → Africa → Americas → Europe."]},{"difficulty":"jamb","question":"Which of the following is NOT an effect of the slave trade on West Africa?","options":[{"label":"A","text":"Depopulation and loss of farm labour"},{"label":"B","text":"Increased warfare to capture captives"},{"label":"C","text":"A shift towards exporting slaves and later palm oil"},{"label":"D","text":"Rapid industrialisation"}],"answer":"D","explanation":"The slave trade did not industrialise West Africa; if anything, it diverted labour and capital away from manufacturing and towards capture and export of people.","hints":["Industrialisation needs investment in production — the trade worked against that."]}]'::jsonb, '{"min_score":80,"required_sections":["his_slave_hook_01","his_slave_intuitive_01","his_slave_formal_01","his_slave_formula_01","his_slave_practice_01"]}'::jsonb, '1')
