INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'British Colonization of Nigeria', 'Conquest and Colonial Administration', 'British Colonization — Conquest and Colonial Administration', '["Explain how Britain came to control Nigeria","Describe indirect rule and the constitutional changes it brought","Explain how taxation and forced labour funded the colony","Trace the growth of Nigerian nationalism in response to colonial rule"]'::jsonb, 'medium', '26', '[{"id":"his_col_hook_01","type":"hook","order":1,"content":{"text":"In 1861 British warships bombarded Lagos and Oba Dosunmu''s men fought them off in the streets of the city, and in 1897 a British punitive expedition burned Benin City to the ground, looting thousands of bronze plaques. Yet Britain''s real achievement was not conquest but administration — building roads, courts and taxes so that the territory paid for itself. Nigeria was ruled for about four decades before Nigerians decided they would rather rule themselves.","prediction_prompt":"Why would colonial officials build roads, courts and schools in a country they were exploiting?"}},{"id":"his_col_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Britain''s problem was that it did not want to govern 37 million people directly. Frederick Lugard''s solution — indirect rule — was elegant: keep traditional rulers in place, make them collect taxes and keep the peace, and put British advisers beside them. For ordinary people this meant that their own chiefs became tax collectors for foreigners, which is why indirect rule produced both colonial cooperation and fierce resistance.","analogy":"It is like inviting a headteacher to keep the school running while someone else controls the timetable and the fees. The headteacher still has authority, but the money goes to a new owner."}},{"id":"his_col_formal_01","type":"formal_explanation","order":3,"content":{"text":"CONQUEST: Royal Niger Company chartered 1886, consolidating Niger Coast Protectorate claims (Goldie, the ''sharing formula'' 1887); Lagos ceded by Oba Dosunmu in 1861; Southern Nigeria and Northern Nigeria Protectorates declared in 1900 after the conquest of Sokoto (1903) and Bida (1901) and the Anglo-French boundary agreement of 1898 (border demarcated 1899); the 1896 Benin massacre provoked the punitive expedition of 1897; amalgamation of Northern and Southern Nigeria in 1914. ADMINISTRATION: indirect rule under Frederick Lugard (Governor-General from 1900); colonial taxation (direct taxation in the Northern provinces from 1901, hut and kasa taxes; the Aba Women''s War of 1929 protested the Women''s Tax); forced labour and conscription (1918–1919 recruitment campaign); land progressively vested in the Crown, beginning with the 1900 Lagos lands ordinance and extended to the Northern Protectorate by the Land and Native Rights Ordinance of 1910; railways Lagos–Kano (1911), Lagos–Ibadan (1908) and Port Harcourt–Maiduguri (1916); cash-crop economy in cocoa, groundnuts and cotton; doctrine of ''indirect rule'' formalised in the Clifford Constitution (1920), Richards Constitution (1944), Macpherson Constitution (1951) and the Lyttleton Federal Constitution (1954). ECONOMICS: colonial revenue came from taxes, not trade — the colony had to pay for itself, which forced cash crops and conscription.","key_terms":[{"term":"Indirect Rule","definition":"Governing through existing traditional rulers and institutions under British supervision"},{"term":"Protectorate","definition":"A territory whose rulers were kept in place under British ''protection'' rather than annexed outright"},{"term":"Royal Niger Company","definition":"Chartered company (1886) that administered parts of Nigeria before direct British rule in 1900"},{"term":"Aba Women''s War","definition":"1929 protest by the women of Aba in the Eastern Region against the Women''s Tax and the arrest of women during a census"},{"term":"Lyttleton Constitution","definition":"1954 constitution that established a federal system with regions and a House of Representatives"}]}},{"id":"his_col_formula_01","type":"formula","order":4,"content":{"formula":"Colonial growth = Economic motive + Technology (railway, telegraph, weapons) + Existing local allies + Legal cover (charters, treaties, conventions)","variables":[{"name":"Economic motive","description":"Trade, raw materials, strategic interest and the need for the territory to pay for itself"},{"name":"Technology","description":"Railways, telegraph, Maxim guns, steam shipping"},{"name":"Existing local allies","description":"Emirs, paramount chiefs and warlords who cooperated to keep order and collect tax"},{"name":"Legal cover","description":"Treaties of cession, charters, the Berlin Conference''s Act, doctrine of effective occupation"}],"when_to_use":"When asked to explain how Britain conquered and administered Nigeria, or why conquest was possible at all.","common_traps":["Saying Britain conquered everything at once — conquest took decades (1897–1903) and relied on allies","Saying land was seized from chiefs outright — it was vested in the Crown, while customary rights were recognised only inconsistently","Confusing protectorate with colony: a colony is annexed directly; a protectorate keeps its rulers"],"units_note":"Key dates: 1886 charter, 1899 amalgamation of protectorates, 1900 direct rule, 1914 amalgamation, 1920 Clifford Constitution, 1944 Richards, 1954 Lyttleton."}},{"id":"his_col_practice_01","type":"worked_example","order":5,"content":{"scenario":"In 1929 women of the Abokio area of the Eastern Region protested a special tax on women. Why did they feel able to protest, and what did the protest achieve?","given":["A new ''women''s tax'' on market traders","The warrant chief was about to replace the Mbakio women''s leadership","Soldiers were sent, and the leader Nnondi Ogbonna was arrested"],"required":"Explain the causes and the consequences","principle":"Colonial taxation of women who were already being displaced politically produced organised resistance that forced concessions.","steps":[{"explanation":"Economic cause","calculation":"Women traders faced a direct tax on their income, on top of existing burdens"},{"explanation":"Political cause","calculation":"The warrant chiefs'' takeover of community government removed the women elders'' authority"},{"explanation":"Catalyst","calculation":"The Women''s War began when soldiers surrounded the market, allegedly over the census, and arrested Nnondi Ogbonna"},{"explanation":"Consequence","calculation":"The Eastern Region government later made concessions on the tax, and later a commission recommended women chiefs and free ''women''s summons''"}],"answer":"Economic and political oppression plus the arrest of their leader triggered the war; it won concessions on the women''s tax and later reforms for women chiefs.","check":"Tax + power + arrest = protest. Protests force concessions."}},{"id":"his_col_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Colonial rule in Nigeria was simply ''bad'' — nothing positive came out of it.","why_wrong":"This is a one-sided claim. Indirect rule did preserve some traditional institutions and introduced formal courts, railways, schools and cash-crop production — many of which later served Nigerians. The historian''s job is to weigh gains against losses: infrastructure against extraction, mass education against a system designed to produce clerks.","correct_model":"Colonial rule was simultaneously modernising and exploitative; assess both, using evidence, rather than labelling the whole era good or bad."}},{"id":"his_col_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests reasons for colonisation, the instruments of rule (indirect rule, taxation, forced labour), the Aba Women''s War, constitutional reforms, and the growth of nationalist organisations.","trap":"For ''why did Britain colonise Nigeria?'', never give only one reason. Examiners expect several: economic (trade and raw materials), strategic (denying France and Germany), administrative (the Royal Niger Company wanted its investment secured), and ideological (civilising mission and missionary protection).","tip":"Chronology drill for constitutional questions: Clifford 1920 → Richards 1944 → Macpherson 1951 → Lyttleton 1954 (federalism).","related_topics":["Nationalism","Aba Women''s War","Amalgamation of 1914"]}},{"id":"his_col_memory_01","type":"memory_hook","order":8,"content":{"text":"Royal Niger Company 1886, RNC lapses 1900, Lugard indirect rule, Protectorates 1900, Amalgamation 1914, Clifford 1920, Richards 1944, Macpherson 1951, Lyttleton 1954.","hook_type":"mnemonic"}},{"id":"his_col_reflection_01","type":"reflection","order":9,"content":{"question":"Why did the same colonial system that built railways and schools also produce the nationalist movement that overthrew it?","expected_understanding":"Every modernising element of colonial rule was double-edged. Railways, schools and courts created an educated class that read the same ideas of self-determination that colonial officials used; the educated elite then applied those ideas to Nigeria itself. Indirect rule also created grievances by making traditional rulers agents of foreign taxation."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Royal Niger Company was chartered in:","options":[{"label":"A","text":"1861"},{"label":"B","text":"1886"},{"label":"C","text":"1900"},{"label":"D","text":"1914"}],"answer":"B","explanation":"The Royal Niger Company was chartered in 1886 to administer British claims along the Niger; its charter was suspended in 1900.","hints":["It was a company, not a colony — before direct rule."]},{"difficulty":"medium","question":"Indirect rule meant that Britain:","options":[{"label":"A","text":"Ruled directly through resident commissioners"},{"label":"B","text":"Governed through existing traditional rulers and institutions"},{"label":"C","text":"Abolished all traditional titles"},{"label":"D","text":"Allowed Nigerians to elect their own governments"}],"answer":"B","explanation":"Indirect rule preserved traditional rulers as subordinate administrators who collected taxes and maintained order under British supervision.","hints":["Traditional rulers stayed, but took orders from London."]},{"difficulty":"jamb","question":"One reason for the Aba Women''s War of 1929 was:","options":[{"label":"A","text":"The introduction of a special tax on women traders"},{"label":"B","text":"A shortage of kola nuts"},{"label":"C","text":"A dispute between Britain and France"},{"label":"D","text":"The abolition of the warrant chiefs"}],"answer":"A","explanation":"The Women''s War was triggered by a new tax on women, political marginalisation of women, and the arrest of the women leader Nnondi Ogbonna.","hints":["Look for the economic trigger: a tax on a group that traded in markets."]}]'::jsonb, '{"min_score":80,"required_sections":["his_col_hook_01","his_col_intuitive_01","his_col_formal_01","his_col_formula_01","his_col_practice_01"]}'::jsonb, '1')
