INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'Nigerian Nationalism', 'The Struggle for Independence', 'Nigerian Nationalism — The Struggle for Independence', '["Define Nigerian nationalism and identify its early forms","Trace the growth of nationalist organisations from 1900 to 1960","Explain the constitutional route to independence","State the events of 1959–1963 that produced the republic"]'::jsonb, 'medium', '26', '[{"id":"his_nat_hook_01","type":"hook","order":1,"content":{"text":"Nigerian nationalism did not begin in 1960. In 1908 Lagos market women rioted over the Land Bill, which claimed the land under their markets for British use. By 1934 the Nigerian Youth Movement was already pressing for ''nigerisation'' of the civil service. Independence in 1960 was the end of a sixty-year argument that began in the markets.","prediction_prompt":"Who would you expect to lead a movement for self-government — farmers, market women, soldiers, or teachers? Why?"}},{"id":"his_nat_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Nationalism matured in three stages. Early nationalism (1900–1930) was protest by people whose livelihoods were hit: market women, students and the newly educated. Organisational nationalism (1934–1945) built parties, newspapers and programmes — the Nigerian Youth Movement, then the NCNC. Mass nationalism (1945–1960) mobilised workers, farmers, women and students through strikes, petitions and mass political parties, until self-government became impossible to refuse.","analogy":"It grew like a tree: roots in the market riots of 1908, a trunk in the parties of the 1940s, and branches in the mass campaigns that made self-government unavoidable."}},{"id":"his_nat_formal_01","type":"formal_explanation","order":3,"content":{"text":"EARLY PROTESTS: Lagos land riots (1908); Ekum and Satiru revolts (1880s–1906); Aba Women''s War (1929) in the Eastern Region; Women''s Union movement in Lagos (early 1920s, Funmilayo Ransome-Kuti). THE ELITE AND ''NIGERIANISATION'': Nigerian Youth Movement (1934), founders Ernest Ikoli and H.O. Davies, first to demand the ''nigerisation'' of the civil service and the end of expatriate control of government. Newspapers as political weapons: West African Pilot (Nnamdi Azikiwe, 1937), Lagos Daily News (Herbert Macaulay, 1925). PARTY FORMATION: National Council of Nigeria and Cameroons (NCNC, 1944), Action Group (1951, Obafemi Awolowo), Northern People''s Congress (1950, Tafawa Balewa and Sa''adu Zungur), United Middle Belt Congress (1955, Joseph Tarka), United Labour Congress (Nigerian Labour Congress, 1942; general strike 1945). CONSTITUTIONAL MILESTONES: Richards Constitution (1944) → Cable House Memorandum (1946, rejecting immediate self-government) → Macpherson Constitution (1951, mostly regional autonomy) → Duke of Edinburgh''s visit (1953) and acceptance of self-government at federal level → Lyttleton Constitution (1954, federalism and elected House of Representatives). In 1954 women of the Western Region got the vote, and in 1955 the National Day of 1 October was declared; the Federation gained full powers in 1958 after the Constitutional Conference. INDEPENDENCE: general election 1959; Balewa (NPC–coalition) became Prime Minister; independence on 1 October 1960 within the Commonwealth, with Elizabeth II as Queen of Nigeria; the 1960 elections produced the first federal government; Nigeria became a republic on 1 October 1963 with Nnamdi Azikiwe as first President (ceremonial) and Balewa as Prime Minister. National Day of Nigeria''s independence marked the end of colonial rule and the beginning of self-government.","key_terms":[{"term":"Nationalism","definition":"A movement to secure self-government and independence for Nigeria"},{"term":"NCNC","definition":"National Council of Nigeria and Cameroons (1944), the first nationalist coalition, led by Nnamdi Azikiwe and Herbert Macaulay"},{"term":"Nigerianisation","definition":"The demand that Nigerians replace expatriate officials in senior posts"},{"term":"Action Group","definition":"Founded 1951 by Obafemi Awolowo in the Western Region; a centre of progressive politics"},{"term":"Independence","definition":"1 October 1960 — Nigeria became a self-governing nation within the Commonwealth"}]}},{"id":"his_nat_formula_01","type":"formula","order":4,"content":{"formula":"Nigerian nationalism = constitutional agitation + mass mobilisation + international pressure. Route to independence = Petition → Constitutional conference → Self-government → Independence within the Commonwealth → Republic","variables":[{"name":"Constitutional agitation","description":"Conferences and memoranda (Cable House 1946, Lyttleton 1954) pushing devolution"},{"name":"Mass mobilisation","description":"Strikes, market protests, student and party campaigns"},{"name":"International pressure","description":"Post-war British weakness, the Atlantic Charter, UN support for self-determination (Resolution 1514, 1960) and Pan-Africanism"}],"when_to_use":"When asked why independence came in 1960 rather than earlier, or how nationalists achieved their aim without violence.","common_traps":["Saying Britain ''gave'' independence — Britain granted it because a strong, largely peaceful movement made it impossible to refuse","Confusing independence (1960) with the republic (1963) and with ''National Day'' (1955)","Naming the NCNC as the party of 1959 — the NPC-led coalition was in power"],"units_note":"Key dates: 1934 NYM, 1944 NCNC, 1951 Macpherson, 1954 Lyttleton, 1959 election, 1960 independence, 1963 republic."}},{"id":"his_nat_practice_01","type":"worked_example","order":5,"content":{"scenario":"Compare the methods of the Lagos market women''s protests (1908–1929) with those of the NCNC (1944–1960). Which was more effective, and why?","given":["Market women''s protests were local, spontaneous and defensive","The NCNC was a national party with programmes and leaders"],"required":"Compare methods and judge effectiveness","principle":"Protest movements raise the price of repression and educate the public; organised national parties turn anger into negotiation.","steps":[{"explanation":"Protest method","calculation":"Riot and petition in defence of immediate rights (land, market, tax)"},{"explanation":"Party method","calculation":"Petitions to the Secretary of State, constitutional memoranda, electoral participation"},{"explanation":"Effectiveness","calculation":"Protest won local concessions but little national change; the NCNC''s sustained pressure led to self-government in 1960"},{"explanation":"Link","calculation":"Protest movements (e.g. Aba 1929) and parties were mutually reinforcing"}],"answer":"The NCNC was more effective nationally because it combined sustained pressure, elections and negotiation, whereas protest movements won only local concessions.","check":"Protest wins battles; organisation wins campaigns."}},{"id":"his_nat_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Nigerian independence in 1960 was a gift from Britain with no role for Nigerians.","why_wrong":"The movement for self-government spanned 1908 to 1960 — market women, students, the Nigerian Youth Movement, the NCNC, Action Group, the NPC and the trade unions all forced changes. Britain agreed because after the Second World War it was financially weakened and faced pressure from its own public and the United Nations.","correct_model":"Independence resulted from British weakness plus Nigerian pressure plus the international context; British concessions were negotiated responses to demands, not generosity."}},{"id":"his_nat_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB asks about nationalist parties and leaders, the constitutional route to independence, and the events of 1960 and 1963.","trap":"Know the party–leader pairs: NYM – Ikoli; NCNC – Azikiwe (with Macaulay); Action Group – Awolowo; NPC – Balewa (with Zungur). Confusing Azikiwe and Awolowo is a classic source of lost marks.","tip":"For ''reasons for Nigerian nationalism'', list at least four: educated elite, economic hardship, British post-war weakness, international pressure (UN, Pan-Africanism), mass mobilisation, and the growth of a national identity after amalgamation.","related_topics":["Constitutional development","Post-Independence Nigeria","Pan-Africanism"]}},{"id":"his_nat_memory_01","type":"memory_hook","order":8,"content":{"text":"NYM 1934 (Ikoli), NCNC 1944 (Azikiwe/Macaulay), NPC 1950 (Balewa), Action Group 1951 (Awolowo), UMBC 1955 (Tarka), Independence 1960, Republic 1963 (Azikiwe president).","hook_type":"mnemonic"}},{"id":"his_nat_reflection_01","type":"reflection","order":9,"content":{"question":"Why did the nationalists generally choose negotiation over armed struggle, and what did that choice mean for the new nation?","expected_understanding":"Negotiation matched a movement led by lawyers, teachers, journalists and chiefs — people whose power lay in public opinion, elections and the courts rather than in armies. It preserved lives and unity, but it also handed power to a small educated elite who had no experience in governing a federation of three very different regions, which shaped the crises of the 1960s."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Nigerian Youth Movement was founded in:","options":[{"label":"A","text":"1934"},{"label":"B","text":"1944"},{"label":"C","text":"1951"},{"label":"D","text":"1958"}],"answer":"A","explanation":"The Nigerian Youth Movement was founded in 1934 and became the first nationalist group to campaign for the ''nigerisation'' of the civil service.","hints":["It predates the NCNC by ten years."]},{"difficulty":"medium","question":"Who led the Action Group, founded in 1951?","options":[{"label":"A","text":"Nnamdi Azikiwe"},{"label":"B","text":"Obafemi Awolowo"},{"label":"C","text":"Tafawa Balewa"},{"label":"D","text":"Joseph Tarka"}],"answer":"B","explanation":"Obafemi Awolowo founded and led the Action Group in the Western Region; Azikiwe led the NCNC, Balewa the NPC and Tarka the UMBC.","hints":["One leader per party: which one was Western?"]},{"difficulty":"jamb","question":"Nigeria became a republic on:","options":[{"label":"A","text":"1 October 1960"},{"label":"B","text":"1 October 1963"},{"label":"C","text":"1 October 1955"},{"label":"D","text":"1 May 1960"}],"answer":"B","explanation":"Nigeria became independent on 1 October 1960 with Elizabeth II as Queen of Nigeria, and became a republic on 1 October 1963 with Nnamdi Azikiwe as first President.","hints":["1960 = independence. What year was the republic?"]}]'::jsonb, '{"min_score":80,"required_sections":["his_nat_hook_01","his_nat_intuitive_01","his_nat_formal_01","his_nat_formula_01","his_nat_practice_01"]}'::jsonb, '1')
