  updated_at = now();

INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'Post-Independence Nigeria', 'Political Development Since 1960', 'Post-Independence Nigeria — Political Development Since 1960', '["Describe Nigeria''s political development from 1960 to date","Explain the causes and consequences of the civil war","Identify the features of Nigeria''s major republics (First Republic to Fourth Republic)","Assess the role of the military in Nigerian politics"]'::jsonb, 'hard', '28', '[{"id":"his_post_hook_01","type":"hook","order":1,"content":{"text":"In 1960 Nigeria was praised in the world''s press as a model of racial harmony — the largest country in Africa, united by a federal constitution. Fifteen years later it was at war with itself, and by 1983 soldiers had overthrown an elected civilian government. Independence did not guarantee stability; it handed a young nation three regions, a fragile revenue system, and armies full of ambitions.","prediction_prompt":"What happens when a country becomes independent while its regions are unequal in size, revenue and military strength?"}},{"id":"his_post_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Nigerian politics after independence has been shaped by four forces. Regionalism: the three regions (Northern, Western, Eastern) each dominated by one party, so national parties became regional parties. Ethnicity: religious and ethnic identity became the strongest political currency. Resources: oil revenue from 1958 made the federal centre more powerful than any region, and control of the centre became worth fighting for. Military: successive coups removed the civilian politicians who could not manage these forces.","analogy":"Think of post-independence Nigeria as three big families sharing one house, one water tap that suddenly began to run with oil, and a fifth relative who kept changing the locks."}},{"id":"his_post_formal_01","type":"formal_explanation","order":3,"content":{"text":"INDEPENDENCE ERA (1960–1963): parliamentary government, Balewa as Prime Minister and Nnamdi Azikiwe as Governor-General. FIRST REPUBLIC (1963–1966): Azikiwe became the first President and head of state while Balewa stayed Prime Minister. Regionally based parties — NPC in the North, Action Group in the West, NCNC in the East — dominated politics, and the ''no doctrine of necessity'' meant parties rarely crossed regional lines. 1964 revenue sharing strengthened the federal centre. MILITARY ERA: 15 January 1966 coup removed the civilian government; another coup in July 1966 killed many senior officers; the Civil War (1967–1970) followed, with the secession of the Republic of Biafra under Lt. Col. Ojukwu; Gowon became Head of State (1966–1975), creating states on a doctrine of necessity; 12 states by 1967, more in 1976. Military–civilian cycles: Murtala Mohammed/Obasanjo (1975–1979), Buhari (1983–1985), Babangida (1985–1993), Abacha (1993–1998), Abdulsalami (1998–1999). SECOND REPUBLIC (1979–1983): Shagari''s civilian government, which ended in a December 1983 coup. THIRD REPUBLIC aborted in 1993. FOURTH REPUBLIC (1999–present): return to civilian rule under the 1999 Constitution (state structure of 36 states + FCT created 1996), with successive civilian presidents — Obasanjo, Umaru Yar''Adua, Goodluck Jonathan, Muhammadu Buhari — a return to the 1999 Constitution and the adoption of the Truth, Reconciliation and Reparations Act (2008) after the Obasanjo era.","key_terms":[{"term":"Doctrine of Necessity","definition":"Military justification for creating new states to divide rivals and make them minority"},{"term":"Biafra","definition":"The secessionist Republic of Biafra (1967–1970) led by Ojukwu"},{"term":"Gowon","definition":"Military Head of State 1966–1975 who led Nigeria through the civil war and was overthrown in the 1975 coup"},{"term":"Fourth Republic","definition":"The civilian republic that began on 29 May 1999"},{"term":"State Creation","definition":"Splitting old regions into smaller states, used by successive military governments"}]}},{"id":"his_post_formula_01","type":"formula","order":4,"content":{"formula":"Civilian government ends when = regional/ethnic tension + unbalanced power + military ambition. Duration of a republic = Years in civilian rule vs years under the military","variables":[{"name":"Regional tension","description":"Rivalry between the three regions for control of federal power"},{"name":"Unequal power","description":"Ethnic imbalances and inequitable distribution of resources"},{"name":"Military ambition","description":"Coups as a way to seize the centre"}],"when_to_use":"When asked to explain the causes of the civil war or the recurring coups, and when comparing Nigeria''s republics.","common_traps":["Confusing the 1966 coups (which ended the First Republic) with independence in 1960","Saying Gowon created 12 states in 1976 — he created 12 states in 1967 after the civil war began, expanding to 19 by 1976","Forgetting that the Second Republic was Shagari (1979–1983) and was ended by the December 1983 coup"],"units_note":"Key dates: 1960 independence, 1963 republic, Jan 1966 coup, 1967–1970 civil war, 1979 Second Republic, 1983 coup, 1999 Fourth Republic."}},{"id":"his_post_practice_01","type":"worked_example","order":5,"content":{"scenario":"Give three reasons why the Nigerian civil war broke out in 1967, and two of its consequences.","given":["Federal abolition of the regional commissions and creation of 12 states","Continued army quarrel about leadership of the federal army","Fear that ''one man, one vote'' would end Igbo political dominance"],"required":"List three causes and two consequences","principle":"Coups and state creation removed the political settlement of the regions while the military remained unreconciled, and Nigeria''s federal system had never settled who controlled its resources and army.","steps":[{"explanation":"Political cause","calculation":"Regional commissions abolished; regions dismantled into states to reduce their power"},{"explanation":"Military cause","calculation":"Army mutinies and counter-coups over who led the federal army"},{"explanation":"Ethnic cause","calculation":"Fear of domination as a minority in the federation with ''one man, one vote''"},{"explanation":"Consequence 1","calculation":"Division of the country; over one million deaths; huge economic cost"},{"explanation":"Consequence 2","calculation":"Kaduna State created; economy devastated; lasting distrust between north and south"}],"answer":"Causes: dismantled regions, military rivalry and ethnic fear. Consequences: civil war with over a million deaths, creation of Kaduna State, and lasting economic and political distrust.","check":"Political, military, ethnic — three headings, three points."}},{"id":"his_post_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The civil war was simply ''Biafra versus Nigeria'' — a purely Igbo war.","why_wrong":"That ignores the federal government''s own role: it had just dismantled the regions, created states specifically to weaken regional power, and had purged Igbo officers and officials. It also ignores the fact that many non-Igbo people fought for the federal side, and that both sides committed atrocities.","correct_model":"The civil war was caused by both federal manipulations and ethnic anxiety, and fought by multiple peoples on both sides — a federal breakdown as much as an ethnic war."}},{"id":"his_post_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB focuses on the 1966 coups, the 1967–1970 civil war, state creation, and the pattern of military rule that ended with the Fourth Republic.","trap":"For ''reasons for the 1966 coup'', answers should include the failure of party politics, the strength of the military in a ''naira on every side'' situation, and the ethnic imbalances in the army.","tip":"Learn the pattern, not just the events: 1960 independence → 1963 republic → 1966 coups → 1967–70 civil war → 1979 Second Republic → 1983 coup → 1999 Fourth Republic. The pattern is ''civilian rule, then a coup, then another republic''.","related_topics":["Oil and the economy","State creation","The 1999 Constitution"]}},{"id":"his_post_memory_01","type":"memory_hook","order":8,"content":{"text":"First Republic 1963 (Azikiwe, Balewa). Coups Jan and July 1966. Civil war 1967–1970 (Biafra, Ojukwu). Gowon creates 12 states. Shagari 1979–1983. Fourth Republic 1999 (Obasanjo, Yar''Adua, Jonathan, Buhari).","hook_type":"mnemonic"}},{"id":"his_post_reflection_01","type":"reflection","order":9,"content":{"question":"How has oil affected the way Nigerians govern and relate to one another since 1958?","expected_understanding":"Oil revenue made the federal centre financially independent of the regions and enabled patronage, state creation and a culture of ''sharing'' the national cake without an economic base capable of producing it. It also raised the stakes of every political contest, made corruption and rent-seeking easier, and made sudden state-creation announcements cheaper than development planning."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Nigerian civil war lasted from:","options":[{"label":"A","text":"1960 to 1963"},{"label":"B","text":"1967 to 1970"},{"label":"C","text":"1975 to 1979"},{"label":"D","text":"1983 to 1985"}],"answer":"B","explanation":"The civil war (January 1967 – January 1970) was fought between the Federal Government and the secessionist Republic of Biafra.","hints":["Biafra seceded in 1967 and surrendered in 1970."]},{"difficulty":"medium","question":"One reason given for the January 1966 coup was:","options":[{"label":"A","text":"The failure of party politics to resolve ethnic and regional tensions"},{"label":"B","text":"A shortage of kola nuts"},{"label":"C","text":"A dispute with France"},{"label":"D","text":"The abolition of the Nnamdi Azikiwe"}],"answer":"A","explanation":"The coup was attributed to the failure of the party system, ethnic and regional tensions, and the military''s perception that civilian politicians had made the country ungovernable.","hints":["Think of the ''naira on every side'' army and the regional tensions."]},{"difficulty":"jamb","question":"The Fourth Republic in Nigeria began in:","options":[{"label":"A","text":"1979"},{"label":"B","text":"1983"},{"label":"C","text":"1993"},{"label":"D","text":"1999"}],"answer":"D","explanation":"Civilian rule was restored on 29 May 1999 under the 1999 Constitution, beginning the Fourth Republic.","hints":["It followed Abdulsalami''s handover after Abacha''s death."]}]'::jsonb, '{"min_score":80,"required_sections":["his_post_hook_01","his_post_intuitive_01","his_post_formal_01","his_post_formula_01","his_post_practice_01"]}'::jsonb, '1')
