INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'West African History', 'Major Empires and Civilizations', 'West African Empires — Ghana, Mali, Songhai and Kanem-Bornu', '["Describe the major West African empires and their founders","Explain the role of the trans-Saharan gold-salt trade","Identify the states'' rulers, capitals and achievements","Explain the causes of the decline of the western Sudanic empires"]'::jsonb, 'medium', '24', '[{"id":"his_wah_hook_01","type":"hook","order":1,"content":{"text":"In 1324 a West African ruler made the most famous pilgrimage in history: Mansa Musa of Mali walked through Cairo with so much gold that the value of gold in Egypt and the Middle East fell for years afterwards. He was not a poor man — Mali was one of the wealthiest states on Earth at that time. The story of the West African empires is really a story about trade: gold went south, salt and horses went north, and empires grew fat on the tolls.","prediction_prompt":"How might an empire grow rich without farming anything itself?"}},{"id":"his_wah_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The western Sudanic empires (Ghana, Mali, Songhai) and the eastern empire (Kanem-Bornu) were all merchant states. They did not conquer the goldfields or the salt mines; they controlled the roads between them. Their rulers taxed every load that passed, protected caravans against raiders, and settled disputes between traders. Their capitals were trading towns — Koumbi Saleh, Niani, Gao, Timbuktu — where Muslim scholars and merchants lived alongside rulers.","analogy":"It is like building a toll station at a mountain pass: you never own the gold, but if you control the only pass for hundreds of kilometres, everyone pays you."}},{"id":"his_wah_formal_01","type":"formal_explanation","order":3,"content":{"text":"GHANA EMPIRE (c. 300–1200, capital Koumbi Saleh): early state of the western Sudan, controlling the gold fields and the trans-Saharan route. Rulers titled the Ghana are recorded in Arab sources from about 700. Fell to the Almoravids (1054) and later to the Susu (c. 1200). MALI EMPIRE (c. 1235–1600, capitals Niani and Timbuktu): founded by Sundiata Keita after the Battle of Kirina (1235) against the Susu; extended control of the gold fields and the upper Niger; Mansa Musa (r. c. 1312–1348) made the hajj of 1324 and built the Djingareyber Mosque in Timbuktu; gold reached Europe and helped finance European growth; captured by Songhai in 1464. SONGHAI EMPIRE (c. 1464–1591, capitals Gao and Timbuktu): founded by Sunni Ali (r. 1464–1492) and Askia Muhammad (r. 1493–1529), who introduced the Askia tax system, appointed judges and provincial governors, and controlled the salt mines of Taghaza; ended when the Saadian dynasty of Morocco invaded and defeated Songhai at Tondibi (1591). KANEM-BORNU (c. 700–1893, Lake Chad): founded by the Sayfawa with the title Mai; traded across the Sahara to North Africa and Egypt; the capital shifted from Kanem to Bornu as the Kanem region became arid; famous for the Bagirmi and Kotoko kingdoms and later for the Kanem-Bornu scholarship traditions. ISLAM: all four empires were Muslim states by c. 1200, and Timbuktu''s Sankore, Djingareyber and Sidi Yahya mosques and the famous University of Timbuktu became centres of Islamic scholarship. SOURCES: Arabic geographers such as Al-Umari, Ibn Khaldun (who travelled to Mali c. 1350s), Leo Africanus (Timbuktu, 1512), and the Catalan Atlas (1375) which shows Mansa Musa enthroned holding a gold coin.","key_terms":[{"term":"Trans-Saharan Trade","definition":"Trade between West Africa and North Africa across the Sahara, in gold, salt, horses, cloth, dates and books"},{"term":"Sudanic","definition":"Of the savanna kingdoms south of the Sahara (Sudan = ''land of the blacks'' in Arabic geography)"},{"term":"Mansa","definition":"Title of the ruler of Mali; Mansa Musa was its most famous ruler"},{"term":"Mai","definition":"Title of the ruler of Kanem-Bornu"},{"term":"Taghaza","definition":"Saharan salt mine controlled and taxed by Ghana, Mali and Songhai"}]}},{"id":"his_wah_formula_01","type":"formula","order":4,"content":{"formula":"Empire wealth = Control of a trade route + tax on goods + military protection of caravans + a market city. Decline = Loss of a route or resource + conquest by a rival empire + internal disputes over succession + neglect of trade","variables":[{"name":"Route control","description":"Position between the goldfields and the salt/horse routes of the north"},{"name":"Tax","description":"Kurdin kasaba — a tax on goods entering and leaving the capital"},{"name":"Protection","description":"Armies defending caravans against raiders and rival states"}],"when_to_use":"When asked why these empires rose, or why they fell.","common_traps":["Calling Ghana ''the modern country of Ghana'' — the empire was in Mauritania/Mali, and its rulers were called Ghana","Placing Mali in East Africa — it is in West Africa, successor to Ghana, founder Sundiata","Saying Songhai fell to the British — it fell to Morocco at Tondibi (1591)"],"units_note":"Key dates: Kirina 1235, Mansa Musa''s hajj 1324, Songhai independence 1464, Tondibi 1591."}},{"id":"his_wah_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain why the trans-Saharan trade built Mali but also exposed it to conquest.","given":["Mali controlled the gold fields and taxed goods entering and leaving its capital","Mali depended on northern partners for horses, salt and arms"],"required":"Explain the rise and the vulnerability","principle":"States that tax a trade must depend on trade partners for goods it cannot produce itself.","steps":[{"explanation":"Rise","calculation":"Mali taxed and protected the gold trade, using the wealth to buy horses, arms and scholars from the north"},{"explanation":"Dependency","calculation":"Mali could not produce salt or horses itself, so it needed continued contact with the north"},{"explanation":"Vulnerability","calculation":"When neighbours in the north closed or redirected the routes, Mali''s revenue collapsed"},{"explanation":"Conquest","calculation":"Songhai expelled the Mali governor in 1464 and took control of the Niger bend"}],"answer":"The trade made Mali rich but dependent on northern partners, so when Songhai took control in 1464 the empire''s source of revenue collapsed.","check":"Wealth from trade = dependence on trade routes."}},{"id":"his_wah_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"These West African empires were wealthy only because they owned gold mines and slaves.","why_wrong":"The wealth came overwhelmingly from taxation and intermediation: they controlled routes and market towns between goldfields and Saharan salt, and from horses and manufactured goods. Mining was mostly in small hands, and the slave trade was a late, relatively minor element in the early empires.","correct_model":"The western Sudanic empires were merchant empires: rich because they controlled and taxed the routes, not because they owned the resources at their source."}},{"id":"his_wah_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests founder–empire pairs (Sundiata–Mali, Askia Muhammad–Songhai, Sayfawa–Kanem-Bornu), the gold-salt trade, and Timbuktu''s scholarly importance.","trap":"Be careful with ''Ghana'': the ancient Ghana Empire is not the modern Republic of Ghana. Also do not confuse Mali the empire with the modern Republic of Mali, nor Songhai with a Hausa state.","tip":"For ''importance of Timbuktu'', write four points: it was a trading and scholarly centre; it housed the Sankore University and great mosques; it produced Arabic chronicles of West Africa; and it was a centre of Islamic jurisprudence for the region.","related_topics":["Trans-Saharan trade","Islamic scholarship in Africa","Mansa Musa"]}},{"id":"his_wah_memory_01","type":"memory_hook","order":8,"content":{"text":"Ghana (Koumbi Saleh) → Mali (Sundiata, Mansa Musa, Timbuktu) → Songhai (Sunni Ali, Askia Muhammad; Tondibi 1591). Kanem-Bornu (Mai, Lake Chad). Gold south, salt and horses north.","hook_type":"mnemonic"}},{"id":"his_wah_reflection_01","type":"reflection","order":9,"content":{"question":"What do the West African empires teach us about how states are built and lost, and do they connect to Nigeria''s own history?","expected_understanding":"They show that control of routes, resources and legitimacy — not size alone — determines a state''s strength, and that states rise through taxation and scholarship as much as through armies. Nigeria inherits the same pattern: Hausa and Yoruba states grew on the kola trade, Sokoto on the kola and Sahara routes, and the modern state still depends on controlling routes and resources."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Mansa Musa was the ruler of:","options":[{"label":"A","text":"Songhai"},{"label":"B","text":"Mali"},{"label":"C","text":"Kanem-Bornu"},{"label":"D","text":"Ashanti"}],"answer":"B","explanation":"Mansa Musa (r. c. 1312–1348) was the famous emperor of Mali whose 1324 hajj to Mecca was legendary for its display of gold.","hints":["He is remembered for the hajj of 1324 and the Djingareyber Mosque."]},{"difficulty":"medium","question":"Songhai was finally defeated by:","options":[{"label":"A","text":"The British"},{"label":"B","text":"The Portuguese"},{"label":"C","text":"The Moroccan Saadian dynasty at Tondibi (1591)"},{"label":"D","text":"The Almoravids"}],"answer":"C","explanation":"Songhai was defeated by an invading Moroccan army from the Saadian dynasty at Tondibi in 1591, which led to the empire''s collapse.","hints":["The invaders came from the far north across the Sahara."]},{"difficulty":"jamb","question":"The main items exchanged in the trans-Saharan trade were:","options":[{"label":"A","text":"Gold from West Africa for salt, horses and cloth from the north"},{"label":"B","text":"Ivory for European cloth only"},{"label":"C","text":"Kola nuts for European guns only"},{"label":"D","text":"Slaves for European silver only"}],"answer":"A","explanation":"The gold-salt trade exchanged West African gold for Saharan salt, horses, cloth and dates; the direction of the trade was gold south, salt and horses north.","hints":["Follow the goods: gold from the goldfields, salt from the desert."]}]'::jsonb, '{"min_score":80,"required_sections":["his_wah_hook_01","his_wah_intuitive_01","his_wah_formal_01","his_wah_formula_01","his_wah_practice_01"]}'::jsonb, '1')
