INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'Colonialism in West Africa', 'The Scramble for Africa', 'Colonialism in West Africa — The Scramble for Africa', '["Explain the causes of the Scramble for Africa","Describe how European powers partitioned West Africa","Assess the effects of colonialism on West African societies","Explain why colonial borders created lasting problems"]'::jsonb, 'medium', '26', '[{"id":"his_col_wah_hook_01","type":"hook","order":1,"content":{"text":"In 1884–1885, European states met in Berlin and, in a drawing room, drew lines across a continent they had never travelled. Within thirty years, almost all of Africa was under European rule. For West Africans, the Scramble meant new taxes, new crops, new laws and new borders that split families and united strangers — and it created the map we still use today.","prediction_prompt":"If Europeans claimed territory they had never visited, on what basis did they decide who owned what?"}},{"id":"his_col_wah_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The Scramble was driven by four pressures: economic (raw materials and markets), strategic (national rivalry and naval bases), technological (steam, railways, Maxim guns, quinine and the telegraph made inland conquest possible) and ideological (a ''civilising mission'' that justified domination). Partition was usually quick: Britain claimed Sierra Leone, Gambia, the Gold Coast and Lagos; France took French West Africa (Senegal, Mali, Niger, Côte d''Ivoire, Dahomey, Guinea) and French Equatorial Africa; Germany took Togoland and Kamerun; Portugal kept Angola, Mozambique and Guinea-Bissau.","analogy":"It is like children drawing lines on a map and then declaring that the lines are boundaries: once the lines exist, the children are told to live inside them, and any family left outside must knock for entry."}},{"id":"his_col_wah_formal_01","type":"formal_explanation","order":3,"content":{"text":"CAUSES: industrial demand for raw materials (palm oil, rubber, cocoa, groundnuts, cotton); the search for new markets; rivalry among Britain, France, Germany and Portugal; the steamship, railway, telegraph and Maxim gun; missionary and humanitarian claims; the need for naval coaling stations (Freetown, Lagos, Luanda). THE BERLIN CONFERENCE (1884–1885): fourteen European powers met under Bismarck''s chairmanship and signed the General Act, which set the rules of ''effective occupation'' and free trade on the Congo, but drew no African boundaries. PARTITION: Britain — Gold Coast (1874 Gold Coast Colony; 1901 Ashanti and the Northern Territories Protectorate), Sierra Leone (1808 colony, 1896 protectorate), Gambia (1816, 1888), Lagos/Nigeria (1861, 1886 Royal Niger Company, 1900 protectorates); France — French West Africa (1895 federation: Senegal, Mauritania, Sudan, Guinea, Ivory Coast, Dahomey, Niger, Upper Volta), French Equatorial Africa (1910), French Togoland; Germany — Togoland, Kamerun, German South-West Africa, German East Africa; Portugal — Angola, Mozambique, Guinea-Bissau, Cape Verde, São Tomé. EFFECTS: cash-crop economies (cocoa in Ghana and Nigeria, groundnuts in Senegal, cotton in French West Africa); cash taxes (hut tax) to pay for forced labour and chiefs'' salaries; forced labour on farms, railways and mines; railways and roads built to move raw materials to the coast (Abidjan–Niger railway 1898–1904; Lagos–Kano 1911); European merchants, missionaries and administrators; European legal systems and Christianity; cash economy replacing subsistence; urban growth (Accra, Lagos, Dakar, Abidjan); resistance — the Asante wars in Ghana, Hut Tax revolts, Yohure (1895) and the Anglo-French boundary clashes in Sierra Leone, Maji Maji (1905–1907), Satiru (1906), the Aba Women''s War (1929), and the 1944 ''women''s war'' in the Eastern Region; BOUNDARIES: arbitrary lines drawn along latitudes and rivers divided ethnic groups (Mande, Hausa, Fulani, Yoruba, Igbo) and joined unrelated communities; the British–French boundary agreed in 1898 and demarcated in 1899 (the ''Ibi'' line) still causes friction today.","key_terms":[{"term":"Berlin Conference","definition":"1884–1885 meeting of European powers that set rules for claiming African territory"},{"term":"Effective Occupation","definition":"The rule that a claim counted only if the power actually controlled the territory"},{"term":"Hut Tax","definition":"A cash tax levied on huts or compounds, used to force Africans into cash crops and wage labour"},{"term":"Cession","definition":"The formal transfer of territory to a colonial power, often signed by a local ruler under pressure"},{"term":"Scarcity","definition":"The way colonial rule deliberately limited education and offices to prevent an African educated elite"}]}},{"id":"his_col_wah_formula_01","type":"formula","order":4,"content":{"formula":"Partition of a region = Claim (charter or treaty) + Effective occupation + Border demarcation + Administration (protectorate or colony). Effect of colonialism = Extraction (tax, forced labour, raw materials) − Development (infrastructure, education, courts)","variables":[{"name":"Claim","description":"Royal charter, treaty of cession, or occupation"},{"name":"Occupation","description":"Garrisons, administrators, ''effective occupation'' under the General Act"},{"name":"Demarcation","description":"Commission setting the line on the ground (e.g. 1899 Anglo-French boundary)"},{"name":"Extraction","description":"Hut tax, forced labour, cash crops for export, mineral royalties"},{"name":"Development","description":"Railways, schools, hospitals, formal courts — built mainly to serve extraction"}],"when_to_use":"When asked to explain how Africa was partitioned or to assess colonial legacies.","common_traps":["Saying the Berlin Conference drew Africa''s borders — it did not; it set rules for later claims","Forgetting Italy (Libya 1911) and Spain","Calling the Congo Free State a colony — it was Leopold II''s personal possession (1885–1908)"],"units_note":"Key dates: 1884–85 Berlin Conference, 1898–99 Anglo-French boundary, 1911 Italian Libya, 1919 League of Nations mandates."}},{"id":"his_col_wah_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain why a single colonial cash tax could transform West African farming, and give two consequences.","given":["The hut tax had to be paid in cash","Farmers could only earn cash by growing cash crops or working for wages"],"required":"Explain the mechanism and two consequences","principle":"A cash requirement forces households to abandon subsistence production and grow what the colony''s buyers wanted.","steps":[{"explanation":"Mechanism","calculation":"The tax must be paid in cash, so subsistence farming alone cannot satisfy it"},{"explanation":"Cash crop","calculation":"Farmers switch to cocoa, groundnuts or cotton for sale on world markets"},{"explanation":"Wage labour","calculation":"Young men migrate to mines, plantations and towns for wage work"},{"explanation":"Consequence 1","calculation":"Food security weakened; soil fertility fell; dependence on world prices"},{"explanation":"Consequence 2","calculation":"Wage labour, urbanisation and protest movements — e.g. the Maji Maji and Hut Tax revolts"}],"answer":"The cash tax forced a switch from subsistence farming to cash crops and wage labour, which weakened food security and provoked resistance.","check":"Cash requirement → production for market → protest."}},{"id":"his_col_wah_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The Berlin Conference divided Africa into fixed national states.","why_wrong":"It drew no borders at all — it merely agreed rules for claiming territory. The borders were drawn later, mostly by European powers with little or no African consultation, often along convenient lines (rivers, latitudes, desert edges).","correct_model":"The Berlin Conference set the procedure; the partition happened through later treaties, charters and boundary commissions, and those arbitrary lines survive as today''s borders."}},{"id":"his_col_wah_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the causes of the Scramble, the Berlin Conference, colonial administrative systems, colonial economies, resistance movements, and the lasting problem of artificial borders.","trap":"For ''reasons for the Scramble'', give at least three: economic (raw materials and markets), strategic (national rivalry), technological (steam, railways, Maxim guns) and ideological (civilising mission).","tip":"For ''problems of artificial boundaries'', write three: division of ethnic groups across borders (e.g. Mande, Hausa, Fulani), the forced union of communities with no shared identity, and disputes over resources and border control.","related_topics":["Imperialism","Resistance movements","Nigerian colonial history"]}},{"id":"his_col_wah_memory_01","type":"memory_hook","order":8,"content":{"text":"Berlin 1884–85 = rules, not borders. Britain (Gold Coast, Sierra Leone, Gambia, Nigeria), France (French West Africa 1895, Equatorial Africa 1910), Germany (Togoland, Kamerun), Portugal (Angola, Mozambique), Italy (Libya 1911). Cash tax → cash crops → revolt.","hook_type":"mnemonic"}},{"id":"his_col_wah_reflection_01","type":"reflection","order":9,"content":{"question":"Were colonial railways and schools a benefit, or were they simply tools of exploitation? Defend your answer.","expected_understanding":"Both can be true: railways moved crops to the coast rather than connecting regions, and schools were limited (scarcity) to produce clerks rather than leaders — but those same railways later carried goods and people within Nigeria, and those schools produced the nationalist elite. The evidence should support the judgement, and the judgement should be stated clearly."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Berlin Conference of 1884–1885 was held mainly to:","options":[{"label":"A","text":"Draw the borders of African states"},{"label":"B","text":"Set rules for claiming African territory"},{"label":"C","text":"Abolish the slave trade"},{"label":"D","text":"Grant independence to African states"}],"answer":"B","explanation":"The General Act set rules for claiming and governing territory (effective occupation, freedom of trade on the Congo); it drew no African boundaries.","hints":["Who drew the borders? Not the conference."]},{"difficulty":"medium","question":"Which European power formed French West Africa?","options":[{"label":"A","text":"France"},{"label":"B","text":"Britain"},{"label":"C","text":"Germany"},{"label":"D","text":"Portugal"}],"answer":"A","explanation":"France federated its West African possessions as French West Africa (1895) and later French Equatorial Africa (1910).","hints":["Obvious, but examiners test it as a baseline fact."]},{"difficulty":"jamb","question":"One lasting problem created by colonial boundaries in West Africa was:","options":[{"label":"A","text":"The disappearance of cash-crop farming"},{"label":"B","text":"The division of ethnic groups such as the Mande and Hausa across several countries"},{"label":"C","text":"The end of resistance movements"},{"label":"D","text":"Universal adoption of local currencies"}],"answer":"B","explanation":"Colonial borders cut across ethnic and political units, dividing groups such as the Mande, Hausa, Fulani and Yoruba among several states and joining communities with no shared history.","hints":["Look for the long-term effect on ethnic and political boundaries."]}]'::jsonb, '{"min_score":80,"required_sections":["his_col_wah_hook_01","his_col_wah_intuitive_01","his_col_wah_formal_01","his_col_wah_formula_01","his_col_wah_practice_01"]}'::jsonb, '1')
