INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('history', 'World History', 'Major World Events and Movements', 'World History — Major Movements That Shaped the Modern Age', '["Outline the major world historical movements from the 15th century to the present","Explain the causes and effects of the world wars and decolonisation","Connect world events to developments in West Africa and Nigeria","Arrange the main events of the modern era in correct chronological order"]'::jsonb, 'medium', '26', '[{"id":"his_world_hook_01","type":"hook","order":1,"content":{"text":"In 1914 a quarrel in Sarajevo set Europe on fire, and in 1945 the ruins of that fire produced the United Nations. Meanwhile, in 1919 the same war brought a demand for self-determination to Egypt and India — and, within decades, to Ghana and Nigeria. World history and Nigerian history are the same story told at different zooms.","prediction_prompt":"Why would a war fought in Europe lead to independence movements in West Africa?"}},{"id":"his_world_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Modern world history can be organised around three great forces. Economic: the expansion of markets, capitalism and later industry after about 1760. Political: the spread of nationalism, ideologies (liberalism, socialism, nationalism) and universal institutions such as the UN. Technological: printing, steam, electricity, the motor car, aircraft, radio and the computer. These forces combined to compress the world: by 1914 trade, empire and war were global, which is why events in Europe could decide the fate of Africa.","analogy":"It is like three rivers joining into one delta. Once they merge, you can no longer say where one ends and the other begins — which is why modern history must be read as a whole."}},{"id":"his_world_formal_01","type":"formal_explanation","order":3,"content":{"text":"AGE OF EXPLORATION AND RENAISSANCE (15th–16th centuries): Portuguese exploration (Prince Henry the Navigator, Gil Eanes 1444, Dias 1488, Vasco da Gama 1498 to India); Columbus''s Atlantic voyages (1492); the Renaissance in Italy (14th–16th centuries); the fall of Constantinople (1453) pushing Europeans to seek sea routes. REFORMATION (16th century): Martin Luther''s 95 Theses (1517); the Council of Trent (1545–1563); Henry VIII''s break with Rome (1534). MERCANTILISM then the ENLIGHTENMENT (17th–18th centuries): reason and natural rights (Locke, Rousseau, Voltaire); the American Declaration of Independence (1776); the French Revolution (1789) and the abolition of the slave trade by Britain (1807). INDUSTRIAL REVOLUTION (c. 1760–1840, Britain): factories, steam power (Watt''s improved steam engine, 1760s), railways, urban growth; colonial raw materials and overseas markets were central. IMPERIALISM (late 19th century): the Scramble for Africa (Berlin Conference 1884–85); the General Strike (Britain, 1907) and the ideology of the white man''s burden. THE WORLD WARS: First World War (1914–1918) — the alliance system, nationalism, militarism, assassination; the Russian Revolution (1917); the League of Nations (1920). Inter-war: the Great Depression (1929), mass unemployment, fascism and Nazism in Germany and Italy, and the rise of the USA and Japan. SECOND WORLD WAR (1939–1945): Nazi aggression and the Holocaust; total war; the United Nations Charter (signed 26 June 1945, in force 24 October 1945) with the Security Council veto. DECOLONISATION (1945–1975): independence for India and Pakistan (1947), Ghana (1957), Nigeria (1960) and dozens of others; the Cold War (c. 1947–1991) and its proxy conflicts; the Organisation of African Unity (1963) and the Non-Aligned Movement. POST-COLD-WAR: the Soviet collapse (1991), European integration (Maastricht 1993), globalisation, the internet and mobile technology, terrorist attacks (2001), the global financial crisis (2008), climate change, and the continuing inequality between the global North and South.","key_terms":[{"term":"Mercantilism","definition":"The early modern policy of accumulating bullion and colonies to strengthen a state"},{"term":"Nationalism","definition":"The drive of a people to be a sovereign nation; the root of the national states of the 19th–20th centuries"},{"term":"Industrial Revolution","definition":"The shift from hand production to machine factory production, beginning in Britain c. 1760"},{"term":"Cold War","definition":"The geopolitical, economic and ideological struggle between the USA and its allies and the USSR, c. 1947–1991"},{"term":"Decolonisation","definition":"The wave of independence movements that ended European empires after 1945"},{"term":"United Nations","definition":"The international organisation founded in 1945 to keep peace and promote cooperation, with the Security Council at its centre"}]}},{"id":"his_world_formula_01","type":"formula","order":4,"content":{"formula":"Cause of a world war = Long-term rivalries + Competition (empire, resources, arms) + Short-term triggers (alliances, assassination) + Failure of diplomacy. Decade chain = 1914–18 First World War → 1917 Russian Revolution → 1929 Great Depression → 1939–45 Second World War → 1945 UN → 1960 Nigerian independence → 1991 end of the Cold War","variables":[{"name":"Long-term rivalries","description":"Anglo-German, Franco-German and colonial competition"},{"name":"Competition","description":"Naval arms race, scramble for colonies, resource and market competition"},{"name":"Trigger","description":"The assassination of Archduke Franz Ferdinand at Sarajevo (June 1914)"},{"name":"Diplomatic failure","description":"July Crisis: the ultimatum, mobilisation schedules and blurred commitments"}],"when_to_use":"When asked to explain the causes of the world wars, or to arrange world events in order.","common_traps":["Saying the First World War was caused only by the assassination — it was the trigger, not the cause","Confusing the League of Nations (1920) with the United Nations (1945)","Placing the Industrial Revolution in the 19th century only — it began in the 1760s"],"units_note":"Key dates: 1453 Constantinople, 1517 Luther, 1789 French Revolution, 1760s Industrial Revolution, 1914–18 and 1939–45 world wars, 1945 UN, 1963 OAU."}},{"id":"his_world_practice_01","type":"worked_example","order":5,"content":{"scenario":"Trace the chain by which the Second World War led to Nigerian independence.","given":["European empires were financially exhausted after 1945","European states sought to limit the cost of rebuilding their empires","The United Nations General Assembly passed Resolution 1514 (1960) in favour of self-determination"],"required":"Explain the chain with at least three links","principle":"Great powers weakened by war lose the capacity to hold empires, and new international norms give subject peoples a language for their claims.","steps":[{"explanation":"Link 1 — exhaustion","calculation":"Britain and France were indebted and had lost life and wealth, so the cost of holding far-flung colonies was too high"},{"explanation":"Link 2 — the Cold War","calculation":"Both superpowers wanted allies, and anti-colonial movements became strategically useful"},{"explanation":"Link 3 — international norm","calculation":"UN General Assembly Resolution 1514 (1960) and the OAU (1963) gave nationalists international support"},{"explanation":"Link 4 — organisation","calculation":"Nigerian parties (NCNC, Action Group, NPC) had been built for decades, so pressure could be converted into negotiation"},{"explanation":"Result","calculation":"Independence in 1960 and republic in 1963"}],"answer":"Post-war European exhaustion plus Cold War competition plus UN support for self-determination plus decades of Nigerian party organisation produced independence in 1960.","check":"War weakens empires; organisation turns pressure into independence."}},{"id":"his_world_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The two world wars were caused by one thing each — alliances in 1914 and Hitler in 1939.","why_wrong":"The First World War grew from decades of imperial, naval and economic rivalry plus alliance obligations and a failed July Crisis; the Second grew from the punitive terms of 1919, the Great Depression, the rise of fascism, appeasement and Hitler''s expansion. Both also depended on nationalism and mass mobilisation.","correct_model":"World wars arise from the interaction of long-term rivalry, competition, militarisation and trigger events — not from a single person or a single treaty."}},{"id":"his_world_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB world-history questions test dates, causes and consequences of major movements and their links to Nigeria.","trap":"Be strict about chronology: Renaissance (14th–16th), Reformation (16th), Industrial Revolution (from 1760s), First World War (1914–18), Russian Revolution (1917), Great Depression (1929), Second World War (1939–45), UN (1945), decolonisation (1945–75), Nigerian independence (1960).","tip":"For ''causes of Nigerian independence'', link world history to local history: European post-war weakness, the Cold War, the UN, US pressure, and Nigerian nationalism.","related_topics":["Decolonisation","Cold War","Nigerian nationalism"]}},{"id":"his_world_memory_01","type":"memory_hook","order":8,"content":{"text":"1453 Constantinople, 1517 Luther, 1760s industry, 1789 French Revolution, 1807 abolition, 1914–18 World War I, 1917 Russia, 1929 Depression, 1939–45 World War II, 1945 UN, 1960 Nigeria, 1963 OAU, 1991 end of Cold War.","hook_type":"mnemonic"}},{"id":"his_world_reflection_01","type":"reflection","order":9,"content":{"question":"Which world-historical development most changed Nigerian daily life, and why?","expected_understanding":"Candidates include imperialism (borders, languages, institutions), industrialisation and trade (railways, exports), and the post-1945 world order (decolonisation, the Cold War, oil, global finance). The answer should argue from evidence: for example, oil''s discovery in 1956 tied Nigeria to world markets and shaped politics, education and migration far more than any single constitution."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The Industrial Revolution began in:","options":[{"label":"A","text":"Britain in the 18th century"},{"label":"B","text":"France in the 17th century"},{"label":"C","text":"Germany in the 19th century"},{"label":"D","text":"Italy in the 15th century"}],"answer":"A","explanation":"The Industrial Revolution began in Britain around 1760, with factory production, steam power and railways.","hints":["Which country first built steam-powered factories and railways?"]},{"difficulty":"medium","question":"The United Nations was founded in:","options":[{"label":"A","text":"1919"},{"label":"B","text":"1920"},{"label":"C","text":"1945"},{"label":"D","text":"1963"}],"answer":"C","explanation":"The United Nations Charter was signed in 1945; the League of Nations was the earlier body set up after the First World War in 1920.","hints":["The League came after 1914–1918; the UN after 1939–1945."]},{"difficulty":"jamb","question":"One long-term cause of the First World War was:","options":[{"label":"A","text":"Rivalries among European powers over empire, trade and arms"},{"label":"B","text":"The invention of the printing press"},{"label":"C","text":"The abolition of the slave trade"},{"label":"D","text":"The discovery of crude oil"}],"answer":"A","explanation":"Imperial, naval and commercial rivalries — especially between Germany and Britain — combined with alliance systems, militarism and nationalism to make war likely; the Sarajevo assassination was only the trigger.","hints":["One trigger, several causes."]}]'::jsonb, '{"min_score":80,"required_sections":["his_world_hook_01","his_world_intuitive_01","his_world_formal_01","his_world_formula_01","his_world_practice_01"]}'::jsonb, '1')
