INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('irs', 'Revelation of the Glorious Qur''an', 'Prophet''s Visits to Cave Hira', 'The First Revelation — When Allah Spoke to Muhammad', '["Describe the Prophet''s (SAW) visits to Cave Hira","Explain the circumstances of the first revelation","Differentiate between the modes of revelation","Understand why the Qur''an was revealed piecemeal"]'::jsonb, 'medium', '20', '[{"id":"irs_hook_01","type":"hook","order":1,"content":{"text":"In the year 610 CE, a 40-year-old man sat alone in a cave on Mount Nur, near Makkah. He was meditating, seeking truth. Then the angel Jibril appeared with a message that would change the world: ''Read, in the name of your Lord.'' This was the first revelation of the Glorious Qur''an.","prediction_prompt":"How would you feel if an angel appeared and told you to ''Read''? What would your reaction be?"}},{"id":"irs_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Before prophethood, Muhammad (SAW) often retreated to Cave Hira to meditate and reflect. He was troubled by the idolatry and injustice in Makkah. On the Night of Power (Laylatul Qadr), Angel Jibril came and commanded: ''Read (Iqra).'' Muhammad (SAW) replied: ''I am not a reader.'' This happened three times. Then the first verses were revealed: ''Read in the name of your Lord who created.'' (Q.96:1-5)","analogy":"Think of the first revelation like receiving the most important letter of your life. Muhammad (SAW) was alone, seeking guidance. The message came directly from Allah through Jibril. It was personal, powerful, and life-changing."}},{"id":"irs_formal_01","type":"formal_explanation","order":3,"content":{"text":"The first revelation occurred in 610 CE in Cave Hira. Angel Jibril brought the first 5 verses of Surah al-Alaq (Q.96:1-5). The Prophet (SAW) was terrified and returned home. Khadijah comforted him and took him to Waraqa ibn Nawfal, who confirmed it was a divine revelation. The Qur''an was revealed over 23 years, piecemeal, for specific occasions and needs.","key_terms":[{"term":"Wahy (Revelation)","definition":"Divine communication from Allah to His prophets through various modes"},{"term":"Jibril (Gabriel)","definition":"The angel assigned by Allah to deliver revelations to prophets"},{"term":"Laylatul Qadr","definition":"The Night of Power — when the first revelation occurred, better than 1000 months (Q.97:1-5)"},{"term":"Piecemeal Revelation","definition":"The Qur''an was revealed gradually over 23 years, not all at once (Q.17:106)"}]}},{"id":"irs_formula_01","type":"formula","order":4,"content":{"formula":"Modes of Revelation (Q.42:51): Inspiration behind the veil, Through an angel, Direct speech","variables":[{"name":"Direct Speech","description":"Allah spoke directly to Musa (Moses) at Mount Sinai"},{"name":"Through Angel","description":"Jibril brought revelations to Muhammad (SAW)"},{"name":"Inspiration (Ilham)","description":"Allah inspired the heart/mind of the Prophet (SAW)"}],"when_to_use":"When asked about how Allah communicated with His prophets.","common_traps":["Confusing the modes of revelation — they are not all the same","Thinking the entire Qur''an was revealed at once — it was gradual","Forgetting the role of Khadijah and Waraqa in confirming the revelation"],"units_note":"The piecemeal revelation allowed the early Muslims to learn and practice gradually."}},{"id":"irs_practice_01","type":"worked_example","order":5,"content":{"scenario":"Why was the Qur''an revealed gradually over 23 years instead of all at once?","given":["The manner of Qur''anic revelation"],"required":"Explain the wisdom behind piecemeal revelation","principle":"Allah''s wisdom in gradual revelation served multiple purposes.","steps":[{"explanation":"Easy to memorize","calculation":"Gradual revelation made it easier for companions to memorize and understand"},{"explanation":"Applied to events","calculation":"Verses were revealed for specific situations — providing guidance when needed"},{"explanation":"Gradual training","calculation":"Muslims could learn and practice Islam step by step"},{"explanation":"Evidence of truth","calculation":"The consistency of the Qur''an over 23 years proves its divine origin"}],"answer":"The piecemeal revelation allowed for easy memorization, application to specific situations, gradual training of Muslims, and demonstrated the Qur''an''s consistency and divine origin.","check":"Q.17:106 confirms: ''A Qur''an which We have divided into parts, so that you may recite it to people over a long period.''"}},{"id":"irs_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The Prophet (SAW) could read and write, so he composed the Qur''an.","why_wrong":"The Prophet (SAW) was ummi (unlettered) — he could not read or write. This is itself a miracle: an unlettered man produced the most eloquent Arabic text.","correct_model":"The Prophet (SAW) was unlettered. The Qur''an''s miraculous eloquence is evidence of its divine origin."}},{"id":"irs_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the first revelation, modes of revelation, and the piecemeal nature of the Qur''an.","trap":"JAMB may ask about specific Qur''anic verses related to revelation (Q.96:1-5, Q.42:51, Q.17:106). Know these references.","tip":"For essay questions, mention the key figures: Jibril, Khadijah, Waraqa. This shows comprehensive knowledge.","related_topics":["Preservation of the Qur''an","Tajwid","Hadith"]}},{"id":"irs_memory_01","type":"memory_hook","order":8,"content":{"text":"First revelation: Cave Hira, 610 CE, Jibril, ''Iqra'' (Read), Surah al-Alaq. Revelation over 23 years, piecemeal. Three modes: direct speech, through angel, inspiration.","hook_type":"mnemonic"}},{"id":"irs_reflection_01","type":"reflection","order":9,"content":{"question":"What does the Prophet''s (SAW) reaction to the first revelation (fear, running home) tell us about the nature of encountering the divine?","expected_understanding":"The Prophet''s (SAW) fear shows that encountering the divine is overwhelming. Even the best of humanity was terrified. This humbles us — the divine is beyond our comprehension, yet merciful enough to communicate with us."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Where did the first revelation take place?","options":[{"label":"A","text":"Masjid al-Haram"},{"label":"B","text":"Cave Hira"},{"label":"C","text":"Masjid al-Nabawi"},{"label":"D","text":"Mount Uhud"}],"answer":"B","explanation":"The first revelation occurred in Cave Hira on Mount Nur, near Makkah.","hints":["The cave where the Prophet (SAW) used to meditate"]},{"difficulty":"medium","question":"The first word revealed in the Qur''an was:","options":[{"label":"A","text":"Muhammad"},{"label":"B","text":"Allah"},{"label":"C","text":"Iqra (Read)"},{"label":"D","text":"Bismillah"}],"answer":"C","explanation":"The first word was ''Iqra'' (Read) — the opening of Surah al-Alaq (Q.96:1).","hints":["The command Jibril gave to the Prophet (SAW)"]},{"difficulty":"jamb","question":"The Qur''an was revealed piecemeal (gradually) to:","options":[{"label":"A","text":"Make it easier to forget"},{"label":"B","text":"Allow gradual learning and practice"},{"label":"C","text":"Show the Prophet was composing it"},{"label":"D","text":"Make the revelations longer"}],"answer":"B","explanation":"Gradual revelation allowed Muslims to learn, understand, and practice Islam step by step.","hints":["Why is gradual learning better than instant knowledge?"]}]'::jsonb, '{"min_score":80,"required_sections":["irs_hook_01","irs_intuitive_01","irs_formal_01","irs_formula_01","irs_practice_01"]}'::jsonb, '1')
