INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('irs', 'Preservation of the Glorious Qur''an', 'Compilation and Standardization', 'How the Qur''an Was Preserved Through the Ages', '["Trace how the Qur''an was recorded and compiled","Identify key companions involved in compilation","Differentiate between Makkan and Madinan surahs","Understand the standardization under Uthman (RA)"]'::jsonb, 'medium', '22', '[{"id":"irs2_hook_01","type":"hook","order":1,"content":{"text":"The Qur''an was revealed over 23 years, yet today millions of Muslims recite the exact same Arabic text — word for word, letter for letter. How was this possible? The answer lies in the meticulous preservation efforts of the Prophet (SAW) and his companions.","prediction_prompt":"How do you think the Qur''an was preserved before the invention of printing presses?"}},{"id":"irs2_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The Prophet (SAW) had scribes who wrote down each revelation as it came. Companions also memorized the entire Qur''an — some knew whole surahs by heart. After the Prophet''s death, the first Caliph Abu Bakr compiled the Qur''an into one book. The third Caliph Uthman standardized it, ensuring one统一 text for all Muslims.","analogy":"Think of the Qur''an''s preservation like a master copy. The Prophet (SAW) dictated, scribes wrote, companions memorized. Multiple copies were made. Uthman''s standardization ensured every copy was identical to the master."}},{"id":"irs2_formal_01","type":"formal_explanation","order":3,"content":{"text":"Preservation process: (1) During revelation: Scribes like Zaid ibn Thabit wrote on parchment, leather, bones. Companions memorized. (2) Abu Bakr''s compilation (632 CE): Collected all written fragments into one mushaf. (3) Uthman''s standardization (645 CE): Made copies, sent to provinces, burned variant copies. (4) Current mushaf: Based on Uthman''s standardization, with diacritical marks added later.","key_terms":[{"term":"Mushaf","definition":"The written compilation of the Qur''an in book form"},{"term":"Hafiz","definition":"One who has memorized the entire Qur''an"},{"term":"Qira''at","definition":"Variations in pronunciation of the Qur''an, all authentic"},{"term":"Diacritical Marks","definition":"Vowel marks added later to ensure correct pronunciation"}]}},{"id":"irs2_formula_01","type":"formula","order":4,"content":{"formula":"Compilation: Revelation → Oral + Written → Abu Bakr (collection) → Uthman (standardization) → Diacritics (final form)","variables":[{"name":"Revelation","description":"Over 23 years, piecemeal"},{"name":"Oral Tradition","description":"Companions memorized entire Qur''an"},{"name":"Written","description":"Scribes recorded on various materials"},{"name":"Abu Bakr","description":"First compilation into one book"},{"name":"Uthman","description":"Standardized text, distributed copies"}],"when_to_use":"When asked about the preservation process of the Qur''an.","common_traps":["Thinking the Qur''an was compiled only after the Prophet''s death — it was also written during his lifetime","Confusing Abu Bakr''s compilation with Uthman''s standardization","Forgetting that oral memorization was equally important as written record"],"units_note":"The Uthmanic mushaf remains the standard text used worldwide today."}},{"id":"irs2_practice_01","type":"worked_example","order":5,"content":{"scenario":"Explain the roles of Abu Bakr and Uthman in preserving the Qur''an.","given":["Two key figures in Qur''anic compilation"],"required":"Distinguish their contributions","principle":"Abu Bakr collected; Uthman standardized.","steps":[{"explanation":"Abu Bakr''s role","calculation":"After the Battle of Yamama, many hafiz died. Abu Bakr ordered Zaid ibn Thabit to collect all written fragments and memorized portions into one mushaf."},{"explanation":"Uthman''s role","calculation":"During Uthman''s caliphate, different dialects caused confusion. He ordered one standard text, sent copies to provinces, and burned variant copies."},{"explanation":"Why both were necessary","calculation":"Abu Bakr ensured the Qur''an was collected. Uthman ensured it was standardized and uniform."},{"explanation":"Legacy","calculation":"The Uthmanic mushaf is the basis of all Qur''ans printed today."}],"answer":"Abu Bakr compiled the first mushaf from written fragments and memorized portions. Uthman standardized the text, distributed copies to provinces, and removed variant readings.","check":"Q.15:9 confirms: ''We have sent down the Reminder (Qur''an) and We will preserve it.''"}},{"id":"irs2_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The Qur''an was compiled by one person at one time.","why_wrong":"It was a collective effort over time — from the Prophet''s scribes to Abu Bakr''s compilation to Uthman''s standardization.","correct_model":"The Qur''an''s preservation involved multiple people over multiple years, ensuring accuracy through both oral and written transmission."}},{"id":"irs2_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the compilation process, key companions, and Qur''anic preservation.","trap":"JAMB may ask about the difference between Makkan and Madinan surahs — Makkan = earlier, shorter, focused on belief. Madinan = later, longer, focused on law and community.","tip":"Know the key names: Zaid ibn Thabit (scribe), Abu Bakr (first compilation), Uthman (standardization).","related_topics":["Revelation of the Qur''an","Tajwid","Six authentic hadith collections"]}},{"id":"irs2_memory_01","type":"memory_hook","order":8,"content":{"text":"Abu Bakr = first compilation. Uthman = standardization. Zaid ibn Thabit = chief scribe. Oral + Written = dual preservation. Q.15:9 = Allah''s promise to preserve the Qur''an.","hook_type":"mnemonic"}},{"id":"irs2_reflection_01","type":"reflection","order":9,"content":{"question":"What does the meticulous preservation of the Qur''an tell us about the importance Muslims place on the text?","expected_understanding":"The extraordinary efforts to preserve every letter and word show that Muslims believe the Qur''an is the literal word of Allah — not a human composition. This reverence drives the preservation effort."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Who was the chief scribe of the Qur''an during the Prophet''s lifetime?","options":[{"label":"A","text":"Abu Bakr"},{"label":"B","text":"Zaid ibn Thabit"},{"label":"C","text":"Uthman"},{"label":"D","text":"Ali"}],"answer":"B","explanation":"Zaid ibn Thabit was the chief scribe who wrote down the revelations during the Prophet''s (SAW) lifetime.","hints":["The companion who compiled the Qur''an under Abu Bakr and Uthman"]},{"difficulty":"medium","question":"Uthman standardized the Qur''an to:","options":[{"label":"A","text":"Create a new version"},{"label":"B","text":"Remove Allah''s words"},{"label":"C","text":"Ensure one统一 text for all Muslims"},{"label":"D","text":"Translate it into other languages"}],"answer":"C","explanation":"Uthman standardized the text to prevent confusion from different dialects and variant readings.","hints":["Why would having different versions be problematic?"]},{"difficulty":"jamb","question":"The Qur''an is unique among scriptures because:","options":[{"label":"A","text":"It has never been changed"},{"label":"B","text":"It has been preserved in its original Arabic, letter for letter"},{"label":"C","text":"It was written by the Prophet (SAW)"},{"label":"D","text":"It contains no Arabic"}],"answer":"B","explanation":"The Qur''an has been preserved in its original Arabic text, with millions of hafiz worldwide ensuring its accuracy.","hints":["What makes the Qur''an''s preservation unique?"]}]'::jsonb, '{"min_score":80,"required_sections":["irs2_hook_01","irs2_intuitive_01","irs2_formal_01","irs2_formula_01","irs2_practice_01"]}'::jsonb, '1')
