INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('irs', 'Hadith Literature', 'History and Authentication', 'Hadith — The Sunnah of the Prophet (SAW)', '["Understand the importance of Hadith in Islam","Distinguish between the six authentic hadith collections","Explain the process of hadith authentication","Differentiate between Sahih, Hassan, and Da''if hadith"]'::jsonb, 'hard', '22', '[{"id":"irs3_hook_01","type":"hook","order":1,"content":{"text":"The Qur''an tells us to pray, but it doesn''t describe HOW to pray — how many rak''ahs, what to recite, the movements. The Prophet''s (SAW) example — his words, actions, and approvals — fills this gap. This is Hadith: the recorded Sunnah of the Prophet (SAW).","prediction_prompt":"If the Qur''an doesn''t describe how to pray in detail, where do Muslims get their prayer instructions?"}},{"id":"irs3_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Hadith is the record of the Prophet''s (SAW) sayings, actions, and silent approvals. It''s the second source of Islamic law after the Qur''an. Scholars developed a rigorous science to verify hadith — checking the chain of narrators (isnad) and the content (matn). Only authentic hadith can be used as evidence.","analogy":"Think of hadith authentication like fact-checking. Before publishing a story, a journalist verifies: Who said it? Who heard it? Is the chain reliable? Does the content make sense? Hadith scholars did the same — with even more rigor."}},{"id":"irs3_formal_01","type":"formal_explanation","order":3,"content":{"text":"Six authentic collections (Kutub al-Sittah): (1) Sahih al-Bukhari ( Imam al-Bukhari, 194-256 AH). (2) Sahih Muslim (Imam Muslim, 204-261 AH). (3) Sunan Abu Dawud. (4) Jami'' al-Tirmidhi. (5) Sunan al-Nasa''i. (6) Sunan Ibn Majah. Authentication: Isnad (chain of narrators) + Matn (content). Classification: Sahih (authentic), Hassan (good), Da''if (weak).","key_terms":[{"term":"Hadith","definition":"The record of the Prophet''s (SAW) sayings, actions, and silent approvals"},{"term":"Isnad","definition":"The chain of narrators who transmitted the hadith"},{"term":"Matn","definition":"The actual text/content of the hadith"},{"term":"Sahih","definition":"Authentic hadith with a continuous chain of reliable narrators"}]}},{"id":"irs3_formula_01","type":"formula","order":4,"content":{"formula":"Hadith Authentication: Isnad (narrator chain) + Matn (content) → Classification","variables":[{"name":"Sahih","description":"Authentic: continuous chain, reliable narrators, no hidden defects"},{"name":"Hassan","description":"Good: slightly less reliable chain but content is sound"},{"name":"Da''if","description":"Weak: unreliable narrator or broken chain — cannot be used as evidence"},{"name":"Mawdu''","description":"Fabricated: falsely attributed to the Prophet (SAW) — rejected entirely"}],"when_to_use":"When asked about hadith classification or authentication methodology.","common_traps":["Confusing the six collectors — each compiled different hadith, some overlapping","Thinking all hadith are equally authentic — only Sahih hadith are used as evidence","Forgetting that hadith complements the Qur''an, not contradicts it"],"units_note":"Al-Bukhari and Muslim are considered the most authentic collections."}},{"id":"irs3_practice_01","type":"worked_example","order":5,"content":{"scenario":"A hadith says: ''The Prophet (SAW) said: whoever prays Fajr in congregation is protected from Allah''s punishment.'' How do scholars determine if this hadith is authentic?","given":["A hadith requiring authentication"],"required":"Explain the authentication process","principle":"Scholars check the isnad (narrator chain) and matn (content).","steps":[{"explanation":"Check the Isnad","calculation":"Who narrated it? Did they meet the person they claim to have heard it from? Were they trustworthy and had a good memory?"},{"explanation":"Check the Matn","calculation":"Does the content contradict the Qur''an or established hadith? Is it reasonable?"},{"explanation":"Cross-reference","calculation":"Do other authentic hadith support this? Multiple chains strengthen a hadith."},{"explanation":"Classification","calculation":"If the chain is unbroken, narrators reliable, content sound → Sahih"}],"answer":"Scholars verify the isnad (each narrator must be trustworthy, have good memory, and directly heard from the previous narrator) and the matn (content must not contradict established sources).","check":"This hadith is found in Sahih al-Bukhari and Sahih Muslim — both authenticated it."}},{"id":"irs3_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The Prophet (SAW) wrote the hadith himself.","why_wrong":"The Prophet (SAW) generally discouraged writing down his hadith during his lifetime (to avoid confusion with the Qur''an). The hadith was recorded by companions after his death.","correct_model":"Hadith was transmitted orally during the Prophet''s lifetime, then recorded by companions and later scholars."}},{"id":"irs3_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the six hadith collectors, authentication process, and hadith classification.","trap":"JAMB may ask about specific hadith collectors. Know: Bukhari (most authentic), Muslim (second most), Abu Dawud (Sunan), Tirmidhi (Jami''), Nasa''i, Ibn Majah.","tip":"For essay questions, mention the importance of hadith: it explains the Qur''an, provides practical guidance, and is the second source of Islamic law.","related_topics":["The Qur''an","Islamic jurisprudence","The Prophet''s biography"]}},{"id":"irs3_memory_01","type":"memory_hook","order":8,"content":{"text":"Six collections: Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasa''i, Ibn Majah. Isnad = chain. Matn = content. Sahih = authentic. Hassan = good. Da''if = weak.","hook_type":"mnemonic"}},{"id":"irs3_reflection_01","type":"reflection","order":9,"content":{"question":"Why is the chain of narration (isnad) so important in hadith authentication?","expected_understanding":"The isnad ensures that the hadith can be traced back to the Prophet (SAW) through reliable, trustworthy people. Without a strong chain, we cannot be sure the hadith is genuinely from the Prophet."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The most authentic collection of hadith is:","options":[{"label":"A","text":"Sahih Muslim"},{"label":"B","text":"Sahih al-Bukhari"},{"label":"C","text":"Sunan Abu Dawud"},{"label":"D","text":"Jami'' al-Tirmidhi"}],"answer":"B","explanation":"Sahih al-Bukhari is considered the most authentic hadith collection after the Qur''an.","hints":["The scholar who spent 16 years compiling it"]},{"difficulty":"medium","question":"The chain of narrators in a hadith is called:","options":[{"label":"A","text":"Matn"},{"label":"B","text":"Isnad"},{"label":"C","text":"Sunan"},{"label":"D","text":"Fiqh"}],"answer":"B","explanation":"The Isnad is the chain of narrators who transmitted the hadith from the Prophet (SAW).","hints":["The ''chain'' that links narrators"]},{"difficulty":"jamb","question":"Hadith is important in Islam because it:","options":[{"label":"A","text":"Replaces the Qur''an"},{"label":"B","text":"Explains and complements the Qur''an"},{"label":"C","text":"Was written by the Prophet (SAW)"},{"label":"D","text":"Is more important than the Qur''an"}],"answer":"B","explanation":"Hadith complements the Qur''an by providing practical guidance, explanations, and the Prophet''s example.","hints":["What does hadith do that the Qur''an doesn''t?"]}]'::jsonb, '{"min_score":80,"required_sections":["irs3_hook_01","irs3_intuitive_01","irs3_formal_01","irs3_formula_01","irs3_practice_01"]}'::jsonb, '1')
