INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('irs', 'Tawhid (Islamic Monotheism)', 'Concept and Importance', 'Tawhid — The Heart of Islam', '["Define Tawhid and its importance","Distinguish between the three types of Tawhid","Explain the concept of Shirk and its categories","Apply Tawhid principles to daily life"]'::jsonb, 'medium', '20', '[{"id":"irs4_hook_01","type":"hook","order":1,"content":{"text":"The Shahadah — ''La ilaha illallah, Muhammadur Rasulullah'' — is not just words. It''s a complete worldview. It declares: there is no god but Allah. This is Tawhid — the absolute oneness of Allah. It''s the foundation of Islam. Everything else in the religion rests on it.","prediction_prompt":"What does it mean to say ''there is no god but Allah''? How does this belief affect daily life?"}},{"id":"irs4_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Tawhid means recognizing that Allah is One — unique, incomparable, the only Creator and Sustainer. It has three aspects: Tawhid ar-Rububiyyah (Allah is the only Lord and Creator), Tawhid al-Uluhiyyah (Allah alone deserves worship), Tawhid al-Asma was-Sifat (Allah''s names and attributes are unique). Shirk (associating partners with Allah) is the opposite of Tawhid — the greatest sin.","analogy":"Think of Tawhid like the sun. There is only one sun in our solar system. It gives light, warmth, and life. Without it, nothing exists. Similarly, Allah is the only source of all creation, sustenance, and guidance. Everything else depends on Him."}},{"id":"irs4_formal_01","type":"formal_explanation","order":3,"content":{"text":"Three types of Tawhid: (1) Tawhid ar-Rububiyyah — Oneness of Lordship: Allah alone creates, sustains, and controls everything. (2) Tawhid al-Uluhiyyah — Oneness of Worship: only Allah deserves to be worshipped. (3) Tawhid al-Asma was-Sifat — Oneness of Names and Attributes: Allah''s names and attributes are unique. Shirk: the opposite of Tawhid — associating others with Allah in worship, love, or obedience.","key_terms":[{"term":"Tawhid","definition":"Islamic monotheism — the absolute oneness of Allah in all aspects"},{"term":"Rububiyyah","definition":"Lordship — Allah is the only Creator, Sustainer, and Controller"},{"term":"Uluhiyyah","definition":"Worship — only Allah deserves to be worshipped"},{"term":"Shirk","definition":"Associating partners with Allah — the greatest sin in Islam"}]}},{"id":"irs4_formula_01","type":"formula","order":4,"content":{"formula":"Tawhid = Oneness of Lordship + Oneness of Worship + Oneness of Names/Attributes","variables":[{"name":"Rububiyyah","description":"Allah alone creates, sustains, controls"},{"name":"Uluhiyyah","description":"Only Allah deserves worship, prayer, sacrifice"},{"name":"Asma was-Sifat","description":"Allah''s names (Ar-Rahman, Al-Malik) and attributes are unique"},{"name":"Shirk","description":"The opposite — giving any of the above to other than Allah"}],"when_to_use":"When asked about the concept of Tawhid or its types.","common_traps":["Confusing the three types — each addresses a different aspect of Allah''s oneness","Thinking Shirk is only idol worship — it can also be loving someone more than Allah","Forgetting that Tawhid is the foundation of all Islamic belief and practice"],"units_note":"Tawhid is the first article of the Shahadah: ''La ilaha illallah.''"}},{"id":"irs4_practice_01","type":"worked_example","order":5,"content":{"scenario":"How does Tawhid affect a Muslim''s daily life? Give three practical examples.","given":["The concept of Tawhid"],"required":"Apply Tawhid to practical situations","principle":"Tawhid means directing all worship, trust, and obedience to Allah alone.","steps":[{"explanation":"Example 1: Prayer","calculation":"A Muslim prays to Allah alone — not to saints, prophets, or idols (Uluhiyyah)"},{"explanation":"Example 2: Trust","calculation":"A Muslim relies on Allah for provision, not on amulets or fortune-tellers (Rububiyyah)"},{"explanation":"Example 3: Obedience","calculation":"A Muslim obeys Allah''s commands even when it conflicts with social pressure (Asma was-Sifat)"},{"explanation":"Summary","calculation":"Tawhid shapes every aspect: worship, trust, morality, and social life"}],"answer":"Tawhid affects daily life through: (1) worshipping Allah alone (prayer, dua), (2) trusting only in Allah for provision (not superstition), (3) obeying Allah''s commands in all matters.","check":"Tawhid is not just belief — it''s a way of life that influences every decision."}},{"id":"irs4_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Tawhid only means not worshipping idols.","why_wrong":"Tawhid goes beyond idols — it means directing ALL aspects of worship, trust, love, and obedience to Allah alone. Loving wealth more than Allah can be a form of shirk.","correct_model":"Tawhid is comprehensive: it affects worship, trust, love, fear, hope, and obedience. Anything directed to other than Allah that should be directed to Him alone is shirk."}},{"id":"irs4_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of Tawhid''s types, its importance, and the concept of shirk.","trap":"JAMB may ask about minor shirk (riya — showing off in worship) vs major shirk (idol worship). Both are prohibited.","tip":"For essay questions, define Tawhid, explain the three types, give examples, and contrast with shirk. This structure covers all bases.","related_topics":["The Shahadah","Types of Shirk","Islamic belief"]}},{"id":"irs4_memory_01","type":"memory_hook","order":8,"content":{"text":"Tawhid = Oneness. Three types: Rububiyyah (Lordship), Uluhiyyah (Worship), Asma/Sifat (Names/Attributes). Opposite = Shirk (associating partners). Greatest sin in Islam.","hook_type":"mnemonic"}},{"id":"irs4_reflection_01","type":"reflection","order":9,"content":{"question":"How is Tawhid different from the Christian concept of the Trinity?","expected_understanding":"Muslims believe Allah is absolutely One — no partners, no divisions. The Trinity (Father, Son, Holy Spirit) is seen as contradicting Tawhid. For Muslims, Tawhid is the purest form of monotheism."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Tawhid means:","options":[{"label":"A","text":"Polytheism"},{"label":"B","text":"Islamic monotheism"},{"label":"C","text":"Prophethood"},{"label":"D","text":"Judgment day"}],"answer":"B","explanation":"Tawhid is the Islamic concept of absolute monotheism — the oneness of Allah.","hints":["Mono = one"]},{"difficulty":"medium","question":"Which of the following is a type of Tawhid?","options":[{"label":"A","text":"Tawhid ar-Rububiyyah"},{"label":"B","text":"Tawhid al-Malikiyyah"},{"label":"C","text":"Tawhid an-Nubuwwah"},{"label":"D","text":"Tawhid al-Hakimiyyah"}],"answer":"A","explanation":"Tawhid ar-Rububiyyah (Oneness of Lordship) is one of the three types of Tawhid.","hints":["The three types: Lordship, Worship, Names/Attributes"]},{"difficulty":"jamb","question":"The greatest sin in Islam is:","options":[{"label":"A","text":"Lying"},{"label":"B","text":"Stealing"},{"label":"C","text":"Shirk (associating partners with Allah)"},{"label":"D","text":"Disobedience to parents"}],"answer":"C","explanation":"Shirk is the greatest sin because it violates the foundation of Islam — Tawhid.","hints":["What is the opposite of Tawhid?"]}]'::jsonb, '{"min_score":80,"required_sections":["irs4_hook_01","irs4_intuitive_01","irs4_formal_01","irs4_formula_01","irs4_practice_01"]}'::jsonb, '1')
