INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('irs', 'The Pillars of Islam', 'Foundations of Muslim Practice', 'The Five Pillars — The Framework of Muslim Life', '["Identify and explain the five pillars of Islam","Understand the requirements of each pillar","Explain the significance of Zakat and Sawm","Apply the pillars to daily Muslim practice"]'::jsonb, 'medium', '20', '[{"id":"irs5_hook_01","type":"hook","order":1,"content":{"text":"Islam is not just a set of beliefs — it''s a way of life. The five pillars are the framework: they structure a Muslim''s day, year, and lifetime. From the daily prayer to the annual pilgrimage, these pillars connect the individual to Allah and to the global Muslim community.","prediction_prompt":"What if someone said ''I believe in Islam but don''t pray''? Would they be a complete Muslim?"}},{"id":"irs5_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"The five pillars are: (1) Shahadah — declaration of faith. (2) Salah — five daily prayers. (3) Zakat — annual charity (2.5% of savings). (4) Sawm — fasting during Ramadan. (5) Hajj — pilgrimage to Makkah (once in a lifetime if able). Each pillar addresses a different aspect: belief, prayer, wealth, body, and community.","analogy":"Think of the pillars like the pillars of a building. Remove one, and the structure weakens. Each pillar supports a different aspect of faith. Together, they create a complete framework for Muslim life."}},{"id":"irs5_formal_01","type":"formal_explanation","order":3,"content":{"text":"(1) Shahadah: ''La ilaha illallah, Muhammadur Rasulullah'' — the foundation. (2) Salah: Five daily prayers (Fajr, Dhuhr, Asr, Maghrib, Isha) — the connection to Allah. (3) Zakat: 2.5% of savings above nisab — purification of wealth. (4) Sawm: Fasting from dawn to sunset during Ramadan — self-discipline and empathy. (5) Hajj: Pilgrimage to Makkah — unity and equality before Allah.","key_terms":[{"term":"Shahadah","definition":"The declaration of faith: ''There is no god but Allah, Muhammad is His messenger''"},{"term":"Salah","definition":"The five daily obligatory prayers"},{"term":"Zakat","definition":"Annual obligatory charity — 2.5% of savings above nisab (minimum threshold)"},{"term":"Sawm","definition":"Fasting during Ramadan — abstaining from food, drink, and other needs from dawn to sunset"}]}},{"id":"irs5_formula_01","type":"formula","order":4,"content":{"formula":"Five Pillars: Shahadah (Belief) → Salah (Prayer) → Zakat (Wealth) → Sawm (Body) → Hajj (Community)","variables":[{"name":"Shahadah","description":"Foundation — declaration of faith"},{"name":"Salah","description":"Connection — five daily prayers at fixed times"},{"name":"Zakat","description":"Purification — 2.5% of wealth for the poor"},{"name":"Sawm","description":"Discipline — fasting during Ramadan"},{"name":"Hajj","description":"Unity — pilgrimage to Makkah (once if able)"}],"when_to_use":"When asked about the five pillars, their order, or their significance.","common_traps":["Forgetting that Hajj is only required if physically and financially able","Confusing Zakat with Sadaqah — Zakat is obligatory, Sadaqah is voluntary","Not knowing the five daily prayers by name"],"units_note":"The five pillars are mentioned in a famous hadith: ''Islam is built on five pillars...'' (Sahih al-Bukhari)."}},{"id":"irs5_practice_01","type":"worked_example","order":5,"content":{"scenario":"A Muslim earns ₦500,000 per year and has savings of ₦2,000,000 above the nisab threshold. How much Zakat must they pay?","given":["Annual income: ₦500,000","Savings above nisab: ₦2,000,000"],"required":"Calculate the Zakat amount","principle":"Zakat is 2.5% of savings above nisab (not income).","steps":[{"explanation":"Identify the base","calculation":"Zakat is calculated on savings above nisab, not income"},{"explanation":"Apply the rate","calculation":"2.5% of ₦2,000,000 = ₦50,000"},{"explanation":"Note","calculation":"The income (₦500,000) is not included — only accumulated savings"},{"explanation":"Purpose","calculation":"Zakat purifies wealth and helps the poor (one of the 8 categories in Q.9:60)"}],"answer":"The Zakat amount is ₦50,000 (2.5% of ₦2,000,000 savings above nisab).","check":"Zakat is calculated annually on wealth, not income. The poor receive: Q.9:60 lists 8 categories."}},{"id":"irs5_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Zakat is voluntary charity.","why_wrong":"Zakat is OBLIGATORY — it''s one of the five pillars. Sadaqah (voluntary charity) is separate and additional.","correct_model":"Zakat = obligatory (2.5% of savings above nisab). Sadaqah = voluntary (any amount, any time)."}},{"id":"irs5_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests knowledge of the five pillars, their requirements, and their significance.","trap":"JAMB may ask about the conditions for Hajj — it''s obligatory only once in a lifetime for those who are physically and financially able.","tip":"For essay questions, describe each pillar and explain why it''s important. Connect them to the hadith: ''Islam is built on five pillars.''","related_topics":["Zakat rates","Ramadan rules","Hajj rituals"]}},{"id":"irs5_memory_01","type":"memory_hook","order":8,"content":{"text":"Five Pillars: Shahadah (faith), Salah (prayer), Zakat (charity), Sawm (fasting), Hajj (pilgrimage). Hadith: ''Islam is built on five pillars.''","hook_type":"mnemonic"}},{"id":"irs5_reflection_01","type":"reflection","order":9,"content":{"question":"Why is Salah (prayer) performed five times a day? What does this frequency teach about the Muslim''s relationship with Allah?","expected_understanding":"Five daily prayers keep the Muslim constantly connected to Allah. It''s a reminder that no matter how busy life gets, Allah comes first. The regularity builds discipline and spiritual awareness."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"How many pillars of Islam are there?","options":[{"label":"A","text":"3"},{"label":"B","text":"4"},{"label":"C","text":"5"},{"label":"D","text":"7"}],"answer":"C","explanation":"There are five pillars of Islam: Shahadah, Salah, Zakat, Sawm, and Hajj.","hints":["The five foundations of Muslim practice"]},{"difficulty":"medium","question":"Zakat is calculated as:","options":[{"label":"A","text":"10% of income"},{"label":"B","text":"2.5% of savings above nisab"},{"label":"C","text":"5% of all wealth"},{"label":"D","text":"20% of profit"}],"answer":"B","explanation":"Zakat is 2.5% of accumulated savings that exceed the nisab (minimum threshold).","hints":["What percentage of wealth above a minimum?"]},{"difficulty":"jamb","question":"Hajj is obligatory for a Muslim who:","options":[{"label":"A","text":"Is healthy and wealthy"},{"label":"B","text":"Is physically and financially able"},{"label":"C","text":"Has completed Ramadan"},{"label":"D","text":"Is over 40 years old"}],"answer":"B","explanation":"Hajj is obligatory once in a lifetime for those who are physically and financially able to undertake it.","hints":["What two conditions must be met?"]}]'::jsonb, '{"min_score":80,"required_sections":["irs5_hook_01","irs5_intuitive_01","irs5_formal_01","irs5_formula_01","irs5_practice_01"]}'::jsonb, '1')
