INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('literature', 'Literary Terms and Devices', 'Figures of Speech and Techniques', 'Literary Devices — The Tools Every Writer Uses', '["Identify and explain various figures of speech","Distinguish between literal and figurative language","Analyze the effect of literary techniques in texts","Apply knowledge of literary devices to exam questions"]'::jsonb, 'medium', '20', '[{"id":"lit_hook_01","type":"hook","order":1,"content":{"text":"When Shakespeare writes ''All the world''s a stage,'' he doesn''t mean the world is literally a theatre. He''s using a metaphor — comparing life to a performance. Literary devices are the tools writers use to make their writing vivid, powerful, and memorable. Knowing them helps you understand what the author REALLY means.","prediction_prompt":"What''s the difference between ''He is brave'' and ''He is a lion''? Which is more powerful and why?"}},{"id":"lit_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Figures of speech are words used in a non-literal way to create an effect. A simile compares using ''like'' or ''as'' (brave as a lion). A metaphor compares directly (he IS a lion). Personification gives human qualities to non-human things (the wind whispered). They make writing more vivid and emotional.","analogy":"Think of literary devices like spices in cooking. Plain rice (literal language) fills you up, but rice with spices (figurative language) creates an experience. Writers use similes, metaphors, and other devices to add flavour to their words."}},{"id":"lit_formal_01","type":"formal_explanation","order":3,"content":{"text":"Major figures of speech: Simile (comparison using like/as), Metaphor (direct comparison), Personification (human qualities to non-human), Hyperbole (exaggeration), Irony (opposite of what is meant), Oxymoron (contradictory terms together), Alliteration (repetition of initial consonant sounds), Assonance (repetition of vowel sounds), Onomatopoeia (words that sound like what they describe).","key_terms":[{"term":"Simile","definition":"A comparison using ''like'' or ''as'' — e.g., ''Her eyes sparkled like diamonds''"},{"term":"Metaphor","definition":"A direct comparison without like/as — e.g., ''Time is money''"},{"term":"Personification","definition":"Giving human qualities to non-human things — e.g., ''The sun smiled down on us''"},{"term":"Irony","definition":"When the opposite of what is expected happens or is said"}]}},{"id":"lit_formula_01","type":"formula","order":4,"content":{"formula":"Identifying Literary Devices: Look for comparison words (like, as) → Simile. Direct comparison (is, are) → Metaphor. Human actions to non-human → Personification. Exaggeration → Hyperbole. Opposite meaning → Irony","variables":[{"name":"Simile","description":"Uses ''like'' or ''as'' for comparison"},{"name":"Metaphor","description":"Direct comparison without comparison words"},{"name":"Personification","description":"Non-human things doing human actions"},{"name":"Hyperbole","description":"Extreme exaggeration for effect"},{"name":"Irony","description":"Words say one thing, meaning is opposite"}],"when_to_use":"For any JAMB question asking you to identify or explain a literary device in a passage.","common_traps":["Confusing simile with metaphor — check for ''like'' or ''as''","Missing personification when it''s subtle (e.g., ''the city sleeps'')","Confusing verbal irony with sarcasm — they''re related but not identical"],"units_note":"JAMB typically tests 5-8 devices per year. Master the main ones first."}},{"id":"lit_practice_01","type":"worked_example","order":5,"content":{"scenario":"Identify the literary device: ''The wind howled through the trees, shaking every leaf in its path.''","given":["A sentence from a literary text"],"required":"Identify and explain the literary device used","principle":"Look at what the wind is doing — ''howled'' is a human action given to wind.","steps":[{"explanation":"Identify the subject","calculation":"The wind (non-human)"},{"explanation":"Identify the action","calculation":"''Howled'' — a human/animal action"},{"explanation":"Match to device","calculation":"Non-human doing human action = Personification"},{"explanation":"Explain the effect","calculation":"Makes the wind seem alive and threatening, creating a mood of danger"}],"answer":"Personification. The wind is given the human/animal ability to ''howl,'' making it seem alive and menacing.","check":"The effect is emotional — we feel the danger of the storm."}},{"id":"lit_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"All comparisons are metaphors.","why_wrong":"Similes and metaphors are both comparisons, but similes use ''like'' or ''as'' while metaphors state something IS something else.","correct_model":"''Brave as a lion'' = simile (uses ''as''). ''He is a lion'' = metaphor (direct comparison). Know the difference."}},{"id":"lit_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests identification of literary devices in passages and their effects on meaning and tone.","trap":"JAMB may use less common devices like synecdoche (part for whole: ''all hands on deck'') or metonymy (associated thing: ''the Crown'' for the monarchy). Learn these too.","tip":"When explaining a device''s effect, always say HOW it contributes to the meaning or mood. Don''t just identify it — explain what it achieves.","related_topics":["Tone and mood","Imagery","Symbolism"]}},{"id":"lit_memory_01","type":"memory_hook","order":8,"content":{"text":"SIMILE uses ''like/as.'' METAPHOR says something IS something. PERSONIFICATION gives human traits. HYPERBOLE exaggerates. IRONY says the opposite. ALLITERATION repeats initial sounds.","hook_type":"mnemonic"}},{"id":"lit_reflection_01","type":"reflection","order":9,"content":{"question":"Why do authors use figurative language instead of just stating facts?","expected_understanding":"Figurative language creates vivid images, evokes emotions, and makes abstract ideas concrete. ''He was sad'' is forgettable. ''He carried the weight of the world on his shoulders'' creates a powerful image."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which literary device is used in ''The stars danced in the night sky''?","options":[{"label":"A","text":"Simile"},{"label":"B","text":"Metaphor"},{"label":"C","text":"Personification"},{"label":"D","text":"Hyperbole"}],"answer":"C","explanation":"Stars cannot literally dance — this is personification, giving human action to non-human things.","hints":["Can stars really dance? What is the author doing?"]},{"difficulty":"medium","question":"''Her voice was music to his ears.'' This is an example of:","options":[{"label":"A","text":"Simile"},{"label":"B","text":"Metaphor"},{"label":"C","text":"Alliteration"},{"label":"D","text":"Onomatopoeia"}],"answer":"B","explanation":"Her voice IS music — direct comparison without ''like'' or ''as'' = metaphor.","hints":["Is there a comparison? Does it use ''like'' or ''as''?"]},{"difficulty":"jamb","question":"''The classroom was a zoo during the teacher''s absence.'' The dominant device is:","options":[{"label":"A","text":"Simile"},{"label":"B","text":"Metaphor"},{"label":"C","text":"Irony"},{"label":"D","text":"Synecdoche"}],"answer":"B","explanation":"The classroom IS a zoo — a direct metaphor comparing the chaos to a zoo. No ''like'' or ''as'' is used.","hints":["The classroom is directly compared to something else"]}]'::jsonb, '{"min_score":80,"required_sections":["lit_hook_01","lit_intuitive_01","lit_formal_01","lit_formula_01","lit_practice_01"]}'::jsonb, '1')
