INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('literature', 'Drama', 'Elements and Types of Drama', 'Drama — Understanding Plays and Performance', '["Identify the key elements of drama (plot, character, setting)","Distinguish between tragedy, comedy, and tragicomedy","Analyze dramatic techniques (soliloquy, aside, dialogue)","Understand plot structure and dramatic conflict"]'::jsonb, 'medium', '20', '[{"id":"drama_hook_01","type":"hook","order":1,"content":{"text":"When you watch a Nollywood movie or a stage play, you''re experiencing drama. But drama is not just entertainment — it''s a mirror that reflects society. Wole Soyinka''s ''Death and the King''s Horseman'' explores the clash between African tradition and colonial rule. Drama teaches us about ourselves and our world.","prediction_prompt":"What makes a story dramatic? Is it the conflict, the characters, or the dialogue?"}},{"id":"drama_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Drama is storytelling through performance — actors speak and act out a story on stage. The key elements are: Plot (what happens), Character (who it happens to), Dialogue (what they say), Setting (where and when), and Conflict (the problem that drives the story). Without conflict, there is no drama.","analogy":"Think of drama like a football match. The plot is the game plan. The characters are the players. The dialogue is what they say to each other. The setting is the stadium. The conflict is the competition — who will win? Without the competition, nobody would watch."}},{"id":"drama_formal_01","type":"formal_explanation","order":3,"content":{"text":"Drama is literature written for performance. Key elements: (1) Plot — exposition, rising action, climax, falling action, resolution. (2) Character — protagonist, antagonist, supporting. (3) Dialogue — conversations between characters. (4) Stage directions — instructions for actors. (5) Setting — time, place, atmosphere. Types: Tragedy (serious, ends in downfall), Comedy (humorous, happy ending), Tragicomedy (mix of both).","key_terms":[{"term":"Soliloquy","definition":"A character speaking their thoughts aloud while alone on stage"},{"term":"Aside","definition":"A character speaking to the audience, unheard by other characters"},{"term":"Climax","definition":"The turning point of the play — the moment of greatest tension"},{"term":"Denouement","definition":"The resolution of the plot after the climax"}]}},{"id":"drama_formula_01","type":"formula","order":4,"content":{"formula":"Plot Structure: Exposition → Rising Action → Climax → Falling Action → Resolution","variables":[{"name":"Exposition","description":"Introduction of characters, setting, and background"},{"name":"Rising Action","description":"Events that build tension and develop the conflict"},{"name":"Climax","description":"The turning point — moment of highest tension"},{"name":"Falling Action","description":"Events after the climax, leading to resolution"},{"name":"Resolution","description":"The conflict is resolved; the play ends"}],"when_to_use":"For any JAMB question about plot structure or dramatic form. This structure applies to most plays and novels.","common_traps":["Confusing climax with the ending — the climax is the turning point, not the conclusion","Missing the difference between tragedy and comedy — check how it ends","Not recognizing soliloquy when a character is alone on stage speaking"],"units_note":"JAMB may test either the 5-part or 3-part structure (beginning, middle, end)."}},{"id":"drama_practice_01","type":"worked_example","order":5,"content":{"scenario":"In a play, a character says: ''To be or not to be, that is the question.'' The character is alone on stage. What dramatic technique is being used?","given":["A famous line from Hamlet","The character is alone on stage"],"required":"Identify the dramatic technique","principle":"When a character speaks their thoughts aloud while alone, it''s a soliloquy.","steps":[{"explanation":"Check if other characters are present","calculation":"The character is alone on stage"},{"explanation":"Check what the character is doing","calculation":"Speaking their inner thoughts and feelings"},{"explanation":"Match to technique","calculation":"Alone + speaking thoughts = Soliloquy"},{"explanation":"Why it matters","calculation":"Soliloquy reveals the character''s innermost feelings to the audience"}],"answer":"Soliloquy. Hamlet is alone on stage, revealing his inner thoughts about life and death to the audience.","check":"If other characters were present and could hear him, it would be an aside instead."}},{"id":"drama_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Soliloquy and aside are the same thing.","why_wrong":"In a soliloquy, the character is ALONE on stage. In an aside, other characters are present but the character speaks to the audience as if they can''t hear.","correct_model":"Soliloquy = alone on stage, speaking thoughts. Aside = others present, speaking to audience (others pretend not to hear)."}},{"id":"drama_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests dramatic techniques, plot structure, and analysis of prescribed set texts (both African and non-African).","trap":"JAMB may ask about the function of a specific dramatic technique, not just its name. Always explain HOW it advances the plot or reveals character.","tip":"For set texts, know the key scenes, characters, and themes. JAMB often quotes specific lines and asks what they reveal about character or theme.","related_topics":["Set text analysis","Character study","Thematic analysis"]}},{"id":"drama_memory_01","type":"memory_hook","order":8,"content":{"text":"SOLILOQUY: Solo + speech = alone on stage. ASIDE: A-side = spoken to the side (audience). Tragedy ends in death/disaster. Comedy ends happily. Tragicomedy mixes both.","hook_type":"mnemonic"}},{"id":"drama_reflection_01","type":"reflection","order":9,"content":{"question":"Why do playwrights use soliloquies instead of having characters explain their feelings through dialogue with others?","expected_understanding":"Soliloquies reveal what a character truly thinks and feels — things they might not say to others. This creates dramatic irony (the audience knows more than other characters) and deepens our understanding of the character''s motivations."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A character speaks their thoughts aloud while alone on stage. This is called:","options":[{"label":"A","text":"Aside"},{"label":"B","text":"Soliloquy"},{"label":"C","text":"Monologue"},{"label":"D","text":"Dialogue"}],"answer":"B","explanation":"A soliloquy is when a character speaks their thoughts aloud while alone on stage.","hints":["Solo + speech = ?"]},{"difficulty":"medium","question":"The turning point in a play, where tension is at its highest, is called the:","options":[{"label":"A","text":"Exposition"},{"label":"B","text":"Denouement"},{"label":"C","text":"Climax"},{"label":"D","text":"Prologue"}],"answer":"C","explanation":"The climax is the turning point of the play — the moment of greatest tension.","hints":["The peak, the highest point"]},{"difficulty":"jamb","question":"In ''Death and the King''s Horseman,'' the conflict between Elesin and the Colonial District Officer represents:","options":[{"label":"A","text":"Individual vs society"},{"label":"B","text":"Tradition vs modernity/colonialism"},{"label":"C","text":"Man vs nature"},{"label":"D","text":"Good vs evil"}],"answer":"B","explanation":"The play explores the clash between Yoruba tradition (Elesin''s ritual suicide) and British colonial authority.","hints":["Think about the two opposing forces in the play"]}]'::jsonb, '{"min_score":80,"required_sections":["drama_hook_01","drama_intuitive_01","drama_formal_01","drama_formula_01","drama_practice_01"]}'::jsonb, '1')
