INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('literature', 'Prose Fiction', 'Elements of Prose and Novel Analysis', 'Prose Fiction — Reading Between the Lines', '["Identify elements of prose (plot, characterization, setting, point of view)","Distinguish between types of novels (epistolary, picaresque, bildungsroman)","Analyze narrative techniques and their effects","Interpret themes and stylistic features in prose"]'::jsonb, 'medium', '20', '[{"id":"prose_hook_01","type":"hook","order":1,"content":{"text":"When you read ''Things Fall Apart'' by Chinua Achebe, you''re not just reading a story — you''re experiencing pre-colonial Igbo life, the arrival of missionaries, and the collapse of a culture. Prose fiction is the art of telling stories that teach us about human nature and society.","prediction_prompt":"What''s the difference between reading a novel for fun and reading it for an exam? What should you pay attention to?"}},{"id":"prose_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Prose fiction is written in sentences and paragraphs (not verse). It includes novels, novellas, and short stories. The key elements are: Plot (what happens), Characterization (how characters are created), Setting (time and place), Point of View (who tells the story), and Theme (the message or idea). Every choice the author makes serves the story.","analogy":"Think of a novel like a movie. The plot is the script. The characters are the actors. The setting is the scenery. The point of view is the camera angle. The theme is the message the director wants to convey. Change any element, and the story changes."}},{"id":"prose_formal_01","type":"formal_explanation","order":3,"content":{"text":"Prose fiction elements: (1) Plot — events arranged in a narrative arc. (2) Characterization — direct (author tells) vs indirect (actions, speech, thoughts). (3) Setting — time, place, social environment. (4) Point of View — first person (I), third person limited (he/she, one character''s thoughts), third person omniscient (all-knowing). (5) Theme — the central idea or message.","key_terms":[{"term":"Protagonist","definition":"The main character of the story"},{"term":"Antagonist","definition":"The character or force that opposes the protagonist"},{"term":"Foreshadowing","definition":"Hints about what will happen later in the story"},{"term":"Flashback","definition":"A scene set in a time earlier than the main story"}]}},{"id":"prose_formula_01","type":"formula","order":4,"content":{"formula":"Characterization Methods: Direct (author tells you) + Indirect (show through action, speech, thoughts, appearance, others'' reactions)","variables":[{"name":"Direct","description":"Author directly states character traits"},{"name":"Action","description":"What the character does reveals who they are"},{"name":"Speech","description":"How and what the character says"},{"name":"Thoughts","description":"Internal monologue reveals feelings"},{"name":"Others","description":"How other characters react to them"}],"when_to_use":"When JAMB asks how a character is portrayed or what characterization method is used.","common_traps":["Confusing flat/round characters — flat = one trait, round = complex","Confusing static/dynamic — static doesn''t change, dynamic does","Missing indirect characterization when the author doesn''t explicitly state traits"],"units_note":"JAMB may ask about specific characters from set texts. Know the main characters in your prescribed novels."}},{"id":"prose_practice_01","type":"worked_example","order":5,"content":{"scenario":"In ''Second Class Citizen'' by Buchi Emecheta, Adah works hard to support her family despite facing gender discrimination. The author shows this through Adah''s actions and determination rather than directly stating it.","given":["A passage describing Adah''s behavior"],"required":"Identify the characterization method","principle":"When the author shows character through actions rather than telling directly, it''s indirect characterization.","steps":[{"explanation":"Check if the author states traits directly","calculation":"The author doesn''t say ''Adah is determined''"},{"explanation":"Check what Adah does","calculation":"She works hard, supports family, faces discrimination"},{"explanation":"Identify the method","calculation":"Actions reveal character = Indirect characterization"},{"explanation":"Identify the technique within indirect","calculation":"Actions and behavior = characterization through action"}],"answer":"Indirect characterization through action. Adah''s determination and resilience are shown through what she does, not what the author says about her.","check":"The reader discovers Adah''s strength by watching her actions, not being told directly."}},{"id":"prose_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A first-person narrator is always reliable.","why_wrong":"First-person narrators can be biased, unreliable, or even lying. The reader must evaluate what the narrator says vs what actually happens.","correct_model":"First-person narrators give intimate access but may be unreliable. Third-person omniscient gives a broader, more objective view."}},{"id":"prose_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests analysis of set texts — characters, themes, plot, and narrative techniques.","trap":"JAMB may quote a passage and ask which technique is used. Look for the method (direct/indirect) and the specific device (action, speech, thought).","tip":"For each set text, make a character map: who is the protagonist, antagonist, what do they want, what stands in their way, how do they change?","related_topics":["Theme analysis","Narrative voice","Set text study"]}},{"id":"prose_memory_01","type":"memory_hook","order":8,"content":{"text":"Prose elements: Plot (what), Character (who), Setting (where/when), POV (whose eyes), Theme (why). Indirect characterization: Action, Speech, Thoughts, Appearance, Others'' reactions.","hook_type":"mnemonic"}},{"id":"prose_reflection_01","type":"reflection","order":9,"content":{"question":"Why might an author choose first-person narration over third-person omniscient?","expected_understanding":"First-person creates intimacy — the reader experiences everything through the narrator''s eyes. It''s powerful for showing personal struggle, bias, or limited understanding. But it limits what the reader knows."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"The main character in a novel is called the:","options":[{"label":"A","text":"Antagonist"},{"label":"B","text":"Protagonist"},{"label":"C","text":"Narrator"},{"label":"D","text":"Author"}],"answer":"B","explanation":"The protagonist is the main character. The antagonist opposes them.","hints":["Pro = first/main"]},{"difficulty":"medium","question":"When an author describes a character''s thoughts and feelings directly, it is:","options":[{"label":"A","text":"Indirect characterization"},{"label":"B","text":"Direct characterization"},{"label":"C","text":"Dialogue"},{"label":"D","text":"Foreshadowing"}],"answer":"B","explanation":"Direct characterization is when the author directly tells the reader about a character''s traits.","hints":["Direct = author tells you directly"]},{"difficulty":"jamb","question":"In ''Things Fall Apart,'' Achebe''s use of Igbo proverbs serves to:","options":[{"label":"A","text":"Make the text longer"},{"label":"B","text":"Show the richness of Igbo culture and wisdom"},{"label":"C","text":"Confuse non-Igbo readers"},{"label":"D","text":"Provide comic relief"}],"answer":"B","explanation":"Achebe uses Igbo proverbs to demonstrate the depth and sophistication of Igbo oral tradition and cultural values.","hints":["What do proverbs represent in a culture?"]}]'::jsonb, '{"min_score":80,"required_sections":["prose_hook_01","prose_intuitive_01","prose_formal_01","prose_formula_01","prose_practice_01"]}'::jsonb, '1')
