INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('literature', 'Poetry', 'Elements and Forms of Poetry', 'Poetry — The Music of Language', '["Identify elements of poetry (rhythm, meter, rhyme, imagery)","Distinguish between poetic forms (sonnet, ode, elegy, ballad)","Analyze figurative language and sound devices in poems","Interpret meaning through close reading of poems"]'::jsonb, 'hard', '22', '[{"id":"poetry_hook_01","type":"hook","order":1,"content":{"text":"Poetry is the most compressed form of literature. Every word matters. A single poem can make you cry, laugh, or see the world differently — in just 14 lines. When Shakespeare writes ''Shall I compare thee to a summer''s day?'', he''s not just asking a question — he''s creating an image, a feeling, and a declaration of love all at once.","prediction_prompt":"Read this: ''The fog comes on little cat feet.'' What does this poem make you see? How does it work?"}},{"id":"poetry_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Poetry is language chosen and arranged for its emotional and aesthetic effect. Poets use rhythm (the beat of the words), rhyme (matching sounds), imagery (vivid pictures in words), and figurative language (non-literal meaning) to create impact. Every word is deliberate — nothing is accidental.","analogy":"Think of poetry like perfume. A novel is a bottle of perfume — lots of liquid, the scent develops over time. A poem is a single drop — concentrated, powerful, lingering. One drop can fill a room. One poem can change how you see the world."}},{"id":"poetry_formal_01","type":"formal_explanation","order":3,"content":{"text":"Poetry elements: (1) Rhythm — pattern of stressed/unstressed syllables. (2) Meter — regular rhythm pattern (iambic: da-DUM). (3) Rhyme scheme — pattern of rhyming words (ABAB, ABBA). (4) Stanza — group of lines (couplet, triplet, quatrain). (5) Imagery — vivid sensory descriptions. (6) Sound devices — alliteration, assonance, consonance, onomatopoeia.","key_terms":[{"term":"Sonnet","definition":"14-line poem, usually about love (Shakespearean: ABAB CDCD EFEF GG)"},{"term":"Elegy","definition":"A poem of mourning for the dead"},{"term":"Ballad","definition":"A narrative poem telling a story, often with a refrain"},{"term":"Free Verse","definition":"Poetry without regular meter or rhyme scheme"}]}},{"id":"poetry_formula_01","type":"formula","order":4,"content":{"formula":"Poem Analysis: Read → Identify form → Find imagery → Check sound devices → Determine theme → Analyze tone","variables":[{"name":"Form","description":"What type of poem? Sonnet, ode, elegy, free verse?"},{"name":"Imagery","description":"What senses does the poet appeal to? (sight, sound, touch, smell, taste)"},{"name":"Sound","description":"Alliteration, assonance, consonance, onomatopoeia"},{"name":"Theme","description":"What is the poem about? What message does it convey?"},{"name":"Tone","description":"What is the poet''s attitude? (sad, angry, joyful, reflective)"}],"when_to_use":"For any JAMB question requiring analysis of a poem. Follow this systematic approach.","common_traps":["Confusing the speaker with the poet — the speaker may not be the poet","Missing the difference between literal and figurative meaning","Not identifying the rhyme scheme correctly"],"units_note":"JAMB may present unfamiliar poems. Use analysis skills, not memorization."}},{"id":"poetry_practice_01","type":"worked_example","order":5,"content":{"scenario":"Analyze: ''The autumn leaves fell softly to the ground, / Like golden tears from nature''s weeping eye.''","given":["Two lines from a poem"],"required":"Identify the literary devices and explain their effect","principle":"Look for comparisons, sensory details, and figurative language.","steps":[{"explanation":"Identify imagery","calculation":"''Autumn leaves fell softly'' — visual and auditory imagery (golden, softly)"},{"explanation":"Identify comparison","calculation":"''Like golden tears'' — simile comparing leaves to tears"},{"explanation":"Identify personification","calculation":"''Nature''s weeping eye'' — nature given human ability to weep"},{"explanation":"Determine effect","calculation":"Creates a mood of sadness and beauty — autumn becomes emotional, not just seasonal"}],"answer":"Simile (''like golden tears''), personification (''nature''s weeping eye''), and imagery (''golden,'' ''softly''). The effect is melancholic — autumn becomes a time of loss and beauty.","check":"The devices work together to create a unified emotional effect."}},{"id":"poetry_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The speaker in a poem is always the poet.","why_wrong":"The speaker is a persona — a voice created by the poet. In dramatic monologues, the speaker is a character, not the poet.","correct_model":"The speaker may or may not be the poet. Always refer to ''the speaker'' not ''the poet'' unless you''re sure they''re the same."}},{"id":"poetry_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests analysis of set poems — identifying devices, interpreting meaning, and explaining effects.","trap":"JAMB may ask about the ''tone'' of a poem. Tone = the speaker''s attitude. Don''t confuse tone (attitude) with mood (feeling created in the reader).","tip":"For each set poem, know: the poet, the speaker, the occasion, the main imagery, the theme, and 2-3 key devices.","related_topics":["Close reading","Theme analysis","Comparative analysis"]}},{"id":"poetry_memory_01","type":"memory_hook","order":8,"content":{"text":"Poetry analysis: Form (type), Imagery (pictures), Sound (music), Theme (message), Tone (attitude). Sonnet=14 lines. Elegy=mourning. Ballad=story. Free verse=no rules.","hook_type":"mnemonic"}},{"id":"poetry_reflection_01","type":"reflection","order":9,"content":{"question":"Why do poets use imagery instead of just stating their feelings directly?","expected_understanding":"Imagery makes feelings vivid and personal. ''I am sad'' tells you. ''The world is a hollow drum echoing my emptiness'' makes you FEEL it. Poetry shows rather than tells."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A 14-line poem about love is called a:","options":[{"label":"A","text":"Ballad"},{"label":"B","text":"Sonnet"},{"label":"C","text":"Elegy"},{"label":"D","text":"Ode"}],"answer":"B","explanation":"A sonnet is a 14-line poem, traditionally about love.","hints":["Shakespeare wrote many of these"]},{"difficulty":"medium","question":"''The wind whispered through the trees'' uses which device?","options":[{"label":"A","text":"Simile"},{"label":"B","text":"Metaphor"},{"label":"C","text":"Personification"},{"label":"D","text":"Alliteration"}],"answer":"C","explanation":"Wind cannot whisper — this is personification, giving a human action to a non-human thing.","hints":["Can wind really whisper?"]},{"difficulty":"jamb","question":"In ''Piano and Drums'' by Gabriel Okara, the contrast between piano and drums represents:","options":[{"label":"A","text":"Music appreciation"},{"label":"B","text":"Conflict between Western and African culture"},{"label":"C","text":"Childhood memories"},{"label":"D","text":"Musical instruments"}],"answer":"B","explanation":"The piano symbolizes Western civilization while drums represent African tradition. The poem explores cultural identity.","hints":["What do piano and drums symbolize in African context?"]}]'::jsonb, '{"min_score":80,"required_sections":["poetry_hook_01","poetry_intuitive_01","poetry_formal_01","poetry_formula_01","poetry_practice_01"]}'::jsonb, '1')
