INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('literature', 'African Literature', 'Themes and Traditions', 'African Literature — Voices of a Continent', '["Identify major themes in African literature","Understand the influence of oral tradition on written African literature","Analyze the impact of colonialism on African literary expression","Compare African and Western literary traditions"]'::jsonb, 'hard', '22', '[{"id":"afr_hook_01","type":"hook","order":1,"content":{"text":"African literature is not just stories — it''s the voice of a continent fighting for identity, independence, and dignity. From Chinua Achebe''s ''Things Fall Apart'' to Chimamanda Adichie''s ''Purple Hibiscus,'' African writers tell stories that the world needs to hear. They challenge stereotypes, preserve cultures, and imagine new futures.","prediction_prompt":"Why do you think Achebe wrote ''Things Fall Apart'' in response to Joseph Conrad''s ''Heart of Darkness''? What was he trying to correct?"}},{"id":"afr_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"African literature has two roots: oral tradition (stories, proverbs, songs passed down through generations) and written tradition (novels, poems, plays). Modern African writers combine both — using proverbs in dialogue, incorporating oral storytelling techniques, and writing about the African experience in a world shaped by colonialism.","analogy":"Think of African literature like a baobab tree. The roots are oral traditions — deep, ancient, nourishing. The trunk is the written word — strong, visible, reaching outward. The branches are the different genres — novels, poetry, drama. The fruit is the message — stories that feed the mind and soul."}},{"id":"afr_formal_01","type":"formal_explanation","order":3,"content":{"text":"Major themes in African literature: (1) Colonialism and its effects — cultural disruption, identity crisis. (2) Tradition vs modernity — tension between old ways and new. (3) Identity — personal, cultural, national. (4) Gender and marriage — women''s roles, bride price, education. (5) Corruption and politics — post-colonial governance. (6) Family and community — Ubuntu philosophy.","key_terms":[{"term":"Oral Tradition","definition":"Stories, proverbs, songs, and history passed down through generations by word of mouth"},{"term":"Negritude","definition":"A literary movement celebrating Black African identity and culture"},{"term":"Post-colonialism","definition":"The study of cultural, social, and political effects of colonialism"},{"term":"Ubuntu","definition":"African philosophy: ''I am because we are'' — community over individualism"}]}},{"id":"afr_formula_01","type":"formula","order":4,"content":{"formula":"Analyzing African Literature: Context (when/where) → Theme (what message) → Character (who) → Technique (how) → Tradition (oral roots)","variables":[{"name":"Context","description":"Historical and cultural background of the work"},{"name":"Theme","description":"Central messages about society, culture, politics"},{"name":"Character","description":"How characters represent African experiences"},{"name":"Technique","description":"Use of proverbs, oral storytelling, multiple languages"},{"name":"Tradition","description":"Connection to oral literature and cultural practices"}],"when_to_use":"When analyzing any African literary text for JAMB. This framework covers all key aspects.","common_traps":["Reading African literature with Western expectations — African storytelling has its own conventions","Missing the use of proverbs and their significance","Not understanding the historical context of colonialism"],"units_note":"JAMB set texts change periodically. Know the themes and techniques of your prescribed texts."}},{"id":"afr_practice_01","type":"worked_example","order":5,"content":{"scenario":"In ''Things Fall Apart,'' Okonkwo says: ''The white man is very clever. He came quietly and peaceably with his religion.'' What does this reveal about the theme of the novel?","given":["A quote from Things Fall Apart"],"required":"Analyze what the quote reveals about the novel''s theme","principle":"Look at the surface meaning and the deeper implication.","steps":[{"explanation":"Read the quote literally","calculation":"Okonkwo acknowledges the white man''s cleverness and peaceful approach"},{"explanation":"Identify the irony","calculation":"Okonkwo says ''peaceably'' but the religion will destroy his culture — he doesn''t see the threat"},{"explanation":"Connect to theme","calculation":"Theme: Colonialism arrived peacefully but its effects were devastating"},{"explanation":"Identify dramatic irony","calculation":"The reader knows what Okonkwo doesn''t — this religion will ''eat deep'' into the culture"}],"answer":"The quote reveals the theme of colonialism''s subtle destruction. The white man''s approach seemed peaceful but was actually a form of cultural invasion that would destroy Igbo traditions.","check":"Achebe uses Okonkwo''s blindness to dramatic irony — the reader sees the danger that Okonkwo cannot."}},{"id":"afr_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"African literature only started when Africans began writing in English.","why_wrong":"African oral literature (folktales, proverbs, songs, epics) existed for thousands of years before colonialism. Written African literature builds on this tradition.","correct_model":"African literature includes both oral and written traditions. Oral literature is the foundation; written literature is the extension."}},{"id":"afr_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests themes, characters, and techniques in prescribed African literary texts.","trap":"JAMB may ask about the cultural significance of specific practices (e.g., the Week of Peace, yam festival) in set texts. Know the cultural context.","tip":"For African literature, always consider: What does this text say about Africa? How does it challenge or reinforce stereotypes? What is the author''s purpose?","related_topics":["Post-colonial analysis","Cultural studies","Comparative literature"]}},{"id":"afr_memory_01","type":"memory_hook","order":8,"content":{"text":"African literature themes: Colonialism, Tradition vs Modernity, Identity, Gender, Corruption, Community. Key authors: Achebe, Soyinka, Adichie, Armah, Emecheta, Ngugi.","hook_type":"mnemonic"}},{"id":"afr_reflection_01","type":"reflection","order":9,"content":{"question":"Why is it important for Africans to tell their own stories rather than having others tell them?","expected_understanding":"As Chimamanda Adichie warns, ''The danger of a single story'' is that others'' stories about Africa are often one-dimensional — poverty, war, disease. Africans telling their own stories creates a fuller, more accurate, more human picture."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Who wrote ''Things Fall Apart''?","options":[{"label":"A","text":"Wole Soyinka"},{"label":"B","text":"Chinua Achebe"},{"label":"C","text":"Chimamanda Adichie"},{"label":"D","text":"Ngugi wa Thiong''o"}],"answer":"B","explanation":"Chinua Achebe wrote ''Things Fall Apart'' (1958), one of the most widely read African novels.","hints":["The most famous African novel about pre-colonial Igbo life"]},{"difficulty":"medium","question":"The main theme of ''Purple Hibiscus'' by Chimamanda Adichie is:","options":[{"label":"A","text":"The Civil War"},{"label":"B","text":"Family, freedom, and growing up"},{"label":"C","text":"Colonialism"},{"label":"D","text":"Slavery"}],"answer":"B","explanation":"Purple Hibiscus explores family dynamics, the search for freedom from a tyrannical father, and the coming-of-age of Kambili.","hints":["The novel is about a teenage girl growing up in a strict household"]},{"difficulty":"jamb","question":"In African literature, the use of proverbs serves to:","options":[{"label":"A","text":"Make the text longer"},{"label":"B","text":"Connect the written text to oral tradition"},{"label":"C","text":"Confuse readers"},{"label":"D","text":"Show off the author''s knowledge"}],"answer":"B","explanation":"Proverbs connect written African literature to the rich oral tradition, adding cultural depth and wisdom.","hints":["Proverbs are a key part of oral tradition"]}]'::jsonb, '{"min_score":80,"required_sections":["afr_hook_01","afr_intuitive_01","afr_formal_01","afr_formula_01","afr_practice_01"]}'::jsonb, '1')
