INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('mathematics', 'Number Bases and Operations', 'Basic Concepts', 'Number Bases — How Different Number Systems Work', '["Convert numbers between base 10 and other bases","Perform arithmetic operations in different bases","Understand binary and hexadecimal number systems","Apply number base conversions in practical problems"]'::jsonb, 'medium', '20', '[{"id":"number_hook_01","type":"hook","order":1,"content":{"text":"Your computer doesn''t understand decimal numbers — it only knows 0s and 1s. The binary system (base 2) is the language of computers. But why stop at 2? Base 8 (octal) and base 16 (hexadecimal) are also used in computing. Understanding number bases is like learning that numbers can be written in many different ways.","prediction_prompt":"The decimal number 10 is written as 1010 in binary. Can you figure out why?"}},{"id":"number_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"In base 10 (decimal), we use digits 0-9 and each position represents a power of 10. So 345 = 3×10² + 4×10¹ + 5×10⁰. In base 2 (binary), we only use 0 and 1, and each position represents a power of 2. So 1010 in binary = 1×2³ + 0×2² + 1×2¹ + 0×2⁰ = 8 + 0 + 2 + 0 = 10 in decimal.","analogy":"Think of it like money. If you have 3 hundreds, 4 tens, and 5 ones, that''s 345 naira. But what if instead of 10 ones = 1 ten, you had 2 ones = 1 two? That''s binary! The ''exchange rate'' between positions changes with the base."}},{"id":"number_formal_01","type":"formal_explanation","order":3,"content":{"text":"A number in base b is written as dₙdₙ₋₁...d₁d₀ where each digit dᵢ satisfies 0 ≤ dᵢ < b. The value is dₙ×bⁿ + dₙ₋₁×bⁿ⁻¹ + ... + d₁×b¹ + d₀×b⁰. To convert from base b to base 10, expand using powers of b. To convert from base 10 to base b, repeatedly divide by b and record remainders.","key_terms":[{"term":"Base (Radix)","definition":"The number of unique digits used in a positional number system"},{"term":"Binary","definition":"Base 2 number system using digits 0 and 1"},{"term":"Octal","definition":"Base 8 number system using digits 0-7"},{"term":"Hexadecimal","definition":"Base 16 number system using digits 0-9 and letters A-F"}]}},{"id":"number_formula_01","type":"formula","order":4,"content":{"formula":"N = dₙ×bⁿ + dₙ₋₁×bⁿ⁻¹ + ... + d₁×b + d₀","variables":[{"name":"N","description":"The number in base 10","unit":"none"},{"name":"b","description":"The base of the number system","unit":"none"},{"name":"dᵢ","description":"The digit at position i","unit":"none"}],"when_to_use":"To convert any base to base 10, or to convert base 10 to any base by repeated division.","common_traps":["Forgetting that in bases > 10, letters represent digits (A=10, B=11, etc.)","Confusing the direction of conversion (expansion vs repeated division)","Not including leading zeros when converting TO a larger base"],"units_note":"Number bases have no units — they are different ways of representing the same quantity."}},{"id":"number_practice_01","type":"worked_example","order":5,"content":{"scenario":"Convert the decimal number 45 to binary.","given":["The number 45 in base 10"],"required":"Convert to binary (base 2)","principle":"Repeatedly divide by 2 and record the remainders. Read remainders from bottom to top.","steps":[{"explanation":"Divide 45 by 2","calculation":"45 ÷ 2 = 22 remainder 1"},{"explanation":"Divide 22 by 2","calculation":"22 ÷ 2 = 11 remainder 0"},{"explanation":"Divide 11 by 2","calculation":"11 ÷ 2 = 5 remainder 1"},{"explanation":"Divide 5 by 2","calculation":"5 ÷ 2 = 2 remainder 1"},{"explanation":"Divide 2 by 2","calculation":"2 ÷ 2 = 1 remainder 0"},{"explanation":"Divide 1 by 2","calculation":"1 ÷ 2 = 0 remainder 1"}],"answer":"45 in decimal = 101101 in binary. Reading remainders from bottom to top: 101101.","check":"1×32 + 0×16 + 1×8 + 1×4 + 0×2 + 1×1 = 32 + 8 + 4 + 1 = 45"}},{"id":"number_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Binary only uses 0 and 1, so binary numbers are always smaller than decimal numbers.","why_wrong":"The number of digits increases in binary. 255 in decimal is 11111111 in binary (8 digits). Binary numbers can be very long even for small decimal values.","correct_model":"The base determines how many digits you need, not the size of the number. Higher bases use fewer digits but more symbols per digit."}},{"id":"number_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests number base conversions (base 10 to other bases and vice versa), arithmetic in different bases, and practical applications.","trap":"JAMB may ask you to perform addition or subtraction IN a given base. Remember to carry/borrow according to that base, not base 10.","tip":"For quick binary conversions: memorize powers of 2 (1, 2, 4, 8, 16, 32, 64, 128, 256). Then find which powers add up to your number.","related_topics":["Binary arithmetic","Hexadecimal conversions","Scientific notation"]}},{"id":"number_memory_01","type":"memory_hook","order":8,"content":{"text":"Powers of 2: 1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024. To convert to binary, find which powers of 2 add up to your number and write 1 for present, 0 for absent.","hook_type":"mnemonic"}},{"id":"number_reflection_01","type":"reflection","order":9,"content":{"question":"Why do computers use binary instead of decimal?","expected_understanding":"Binary is simpler for electronic circuits — only two states (on/off, high/low voltage). This makes hardware cheaper and more reliable. Decimal would need 10 distinct voltage levels, which is harder to distinguish reliably."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What is 13 in binary?","options":[{"label":"A","text":"1101"},{"label":"B","text":"1011"},{"label":"C","text":"1110"},{"label":"D","text":"1001"}],"answer":"A","explanation":"13 = 8 + 4 + 1 = 2³ + 2² + 2⁰ = 1101 in binary.","hints":["Break 13 into powers of 2: 8 + 4 + 1"]},{"difficulty":"medium","question":"Convert 110112 to base 10.","options":[{"label":"A","text":"27"},{"label":"B","text":"25"},{"label":"C","text":"11"},{"label":"D","text":"31"}],"answer":"A","explanation":"1×16 + 1×8 + 0×4 + 1×2 + 1×1 = 16 + 8 + 2 + 1 = 27.","hints":["Multiply each digit by the power of 2 for its position"]},{"difficulty":"jamb","question":"Add 10112 and 11012 in binary.","options":[{"label":"A","text":"11000"},{"label":"B","text":"10100"},{"label":"C","text":"11100"},{"label":"D","text":"11010"}],"answer":"A","explanation":"1011 + 1101: 1+1=10 (write 0, carry 1), 1+0+1=10 (write 0, carry 1), 0+1+1=10 (write 0, carry 1), 1+1+1=11 (write 1, carry 1), carry=1. Result: 11000.","hints":["Remember: in binary, 1+1=10 (carry 1)"]}]'::jsonb, '{"min_score":80,"required_sections":["number_hook_01","number_intuitive_01","number_formal_01","number_formula_01","number_practice_01"]}'::jsonb, '1')
