INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('mathematics', 'Algebraic Expressions and Simplification', 'Basic Concepts', 'Algebra — The Language of Mathematical Relationships', '["Simplify algebraic expressions using basic operations","Factorize expressions completely","Expand brackets and collect like terms","Solve linear equations and inequalities"]'::jsonb, 'medium', '20', '[{"id":"algebra_hook_01","type":"hook","order":1,"content":{"text":"Algebra is not just ''x + y = z''. It''s the language of patterns. When you say ''I''ll save ₦500 every week,'' you''re doing algebra — your total savings after w weeks is 500w. Algebra lets you predict, calculate, and solve problems before they happen.","prediction_prompt":"If a phone costs ₦x and you have ₦5000, how many phones can you buy? Write it as an algebraic expression."}},{"id":"algebra_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"In algebra, letters represent unknown numbers. ''Like terms'' are terms that have the same variable part — you can add and subtract them like combining fruits: 3 apples + 2 apples = 5 apples, but 3 apples + 2 oranges = 3 apples + 2 oranges (can''t combine).","analogy":"Think of algebraic expressions as shopping lists. 3x + 2y means ''3 units of item x and 2 units of item y.'' You can simplify: 3x + 5x = 8x (same item), but 3x + 5y stays as is (different items)."}},{"id":"algebra_formal_01","type":"formal_explanation","order":3,"content":{"text":"An algebraic expression is a combination of variables, constants, and operations. To simplify: collect like terms, apply distributive law a(b+c) = ab + ac, and use exponent laws. Factorization is the reverse of expansion: finding what multiplies to give the expression.","key_terms":[{"term":"Variable","definition":"A letter that represents an unknown number"},{"term":"Coefficient","definition":"The number multiplying a variable (e.g., in 3x, the coefficient is 3)"},{"term":"Like Terms","definition":"Terms with the same variable(s) raised to the same power"},{"term":"Factorization","definition":"Expressing a polynomial as a product of its factors"}]}},{"id":"algebra_formula_01","type":"formula","order":4,"content":{"formula":"a(b + c) = ab + ac  |  (a + b)(c + d) = ac + ad + bc + bd","variables":[{"name":"Distributive Law","description":"a(b + c) = ab + ac — multiply each term inside the bracket"},{"name":"FOIL Method","description":"First, Outer, Inner, Last — for multiplying two brackets"},{"name":"Difference of Squares","description":"a² − b² = (a + b)(a − b)"},{"name":"Perfect Square","description":"(a ± b)² = a² ± 2ab + b²"}],"when_to_use":"Use distributive law for expanding brackets, FOIL for two brackets, and special products for quick factorization.","common_traps":["Forgetting to multiply ALL terms inside the bracket by the factor outside","Sign errors when multiplying negative terms","Not fully factorizing — always check for common factors first"],"units_note":"Algebraic expressions have no units until variables are assigned values with units."}},{"id":"algebra_interactive_graph_01","type":"interactive","order":5,"content":{"component":"graph_explorer","config":{"function":"quadratic","x_min":-5,"x_max":5},"instruction":"Change a, b and c one at a time. Then set b to zero and watch the parabola become symmetric about the y-axis, with the vertex moving to x = 0.","prediction_prompt":"If you make a negative, does the parabola still open upwards? Predict first."}},{"id":"algebra_practice_01","type":"worked_example","order":6,"content":{"scenario":"Simplify: 3(2x − 4) + 2(x + 5) − 3x","given":["An algebraic expression to simplify"],"required":"Simplify by expanding brackets and collecting like terms","principle":"Expand each bracket using the distributive law, then collect like terms.","steps":[{"explanation":"Expand 3(2x − 4)","calculation":"6x − 12"},{"explanation":"Expand 2(x + 5)","calculation":"2x + 10"},{"explanation":"Write full expression","calculation":"6x − 12 + 2x + 10 − 3x"},{"explanation":"Collect x terms","calculation":"6x + 2x − 3x = 5x"},{"explanation":"Collect constants","calculation":"−12 + 10 = −2"}],"answer":"5x − 2","check":"Expand: 5(2) − 2 = 8. Original: 3(4−4) + 2(7) − 6 = 0 + 14 − 6 = 8. ✓"}},{"id":"algebra_misconception_01","type":"common_misconception","order":7,"content":{"mistake":"(x + y)² = x² + y²","why_wrong":"This is one of the most common algebra errors. Squaring a sum is NOT the same as squaring each term separately.","correct_model":"(x + y)² = x² + 2xy + y². The middle term 2xy is essential. Use the formula: (a + b)² = a² + 2ab + b²."}},{"id":"algebra_jamb_01","type":"jamb_insight","order":8,"content":{"focus_area":"JAMB tests expansion, factorization, simplification, and solving equations. Questions often combine multiple skills.","trap":"JAMB may include expressions with negative signs before brackets. Remember: −(x − 3) = −x + 3 (both signs change).","tip":"Always factor out common factors first before attempting other factorization methods. Check: is there a number or variable that divides ALL terms?","related_topics":["Quadratic equations","Simultaneous equations","Inequalities"]}},{"id":"algebra_memory_01","type":"memory_hook","order":9,"content":{"text":"FOIL: First, Outer, Inner, Last. Difference of squares: a²−b² = (a+b)(a−b). Perfect square: (a+b)² = a²+2ab+b². Signs matter — a negative before a bracket changes EVERYTHING inside.","hook_type":"mnemonic"}},{"id":"algebra_reflection_01","type":"reflection","order":10,"content":{"question":"Why is factorization useful? How does it help in solving equations?","expected_understanding":"Factorization reveals the structure of expressions. If (x−2)(x+3) = 0, then x = 2 or x = 3. This is how we solve quadratic equations — find values that make each factor zero."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Simplify: 2x + 3x − x","options":[{"label":"A","text":"4x"},{"label":"B","text":"5x"},{"label":"C","text":"6x"},{"label":"D","text":"3x"}],"answer":"A","explanation":"2x + 3x − x = (2 + 3 − 1)x = 4x.","hints":["Combine the coefficients: 2 + 3 − 1"]},{"difficulty":"medium","question":"Expand: (2x + 3)(x − 4)","options":[{"label":"A","text":"2x² − 5x − 12"},{"label":"B","text":"2x² + 5x − 12"},{"label":"C","text":"2x² − 11x − 12"},{"label":"D","text":"2x² − 5x + 12"}],"answer":"A","explanation":"FOIL: 2x·x = 2x², 2x·(−4) = −8x, 3·x = 3x, 3·(−4) = −12. Total: 2x² − 5x − 12.","hints":["Use FOIL: First, Outer, Inner, Last"]},{"difficulty":"jamb","question":"Factorize completely: 6x² − 13x + 6","options":[{"label":"A","text":"(2x − 3)(3x − 2)"},{"label":"B","text":"(2x + 3)(3x + 2)"},{"label":"C","text":"(6x − 1)(x − 6)"},{"label":"D","text":"(3x − 6)(2x − 1)"}],"answer":"A","explanation":"6x² − 13x + 6: find two numbers that multiply to 36 (6×6) and add to −13: those are −9 and −4. Rewrite: 6x² − 9x − 4x + 6 = 3x(2x−3) − 2(2x−3) = (3x−2)(2x−3).","hints":["Use the AC method: multiply a×c = 36, find factors that sum to b = −13"]}]'::jsonb, '{"min_score":80,"required_sections":["algebra_hook_01","algebra_intuitive_01","algebra_formal_01","algebra_formula_01","algebra_practice_01"]}'::jsonb, '1')
