INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('mathematics', 'Geometry and Trigonometry', 'Shapes and Angles', 'Geometry — Understanding Shapes, Angles, and Triangles', '["Calculate angles in triangles, quadrilaterals, and circles","Apply Pythagoras theorem and trigonometric ratios","Solve problems involving area and volume of 3D shapes","Use sine rule and cosine rule for non-right-angled triangles"]'::jsonb, 'hard', '25', '[{"id":"geo_hook_01","type":"hook","order":1,"content":{"text":"Every building, bridge, and phone screen uses geometry. When an architect designs a house, they calculate angles to make sure walls are straight, roofs don''t collapse, and doors fit. Geometry is not just about drawing shapes — it''s about understanding the rules that govern space.","prediction_prompt":"A ladder leans against a wall at 60° to the ground. If the ladder is 5m long, how high does it reach? Can you figure it out without trigonometry?"}},{"id":"geo_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Geometry is about relationships between points, lines, and shapes. Angles tell us how much something turns. Triangles are the strongest shape — they can''t be deformed without changing the length of a side. This is why bridges use triangular frameworks. The angles in ANY triangle always add up to 180°.","analogy":"Think of a triangle like a three-legged stool. If you know two legs (angles), the third is determined. Two angles always determine the third because 180° − angle1 − angle2 = angle3. This is why triangles are so useful in construction and navigation."}},{"id":"geo_formal_01","type":"formal_explanation","order":3,"content":{"text":"Key geometry rules: (1) Angles on a straight line sum to 180°. (2) Angles in a triangle sum to 180°. (3) Opposite angles at a point are equal. (4) Angles in a quadrilateral sum to 360°. (5) Angle at centre of circle = 2 × angle at circumference. (6) Pythagoras: a² + b² = c² for right-angled triangles.","key_terms":[{"term":"Pythagoras Theorem","definition":"In a right-angled triangle, the square of the hypotenuse equals the sum of squares of the other two sides: a² + b² = c²"},{"term":"Sine","definition":"sin θ = opposite/hypotenuse"},{"term":"Cosine","definition":"cos θ = adjacent/hypotenuse"},{"term":"Tangent","definition":"tan θ = opposite/adjacent"}]}},{"id":"geo_formula_01","type":"formula","order":4,"content":{"formula":"sin θ = opp/hyp  |  cos θ = adj/hyp  |  tan θ = opp/adj  |  a² + b² = c²","variables":[{"name":"θ","description":"The angle being calculated or used","unit":"degrees or radians"},{"name":"opp","description":"Side opposite to the angle","unit":"length"},{"name":"adj","description":"Side adjacent to the angle","unit":"length"},{"name":"hyp","description":"Hypotenuse (longest side, opposite right angle)","unit":"length"}],"when_to_use":"SOH CAH TOA: Sine=Opp/Hyp, Cosine=Adj/Hyp, Tangent=Opp/Adj. Use Pythagoras to find missing sides in right triangles.","common_traps":["Using the wrong trig ratio — always label the sides relative to the angle first","Confusing the hypotenuse with the adjacent side","Forgetting to set calculator to degrees mode"],"units_note":"Angles in degrees for JAMB. Convert radians: π radians = 180°."}},{"id":"geo_practice_01","type":"worked_example","order":5,"content":{"scenario":"A ship sails 10km on a bearing of 030°, then 8km on a bearing of 120°. How far is the ship from its starting point?","given":["Two bearings and distances"],"required":"Find the straight-line distance from start to end","principle":"Draw a diagram. Use the cosine rule or resolve into components.","steps":[{"explanation":"Draw the path","calculation":"First leg: 10km at 30° from north. Second leg: 8km at 120° from north."},{"explanation":"Find the angle between the two legs","calculation":"120° − 30° = 90° between the two directions"},{"explanation":"Apply Pythagoras (right angle)","calculation":"d² = 10² + 8² = 100 + 64 = 164"},{"explanation":"Find distance","calculation":"d = √164 = 2√41 ≈ 12.8 km"}],"answer":"The ship is approximately 12.8 km from its starting point.","check":"Since the angle between paths is 90°, Pythagoras applies directly."}},{"id":"geo_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"sin(A + B) = sin A + sin B","why_wrong":"This is a common error. Trigonometric functions do NOT distribute over addition. The correct formula is sin(A + B) = sin A cos B + cos A sin B.","correct_model":"Use the compound angle formulas: sin(A±B) = sinA cosB ± cosA sinB. Never assume sin(A+B) = sinA + sinB."}},{"id":"geo_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB geometry tests Pythagoras, trigonometric ratios, circle theorems, bearings, and area/volume calculations.","trap":"JAMB often includes bearing questions where students confuse the angle from north with the angle from the horizontal. Bearings are measured clockwise from north.","tip":"For bearings: always draw a north line at each point. The bearing is the angle measured clockwise from north. Use trig to resolve into north-south and east-west components.","related_topics":["Bearings and navigation","Circle theorems","Mensuration"]}},{"id":"geo_memory_01","type":"memory_hook","order":8,"content":{"text":"SOH CAH TOA: Sin=Opp/Hyp, Cos=Adj/Hyp, Tan=Opp/Adj. Pythagoras: a²+b²=c². Triangle angles = 180°. Circle: angle at centre = 2× angle at circumference.","hook_type":"mnemonic"}},{"id":"geo_reflection_01","type":"reflection","order":9,"content":{"question":"Why are triangles used in bridge construction instead of squares?","expected_understanding":"Triangles are rigid — they cannot be deformed without changing side lengths. Squares can be pushed into parallelograms. This is why trusses (triangular frameworks) are used in bridges and roof structures."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"In a right-angled triangle, if two sides are 3cm and 4cm, what is the hypotenuse?","options":[{"label":"A","text":"5cm"},{"label":"B","text":"6cm"},{"label":"C","text":"7cm"},{"label":"D","text":"25cm"}],"answer":"A","explanation":"By Pythagoras: c² = 3² + 4² = 9 + 16 = 25, so c = 5cm.","hints":["Use Pythagoras: a² + b² = c²"]},{"difficulty":"medium","question":"What is sin 30°?","options":[{"label":"A","text":"0.5"},{"label":"B","text":"0.707"},{"label":"C","text":"0.866"},{"label":"D","text":"1"}],"answer":"A","explanation":"sin 30° = 0.5. This is one of the standard angles you should memorize.","hints":["sin 30° = 1/2"]},{"difficulty":"jamb","question":"A ladder 10m long leans against a wall at 60° to the ground. How high up the wall does it reach?","options":[{"label":"A","text":"5m"},{"label":"B","text":"8.66m"},{"label":"C","text":"5√3 m"},{"label":"D","text":"Both B and C"}],"answer":"D","explanation":"sin 60° = height/10. Height = 10 × sin 60° = 10 × (√3/2) = 5√3 ≈ 8.66m.","hints":["sin 60° = √3/2 ≈ 0.866. Use sin = opposite/hypotenuse"]}]'::jsonb, '{"min_score":80,"required_sections":["geo_hook_01","geo_intuitive_01","geo_formal_01","geo_formula_01","geo_practice_01"]}'::jsonb, '1')
