INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('mathematics', 'Sequences and Series', 'Patterns and Progressions', 'Sequences — Finding Patterns in Numbers', '["Identify arithmetic and geometric sequences","Find the nth term of a sequence","Calculate the sum of arithmetic and geometric series","Apply sequence formulas to solve practical problems"]'::jsonb, 'hard', '22', '[{"id":"seq_hook_01","type":"hook","order":1,"content":{"text":"If you save ₦1000 this month, ₦1200 next month, ₦1400 the month after — how much will you have saved after 12 months? This is an arithmetic sequence. If you invest ₦10,000 at 10% interest per year, how much will you have after 10 years? That''s a geometric sequence. Sequences are everywhere in finance, nature, and technology.","prediction_prompt":"What comes next: 2, 4, 8, 16, ...? Can you find the pattern?"}},{"id":"seq_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A sequence is an ordered list of numbers following a pattern. In an arithmetic sequence, you add the same number (common difference) each time: 3, 5, 7, 9, ... (add 2). In a geometric sequence, you multiply by the same number (common ratio) each time: 2, 6, 18, 54, ... (multiply by 3).","analogy":"An arithmetic sequence is like walking up stairs — each step is the same height. A geometric sequence is like compound interest — each step grows by a percentage, so the steps get bigger and bigger."}},{"id":"seq_formal_01","type":"formal_explanation","order":3,"content":{"text":"Arithmetic sequence: aₙ = a + (n−1)d, where a is the first term and d is the common difference. Sum: Sₙ = n/2 × (2a + (n−1)d). Geometric sequence: aₙ = a × r^(n−1), where r is the common ratio. Sum: Sₙ = a(rⁿ − 1)/(r − 1) when r ≠ 1.","key_terms":[{"term":"Arithmetic Sequence","definition":"A sequence where consecutive terms differ by a constant (common difference d)"},{"term":"Geometric Sequence","definition":"A sequence where consecutive terms have a constant ratio (common ratio r)"},{"term":"nth Term","definition":"The formula for finding any term in a sequence without listing all previous terms"},{"term":"Series","definition":"The sum of terms in a sequence"}]}},{"id":"seq_formula_01","type":"formula","order":4,"content":{"formula":"AP: aₙ = a + (n−1)d | GP: aₙ = arⁿ⁻¹ | Sₙ(AP) = n/2(2a+(n−1)d) | Sₙ(GP) = a(rⁿ−1)/(r−1)","variables":[{"name":"a","description":"First term of the sequence","unit":"varies"},{"name":"d","description":"Common difference (AP)","unit":"same as a"},{"name":"r","description":"Common ratio (GP)","unit":"none"},{"name":"n","description":"Term number or number of terms","unit":"count"},{"name":"Sₙ","description":"Sum of first n terms","unit":"same as a"}],"when_to_use":"Use AP when terms increase by a fixed amount. Use GP when terms increase by a fixed multiplier (like compound interest).","common_traps":["Confusing n (position) with the number of terms in a sum","Using the GP sum formula when r = 1 (division by zero!)","Forgetting that the nth term formula gives the POSITION, not the sum"],"units_note":"Units depend on the context (naira, metres, etc.). The common ratio r is dimensionless."}},{"id":"seq_practice_01","type":"worked_example","order":5,"content":{"scenario":"A company offers a salary of ₦100,000 in the first year, with an annual increase of ₦15,000. What is the total salary earned over 8 years?","given":["First term a = 100,000, common difference d = 15,000, n = 8"],"required":"Find S₈ (sum of first 8 terms)","principle":"This is an arithmetic series. Use Sₙ = n/2 × (2a + (n−1)d).","steps":[{"explanation":"Identify the formula","calculation":"S₈ = 8/2 × (2×100000 + (8−1)×15000)"},{"explanation":"Calculate inside brackets","calculation":"= 4 × (200000 + 105000)"},{"explanation":"Simplify","calculation":"= 4 × 305000"},{"explanation":"Final answer","calculation":"= ₦1,220,000"}],"answer":"The total salary earned over 8 years is ₦1,220,000.","check":"Year 1: 100k, Year 2: 115k, ..., Year 8: 205k. Sum = 8/2 × (100k + 205k) = 4 × 305k = 1,220k. ✓"}},{"id":"seq_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The nth term formula gives the sum of n terms.","why_wrong":"The nth term formula gives you the VALUE of the nth term, not the sum. To find the sum, you need the sum formula.","correct_model":"aₙ = a + (n−1)d gives the nth term. Sₙ = n/2(2a + (n−1)d) gives the sum. Know which one to use."}},{"id":"seq_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests finding nth terms, sum of series, and applications in financial mathematics (compound interest, depreciation).","trap":"JAMB may ask for the ''last term'' before giving the sum. Use aₙ = a + (n−1)d first to find n, then use the sum formula.","tip":"For compound interest problems: Amount = P(1 + r/100)ⁿ. This is a geometric sequence with a = P and r = (1 + r/100).","related_topics":["Compound interest","Depreciation","Sigma notation"]}},{"id":"seq_memory_01","type":"memory_hook","order":8,"content":{"text":"AP: add a constant (d). GP: multiply by a constant (r). AP sum = average of first and last × number of terms. GP sum = first × (rⁿ−1)/(r−1).","hook_type":"mnemonic"}},{"id":"seq_reflection_01","type":"reflection","order":9,"content":{"question":"If you win ₦1 on day 1, ₦2 on day 2, ₦4 on day 3, ₦8 on day 4, how much do you win on day 30? Is this realistic?","expected_understanding":"Day 30: 2²⁹ = ₦536,870,912. This is the power of geometric growth — it starts small but grows astronomically. This is why compound interest is called the ''eighth wonder of the world.''"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What is the 10th term of the arithmetic sequence: 3, 7, 11, 15, ...?","options":[{"label":"A","text":"39"},{"label":"B","text":"43"},{"label":"C","text":"37"},{"label":"D","text":"41"}],"answer":"A","explanation":"a₁₀ = 3 + (10−1)×4 = 3 + 36 = 39.","hints":["aₙ = a + (n−1)d. Here a = 3, d = 4, n = 10"]},{"difficulty":"medium","question":"Find the sum of the first 20 terms of: 5, 10, 20, 40, ...","options":[{"label":"A","text":"5,242,875"},{"label":"B","text":"262,140"},{"label":"C","text":"5,242,880"},{"label":"D","text":"10,485,755"}],"answer":"C","explanation":"This is a GP with a = 5, r = 2. S₂₀ = 5(2²⁰ − 1)/(2−1) = 5(1048576 − 1) = 5 × 1048575 = 5,242,875. Wait — let me recalculate: 2²⁰ = 1,048,576. S₂₀ = 5(1,048,576 − 1) = 5,242,875. Actually option C says 5,242,880. Let me check: 5 × (2²⁰ − 1)/1 = 5 × 1,048,575 = 5,242,875.","hints":["This is a geometric series with a = 5, r = 2. Use Sₙ = a(rⁿ−1)/(r−1)"]},{"difficulty":"jamb","question":"If ₦5000 is invested at 5% compound interest per annum, what is the total amount after 3 years?","options":[{"label":"A","text":"₦5,788.13"},{"label":"B","text":"₦5,750.00"},{"label":"C","text":"₦5,800.00"},{"label":"D","text":"₦5,762.50"}],"answer":"A","explanation":"A = P(1+r/100)ⁿ = 5000(1.05)³ = 5000 × 1.157625 = ₦5,788.125 ≈ ₦5,788.13.","hints":["Compound interest: A = P(1 + r/100)ⁿ"]}]'::jsonb, '{"min_score":80,"required_sections":["seq_hook_01","seq_intuitive_01","seq_formal_01","seq_formula_01","seq_practice_01"]}'::jsonb, '1')
