INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Forces', 'Mechanics', 'Forces — Understanding How Things Push and Pull', '["Define force and state its SI unit","Identify types of forces: weight, normal reaction, friction, tension, applied force","Apply Newton''s Second Law (F = ma) to solve problems","Distinguish between contact and non-contact forces"]'::jsonb, 'medium', '20', '[{"id":"forces_hook_01","type":"hook","order":1,"content":{"text":"Why does a book slide off a table if you push it gently, but stays still if you just place it there? Why does a car need its engine running to move on a rough road? Why does a ball thrown upward slow down and come back? All of these involve forces — pushes and pulls that change how objects move.","prediction_prompt":"If you throw a ball straight up, what force acts on it while it''s in the air? Does the ball have a force acting on it at the highest point?"}},{"id":"forces_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A force is simply a push or a pull. When you push a door, you apply a force. When gravity pulls you down, that''s a force. Friction slows your sliding car — that''s a force too. Forces change motion: they can speed things up, slow them down, change direction, or deform objects.","analogy":"Think of football. When a player kicks the ball, they apply a force. The ball accelerates. When friction from the grass acts on the ball, it slows down. When gravity pulls it down, it follows a curved path. Every change in the ball''s motion is caused by a force."}},{"id":"forces_formal_01","type":"formal_explanation","order":3,"content":{"text":"A force is a vector quantity that causes a change in the state of rest or motion of a body. Forces are measured in Newtons (N). 1 N is the force needed to accelerate a 1 kg mass at 1 m/s². Forces can be contact forces (friction, tension, normal reaction) or non-contact forces (gravity, electrostatic, magnetic).","key_terms":[{"term":"Weight (W)","definition":"Gravitational force on an object. W = mg. Acts downwards. SI unit: Newton (N)"},{"term":"Normal reaction (R or N)","definition":"Perpendicular contact force from a surface. Acts perpendicular to the surface."},{"term":"Friction (Ff)","definition":"Force opposing motion between surfaces in contact. Acts opposite to direction of motion."},{"term":"Tension (T)","definition":"Force transmitted through a string, rope, or cable when pulled taut."},{"term":"Applied force (F)","definition":"External push or pull applied to an object."}]}},{"id":"forces_formula_01","type":"formula","order":4,"content":{"formula":"F = ma","variables":[{"name":"F","description":"Resultant force","unit":"N (Newtons)"},{"name":"m","description":"Mass","unit":"kg (kilograms)"},{"name":"a","description":"Acceleration","unit":"m/s²"}],"when_to_use":"When you know the mass of an object and the net force acting on it (or vice versa) and need to find acceleration. Newton''s Second Law.","common_traps":["Confusing mass and weight. Mass is in kg (scalar). Weight is in N (vector, W = mg).","Using F = ma when forces are not all in the same direction — resolve forces first.","Forgetting that friction opposes motion — it acts in the opposite direction to the applied force."],"units_note":"F in newtons, m in kilograms, a in m/s². If mass is given in grams, convert to kg (÷ 1000)."}},{"id":"forces_interactive_pendulum_01","type":"interactive","order":5,"content":{"component":"pendulum_simulator","config":{"length":1,"angle":30,"gravity":9.8},"instruction":"Double the length and watch the period. Then change the initial angle — does the period change? Add damping and watch the energy bar fall.","prediction_prompt":"Does the period of a pendulum depend on how far you pull it back, or only on its length? Predict before you change the angle."}},{"id":"forces_worked_example_01","type":"worked_example","order":6,"content":{"scenario":"A block of mass 5 kg is placed on a smooth (frictionless) horizontal surface. A horizontal force of 20 N is applied. Calculate the acceleration of the block.","given":["m = 5 kg","F = 20 N","Surface is frictionless"],"required":"a (acceleration)","principle":"Newton''s Second Law: F = ma. Rearrange to find a = F/m.","steps":[{"explanation":"Write Newton''s Second Law","calculation":"F = ma"},{"explanation":"Rearrange for acceleration","calculation":"a = F/m"},{"explanation":"Substitute values","calculation":"a = 20/5 = 4 m/s²"}],"answer":"a = 4 m/s²","check":"F = ma = 5 × 4 = 20 N ✓"}},{"id":"forces_misconception_01","type":"common_misconception","order":7,"content":{"mistake":"A heavier object falls faster than a lighter one because it has more weight.","why_wrong":"In the absence of air resistance, ALL objects fall with the same acceleration (g ≈ 10 m/s²) regardless of mass. Weight increases, but so does the mass being accelerated — they cancel out.","correct_model":"Near the Earth''s surface, all objects in free fall accelerate at g ≈ 10 m/s², whether heavy or light. Galileo demonstrated this."}},{"id":"forces_jamb_01","type":"jamb_insight","order":8,"content":{"focus_area":"JAMB tests F = ma calculations, free-body diagrams, and resolving forces on inclined planes. They often give a scenario and ask for acceleration or a specific force.","trap":"JAMB may give mass in grams — convert to kg. Also, on inclined planes, the component of weight along the plane is mg sin θ, not mg.","tip":"Draw a free-body diagram for every forces problem. Identify all forces, resolve into components, then apply F = ma in each direction.","related_topics":["Motion","Moments","Work, energy, power"]}},{"id":"forces_memory_01","type":"memory_hook","order":9,"content":{"text":"F = ma. Think ''Force = Mass × acceleration''. A big force on a small mass gives big acceleration. A small force on a big mass gives small acceleration. Newton''s Second Law.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A 10 kg object is pushed with a force of 50 N on a frictionless surface. What is its acceleration?","options":[{"label":"A","text":"5 m/s²"},{"label":"B","text":"500 m/s²"},{"label":"C","text":"0.2 m/s²"},{"label":"D","text":"10 m/s²"}],"answer":"A","explanation":"a = F/m = 50/10 = 5 m/s²","hints":["Use F = ma","Rearrange: a = F/m"]},{"difficulty":"medium","question":"A car of mass 1200 kg accelerates from rest to 20 m/s in 10 seconds. What is the net force acting on it?","options":[{"label":"A","text":"2400 N"},{"label":"B","text":"1200 N"},{"label":"C","text":"6000 N"},{"label":"D","text":"24000 N"}],"answer":"A","explanation":"a = (v - u)/t = (20 - 0)/10 = 2 m/s². F = ma = 1200 × 2 = 2400 N","hints":["First find acceleration: a = (v-u)/t","Then use F = ma"]},{"difficulty":"jamb","question":"A body of weight 100 N is placed on a horizontal surface. If the coefficient of friction is 0.2, what is the minimum horizontal force needed to move the body? (g = 10 m/s²)","options":[{"label":"A","text":"20 N"},{"label":"B","text":"50 N"},{"label":"C","text":"100 N"},{"label":"D","text":"500 N"}],"answer":"A","explanation":"Mass = W/g = 100/10 = 10 kg. Maximum friction = μR = μmg = 0.2 × 100 = 20 N. Minimum force to move = 20 N.","hints":["Friction force = μ × normal reaction","Normal reaction = weight on horizontal surface","On horizontal surface, R = mg = W"]}]'::jsonb, '{"min_score":80,"required_sections":["forces_hook_01","forces_intuitive_01","forces_formal_01","forces_formula_01","forces_worked_example_01"]}'::jsonb, '1')
