INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Work, energy, power', 'Mechanics', 'Work, Energy, and Power — How Energy Moves and Transforms', '["Define work, energy, and power and state their SI units","Calculate work done using W = Fs cos θ","Apply the work-energy theorem and conservation of energy","Calculate kinetic energy, potential energy, and power"]'::jsonb, 'medium', '22', '[{"id":"work_energy_hook_01","type":"hook","order":1,"content":{"text":"Why does a heavy ball do more damage than a light one when thrown at the same speed? Why does a car need more fuel to go faster? Why does a pendulum swing back to the same height? All of these involve energy — how it''s stored, transferred, and transformed.","prediction_prompt":"A ball is dropped from a height of 20 m. Just before it hits the ground, how fast is it moving? Can you estimate without any formula?"}},{"id":"work_energy_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Work is done when you push something and it moves. If you push a wall and it doesn''t move, you''ve done no work (physically). Energy is the ability to do work. Power is how fast you do work — a powerful engine does work quickly.","analogy":"Think of carrying buckets of water upstairs. Work = weight of bucket × height climbed. If you carry 2 buckets vs 1, you do double the work. If you run up instead of walk, you do the same work but in less time — more power."}},{"id":"work_energy_formal_01","type":"formal_explanation","order":3,"content":{"text":"Work is done when a force acts on a body and the body moves in the direction of the force. Work = Force × displacement in the direction of the force. Energy is the capacity to do work. Kinetic energy is energy of motion. Potential energy is stored energy due to position. Power is the rate of doing work.","key_terms":[{"term":"Work (W)","definition":"W = Fs cos θ. SI unit: Joule (J). 1 J = 1 N × 1 m."},{"term":"Kinetic Energy (KE)","definition":"Energy of a moving body. KE = ½mv². SI unit: Joule (J)"},{"term":"Potential Energy (PE)","definition":"Stored energy due to position. PE = mgh (gravitational). SI unit: Joule (J)"},{"term":"Power (P)","definition":"Rate of doing work. P = W/t = Fv. SI unit: Watt (W). 1 W = 1 J/s"}]}},{"id":"work_energy_formula_01","type":"formula","order":4,"content":{"formula":"W = Fs cos θ, KE = ½mv², PE = mgh, P = W/t","variables":[{"name":"W","description":"Work done","unit":"J (Joules)"},{"name":"F","description":"Applied force","unit":"N (Newtons)"},{"name":"s","description":"Displacement","unit":"m (metres)"},{"name":"θ","description":"Angle between force and displacement","unit":"degrees"},{"name":"m","description":"Mass","unit":"kg"},{"name":"v","description":"Velocity","unit":"m/s"},{"name":"g","description":"Acceleration due to gravity","unit":"m/s² (≈ 10)"},{"name":"h","description":"Height","unit":"m"},{"name":"P","description":"Power","unit":"W (Watts)"},{"name":"t","description":"Time","unit":"s"}],"when_to_use":"W = Fs cos θ for work done by a force. KE = ½mv² for energy of motion. PE = mgh for gravitational potential energy. P = W/t for average power.","common_traps":["Using W = Fs when the force is at an angle — use W = Fs cos θ.","Confusing weight (mg) with mass (m). Weight is in N, mass in kg.","Forgetting that at the highest point of a projectile, KE is minimum (not zero for horizontal projectiles) and PE is maximum."],"units_note":"All energy in joules. Force in N, distance in m, mass in kg, velocity in m/s, height in m, g ≈ 10 m/s²."}},{"id":"work_energy_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A ball is dropped from a height of 20 m. Assuming no air resistance, calculate its velocity just before hitting the ground. (g = 10 m/s²)","given":["h = 20 m","u = 0 (dropped)","g = 10 m/s²"],"required":"v (final velocity)","principle":"Conservation of energy: PE at top = KE at bottom. mgh = ½mv²","steps":[{"explanation":"At the top, all energy is PE","calculation":"PE = mgh"},{"explanation":"At the bottom, all energy is KE","calculation":"KE = ½mv²"},{"explanation":"By conservation of energy: PE = KE","calculation":"mgh = ½mv²"},{"explanation":"Mass cancels out","calculation":"gh = ½v²"},{"explanation":"Rearrange for v","calculation":"v² = 2gh = 2 × 10 × 20 = 400"},{"explanation":"Take square root","calculation":"v = √400 = 20 m/s"}],"answer":"v = 20 m/s","check":"KE = ½mv² = ½ × m × 400 = 200m. PE = mgh = m × 10 × 20 = 200m. ✓"}},{"id":"work_energy_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"When a ball is thrown upward, at the highest point its kinetic energy is maximum.","why_wrong":"At the highest point, velocity is zero (for vertical throw), so KE = ½mv² = 0. All the energy has been converted to PE.","correct_model":"KE is maximum at launch (when velocity is highest). KE decreases as the ball rises (converted to PE). At the top, KE = 0, PE = maximum."}},{"id":"work_energy_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests conservation of energy, work-energy theorem, and power calculations. They often give scenarios involving falling bodies, pendulums, or inclines.","trap":"JAMB may ask for velocity at a certain height, not at the ground. Make sure you know what height they''re asking about.","tip":"Conservation of energy is your best friend: Total energy at start = Total energy at end. If energy is lost to friction, account for it.","related_topics":["Forces","Motion","Simple machines"]}},{"id":"work_energy_memory_01","type":"memory_hook","order":8,"content":{"text":"Work = Force × Distance (in direction of force). Energy = ability to do work. Power = how fast you do work. Think: WEP — Work, Energy, Power.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A force of 10 N pushes a box 5 m along the direction of the force. How much work is done?","options":[{"label":"A","text":"50 J"},{"label":"B","text":"2 J"},{"label":"C","text":"15 J"},{"label":"D","text":"5 J"}],"answer":"A","explanation":"W = Fs = 10 × 5 = 50 J","hints":["Work = Force × distance","W = Fs"]},{"difficulty":"medium","question":"A 2 kg ball is thrown vertically upward with a speed of 15 m/s. What is its maximum height? (g = 10 m/s²)","options":[{"label":"A","text":"11.25 m"},{"label":"B","text":"22.5 m"},{"label":"C","text":"15 m"},{"label":"D","text":"7.5 m"}],"answer":"A","explanation":"At max height, KE = PE. ½mv² = mgh → ½(15²) = 10h → 112.5 = 10h → h = 11.25 m","hints":["At max height, all KE converts to PE","½mv² = mgh","Mass cancels: ½v² = gh"]},{"difficulty":"jamb","question":"An engine moves a car of mass 800 kg along a horizontal road at a constant speed of 20 m/s. If the resistance to motion is 400 N, what is the power of the engine?","options":[{"label":"A","text":"8 kW"},{"label":"B","text":"16 kW"},{"label":"C","text":"4 kW"},{"label":"D","text":"32 kW"}],"answer":"A","explanation":"At constant speed, driving force = resistance = 400 N. P = Fv = 400 × 20 = 8000 W = 8 kW.","hints":["At constant speed, driving force = resistance","Power = Force × velocity","P = Fv"]}]'::jsonb, '{"min_score":80,"required_sections":["work_energy_hook_01","work_energy_intuitive_01","work_energy_formal_01","work_energy_formula_01","work_energy_worked_example_01"]}'::jsonb, '1')
