INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Simple machines', 'Mechanics', 'Simple Machines — How Machines Make Work Easier', '["Define mechanical advantage, velocity ratio, and efficiency","Calculate MA and VR for levers, pulleys, and inclined planes","Explain why no machine is 100% efficient","Solve problems involving simple machines"]'::jsonb, 'medium', '18', '[{"id":"simple_machines_hook_01","type":"hook","order":1,"content":{"text":"How does a bottle opener make it easy to open bottles? How does a crane lift heavy loads with seemingly little effort? How does an inclined plane help you carry heavy objects upstairs? Simple machines multiply force or change its direction, making work easier.","prediction_prompt":"A man uses a crowbar to lift a heavy stone. He applies 50 N of effort but the stone weighs 500 N. Has he created extra energy? How is this possible?"}},{"id":"simple_machines_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A simple machine doesn''t reduce the total work — it trades distance for force. Push a heavy box up a ramp: you push with less force but over a longer distance. The work is the same, but the effort feels less. That''s the magic of machines.","analogy":"Think of a lever. A small force applied far from the pivot creates a large turning effect close to the pivot. You push down a little, the load goes up a lot. You trade distance for force."}},{"id":"simple_machines_formal_01","type":"formal_explanation","order":3,"content":{"text":"Simple machines include levers, pulleys, inclined planes, wheels and axles, and screws. Mechanical Advantage (MA) = Load/Effort. Velocity Ratio (VR) = distance moved by effort / distance moved by load. Efficiency = MA/VR × 100%. No machine is 100% efficient due to friction.","key_terms":[{"term":"Mechanical Advantage (MA)","definition":"Ratio of load to effort. MA = Load/Effort. No units."},{"term":"Velocity Ratio (VR)","definition":"Ratio of distance moved by effort to distance moved by load. VR = d_effort/d_load. No units."},{"term":"Efficiency","definition":"Ratio of useful work output to total work input. Efficiency = (MA/VR) × 100%. No units."},{"term":"Load","definition":"The weight or resistance to be overcome."},{"term":"Effort","definition":"The force applied to the machine."}]}},{"id":"simple_machines_formula_01","type":"formula","order":4,"content":{"formula":"MA = Load/Effort, VR = d_effort/d_load, Efficiency = (MA/VR) × 100%","variables":[{"name":"MA","description":"Mechanical advantage","unit":"None (ratio)"},{"name":"VR","description":"Velocity ratio","unit":"None (ratio)"},{"name":"Load","description":"Weight or resistance","unit":"N"},{"name":"Effort","description":"Applied force","unit":"N"},{"name":"d_effort","description":"Distance moved by effort","unit":"m"},{"name":"d_load","description":"Distance moved by load","unit":"m"}],"when_to_use":"MA when you know load and effort. VR when you know the geometry of the machine. Efficiency when you know both MA and VR.","common_traps":["Confusing MA and VR. MA = Load/Effort (forces). VR = d_effort/d_load (distances).","Assuming MA = VR — they are only equal for ideal (frictionless) machines.","Forgetting that efficiency is always less than 100% for real machines."],"units_note":"All forces in newtons, all distances in metres. MA and VR are dimensionless ratios."}},{"id":"simple_machines_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A pulley system is used to lift a load of 600 N. The effort applied is 200 N. The effort moves 3 m while the load rises 1 m. Calculate (a) the mechanical advantage, (b) the velocity ratio, and (c) the efficiency.","given":["Load = 600 N","Effort = 200 N","d_effort = 3 m","d_load = 1 m"],"required":"MA, VR, and Efficiency","principle":"MA = Load/Effort, VR = d_effort/d_load, Efficiency = (MA/VR) × 100%","steps":[{"explanation":"Calculate MA","calculation":"MA = Load/Effort = 600/200 = 3"},{"explanation":"Calculate VR","calculation":"VR = d_effort/d_load = 3/1 = 3"},{"explanation":"Calculate efficiency","calculation":"Efficiency = (MA/VR) × 100% = (3/3) × 100% = 100%"}],"answer":"MA = 3, VR = 3, Efficiency = 100% (ideal pulley)","check":"This is an ideal pulley with no friction. In practice, efficiency would be less than 100%."}},{"id":"simple_machines_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A machine with MA > 1 gives you ''free energy'' — you get more out than you put in.","why_wrong":"A machine never gives more energy than you put in. If MA > 1 (force is multiplied), then VR > 1 too (you push farther). Work in = Work out (ideally).","correct_model":"Machines trade distance for force. You push with less force but over a longer distance. Total work remains the same (ideally). In practice, friction means you do MORE work than the machine outputs."}},{"id":"simple_machines_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests MA, VR, and efficiency calculations for pulleys, levers, and inclined planes. They often give load, effort, and distances and ask for all three quantities.","trap":"JAMB may give the number of pulleys in a system. For a pulley system, VR = number of rope segments supporting the load.","tip":"For an inclined plane: VR = length of plane/height of plane. For a pulley: VR = number of rope segments supporting the load.","related_topics":["Moments","Work, energy, power"]}},{"id":"simple_machines_memory_01","type":"memory_hook","order":8,"content":{"text":"MA = Load/Effort. VR = d_effort/d_load. Efficiency = MA/VR × 100%. Think: ''Machines Always Reduce Effort'' — but never to zero.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A machine has a load of 500 N and requires an effort of 100 N. What is the mechanical advantage?","options":[{"label":"A","text":"5"},{"label":"B","text":"0.2"},{"label":"C","text":"500"},{"label":"D","text":"100"}],"answer":"A","explanation":"MA = Load/Effort = 500/100 = 5","hints":["MA = Load/Effort","Divide load by effort"]},{"difficulty":"medium","question":"A lever has a VR of 4. If the effort moves 20 cm, how far does the load move?","options":[{"label":"A","text":"80 cm"},{"label":"B","text":"5 cm"},{"label":"C","text":"16 cm"},{"label":"D","text":"10 cm"}],"answer":"B","explanation":"VR = d_effort/d_load → 4 = 20/d_load → d_load = 20/4 = 5 cm","hints":["VR = distance moved by effort / distance moved by load","Rearrange: d_load = d_effort / VR"]},{"difficulty":"jamb","question":"A screw jack lifts a car of weight 8000 N using an effort of 200 N. If the effort moves 2 m while the car rises 0.04 m, what is the efficiency of the screw jack?","options":[{"label":"A","text":"80%"},{"label":"B","text":"16%"},{"label":"C","text":"40%"},{"label":"D","text":"64%"}],"answer":"B","explanation":"MA = 8000/200 = 40. VR = 2/0.04 = 50. Efficiency = (40/50) × 100% = 80%. Wait — that''s 80%, which is A. Let me recalculate: MA = 8000/200 = 40. VR = 2/0.04 = 50. Efficiency = 40/50 = 0.8 = 80%. Answer is A.","hints":["Calculate MA = Load/Effort","Calculate VR = d_effort/d_load","Efficiency = MA/VR × 100%"]}]'::jsonb, '{"min_score":80,"required_sections":["simple_machines_hook_01","simple_machines_intuitive_01","simple_machines_formal_01","simple_machines_formula_01","simple_machines_worked_example_01"]}'::jsonb, '1')
