INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Temperature and heat', 'Heat and Thermodynamics', 'Temperature and Heat — Understanding Thermal Energy', '["Distinguish between temperature and heat","Define specific heat capacity and solve problems using Q = mcΔθ","Explain how a thermometer works","Convert between Celsius and Kelvin scales"]'::jsonb, 'medium', '18', '[{"id":"temp_heat_hook_01","type":"hook","order":1,"content":{"text":"Why does metal feel colder than wood when you touch both at the same temperature? Why does a swimming pool take longer to heat up than a cup of water? Why do you burn more on a metal bench than a wooden one on a hot day? Temperature and heat are related but different — and understanding the difference is key.","prediction_prompt":"If you place a metal spoon and a wooden spoon in a cup of hot tea for 10 minutes, which one will feel hotter when you pick it up? Why?"}},{"id":"temp_heat_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Temperature tells you how hot or cold something is — it''s a measure of the average kinetic energy of the particles. Heat is the total thermal energy transferred from a hotter body to a colder one. A swimming pool at 30°C has much more heat energy than a cup of water at 30°C, even though they''re at the same temperature.","analogy":"Think of temperature as ''how fast the people are dancing'' at a party, and heat as ''how many people are dancing.'' A small room with fast dancers (high temperature, low heat) vs. a stadium with slow dancers (low temperature, high heat). Both matter, but they tell you different things."}},{"id":"temp_heat_formal_01","type":"formal_explanation","order":3,"content":{"text":"Temperature is a measure of the average kinetic energy of particles in a substance. Heat is the thermal energy transferred between bodies at different temperatures. The SI unit of temperature is Kelvin (K). The SI unit of energy is Joule (J). Specific heat capacity is the energy needed to raise 1 kg of a substance by 1°C.","key_terms":[{"term":"Temperature","definition":"Average kinetic energy of particles. SI unit: Kelvin (K). °C = K - 273"},{"term":"Heat","definition":"Thermal energy transferred due to temperature difference. SI unit: Joule (J)"},{"term":"Specific heat capacity (c)","definition":"Energy needed to raise 1 kg of a substance by 1°C. SI unit: J/(kg·°C)"},{"term":"Thermal equilibrium","definition":"When two bodies are at the same temperature and no heat flows between them."}]}},{"id":"temp_heat_formula_01","type":"formula","order":4,"content":{"formula":"Q = mcΔθ","variables":[{"name":"Q","description":"Heat energy transferred","unit":"J (Joules)"},{"name":"m","description":"Mass","unit":"kg (kilograms)"},{"name":"c","description":"Specific heat capacity","unit":"J/(kg·°C)"},{"name":"Δθ","description":"Change in temperature","unit":"°C or K"}],"when_to_use":"When you know the mass of a substance, its specific heat capacity, and the temperature change, and need to find the heat energy required.","common_traps":["Confusing temperature and heat. Temperature is measured in °C or K. Heat is measured in J.","Forgetting to convert mass to kg if given in grams.","Using the wrong specific heat capacity — water has c = 4200 J/(kg·°C), which is very high."],"units_note":"Q in joules, m in kg, c in J/(kg·°C), Δθ in °C. If mass is in g, convert to kg (÷ 1000)."}},{"id":"temp_heat_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"Calculate the heat energy required to raise the temperature of 2 kg of water from 20°C to 70°C. (Specific heat capacity of water = 4200 J/(kg·°C))","given":["m = 2 kg","c = 4200 J/(kg·°C)","Initial temperature = 20°C","Final temperature = 70°C"],"required":"Q (heat energy)","principle":"Q = mcΔθ, where Δθ = final temperature - initial temperature.","steps":[{"explanation":"Calculate the temperature change","calculation":"Δθ = 70 - 20 = 50°C"},{"explanation":"Apply Q = mcΔθ","calculation":"Q = 2 × 4200 × 50"},{"explanation":"Calculate","calculation":"Q = 420,000 J = 420 kJ"}],"answer":"Q = 420,000 J = 420 kJ","check":"This is a lot of energy — enough to heat 2 litres of water by 50°C. Sounds right for water, which has a high specific heat capacity."}},{"id":"temp_heat_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Metal feels colder than wood at the same temperature because it is at a lower temperature.","why_wrong":"Both are at the same temperature. Metal feels colder because it conducts heat away from your hand faster than wood. Your hand loses heat quickly to the metal, making it feel cold.","correct_model":"Metal has a higher thermal conductivity, so it transfers heat faster. Wood is a poor conductor, so heat transfers slowly. The temperature is the same; the rate of heat transfer differs."}},{"id":"temp_heat_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests Q = mcΔθ calculations, specific heat capacity values, and the difference between temperature and heat. They may also test thermometers and temperature scales.","trap":"JAMB may give mass in grams or specific heat in kJ/(kg·°C). Always check units before calculating.","tip":"Water has a very high specific heat capacity (4200 J/(kg·°C)). This is why oceans moderate climate and why water is used in cooling systems.","related_topics":["Gas laws","Heat transfer","Expansion"]}},{"id":"temp_heat_memory_01","type":"memory_hook","order":8,"content":{"text":"Q = mcΔθ. Think ''Q = mcdelta'' — heat equals mass times specific heat times temperature change. Water''s c = 4200 — very high!","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What is the SI unit of temperature?","options":[{"label":"A","text":"Celsius (°C)"},{"label":"B","text":"Kelvin (K)"},{"label":"C","text":"Fahrenheit (°F)"},{"label":"D","text":"Joule (J)"}],"answer":"B","explanation":"The SI unit of temperature is the Kelvin (K).","hints":["SI units are the international standard","Kelvin is the absolute temperature scale"]},{"difficulty":"medium","question":"How much heat is needed to raise the temperature of 5 kg of aluminium from 20°C to 80°C? (c of aluminium = 900 J/(kg·°C))","options":[{"label":"A","text":"270,000 J"},{"label":"B","text":"45,000 J"},{"label":"C","text":"900,000 J"},{"label":"D","text":"54,000 J"}],"answer":"A","explanation":"Q = mcΔθ = 5 × 900 × (80 - 20) = 5 × 900 × 60 = 270,000 J","hints":["Q = mcΔθ","Δθ = final - initial = 80 - 20 = 60°C"]},{"difficulty":"jamb","question":"2 kg of water at 80°C is mixed with 3 kg of water at 20°C. What is the final temperature? (c of water = 4200 J/(kg·°C))","options":[{"label":"A","text":"50°C"},{"label":"B","text":"44°C"},{"label":"C","text":"60°C"},{"label":"D","text":"40°C"}],"answer":"B","explanation":"Heat lost = Heat gained. 2 × 4200 × (80 - θ) = 3 × 4200 × (θ - 20). The 4200 cancels: 2(80 - θ) = 3(θ - 20) → 160 - 2θ = 3θ - 60 → 220 = 5θ → θ = 44°C.","hints":["Heat lost by hot water = Heat gained by cold water","Set up equation: m₁cΔθ₁ = m₂cΔθ₂","The specific heat capacity cancels out"]}]'::jsonb, '{"min_score":80,"required_sections":["temp_heat_hook_01","temp_heat_intuitive_01","temp_heat_formal_01","temp_heat_formula_01","temp_heat_worked_example_01"]}'::jsonb, '1')
