INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Gas laws', 'Heat and Thermodynamics', 'Gas Laws — How Gases Behave Under Pressure and Temperature', '["State Boyle''s Law, Charles''s Law, and the Ideal Gas Law","Apply PV = nRT to solve problems involving gases","Convert between units of pressure, volume, and temperature","Explain the relationship between pressure, volume, and temperature of a gas"]'::jsonb, 'medium', '20', '[{"id":"gas_laws_hook_01","type":"hook","order":1,"content":{"text":"Why does a balloon expand when you blow into it? Why does a tyre burst on a hot day? Why does a spray can become less effective as it gets empty? All of these involve the behaviour of gases — how they respond to changes in pressure, volume, and temperature.","prediction_prompt":"If you compress a gas into half its volume while keeping the temperature constant, what happens to its pressure? Does it double? Halve? Stay the same?"}},{"id":"gas_laws_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Gas particles are always moving randomly and bouncing off the walls of their container. When you squeeze a gas into a smaller space (reduce volume), the particles hit the walls more often — pressure increases. When you heat a gas, particles move faster and hit harder — pressure increases. Everything is connected.","analogy":"Imagine people in a room. If you shrink the room (reduce volume), people bump into walls more often (pressure increases). If you make them run (increase temperature), they bump into walls harder and more often (pressure increases even more)."}},{"id":"gas_laws_formal_01","type":"formal_explanation","order":3,"content":{"text":"Boyle''s Law: at constant temperature, PV = constant (P ∝ 1/V). Charles''s Law: at constant pressure, V/T = constant (V ∝ T). The Ideal Gas Law combines these: PV = nRT, where n is the number of moles and R is the gas constant (8.314 J/(mol·K)).","key_terms":[{"term":"Boyle''s Law","definition":"At constant temperature: P₁V₁ = P₂V₂. Pressure is inversely proportional to volume."},{"term":"Charles''s Law","definition":"At constant pressure: V₁/T₁ = V₂/T₂. Volume is directly proportional to absolute temperature."},{"term":"Ideal Gas Law","definition":"PV = nRT. Relates pressure, volume, temperature, and amount of gas."},{"term":"Absolute temperature","definition":"Temperature in Kelvin. T(K) = T(°C) + 273."}]}},{"id":"gas_laws_formula_01","type":"formula","order":4,"content":{"formula":"PV = nRT","variables":[{"name":"P","description":"Pressure","unit":"Pa (Pascals). 1 atm = 101,325 Pa"},{"name":"V","description":"Volume","unit":"m³ (cubic metres). 1 litre = 0.001 m³"},{"name":"n","description":"Number of moles","unit":"mol"},{"name":"R","description":"Universal gas constant","unit":"8.314 J/(mol·K)"},{"name":"T","description":"Absolute temperature","unit":"K (Kelvin). T(K) = T(°C) + 273"}],"when_to_use":"When you know three of P, V, n, T and need to find the fourth. Also use Boyle''s Law (P₁V₁ = P₂V₂) for constant temperature, or Charles''s Law (V₁/T₁ = V₂/T₂) for constant pressure.","common_traps":["Using °C instead of K in PV = nRT. ALWAYS convert to Kelvin.","Confusing units of pressure — Pa, kPa, atm. 1 atm = 101,325 Pa = 101.325 kPa.","Forgetting that volume must be in m³, not litres. 1 litre = 10⁻³ m³."],"units_note":"P in Pa, V in m³, n in mol, T in K, R = 8.314 J/(mol·K). For Boyle''s Law: P₁V₁ = P₂V₂ (any consistent units)."}},{"id":"gas_laws_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A gas has a volume of 4.0 m³ at a pressure of 2 atm. It is compressed isothermally (constant temperature) until the pressure becomes 4 atm. What is the new volume?","given":["P₁ = 2 atm","V₁ = 4.0 m³","P₂ = 4 atm","Temperature constant"],"required":"V₂ (new volume)","principle":"Boyle''s Law: P₁V₁ = P₂V₂ (at constant temperature).","steps":[{"explanation":"Write Boyle''s Law","calculation":"P₁V₁ = P₂V₂"},{"explanation":"Rearrange for V₂","calculation":"V₂ = P₁V₁/P₂"},{"explanation":"Substitute","calculation":"V₂ = (2 × 4.0)/4 = 8/4 = 2.0 m³"}],"answer":"V₂ = 2.0 m³","check":"Pressure doubled (2 → 4 atm), so volume halved (4 → 2 m³). PV = constant. ✓"}},{"id":"gas_laws_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"If you double the temperature of a gas (in °C), its volume doubles.","why_wrong":"Temperature must be in KELVIN for gas laws. Doubling 20°C to 40°C does NOT double the absolute temperature (293 K to 313 K).","correct_model":"Always convert to Kelvin first. T(K) = T(°C) + 273. Volume is proportional to absolute temperature (K), not Celsius."}},{"id":"gas_laws_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests Boyle''s Law, Charles''s Law, and PV = nRT calculations. They often give initial and final conditions and ask for the unknown quantity.","trap":"JAMB often gives temperature in °C — convert to K. Also, pressure may be in different units — convert to consistent units.","tip":"For Boyle''s Law problems, write P₁V₁ = P₂V₂. For Charles''s Law, write V₁/T₁ = V₂/T₂. For combined problems, use PV = nRT.","related_topics":["Temperature and heat","Expansion"]}},{"id":"gas_laws_memory_01","type":"memory_hook","order":8,"content":{"text":"Boyle''s Law: P↑ V↓ (at constant T). Charles''s Law: T↑ V↑ (at constant P). Ideal Gas Law: PV = nRT. Remember: ''Big PV equals nRT''.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A gas at 1 atm occupies 3.0 m³. What volume will it occupy at 3 atm if temperature is constant?","options":[{"label":"A","text":"9.0 m³"},{"label":"B","text":"1.0 m³"},{"label":"C","text":"3.0 m³"},{"label":"D","text":"0.33 m³"}],"answer":"B","explanation":"P₁V₁ = P₂V₂ → 1 × 3.0 = 3 × V₂ → V₂ = 1.0 m³","hints":["Boyle''s Law: P₁V₁ = P₂V₂","Pressure triples, volume must divide by 3"]},{"difficulty":"medium","question":"A gas at 27°C has a volume of 500 cm³. What volume will it occupy at 127°C if pressure is constant?","options":[{"label":"A","text":"667 cm³"},{"label":"B","text":"375 cm³"},{"label":"C","text":"750 cm³"},{"label":"D","text":"500 cm³"}],"answer":"A","explanation":"V₁/T₁ = V₂/T₂. T₁ = 27 + 273 = 300 K. T₂ = 127 + 273 = 400 K. V₂ = V₁ × T₂/T₁ = 500 × 400/300 = 667 cm³.","hints":["Charles''s Law: V₁/T₁ = V₂/T₂","Convert °C to K: add 273","Temperature increases, volume increases"]},{"difficulty":"jamb","question":"A gas has a volume of 2.0 m³ at a pressure of 1.0 × 10⁵ Pa and temperature 300 K. What is the pressure when the volume is reduced to 1.0 m³ and the temperature is raised to 600 K?","options":[{"label":"A","text":"4.0 × 10⁵ Pa"},{"label":"B","text":"2.0 × 10⁵ Pa"},{"label":"C","text":"1.0 × 10⁵ Pa"},{"label":"D","text":"0.5 × 10⁵ Pa"}],"answer":"A","explanation":"Using P₁V₁/T₁ = P₂V₂/T₂: (1.0 × 10⁵ × 2.0)/300 = (P₂ × 1.0)/600. P₂ = (1.0 × 10⁵ × 2.0 × 600)/(300 × 1.0) = 4.0 × 10⁵ Pa.","hints":["Use the combined gas law: P₁V₁/T₁ = P₂V₂/T₂","Convert all temperatures to Kelvin","Rearrange for P₂"]}]'::jsonb, '{"min_score":80,"required_sections":["gas_laws_hook_01","gas_laws_intuitive_01","gas_laws_formal_01","gas_laws_formula_01","gas_laws_worked_example_01"]}'::jsonb, '1')
