INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Expansion', 'Heat and Thermodynamics', 'Expansion — How Materials Change Size with Temperature', '["Define linear, area, and volume expansion","Apply the formula ΔL = αL₀Δθ to calculate linear expansion","Explain practical applications and problems caused by expansion","Distinguish between linear, area, and volume expansion coefficients"]'::jsonb, 'medium', '18', '[{"id":"expansion_hook_01","type":"hook","order":1,"content":{"text":"Why are gaps left between railway tracks? Why do power lines sag more in summer? Why do bridges have expansion joints? All of these are because materials expand when heated and contract when cooled. If we don''t account for this, structures can buckle and break.","prediction_prompt":"If you heat a metal rod, does it get longer, shorter, or stay the same? By how much would a 10 m rod change in length if heated?"}},{"id":"expansion_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"When you heat a material, its particles vibrate more vigorously and take up more space. The material expands. Different materials expand by different amounts — metals expand more than glass. This is why gaps are left in bridges and railway tracks: to allow for expansion in hot weather.","analogy":"Think of people in a crowded room. If everyone starts dancing (heating), they need more space. The room feels more crowded. Similarly, heated particles need more space, and the material expands."}},{"id":"expansion_formal_01","type":"formal_explanation","order":3,"content":{"text":"Linear expansion: ΔL = αL₀Δθ. Area expansion: ΔA = βA₀Δθ ≈ 2αA₀Δθ. Volume expansion: ΔV = γV₀Δθ ≈ 3αV₀Δθ. Where α is the coefficient of linear expansion, β ≈ 2α is the coefficient of area expansion, and γ ≈ 3α is the coefficient of volume expansion.","key_terms":[{"term":"Coefficient of linear expansion (α)","definition":"Fractional change in length per degree change in temperature. SI unit: /°C or /K"},{"term":"Linear expansion","definition":"ΔL = αL₀Δθ. Change in length depends on original length, temperature change, and material."},{"term":"Area expansion","definition":"ΔA = 2αA₀Δθ. For thin sheets, area expands approximately twice as much as length."},{"term":"Volume expansion","definition":"ΔV = 3αV₀Δθ. For solids, volume expands approximately three times as much as length."}]}},{"id":"expansion_formula_01","type":"formula","order":4,"content":{"formula":"ΔL = αL₀Δθ","variables":[{"name":"ΔL","description":"Change in length (expansion or contraction)","unit":"m"},{"name":"α","description":"Coefficient of linear expansion","unit":"per °C (or per K)"},{"name":"L₀","description":"Original length","unit":"m"},{"name":"Δθ","description":"Change in temperature","unit":"°C or K"}],"when_to_use":"When you need to find the change in length of a material due to a temperature change. Also used for area (ΔA = 2αA₀Δθ) and volume (ΔV = 3αV₀Δθ).","common_traps":["Using α for area or volume expansion — use 2α for area and 3α for volume.","Forgetting that expansion can be negative (contraction) if temperature decreases.","Confusing the coefficients: α (linear) ≈ β/2 ≈ γ/3."],"units_note":"α is typically very small (e.g., 12 × 10⁻⁶ /°C for steel). Δθ in °C or K (same magnitude). L₀ in metres."}},{"id":"expansion_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A steel railway track is 10 m long at 20°C. Calculate the change in length when the temperature rises to 50°C. (α for steel = 12 × 10⁻⁶ /°C)","given":["L₀ = 10 m","α = 12 × 10⁻⁶ /°C","Initial temperature = 20°C","Final temperature = 50°C"],"required":"ΔL (change in length)","principle":"ΔL = αL₀Δθ","steps":[{"explanation":"Calculate the temperature change","calculation":"Δθ = 50 - 20 = 30°C"},{"explanation":"Apply the formula","calculation":"ΔL = αL₀Δθ = 12 × 10⁻⁶ × 10 × 30"},{"explanation":"Calculate","calculation":"ΔL = 12 × 10⁻⁶ × 300 = 3600 × 10⁻⁶ = 3.6 × 10⁻³ m = 3.6 mm"}],"answer":"ΔL = 3.6 mm","check":"The track expands by 3.6 mm over 10 m. This is why gaps are needed between rail sections."}},{"id":"expansion_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A hole in a metal plate gets smaller when the plate is heated.","why_wrong":"When a plate with a hole is heated, the hole also expands — it gets BIGGER, not smaller. Every dimension expands, including the hole.","correct_model":"Think of the hole as being filled with the same metal. When heated, that imaginary metal expands, making the hole larger."}},{"id":"expansion_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests linear expansion calculations and practical applications (gaps in tracks, expansion joints). They may also test the concept of a hole expanding.","trap":"JAMB may give α in mm/(m·°C) instead of /°C. Make sure units are consistent.","tip":"The change in length is usually very small — often in mm for metre-long objects. Don''t expect large numbers.","related_topics":["Temperature and heat","Gas laws"]}},{"id":"expansion_memory_01","type":"memory_hook","order":8,"content":{"text":"ΔL = αL₀Δθ. Think ''alpha-L-zero-delta-theta''. Linear expansion: length change = expansion coefficient × original length × temperature change.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"When a material is heated, it generally:","options":[{"label":"A","text":"Expands"},{"label":"B","text":"Contracts"},{"label":"C","text":"Stays the same size"},{"label":"D","text":"Melts"}],"answer":"A","explanation":"Most materials expand when heated because the particles vibrate more and take up more space.","hints":["Heating increases particle vibration","More vibration means more space needed"]},{"difficulty":"medium","question":"A brass rod is 2.0 m long at 25°C. What is its length at 75°C? (α for brass = 19 × 10⁻⁶ /°C)","options":[{"label":"A","text":"2.0019 m"},{"label":"B","text":"2.019 m"},{"label":"C","text":"1.981 m"},{"label":"D","text":"2.0095 m"}],"answer":"A","explanation":"ΔL = αL₀Δθ = 19 × 10⁻⁶ × 2.0 × 50 = 1.9 × 10⁻³ m = 0.0019 m. New length = 2.0 + 0.0019 = 2.0019 m.","hints":["Calculate ΔL = αL₀Δθ first","Then add to original length: L = L₀ + ΔL","Δθ = 75 - 25 = 50°C"]},{"difficulty":"jamb","question":"A circular hole is cut in a metal plate. When the plate is heated, the diameter of the hole:","options":[{"label":"A","text":"Increases"},{"label":"B","text":"Decreases"},{"label":"C","text":"Stays the same"},{"label":"D","text":"First increases then decreases"}],"answer":"A","explanation":"When a plate with a hole is heated, the hole expands just as if it were filled with the same material. Every dimension expands, including the hole.","hints":["The hole behaves as if it''s filled with the same metal","All dimensions expand when heated","The hole gets BIGGER, not smaller"]}]'::jsonb, '{"min_score":80,"required_sections":["expansion_hook_01","expansion_intuitive_01","expansion_formal_01","expansion_formula_01","expansion_worked_example_01"]}'::jsonb, '1')
