INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Heat transfer', 'Heat and Thermodynamics', 'Heat Transfer — How Heat Moves from Hot to Cold', '["Explain the three methods of heat transfer: conduction, convection, and radiation","Distinguish between conductors and insulators","Explain everyday examples of each heat transfer method","Identify which method of heat transfer is responsible for different phenomena"]'::jsonb, 'medium', '18', '[{"id":"heat_transfer_hook_01","type":"hook","order":1,"content":{"text":"Why is a metal spoon in hot tea hotter than the wooden handle? Why does hot air rise? Why can you feel the heat of a fire even from a distance? Heat moves in three different ways — and knowing which way helps explain the world around you.","prediction_prompt":"If you hold one end of a metal rod and heat the other end, why does your hand eventually feel hot? How did the heat travel?"}},{"id":"heat_transfer_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Heat always flows from hot to cold. It can travel through direct contact (conduction), through moving fluids (convection), or through electromagnetic waves (radiation). Each method works differently and is responsible for different everyday phenomena.","analogy":"Think of three ways to spread gossip: (1) Whisper to the person next to you (conduction — direct contact). (2) Tell a group who then tell others (convection — carried by moving people). (3) Post it on social media (radiation — travels through space)."}},{"id":"heat_transfer_formal_01","type":"formal_explanation","order":3,"content":{"text":"Conduction: transfer of heat through direct contact, without movement of matter. Occurs mainly in solids. Good conductors (metals) transfer heat faster than insulators (wood, plastic). Convection: transfer of heat through the movement of fluid (liquid or gas). Hot fluid rises, cold fluid sinks, creating convection currents. Radiation: transfer of heat through electromagnetic waves. No medium required. All bodies emit and absorb radiation.","key_terms":[{"term":"Conduction","definition":"Heat transfer through direct contact. Particles vibrate and pass energy to neighbours. Best in solids, especially metals."},{"term":"Convection","definition":"Heat transfer through the movement of fluids (liquids and gases). Hot fluid rises, cold fluid sinks."},{"term":"Radiation","definition":"Heat transfer through electromagnetic waves. No medium needed. All objects emit and absorb radiation."},{"term":"Conductor","definition":"A material that allows heat to pass through it easily (e.g., metals)."},{"term":"Insulator","definition":"A material that does not allow heat to pass through it easily (e.g., wood, plastic, air)."}]}},{"id":"heat_transfer_formula_01","type":"formula","order":4,"content":{"formula":"Rate of heat transfer by conduction: Q/t = kA(Δθ)/d","variables":[{"name":"Q/t","description":"Rate of heat flow","unit":"W (Watts)"},{"name":"k","description":"Thermal conductivity","unit":"W/(m·°C)"},{"name":"A","description":"Cross-sectional area","unit":"m²"},{"name":"Δθ","description":"Temperature difference","unit":"°C"},{"name":"d","description":"Thickness of material","unit":"m"}],"when_to_use":"For conduction problems involving thermal conductivity. Convection and radiation are more qualitative in JAMB.","common_traps":["Confusing conduction and convection. Conduction = through solids (no movement). Convection = through fluids (movement).","Forgetting that radiation can travel through a vacuum (unlike conduction and convection).","Assuming all metals are equally good conductors — copper and silver are much better than iron."],"units_note":"Thermal conductivity k is in W/(m·°C). Higher k means better conductor."}},{"id":"heat_transfer_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A house has a metal roof, wooden walls, and glass windows. Explain which method of heat transfer is most significant for each, and describe how a house stays cool in summer.","given":["Metal roof (good conductor)","Wooden walls (insulator)","Glass windows (transparent to radiation)"],"required":"Explanation of heat transfer methods in a house","principle":"Identify the dominant heat transfer method for each component based on its properties.","steps":[{"explanation":"Metal roof: Conduction","calculation":"Heat conducts through the metal roof from the sun-heated surface to the interior. Metal has high thermal conductivity, so the roof gets very hot."},{"explanation":"Wooden walls: Conduction and insulation","calculation":"Wood is a poor conductor (insulator). Heat transfers slowly through the walls. This helps keep the interior cooler."},{"explanation":"Glass windows: Radiation","calculation":"Sunlight (radiation) passes through glass into the room. The glass traps some heat inside (greenhouse effect). Windows are the main entry point for solar radiation."},{"explanation":"Air circulation: Convection","calculation":"Hot air inside rises and escapes through vents. Cool air enters from below. This natural convection helps cool the house."}],"answer":"Metal roof: conduction (heat enters through roof). Wooden walls: conduction/insulation (heat transfers slowly). Glass windows: radiation (sunlight enters). Ventilation: convection (hot air rises, cool air enters).","check":"This is why houses in Nigeria often have ventilation blocks and ceiling fans — to promote convection and remove hot air."}},{"id":"heat_transfer_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Heat can only travel through solids by conduction.","why_wrong":"Conduction occurs in ALL materials — solids, liquids, and gases. However, it is most significant in solids because particles are closer together.","correct_model":"Conduction happens in all matter. In fluids (liquids and gases), convection is usually more significant because the fluid can move and carry heat."}},{"id":"heat_transfer_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests identification of heat transfer methods in everyday scenarios. They describe a situation and ask which method is responsible.","trap":"JAMB may ask about a vacuum flask — it minimises all three: conduction (vacuum), convection (vacuum), radiation (silvered surfaces reflect radiation).","tip":"If there''s direct contact → conduction. If a fluid is moving → convection. If it travels through space or a vacuum → radiation.","related_topics":["Temperature and heat","Expansion","Gas laws"]}},{"id":"heat_transfer_memory_01","type":"memory_hook","order":8,"content":{"text":"Three ways heat moves: Conduction (contact), Convection (fluids move), Radiation (waves, no medium). Think: ''CCR'' — Contact, Current, Rays.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Which of the following is a good heat conductor?","options":[{"label":"A","text":"Wood"},{"label":"B","text":"Plastic"},{"label":"C","text":"Copper"},{"label":"D","text":"Air"}],"answer":"C","explanation":"Copper is a metal and an excellent conductor of heat. Wood, plastic, and air are poor conductors (insulators).","hints":["Metals are good conductors","Non-metals are usually insulators"]},{"difficulty":"medium","question":"Which method of heat transfer is primarily responsible for heating the water at the bottom of a pot on a stove?","options":[{"label":"A","text":"Conduction"},{"label":"B","text":"Convection"},{"label":"C","text":"Radiation"},{"label":"D","text":"All equally"}],"answer":"B","explanation":"The water at the bottom is heated by conduction from the pot, but the heat distributes through the water mainly by convection — hot water rises, cool water sinks.","hints":["Heat in liquids is mainly transferred by convection","Hot water rises, cold water sinks","This creates a convection current"]},{"difficulty":"jamb","question":"A vacuum flask is designed to keep drinks hot for a long time. Which of the following best explains how it works?","options":[{"label":"A","text":"It prevents conduction only"},{"label":"B","text":"It prevents convection only"},{"label":"C","text":"It prevents all three methods: conduction, convection, and radiation"},{"label":"D","text":"It absorbs all radiation"}],"answer":"C","explanation":"A vacuum flask has: (1) a vacuum between double walls — prevents conduction and convection. (2) Silvered surfaces — reflect radiation back in. It minimises all three heat transfer methods.","hints":["The vacuum prevents conduction and convection","Silvered surfaces reflect radiation","A vacuum flask is a near-perfect insulator"]}]'::jsonb, '{"min_score":80,"required_sections":["heat_transfer_hook_01","heat_transfer_intuitive_01","heat_transfer_formal_01","heat_transfer_formula_01","heat_transfer_worked_example_01"]}'::jsonb, '1')
