INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Capacitors', 'Electricity', 'Capacitors — Storing Electric Charge and Energy', '["Define capacitance and state its SI unit","Apply Q = CV to calculate charge, capacitance, or voltage","Calculate energy stored in a capacitor using E = ½CV²","Explain how capacitors are used in electronic circuits"]'::jsonb, 'medium', '18', '[{"id":"capacitors_hook_01","type":"hook","order":1,"content":{"text":"How does a camera flash store enough energy to produce a bright burst of light in an instant? How does a car audio system deliver powerful bass notes? How do electronic devices maintain a steady voltage? The answer lies in capacitors — components that store electric charge and energy.","prediction_prompt":"If you connect a capacitor to a battery, what happens to the charge on the capacitor plates? Does it keep increasing forever?"}},{"id":"capacitors_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A capacitor is like a tiny rechargeable battery, but it stores energy differently. It holds charge on two metal plates separated by an insulator. The more voltage you apply, the more charge it stores. When you connect a load, it releases the stored energy quickly — that''s why camera flashes are so bright and brief.","analogy":"Think of a capacitor as a water tank. The tank has a fixed capacity (capacitance). The water level (voltage) determines how much water (charge) is in the tank. A bigger tank (higher capacitance) holds more water at the same level. When you open the tap, water flows out quickly."}},{"id":"capacitors_formal_01","type":"formal_explanation","order":3,"content":{"text":"Capacitance is the ratio of charge stored to the potential difference across the plates: C = Q/V. The SI unit is the Farad (F). 1 F = 1 Coulomb per Volt. In practice, capacitors are usually in microfarads (μF) or picofarads (pF). Energy stored: E = ½CV² = ½QV = Q²/(2C).","key_terms":[{"term":"Capacitance (C)","definition":"Charge stored per unit voltage. C = Q/V. SI unit: Farad (F). 1 F = 1 C/V"},{"term":"Charge (Q)","definition":"Total charge stored on the capacitor plates. SI unit: Coulomb (C)"},{"term":"Voltage (V)","definition":"Potential difference across the capacitor plates. SI unit: Volt (V)"},{"term":"Energy (E)","definition":"Energy stored in the capacitor. E = ½CV². SI unit: Joule (J)"}]}},{"id":"capacitors_formula_01","type":"formula","order":4,"content":{"formula":"Q = CV, E = ½CV²","variables":[{"name":"Q","description":"Charge stored","unit":"C (Coulombs)"},{"name":"C","description":"Capacitance","unit":"F (Farads). 1 μF = 10⁻⁶ F, 1 pF = 10⁻¹² F"},{"name":"V","description":"Voltage across capacitor","unit":"V (Volts)"},{"name":"E","description":"Energy stored","unit":"J (Joules)"}],"when_to_use":"Q = CV when you know any two of Q, C, V. E = ½CV² when you know C and V and need the stored energy.","common_traps":["Confusing capacitance with charge. Capacitance (C) is a property of the capacitor. Charge (Q) depends on the voltage applied.","Forgetting to convert μF or pF to F before calculations. 1 μF = 10⁻⁶ F, 1 pF = 10⁻¹² F.","Using E = CV² instead of E = ½CV². The correct formula has the ½."],"units_note":"Q in coulombs, C in farads, V in volts, E in joules. For μF: multiply by 10⁻⁶. For pF: multiply by 10⁻¹²."}},{"id":"capacitors_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"Calculate the charge on a 10 μF capacitor when connected across a 12 V battery. Also calculate the energy stored.","given":["C = 10 μF = 10 × 10⁻⁶ F","V = 12 V"],"required":"Q (charge) and E (energy stored)","principle":"Q = CV for charge. E = ½CV² for energy.","steps":[{"explanation":"Convert capacitance to Farads","calculation":"C = 10 μF = 10 × 10⁻⁶ F = 10⁻⁵ F"},{"explanation":"Calculate charge","calculation":"Q = CV = 10⁻⁵ × 12 = 1.2 × 10⁻⁴ C = 120 μC"},{"explanation":"Calculate energy","calculation":"E = ½CV² = ½ × 10⁻⁵ × 12² = ½ × 10⁻⁵ × 144 = 7.2 × 10⁻⁴ J = 0.72 mJ"}],"answer":"Q = 120 μC, E = 0.72 mJ","check":"Q = CV = 10 × 10⁻⁶ × 12 = 120 × 10⁻⁶ C = 120 μC ✓"}},{"id":"capacitors_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A capacitor stores energy in the same way as a battery — by chemical reaction.","why_wrong":"A capacitor stores energy electrostatically — charge builds up on the plates. A battery stores energy chemically. Capacitors charge/discharge much faster but hold less energy.","correct_model":"Capacitors store energy in the electric field between the plates. They can charge and discharge very quickly, which is why they''re used for camera flashes and power smoothing."}},{"id":"capacitors_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests Q = CV calculations and energy storage. They may also test capacitors in series and parallel, similar to resistors but with reversed formulas.","trap":"JAMB may give capacitance in μF or pF — always convert to F first. Also, for capacitors in series, 1/Ctotal = 1/C1 + 1/C2 (opposite to resistors in series).","tip":"For capacitors in parallel: Ctotal = C1 + C2 + ... For capacitors in series: 1/Ctotal = 1/C1 + 1/C2 + ...","related_topics":["Ohm''s law","Current electricity"]}},{"id":"capacitors_memory_01","type":"memory_hook","order":8,"content":{"text":"Q = CV. Think ''Q sees V'' — charge equals capacitance times voltage. Energy = half CV squared. Capacitors charge fast, discharge fast.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A 5 μF capacitor is connected to a 10 V supply. What is the charge on the capacitor?","options":[{"label":"A","text":"50 μC"},{"label":"B","text":"2 μC"},{"label":"C","text":"0.5 μC"},{"label":"D","text":"500 μC"}],"answer":"A","explanation":"Q = CV = 5 × 10⁻⁶ × 10 = 50 × 10⁻⁶ C = 50 μC","hints":["Q = CV","Multiply capacitance by voltage"]},{"difficulty":"medium","question":"A capacitor stores 2.4 × 10⁻³ J of energy when connected to a 12 V supply. What is its capacitance?","options":[{"label":"A","text":"20 μF"},{"label":"B","text":"33.3 μF"},{"label":"C","text":"10 μF"},{"label":"D","text":"40 μF"}],"answer":"B","explanation":"E = ½CV² → C = 2E/V² = 2 × 2.4 × 10⁻³ / 144 = 4.8 × 10⁻³ / 144 = 3.33 × 10⁻⁵ F = 33.3 μF","hints":["Rearrange E = ½CV² to find C","C = 2E/V²"]},{"difficulty":"jamb","question":"Two capacitors of 3 μF and 6 μF are connected in series. What is the equivalent capacitance?","options":[{"label":"A","text":"9 μF"},{"label":"B","text":"2 μF"},{"label":"C","text":"4.5 μF"},{"label":"D","text":"18 μF"}],"answer":"B","explanation":"1/Ctotal = 1/3 + 1/6 = 2/6 + 1/6 = 3/6 = 1/2. So Ctotal = 2 μF.","hints":["For capacitors in series: 1/Ctotal = 1/C1 + 1/C2","This is the OPPOSITE of resistors in series","1/Ctotal = 1/3 + 1/6"]}]'::jsonb, '{"min_score":80,"required_sections":["capacitors_hook_01","capacitors_intuitive_01","capacitors_formal_01","capacitors_formula_01","capacitors_worked_example_01"]}'::jsonb, '1')
