INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Electromagnetism', 'Electricity', 'Electromagnetism — The Link Between Electricity and Magnetism', '["Explain how a current-carrying conductor produces a magnetic field","Apply F = BIL to calculate the force on a current-carrying conductor in a magnetic field","Describe the working principle of an electric motor","Explain Fleming''s Left-Hand Rule"]'::jsonb, 'medium', '20', '[{"id":"electromagnetism_hook_01","type":"hook","order":1,"content":{"text":"How does an electric motor work? Why does a wire carrying current move when placed in a magnetic field? How do speakers produce sound? The connection between electricity and magnetism is one of the most powerful discoveries in physics — it''s what makes our modern world work.","prediction_prompt":"If you pass a current through a wire placed near a compass, what happens to the compass needle? Why?"}},{"id":"electromagnetism_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Electricity and magnetism are two sides of the same coin. A moving electric charge (current) creates a magnetic field. A magnetic field can push on a current-carrying wire. This mutual relationship is called electromagnetism. It''s how motors, generators, and transformers work.","analogy":"Think of electricity and magnetism as dance partners. When electricity moves (current flows), it ''dances'' with magnetism — creating a magnetic field around the wire. When you bring a magnet near the dancing partner, it pushes back — the wire moves. That''s a motor!"}},{"id":"electromagnetism_formal_01","type":"formal_explanation","order":3,"content":{"text":"A current-carrying conductor placed in a magnetic field experiences a force. The magnitude of this force is F = BIL, where B is the magnetic flux density, I is the current, and L is the length of the conductor in the field. The direction is given by Fleming''s Left-Hand Rule.","key_terms":[{"term":"Magnetic flux density (B)","definition":"Strength of the magnetic field. SI unit: Tesla (T). 1 T = 1 N/(A·m)"},{"term":"Force (F)","definition":"Force on the conductor. SI unit: Newton (N)"},{"term":"Current (I)","definition":"Current flowing through the conductor. SI unit: Ampere (A)"},{"term":"Length (L)","definition":"Length of conductor in the magnetic field. SI unit: metre (m)"},{"term":"Fleming''s Left-Hand Rule","definition":"Thumb = force (motion), First finger = magnetic field (N to S), Second finger = current. All three are perpendicular."}]}},{"id":"electromagnetism_formula_01","type":"formula","order":4,"content":{"formula":"F = BIL","variables":[{"name":"F","description":"Force on the conductor","unit":"N (Newtons)"},{"name":"B","description":"Magnetic flux density","unit":"T (Tesla)"},{"name":"I","description":"Current","unit":"A (Amperes)"},{"name":"L","description":"Length of conductor in field","unit":"m (metres)"}],"when_to_use":"When you know the magnetic field strength, current, and length of conductor in the field, and need to find the force. The conductor must be perpendicular to the field.","common_traps":["Using F = BIL when the conductor is parallel to the field — force is zero in that case.","Confusing the direction — use Fleming''s Left-Hand Rule: thumb = motion, first finger = field, second finger = current.","Forgetting that B is measured in Tesla (T), not just ''magnetic field strength.''"],"units_note":"F in newtons, B in tesla, I in amperes, L in metres. The conductor must be perpendicular to the field for maximum force."}},{"id":"electromagnetism_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A straight wire of length 0.5 m carries a current of 4 A. It is placed perpendicular to a uniform magnetic field of flux density 0.2 T. Calculate the force on the wire.","given":["L = 0.5 m","I = 4 A","B = 0.2 T","Wire is perpendicular to field"],"required":"F (force on the wire)","principle":"F = BIL (since the wire is perpendicular to the field).","steps":[{"explanation":"Write the formula","calculation":"F = BIL"},{"explanation":"Substitute values","calculation":"F = 0.2 × 4 × 0.5"},{"explanation":"Calculate","calculation":"F = 0.4 N"}],"answer":"F = 0.4 N","check":"F = BIL = 0.2 × 4 × 0.5 = 0.4 N ✓. Use Fleming''s Left-Hand Rule to find the direction of the force."}},{"id":"electromagnetism_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A magnetic field exerts a force on a stationary current-carrying wire.","why_wrong":"The wire must be carrying a current (moving charges) for the magnetic field to exert a force. A stationary wire with no current experiences no force.","correct_model":"F = BIL requires current (I). If I = 0, F = 0. The force only acts on moving charges (current) in a magnetic field."}},{"id":"electromagnetism_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests F = BIL calculations, Fleming''s Left-Hand Rule, and the working principle of electric motors. They often give B, I, L and ask for F or the direction of motion.","trap":"JAMB may give B in mT (millitesla). Convert to T: 1 mT = 10⁻³ T.","tip":"Fleming''s Left-Hand Rule: Point your left hand''s first finger in the direction of the magnetic field (N to S), second finger in the direction of current, and your thumb points in the direction of force (motion).","related_topics":["Ohm''s law","Current electricity"]}},{"id":"electromagnetism_memory_01","type":"memory_hook","order":8,"content":{"text":"F = BIL. Fleming''s Left-Hand Rule: Thumb = Motion, First finger = Field, Second finger = Current. Think: ''FBI'' — Force, B-field, I-current.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What is the SI unit of magnetic flux density?","options":[{"label":"A","text":"Weber (Wb)"},{"label":"B","text":"Tesla (T)"},{"label":"C","text":"Gauss (G)"},{"label":"D","text":"Henry (H)"}],"answer":"B","explanation":"The SI unit of magnetic flux density is the Tesla (T).","hints":["Tesla is the SI unit for magnetic field strength","Named after Nikola Tesla"]},{"difficulty":"medium","question":"A wire of length 0.2 m carries a current of 5 A in a magnetic field of 0.8 T. What is the force on the wire if it is perpendicular to the field?","options":[{"label":"A","text":"0.08 N"},{"label":"B","text":"0.8 N"},{"label":"C","text":"0.4 N"},{"label":"D","text":"1.6 N"}],"answer":"B","explanation":"F = BIL = 0.8 × 5 × 0.2 = 0.8 N","hints":["F = BIL","The wire is perpendicular, so use the full formula"]},{"difficulty":"jamb","question":"A straight conductor of length 10 cm carries a current of 2 A. It is placed in a uniform magnetic field of 0.5 T perpendicular to the conductor. What is the magnitude and direction of the force on the conductor? (Use Fleming''s Left-Hand Rule)","options":[{"label":"A","text":"0.1 N, upwards"},{"label":"B","text":"0.1 N, downwards"},{"label":"C","text":"1.0 N, perpendicular to both field and current"},{"label":"D","text":"0.01 N, along the conductor"}],"answer":"C","explanation":"F = BIL = 0.5 × 2 × 0.1 = 0.1 N. The force is perpendicular to both the magnetic field and the current (by Fleming''s Left-Hand Rule). So the force is perpendicular to both B and I, which means it''s perpendicular to both. Option C describes this direction correctly.","hints":["Convert 10 cm to 0.1 m","F = BIL = 0.5 × 2 × 0.1 = 0.1 N","The force is always perpendicular to both the field and the current"]}]'::jsonb, '{"min_score":80,"required_sections":["electromagnetism_hook_01","electromagnetism_intuitive_01","electromagnetism_formal_01","electromagnetism_formula_01","electromagnetism_worked_example_01"]}'::jsonb, '1')
