INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Sound waves', 'Waves and Optics', 'Sound Waves — How Sound Travels and What Makes It Special', '["Explain how sound waves are produced and transmitted","State the speed of sound in air and factors that affect it","Apply v = fλ to sound waves","Calculate wavelength and frequency of sound"]'::jsonb, 'medium', '18', '[{"id":"sound_hook_01","type":"hook","order":1,"content":{"text":"Why does thunder rumble after lightning? Lightning heats the air to 30,000°C in a fraction of a second, creating a shock wave that becomes the sound we hear. But light reaches you almost instantly — you see the flash first, then hear the boom. Sound is slower than light, and that delay tells you something important about sound waves.","prediction_prompt":"If you clap your hands 100 metres from a wall and hear the echo 0.6 seconds later, can you estimate the speed of sound?"}},{"id":"sound_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Sound is a vibration that travels through a medium — air, water, or solids. When you speak, your vocal cords vibrate, compressing and rarefying air molecules. These pressure waves spread outward until they reach someone''s ear. No medium, no sound — that''s why there''s no sound in space.","analogy":"Think of a line of dominos. You push the first one, it hits the next, which hits the next. Each domino only moves a little, but the energy travels the whole line. Air molecules do the same — they pass the vibration along without travelling the full distance themselves."}},{"id":"sound_formal_01","type":"formal_explanation","order":3,"content":{"text":"Sound waves are longitudinal waves — the particles vibrate parallel to the direction of wave travel. They consist of compressions (high pressure) and rarefactions (low pressure). Sound cannot travel through a vacuum. Its speed depends on the medium: about 340 m/s in air at room temperature, about 1,480 m/s in water, and about 5,000 m/s in steel.","key_terms":[{"term":"Compression","definition":"Region of high pressure where air molecules are pushed together"},{"term":"Rarefaction","definition":"Region of low pressure where air molecules are spread apart"},{"term":"Speed of sound","definition":"The distance a sound wave travels per unit time. In air at 20°C, approximately 340 m/s"},{"term":"Echo","definition":"A reflected sound wave that arrives at the listener with a detectable delay"}]}},{"id":"sound_formula_01","type":"formula","order":4,"content":{"formula":"v = fλ (with v ≈ 340 m/s in air)","variables":[{"name":"v","description":"Speed of sound","unit":"m/s"},{"name":"f","description":"Frequency","unit":"Hz"},{"name":"λ","description":"Wavelength","unit":"m"}],"when_to_use":"When you know two of speed, frequency, and wavelength for sound in air (or any medium with known speed).","common_traps":["Using 340 m/s when the temperature is very different — speed of sound increases with temperature.","Confusing sound waves (longitudinal) with light waves (transverse).","Forgetting that frequency does not change when sound enters a different medium — speed and wavelength change."],"units_note":"v in m/s, f in Hz, λ in m. If given km/h, convert to m/s by dividing by 3.6."}},{"id":"sound_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A tuning fork vibrates at 440 Hz. Calculate the wavelength of the sound it produces in air, where the speed of sound is 340 m/s.","given":["f = 440 Hz","v = 340 m/s"],"required":"λ (wavelength)","principle":"Use the wave equation: v = fλ. Rearrange to find λ = v/f.","steps":[{"explanation":"Write the wave equation","calculation":"v = fλ"},{"explanation":"Rearrange for wavelength","calculation":"λ = v/f"},{"explanation":"Substitute values","calculation":"λ = 340/440 ≈ 0.773 m"}],"answer":"λ ≈ 0.77 m","check":"v = fλ = 440 × 0.773 ≈ 340 m/s ✓"}},{"id":"sound_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Higher-pitched sounds travel faster than lower-pitched sounds.","why_wrong":"The speed of sound depends on the medium, not the frequency. All frequencies travel at the same speed in a given medium.","correct_model":"A high note and a low note from the same location reach you at the same time. Frequency affects pitch, not speed."}},{"id":"sound_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests v = fλ applied to sound, speed of sound calculations, and properties of longitudinal waves.","trap":"JAMB may give frequency in kHz. Convert: 1 kHz = 1000 Hz. Also watch for temperature changes affecting speed.","tip":"Know the speed of sound in air (340 m/s), water (~1,480 m/s), and steel (~5,000 m/s). JAMB loves comparing these.","related_topics":["Wave motion","Light waves","Echo and reverberation"]}},{"id":"sound_memory_01","type":"memory_hook","order":8,"content":{"text":"Sound is SLOW compared to light. 340 m/s means it takes about 3 seconds to travel 1 km. That''s why you see lightning before you hear thunder — count the seconds and divide by 3 for the distance in km.","hook_type":"practical_rule"}},{"id":"sound_reflection_01","type":"reflection","order":9,"content":{"question":"Why can''t you hear an echo in a small room, but you can in a large hall?","expected_understanding":"An echo needs the reflected sound to arrive at least 0.1 seconds after the original sound. In a small room, the reflection arrives too quickly to be distinguished. In a large hall, the path difference is enough to create a noticeable echo."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A sound wave has a frequency of 200 Hz and a wavelength of 1.7 m. What is the speed of sound?","options":[{"label":"A","text":"340 m/s"},{"label":"B","text":"118 m/s"},{"label":"C","text":"510 m/s"},{"label":"D","text":"85 m/s"}],"answer":"A","explanation":"v = fλ = 200 × 1.7 = 340 m/s","hints":["v = fλ","Multiply frequency by wavelength"]},{"difficulty":"medium","question":"A sound wave travels at 340 m/s and has a wavelength of 0.5 m. What is its frequency?","options":[{"label":"A","text":"170 Hz"},{"label":"B","text":"680 Hz"},{"label":"C","text":"340 Hz"},{"label":"D","text":"0.0015 Hz"}],"answer":"B","explanation":"f = v/λ = 340/0.5 = 680 Hz","hints":["Rearrange v = fλ to find f","f = v/λ"]},{"difficulty":"jamb","question":"A person claps her hands near a cliff. She hears the echo 1.5 s later. If the speed of sound is 340 m/s, how far is the cliff?","options":[{"label":"A","text":"510 m"},{"label":"B","text":"255 m"},{"label":"C","text":"127.5 m"},{"label":"D","text":"1020 m"}],"answer":"B","explanation":"The sound travels to the cliff and back. Total distance = v × t = 340 × 1.5 = 510 m. Distance to cliff = 510/2 = 255 m.","hints":["The echo travels to the cliff AND back","Total distance = v × t","Divide by 2 for one-way distance"]}]'::jsonb, '{"min_score":80,"required_sections":["sound_hook_01","sound_intuitive_01","sound_formal_01","sound_formula_01","sound_worked_example_01"]}'::jsonb, '1')
