INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Light waves', 'Waves and Optics', 'Light Waves — The Speed Limit of the Universe', '["State that light is an electromagnetic wave and travels at 3 × 10⁸ m/s in vacuum","Explain why light bends when entering a different medium","Calculate time taken for light to travel a given distance","Distinguish between transparent, translucent, and opaque materials"]'::jsonb, 'medium', '18', '[{"id":"light_hook_01","type":"hook","order":1,"content":{"text":"Why does light bend when entering water? When you look at a swimming pool, the bottom appears shallower than it really is. A straw in a glass of water looks bent at the surface. Light changes speed when it moves from one medium to another, and that change in speed causes it to change direction.","prediction_prompt":"If light travels at 3 × 10⁸ m/s, how long does it take to travel from the Sun to Earth (150 million km)?"}},{"id":"light_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Light is energy that travels as electromagnetic waves — it doesn''t need air or water or any material to travel through. That''s why we can see the Sun, even though there''s empty space between us. Light is the fastest thing in the universe. Nothing with mass can travel faster than light.","analogy":"Imagine running from a road onto sand. Your feet hit the sand first and slow down, while your other foot is still on the road going fast. This makes you veer to one side. Light does the same thing when it enters water — one part slows down before the other, so it bends."}},{"id":"light_formal_01","type":"formal_explanation","order":3,"content":{"text":"Light is a transverse electromagnetic wave. In a vacuum, it travels at c = 3 × 10⁸ m/s (approximately 300,000 km/s). When light enters a denser medium like water or glass, it slows down. The refractive index n = c/v tells you how much it slows. Transparent materials let light through clearly; translucent materials scatter light; opaque materials block it entirely.","key_terms":[{"term":"Speed of light (c)","definition":"The speed of light in a vacuum. c ≈ 3 × 10⁸ m/s"},{"term":"Refractive index (n)","definition":"The ratio of the speed of light in a vacuum to its speed in the medium. n = c/v. No units."},{"term":"Transparent","definition":"A material that allows light to pass through clearly (e.g., clear glass)"},{"term":"Translucent","definition":"A material that allows light through but scatters it (e.g., frosted glass)"},{"term":"Opaque","definition":"A material that does not allow light to pass through (e.g., wood, metal)"}]}},{"id":"light_formula_01","type":"formula","order":4,"content":{"formula":"t = d/c (time for light to travel distance d)","variables":[{"name":"t","description":"Time","unit":"s"},{"name":"d","description":"Distance","unit":"m"},{"name":"c","description":"Speed of light in vacuum","unit":"3 × 10⁸ m/s"}],"when_to_use":"When calculating how long light takes to travel a given distance (e.g., Sun to Earth, laser to Moon).","common_traps":["Using 340 m/s (speed of sound) instead of 3 × 10⁸ m/s (speed of light).","Forgetting to convert km to m — 1 km = 1,000 m.","Not using scientific notation for very large distances."],"units_note":"Distance in metres, speed in m/s, time in seconds. For astronomical distances, use km and convert to metres."}},{"id":"light_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"Calculate the time it takes for light to travel 1 km in air.","given":["d = 1 km = 1,000 m","c = 3 × 10⁸ m/s"],"required":"t (time)","principle":"Time = distance ÷ speed. t = d/c.","steps":[{"explanation":"Convert distance to metres","calculation":"d = 1 km = 1,000 m"},{"explanation":"Apply the formula","calculation":"t = d/c = 1,000 / (3 × 10⁸)"},{"explanation":"Calculate","calculation":"t ≈ 3.33 × 10⁻⁶ s = 3.33 microseconds"}],"answer":"t ≈ 3.33 microseconds","check":"In 1 microsecond, light travels 300 m. So in 3.33 μs, it travels about 1,000 m = 1 km ✓"}},{"id":"light_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Light always travels in straight lines, so it never bends.","why_wrong":"Light travels in straight lines within a single medium. But when it enters a different medium, it changes speed and bends (refracts).","correct_model":"Light travels in straight lines in one medium. It bends at the boundary between two media because it changes speed."}},{"id":"light_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the speed of light, refractive index calculations, and properties of light (transverse, electromagnetic).","trap":"JAMB may ask about the speed of light in glass or water — remember to use n = c/v to find the reduced speed.","tip":"The speed of light in vacuum is a constant: c = 3 × 10⁸ m/s. Memorise this number — it appears in many JAMB questions.","related_topics":["Reflection","Refraction","Lenses","Electromagnetic spectrum"]}},{"id":"light_memory_01","type":"memory_hook","order":8,"content":{"text":"Light speed: 3 × 10⁸ m/s. That''s 300,000 km every second. In one nanosecond (billionth of a second), light travels about 30 cm — roughly the length of a ruler.","hook_type":"visualization"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Light travels at 3 × 10⁸ m/s. How far does it travel in 2 seconds?","options":[{"label":"A","text":"6 × 10⁸ m"},{"label":"B","text":"1.5 × 10⁸ m"},{"label":"C","text":"6 × 10⁶ m"},{"label":"D","text":"3 × 10⁸ m"}],"answer":"A","explanation":"Distance = speed × time = 3 × 10⁸ × 2 = 6 × 10⁸ m = 600,000 km","hints":["Distance = speed × time","d = c × t"]},{"difficulty":"medium","question":"The speed of light in glass is 2 × 10⁸ m/s. What is the refractive index of glass?","options":[{"label":"A","text":"1.5"},{"label":"B","text":"2"},{"label":"C","text":"0.67"},{"label":"D","text":"3"}],"answer":"A","explanation":"n = c/v = (3 × 10⁸)/(2 × 10⁸) = 1.5","hints":["n = c/v","Divide the speed of light in vacuum by the speed in the medium"]},{"difficulty":"jamb","question":"Light from the Sun takes about 8 minutes to reach Earth. If the Sun-Earth distance is 1.5 × 10¹¹ m, what is the speed of light?","options":[{"label":"A","text":"3 × 10⁸ m/s"},{"label":"B","text":"1.5 × 10⁸ m/s"},{"label":"C","text":"3 × 10⁶ m/s"},{"label":"D","text":"6 × 10⁸ m/s"}],"answer":"A","explanation":"Time = 8 minutes = 480 s. Speed = distance/time = 1.5 × 10¹¹ / 480 = 3.125 × 10⁸ ≈ 3 × 10⁸ m/s","hints":["Convert 8 minutes to seconds","Speed = distance ÷ time","1.5 × 10¹¹ ÷ 480 ≈ ?"]}]'::jsonb, '{"min_score":80,"required_sections":["light_hook_01","light_intuitive_01","light_formal_01","light_formula_01","light_worked_example_01"]}'::jsonb, '1')
