INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Reflection', 'Waves and Optics', 'Reflection — Why Mirrors Work and Light Bounces Back', '["State the laws of reflection","Draw ray diagrams showing reflection at plane mirrors","Explain the formation of images in plane mirrors","Calculate angles of incidence and reflection"]'::jsonb, 'medium', '18', '[{"id":"reflection_hook_01","type":"hook","order":1,"content":{"text":"Why can you see yourself in a mirror but not in a wall? A mirror reflects almost all the light that hits it, sending it back in a predictable way. A wall scatters light in every direction — that''s called diffuse reflection. Both bounce light, but only one gives you a clear image.","prediction_prompt":"If you shine a torch at a mirror at 30° to the surface, at what angle does the light bounce off?"}},{"id":"reflection_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Reflection is when light bounces off a surface. When you look in a mirror, light from your face hits the mirror and bounces back to your eyes. Your brain traces the light back in a straight line, so you see an image that appears to be behind the mirror. That image is virtual — there''s nothing actually there.","analogy":"Think of throwing a ball at a wall. If you throw it straight on, it bounces straight back. If you throw it at an angle, it bounces off at the same angle on the other side. Light does exactly the same thing with a smooth surface."}},{"id":"reflection_formal_01","type":"formal_explanation","order":3,"content":{"text":"The law of reflection states: (1) The angle of incidence equals the angle of reflection. (2) The incident ray, the reflected ray, and the normal all lie in the same plane. The normal is an imaginary line perpendicular to the surface at the point of incidence. All angles are measured from the normal, not from the surface.","key_terms":[{"term":"Incident ray","definition":"The incoming light ray that strikes the surface"},{"term":"Reflected ray","definition":"The light ray that bounces off the surface"},{"term":"Normal","definition":"An imaginary line perpendicular to the surface at the point of incidence"},{"term":"Angle of incidence (i)","definition":"The angle between the incident ray and the normal"},{"term":"Angle of reflection (r)","definition":"The angle between the reflected ray and the normal"}]}},{"id":"reflection_formula_01","type":"formula","order":4,"content":{"formula":"Angle of incidence = Angle of reflection (i = r)","variables":[{"name":"i","description":"Angle of incidence","unit":"degrees"},{"name":"r","description":"Angle of reflection","unit":"degrees"}],"when_to_use":"When light reflects off any smooth surface. The angles are always equal.","common_traps":["Measuring angles from the surface instead of from the normal. Always measure from the normal.","Confusing reflection (bouncing off) with refraction (passing through and bending).","Thinking the image in a mirror is real — it''s virtual (formed by extending reflected rays backwards)."],"units_note":"Angles are measured in degrees from the normal (perpendicular to the surface)."}},{"id":"reflection_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A light ray hits a plane mirror at an angle of 35° to the surface. Calculate the angle of reflection.","given":["Angle to the surface = 35°"],"required":"Angle of reflection (r)","principle":"First find the angle of incidence (measured from the normal). The normal is 90° to the surface. Then i = r.","steps":[{"explanation":"Find angle of incidence","calculation":"i = 90° − 35° = 55° (angle from the normal)"},{"explanation":"Apply law of reflection","calculation":"r = i = 55°"}],"answer":"Angle of reflection = 55°","check":"The angle to the surface on the reflected side should also be 35° (90° − 55° = 35°) ✓"}},{"id":"reflection_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"The angle of incidence is measured from the surface of the mirror.","why_wrong":"In physics, all angles in reflection and refraction are measured from the NORMAL — the line perpendicular to the surface.","correct_model":"Always draw the normal first. Measure all angles from the normal. If the angle to the surface is 40°, the angle of incidence is 50°."}},{"id":"reflection_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the law of reflection, ray diagrams for plane mirrors, and properties of images (virtual, upright, same size, laterally inverted).","trap":"JAMB often gives the angle to the mirror surface instead of the normal. Always convert: angle of incidence = 90° − angle to surface.","tip":"Image properties in a plane mirror: virtual, upright, same size, same distance behind the mirror as the object is in front, laterally inverted.","related_topics":["Refraction","Lenses","Curved mirrors"]}},{"id":"reflection_memory_01","type":"memory_hook","order":8,"content":{"text":"i = r. The normal is your best friend in optics. Always draw it first. All angles measured from the normal. No exceptions.","hook_type":"mnemonic"}},{"id":"reflection_reflection_01","type":"reflection","order":9,"content":{"question":"If you stand 2 m in front of a mirror, how far does your image appear to be behind the mirror? How far is the distance between you and your image?","expected_understanding":"Your image appears 2 m behind the mirror (same distance as you are in front). The total distance between you and your image is 4 m."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A light ray strikes a mirror at an angle of incidence of 40°. What is the angle of reflection?","options":[{"label":"A","text":"40°"},{"label":"B","text":"50°"},{"label":"C","text":"80°"},{"label":"D","text":"20°"}],"answer":"A","explanation":"By the law of reflection, angle of incidence = angle of reflection = 40°","hints":["i = r","The angles are always equal"]},{"difficulty":"medium","question":"A light ray makes an angle of 60° with the surface of a mirror. What is the angle of reflection?","options":[{"label":"A","text":"60°"},{"label":"B","text":"30°"},{"label":"C","text":"45°"},{"label":"D","text":"90°"}],"answer":"B","explanation":"Angle of incidence = 90° − 60° = 30° (measured from normal). Angle of reflection = 30°.","hints":["Convert angle from surface to angle from normal","Angle of incidence = 90° − angle to surface"]},{"difficulty":"jamb","question":"An object is placed 5 m in front of a plane mirror. What is the distance between the object and its image?","options":[{"label":"A","text":"5 m"},{"label":"B","text":"10 m"},{"label":"C","text":"2.5 m"},{"label":"D","text":"15 m"}],"answer":"B","explanation":"Image is 5 m behind the mirror. Object is 5 m in front. Total distance = 5 + 5 = 10 m.","hints":["Image distance = object distance behind the mirror","Total distance = object distance + image distance"]}]'::jsonb, '{"min_score":80,"required_sections":["reflection_hook_01","reflection_intuitive_01","reflection_formal_01","reflection_formula_01","reflection_worked_example_01"]}'::jsonb, '1')
