INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Refraction', 'Waves and Optics', 'Refraction — Why Light Bends When It Changes Speed', '["Explain why light bends when entering a medium of different density","State Snell''s law: n₁sin θ₁ = n₂sin θ₂","Calculate angles of refraction using Snell''s law","Define critical angle and total internal reflection"]'::jsonb, 'medium', '20', '[{"id":"refraction_hook_01","type":"hook","order":1,"content":{"text":"Why does a straw look bent in water? When light passes from water into air, it speeds up and bends away from the normal. Your brain doesn''t account for this bending — it assumes light travels in straight lines. So the straw appears to be at a different position than it actually is.","prediction_prompt":"If you shine a laser from air into water, does it bend towards or away from the normal? Why?"}},{"id":"refraction_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Refraction happens because light travels at different speeds in different materials. When light enters a denser medium (like water), it slows down and bends towards the normal. When it enters a less dense medium (like air from water), it speeds up and bends away from the normal. This is why pools look shallower than they are.","analogy":"Imagine pushing a shopping trolley from a smooth floor onto grass at an angle. One wheel hits the grass first and slows down, while the other is still on the smooth floor going fast. The trolley turns. Light does the same — one wavefront slows down before the other, so it changes direction."}},{"id":"refraction_formal_01","type":"formal_explanation","order":3,"content":{"text":"Refraction is the bending of light as it passes from one medium to another due to a change in speed. Snell''s law relates the angles and refractive indices: n₁sin θ₁ = n₂sin θ₂. When light goes from a less dense to a more dense medium (n₂ > n₁), it bends towards the normal (θ₂ < θ₁). The opposite happens going the other way.","key_terms":[{"term":"Refractive index (n)","definition":"A measure of how much light slows down in a medium. n = c/v. Air ≈ 1.00, water ≈ 1.33, glass ≈ 1.5"},{"term":"Snell''s law","definition":"n₁sin θ₁ = n₂sin θ₂. Relates the angles of incidence and refraction to the refractive indices."},{"term":"Critical angle","definition":"The angle of incidence in the denser medium that produces an angle of refraction of 90°. Beyond this, total internal reflection occurs."},{"term":"Total internal reflection","definition":"When light travelling in a denser medium hits the boundary at an angle greater than the critical angle, it is completely reflected back."}]}},{"id":"refraction_formula_01","type":"formula","order":4,"content":{"formula":"n₁sin θ₁ = n₂sin θ₂","variables":[{"name":"n₁","description":"Refractive index of the first medium","unit":"none"},{"name":"θ₁","description":"Angle of incidence","unit":"degrees"},{"name":"n₂","description":"Refractive index of the second medium","unit":"none"},{"name":"θ₂","description":"Angle of refraction","unit":"degrees"}],"when_to_use":"When light passes between two media and you need to find the angle of refraction (or angle of incidence) given the refractive indices.","common_traps":["Using angles measured from the surface instead of from the normal.","Confusing which medium is n₁ and which is n₂ — n₁ is where the light comes FROM.","Forgetting to use degrees mode (not radians) on the calculator for sin θ."],"units_note":"Refractive index has no units. Angles must be in degrees. Use sin on your calculator — make sure it''s in degree mode."}},{"id":"refraction_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A light ray in air (n = 1.00) strikes the surface of water (n = 1.33) at an angle of incidence of 45°. Calculate the angle of refraction in water.","given":["n₁ = 1.00 (air)","n₂ = 1.33 (water)","θ₁ = 45°"],"required":"θ₂ (angle of refraction)","principle":"Use Snell''s law: n₁sin θ₁ = n₂sin θ₂","steps":[{"explanation":"Write Snell''s law","calculation":"n₁sin θ₁ = n₂sin θ₂"},{"explanation":"Rearrange for sin θ₂","calculation":"sin θ₂ = (n₁/n₂) × sin θ₁"},{"explanation":"Substitute values","calculation":"sin θ₂ = (1.00/1.33) × sin 45° = 0.752 × 0.707 = 0.532"},{"explanation":"Find θ₂","calculation":"θ₂ = sin⁻¹(0.532) ≈ 32.1°"}],"answer":"θ₂ ≈ 32°","check":"Light entering water should bend towards the normal: 32° < 45° ✓"}},{"id":"refraction_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"When light enters a denser medium, it bends away from the normal.","why_wrong":"The opposite is true. Light slows down in a denser medium, which causes it to bend TOWARDS the normal.","correct_model":"Less dense → denser: bends towards normal (angle decreases). Denser → less dense: bends away from normal (angle increases)."}},{"id":"refraction_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests Snell''s law calculations, critical angle, total internal reflection, and real-world applications (mirages, fibre optics).","trap":"JAMB may give the angle to the surface instead of the normal. Always convert to angle from normal first.","tip":"Memorise: n_air = 1.00, n_water = 1.33, n_glass = 1.5. JAMB rarely gives these — you''re expected to know them.","related_topics":["Reflection","Lenses","Electromagnetic spectrum"]}},{"id":"refraction_memory_01","type":"memory_hook","order":8,"content":{"text":"Snell''s law: n₁sin θ₁ = n₂sin θ₂. Think ''Snell is balanced'' — both sides are equal. Denser medium = higher n = smaller angle (closer to normal).","hook_type":"mnemonic"}},{"id":"refraction_reflection_01","type":"reflection","order":9,"content":{"question":"Why does a pool look shallower than it really is? Draw a ray diagram to explain.","expected_understanding":"Light from the bottom of the pool refracts at the water surface, bending away from the normal. Your brain traces the light back in a straight line, so the bottom appears to be at a shallower depth than it actually is."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"Light travels from air into glass (n = 1.5) at an angle of incidence of 30°. What is the angle of refraction?","options":[{"label":"A","text":"30°"},{"label":"B","text":"19.5°"},{"label":"C","text":"45°"},{"label":"D","text":"48.6°"}],"answer":"B","explanation":"sin θ₂ = (1.00/1.5) × sin 30° = 0.667 × 0.5 = 0.333. θ₂ = sin⁻¹(0.333) ≈ 19.5°","hints":["Use Snell''s law: n₁sin θ₁ = n₂sin θ₂","sin θ₂ = (n₁/n₂) × sin θ₁"]},{"difficulty":"medium","question":"A light ray in water (n = 1.33) makes an angle of 25° with the normal. It enters air. What is the angle of refraction?","options":[{"label":"A","text":"18.5°"},{"label":"B","text":"25°"},{"label":"C","text":"34.3°"},{"label":"D","text":"45°"}],"answer":"C","explanation":"sin θ₂ = (1.33/1.00) × sin 25° = 1.33 × 0.4226 = 0.562. θ₂ = sin⁻¹(0.562) ≈ 34.2°","hints":["Light going from denser to less dense bends AWAY from normal","Use Snell''s law: n₁sin θ₁ = n₂sin θ₂"]},{"difficulty":"jamb","question":"The critical angle for glass-air interface is 42°. A ray of light strikes the glass-air boundary at 50°. What happens?","options":[{"label":"A","text":"It is refracted into air at 90°"},{"label":"B","text":"It is refracted into air at an angle less than 90°"},{"label":"C","text":"It is totally internally reflected"},{"label":"D","text":"It passes straight through without bending"}],"answer":"C","explanation":"50° > 42° (critical angle). When the angle of incidence exceeds the critical angle, total internal reflection occurs.","hints":["Compare the angle of incidence to the critical angle","If angle > critical angle, total internal reflection occurs"]}]'::jsonb, '{"min_score":80,"required_sections":["refraction_hook_01","refraction_intuitive_01","refraction_formal_01","refraction_formula_01","refraction_worked_example_01"]}'::jsonb, '1')
