INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Lenses', 'Waves and Optics', 'Lenses — How Glasses, Cameras, and Eyes Focus Light', '["Distinguish between convex and concave lenses","State the lens formula: 1/f = 1/u + 1/v","Draw ray diagrams for convex and concave lenses","Calculate image distance, object distance, or focal length"]'::jsonb, 'medium', '20', '[{"id":"lens_hook_01","type":"hook","order":1,"content":{"text":"How do glasses correct vision? When your eye''s lens can''t focus light properly on your retina, glasses add another lens to fix the problem. A convex lens converges light (for long-sightedness), and a concave lens diverges light (for short-sightedness). Your eye is a lens system — and JAMB tests this.","prediction_prompt":"If a convex lens has a focal length of 10 cm and you place an object 20 cm away, where does the image form?"}},{"id":"lens_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"A convex lens is thicker in the middle and thinner at the edges. It converges (brings together) parallel rays of light to a single point called the focal point. A concave lens is thinner in the middle and spreads light out. Your eye has a natural convex lens that focuses light onto the retina.","analogy":"A convex lens is like a magnifying glass focusing sunlight into a bright dot. That dot is the focal point. The distance from the lens to that dot is the focal length. A concave lens is the opposite — it spreads light out instead of bringing it together."}},{"id":"lens_formal_01","type":"formal_explanation","order":3,"content":{"text":"The lens formula relates object distance (u), image distance (v), and focal length (f): 1/f = 1/u + 1/v. For a convex lens, f is positive. For a concave lens, f is negative. Real images are formed on the same side as the outgoing light (can be projected on a screen). Virtual images are on the same side as the object (cannot be projected).","key_terms":[{"term":"Focal length (f)","definition":"Distance from the lens to the focal point. Positive for convex, negative for concave."},{"term":"Object distance (u)","definition":"Distance from the lens to the object. Usually positive."},{"term":"Image distance (v)","definition":"Distance from the lens to the image. Positive for real images, negative for virtual images."},{"term":"Magnification (m)","definition":"m = v/u = height of image / height of object. Positive = upright, negative = inverted."}]}},{"id":"lens_formula_01","type":"formula","order":4,"content":{"formula":"1/f = 1/u + 1/v","variables":[{"name":"f","description":"Focal length","unit":"cm or m"},{"name":"u","description":"Object distance","unit":"cm or m"},{"name":"v","description":"Image distance","unit":"cm or m"}],"when_to_use":"When you know any two of f, u, v and need to find the third for a thin lens.","common_traps":["Using the wrong sign convention: f is positive for convex, negative for concave. v is positive for real images, negative for virtual.","Forgetting to rearrange the formula: 1/v = 1/f − 1/u.","Confusing the lens formula with the mirror formula (they look similar but sign conventions differ)."],"units_note":"All distances must be in the same unit (all cm or all m). Focal length in cm is most common for JAMB problems."}},{"id":"lens_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A convex lens has a focal length of 15 cm. An object is placed 30 cm from the lens. Find the image distance and state whether the image is real or virtual.","given":["f = +15 cm (convex)","u = 30 cm"],"required":"v (image distance)","principle":"Use the lens formula: 1/f = 1/u + 1/v. Rearrange to find v.","steps":[{"explanation":"Write the lens formula","calculation":"1/f = 1/u + 1/v"},{"explanation":"Rearrange for v","calculation":"1/v = 1/f − 1/u = 1/15 − 1/30"},{"explanation":"Calculate","calculation":"1/v = 2/30 − 1/30 = 1/30. So v = 30 cm"},{"explanation":"Determine image type","calculation":"v is positive → image is real"}],"answer":"v = 30 cm, real image","check":"When u = 2f (2 × 15 = 30), the image forms at 2f on the other side. This is a standard result for convex lenses ✓"}},{"id":"lens_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"A concave lens can form a real image.","why_wrong":"A concave lens always diverges light. The image is always virtual, upright, and smaller than the object. It can never form a real image.","correct_model":"Convex lenses can form real or virtual images depending on object position. Concave lenses always form virtual images."}},{"id":"lens_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests the lens formula, ray diagrams, and image properties (real/virtual, upright/inverted, magnified/diminished).","trap":"JAMB may give u and v in different units — always convert to the same unit before using the formula.","tip":"Know the standard cases: u > 2f (real, diminished), u = 2f (real, same size), f < u < 2f (real, magnified), u < f (virtual, magnified).","related_topics":["Reflection","Refraction","The eye"]}},{"id":"lens_memory_01","type":"memory_hook","order":8,"content":{"text":"1/f = 1/u + 1/v. Think of it as ''focal length is the harmonic mean of u and v'' — or just remember the triangle: cover what you want to find.","hook_type":"visualization"}},{"id":"lens_reflection_01","type":"reflection","order":9,"content":{"question":"Why do people who are short-sighted (myopic) need concave lenses? What would happen if they wore convex lenses instead?","expected_understanding":"In short-sightedness, the eye focuses light in front of the retina (the eye is too long or the lens is too strong). A concave lens diverges the light slightly before it enters the eye, pushing the focal point back onto the retina. A convex lens would make it worse — focusing even more in front of the retina."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A convex lens has a focal length of 10 cm. An object is placed 20 cm away. What is the image distance?","options":[{"label":"A","text":"10 cm"},{"label":"B","text":"20 cm"},{"label":"C","text":"5 cm"},{"label":"D","text":"40 cm"}],"answer":"B","explanation":"1/v = 1/10 − 1/20 = 2/20 − 1/20 = 1/20. v = 20 cm.","hints":["1/f = 1/u + 1/v","Rearrange: 1/v = 1/f − 1/u"]},{"difficulty":"medium","question":"A concave lens has a focal length of −20 cm. An object is placed 15 cm from the lens. Where is the image?","options":[{"label":"A","text":"−8.57 cm"},{"label":"B","text":"8.57 cm"},{"label":"C","text":"−60 cm"},{"label":"D","text":"60 cm"}],"answer":"A","explanation":"1/v = 1/(−20) − 1/15 = −3/60 − 4/60 = −7/60. v = −60/7 ≈ −8.57 cm. Negative means virtual image.","hints":["Concave lens has negative f","1/v = 1/f − 1/u","Negative v = virtual image"]},{"difficulty":"jamb","question":"A convex lens of focal length 5 cm forms a real image at 15 cm from the lens. How far is the object from the lens?","options":[{"label":"A","text":"7.5 cm"},{"label":"B","text":"10 cm"},{"label":"C","text":"15 cm"},{"label":"D","text":"20 cm"}],"answer":"A","explanation":"1/u = 1/f − 1/v = 1/5 − 1/15 = 3/15 − 1/15 = 2/15. u = 15/2 = 7.5 cm.","hints":["1/f = 1/u + 1/v","Rearrange: 1/u = 1/f − 1/v"]}]'::jsonb, '{"min_score":80,"required_sections":["lens_hook_01","lens_intuitive_01","lens_formal_01","lens_formula_01","lens_worked_example_01"]}'::jsonb, '1')
