INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Nuclear physics', 'Modern Physics', 'Nuclear Physics — Mass-Energy and the Power of the Atom', '["State Einstein''s mass-energy equivalence: E = mc²","Explain mass defect and binding energy","Calculate energy released in nuclear reactions","Distinguish between nuclear fission and fusion"]'::jsonb, 'hard', '20', '[{"id":"nuclear_hook_01","type":"hook","order":1,"content":{"text":"Where does the energy in a nuclear bomb come from? A tiny amount of mass is converted into a enormous amount of energy. Einstein showed that mass and energy are equivalent — they are two forms of the same thing. Even a small piece of matter contains a staggering amount of energy, because c² is an enormous number.","prediction_prompt":"If you could convert 1 gram of matter completely into energy, how much energy would you get? (c = 3 × 10⁸ m/s)"}},{"id":"nuclear_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"When you combine small nuclei into a larger one (fusion), the total mass of the product is slightly less than the total mass of the ingredients. That ''missing'' mass has been converted into energy. The same happens in reverse during fission — splitting a heavy nucleus releases energy because the fragments have less total mass than the original nucleus.","analogy":"Imagine building a Lego house. If the finished house weighs slightly less than all the individual bricks you started with, where did the missing weight go? In nuclear physics, that missing mass becomes energy — and it''s a LOT of energy because c² is huge."}},{"id":"nuclear_formal_01","type":"formal_explanation","order":3,"content":{"text":"Einstein''s mass-energy equivalence states E = mc². Mass defect (Δm) is the difference between the mass of individual nucleons and the mass of the nucleus. The binding energy is the energy released when nucleons combine: E = Δmc². Nuclear fission: a heavy nucleus splits into lighter nuclei (e.g., uranium-235). Nuclear fusion: light nuclei combine to form a heavier nucleus (e.g., hydrogen → helium in the Sun).","key_terms":[{"term":"Mass defect (Δm)","definition":"The difference between the sum of individual nucleon masses and the actual nuclear mass"},{"term":"Binding energy","definition":"The energy required to separate a nucleus into its constituent nucleons. E = Δmc²"},{"term":"Fission","definition":"The splitting of a heavy nucleus into two or more lighter nuclei"},{"term":"Fusion","definition":"The combining of light nuclei to form a heavier nucleus"}]}},{"id":"nuclear_formula_01","type":"formula","order":4,"content":{"formula":"E = mc²","variables":[{"name":"E","description":"Energy released","unit":"J"},{"name":"m","description":"Mass (defect)","unit":"kg"},{"name":"c","description":"Speed of light","unit":"3 × 10⁸ m/s"}],"when_to_use":"When calculating energy released from a mass defect in nuclear reactions (fission or fusion).","common_traps":["Forgetting to convert mass from grams or atomic mass units (u) to kilograms. 1 u = 1.66 × 10⁻²⁷ kg.","Using c = 3 × 10⁸ m/s but forgetting to square it: c² = 9 × 10¹⁶ m²/s².","Confusing mass defect with total mass — Δm is the DIFFERENCE, not the total."],"units_note":"Mass in kg, c in m/s, energy in Joules. For atomic-scale calculations, 1 u of mass corresponds to 931.5 MeV of energy."}},{"id":"nuclear_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"In a nuclear reaction, the mass defect is 0.002 u. Calculate the energy released. (1 u = 1.66 × 10⁻²⁷ kg, c = 3 × 10⁸ m/s)","given":["Δm = 0.002 u","1 u = 1.66 × 10⁻²⁷ kg","c = 3 × 10⁸ m/s"],"required":"E (energy released)","principle":"Convert mass to kg, then use E = mc².","steps":[{"explanation":"Convert mass defect to kg","calculation":"Δm = 0.002 × 1.66 × 10⁻²⁷ = 3.32 × 10⁻³⁰ kg"},{"explanation":"Apply E = mc²","calculation":"E = (3.32 × 10⁻³⁰)(3 × 10⁸)²"},{"explanation":"Calculate c²","calculation":"c² = 9 × 10¹⁶ m²/s²"},{"explanation":"Calculate energy","calculation":"E = 3.32 × 10⁻³⁰ × 9 × 10¹⁶ = 2.99 × 10⁻¹³ J"}],"answer":"E ≈ 2.99 × 10⁻¹³ J (about 1.87 MeV)","check":"Each u corresponds to about 931.5 MeV. So 0.002 u → 0.002 × 931.5 ≈ 1.86 MeV ✓"}},{"id":"nuclear_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"Nuclear fission destroys matter — matter is turned into nothing.","why_wrong":"Matter is not destroyed. It is CONVERTED into energy. The total mass-energy is conserved. The ''missing'' mass appears as kinetic energy and radiation.","correct_model":"In nuclear reactions, a small amount of mass is converted to energy. Mass is not destroyed — it transforms. This is what E = mc² means."}},{"id":"nuclear_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests E = mc² calculations, mass defect, binding energy, and the difference between fission and fusion.","trap":"JAMB may give mass in atomic mass units (u). Convert: 1 u = 1.66 × 10⁻²⁷ kg. Or use 1 u = 931.5 MeV directly.","tip":"Fission: splitting heavy atoms (uranium in nuclear power plants). Fusion: joining light atoms (hydrogen in the Sun). Both release energy because products have less mass than reactants.","related_topics":["Photoelectric effect","Atomic structure","Radioactivity"]}},{"id":"nuclear_memory_01","type":"memory_hook","order":8,"content":{"text":"E = mc². ''Energy equals mass times the speed of light squared.'' c² = 9 × 10¹⁶ — that''s why a tiny bit of mass gives a huge amount of energy.","hook_type":"mnemonic"}},{"id":"nuclear_reflection_01","type":"reflection","order":9,"content":{"question":"Why does fusion release more energy per kilogram of fuel than fission?","expected_understanding":"Fusion involves the lightest elements (hydrogen), where the mass defect per nucleon is much larger. When hydrogen fuses to helium, a larger fraction of the mass is converted to energy compared to splitting uranium."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"What does E = mc² tell us?","options":[{"label":"A","text":"Energy and mass are equivalent"},{"label":"B","text":"Mass is conserved in all reactions"},{"label":"C","text":"Light has no mass"},{"label":"D","text":"Energy is always conserved"}],"answer":"A","explanation":"E = mc² states that mass and energy are equivalent — a small amount of mass can be converted into a large amount of energy.","hints":["This is Einstein''s most famous equation","Mass can be converted to energy"]},{"difficulty":"medium","question":"A mass defect of 0.005 u is observed in a nuclear reaction. How much energy is released? (1 u = 931.5 MeV)","options":[{"label":"A","text":"4.66 MeV"},{"label":"B","text":"186.3 MeV"},{"label":"C","text":"0.005 MeV"},{"label":"D","text":"931.5 MeV"}],"answer":"A","explanation":"E = 0.005 × 931.5 = 4.66 MeV","hints":["E = Δm × 931.5 MeV/u","Multiply mass defect by 931.5"]},{"difficulty":"jamb","question":"The mass of a helium-4 nucleus is 4.0026 u. The mass of 2 protons and 2 neutrons is 4.0319 u. What is the mass defect and the binding energy? (1 u = 1.66 × 10⁻²⁷ kg, c = 3 × 10⁸ m/s)","options":[{"label":"A","text":"Δm = 0.0293 u, E = 27.3 MeV"},{"label":"B","text":"Δm = 0.0293 u, E = 4.38 × 10⁻¹² J"},{"label":"C","text":"Δm = 0.0293 u, E = 27.3 MeV and 4.38 × 10⁻¹² J"},{"label":"D","text":"Δm = 0.0026 u, E = 2.4 MeV"}],"answer":"C","explanation":"Δm = 4.0319 − 4.0026 = 0.0293 u. In MeV: 0.0293 × 931.5 = 27.3 MeV. In Joules: 0.0293 × 1.66 × 10⁻²⁷ × 9 × 10¹⁶ = 4.38 × 10⁻¹² J.","hints":["Mass defect = sum of parts − actual mass","E = Δm × 931.5 MeV/u for MeV","E = Δmc² for Joules"]}]'::jsonb, '{"min_score":80,"required_sections":["nuclear_hook_01","nuclear_intuitive_01","nuclear_formal_01","nuclear_formula_01","nuclear_worked_example_01"]}'::jsonb, '1')
