INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Radioactivity', 'Modern Physics', 'Radioactivity — Understanding Radiation and Half-Life', '["Describe alpha, beta, and gamma radiation","Explain the concept of half-life","Calculate remaining activity using N = N₀e^(-λt)","State the uses and dangers of radioactive materials"]'::jsonb, 'hard', '20', '[{"id":"radio_hook_01","type":"hook","order":1,"content":{"text":"How do doctors use radiation to treat cancer? Radiation can kill cells. In controlled doses, it can target and destroy cancer cells without harming surrounding healthy tissue too much. But radiation is also dangerous — it can cause cancer. The key is understanding how radioactivity works, what the different types are, and how to measure and control them.","prediction_prompt":"If a radioactive sample has a half-life of 10 years, how much of it remains after 30 years?"}},{"id":"radio_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Radioactivity is the spontaneous emission of particles or energy from an unstable nucleus. Think of it like a shaking building in an earthquake — eventually, pieces fall off. There are three main types: alpha (big chunks — helium nuclei), beta (small particles — electrons), and gamma (energy — electromagnetic waves).","analogy":"Imagine a bucket with a hole in the bottom. Water drips out at a steady rate. The half-life is like the time it takes for half the water to drip out. After another half-life, half of the remaining water drips out — so a quarter is left. This is exactly how radioactive decay works."}},{"id":"radio_formal_01","type":"formal_explanation","order":3,"content":{"text":"Radioactive decay is random and spontaneous. The activity (rate of decay) decreases exponentially over time. Alpha particles (α): ₂⁴He — heavy, positive, stopped by paper. Beta particles (β): ⁰₋₁e — light, negative, stopped by aluminium. Gamma rays (γ): electromagnetic — no mass, no charge, stopped by thick lead. Half-life (T½) is the time for half the radioactive atoms to decay.","key_terms":[{"term":"Activity","definition":"The rate of decay of a radioactive sample. Measured in Becquerels (Bq). 1 Bq = 1 decay per second"},{"term":"Half-life (T½)","definition":"The time taken for half the radioactive nuclei in a sample to decay"},{"term":"Decay constant (λ)","definition":"The probability of decay per unit time. Related to half-life: T½ = ln2/λ = 0.693/λ"},{"term":"Alpha particle","definition":"A helium nucleus: ₂⁴He. Mass number 4, atomic number 2. Stopped by paper."},{"term":"Beta particle","definition":"A high-speed electron: ⁰₋₁e. Very small mass, negative charge. Stopped by thin aluminium."},{"term":"Gamma ray","definition":"High-energy electromagnetic radiation. No mass, no charge. Stopped by thick lead or concrete."}]}},{"id":"radio_formula_01","type":"formula","order":4,"content":{"formula":"N = N₀e^(-λt) and T½ = ln2/λ","variables":[{"name":"N","description":"Remaining number of radioactive atoms (or activity)","unit":"atoms or Bq"},{"name":"N₀","description":"Initial number of radioactive atoms (or activity)","unit":"atoms or Bq"},{"name":"λ","description":"Decay constant","unit":"s⁻¹"},{"name":"t","description":"Time elapsed","unit":"s"},{"name":"T½","description":"Half-life","unit":"s (or years, etc.)"}],"when_to_use":"When calculating the remaining amount of a radioactive substance after a given time, or when finding the half-life from the decay constant.","common_traps":["Confusing half-life with decay constant: T½ = 0.693/λ, not T½ = λ.","Using natural log (ln) instead of base-10 log — the formula uses e, so use ln.","Forgetting that after n half-lives, the remaining amount is N₀ × (1/2)ⁿ."],"units_note":"Time and half-life must be in the same units. Decay constant λ has units of 1/time (e.g., s⁻¹ or year⁻¹)."}},{"id":"radio_worked_example_01","type":"worked_example","order":5,"content":{"scenario":"A radioactive sample has an initial activity of 800 Bq and a half-life of 5 years. Calculate its activity after 15 years.","given":["N₀ = 800 Bq","T½ = 5 years","t = 15 years"],"required":"N (remaining activity)","principle":"After each half-life, the activity halves. 15 years = 3 half-lives. N = N₀ × (1/2)ⁿ","steps":[{"explanation":"Find the number of half-lives","calculation":"n = t/T½ = 15/5 = 3 half-lives"},{"explanation":"Apply the half-life rule","calculation":"N = N₀ × (1/2)³ = 800 × 1/8 = 100 Bq"}],"answer":"Activity after 15 years = 100 Bq","check":"After 5 years: 400 Bq. After 10 years: 200 Bq. After 15 years: 100 Bq ✓"}},{"id":"radio_misconception_01","type":"common_misconception","order":6,"content":{"mistake":"After one half-life, all the radioactive atoms have decayed.","why_wrong":"After one half-life, only HALF the atoms have decayed. The other half are still radioactive. After two half-lives, three-quarters have decayed, and so on.","correct_model":"Half-life means HALF remains. After 1 half-life: 50% left. After 2: 25%. After 3: 12.5%. After 10: about 0.1%."}},{"id":"radio_jamb_01","type":"jamb_insight","order":7,"content":{"focus_area":"JAMB tests half-life calculations, properties of alpha/beta/gamma radiation, and practical uses of radioactivity (medicine, industry, dating).","trap":"JAMB may give half-life in different units (days, years) and ask for activity at a different time scale. Convert all to the same unit first.","tip":"Know the penetrating power: alpha (paper), beta (aluminium), gamma (lead). Know the charges: alpha (+2), beta (−1), gamma (0).","related_topics":["Nuclear physics","Photoelectric effect","Atomic structure"]}},{"id":"radio_memory_01","type":"memory_hook","order":8,"content":{"text":"Alpha = big, stopped by paper. Beta = medium, stopped by aluminium. Gamma = energy, stopped by lead. Half-life: after each half-life, HALF remains. 1→1/2→1/4→1/8...","hook_type":"mnemonic"}},{"id":"radio_reflection_01","type":"reflection","order":9,"content":{"question":"Why is gamma radiation used to sterilise medical equipment rather than alpha or beta radiation?","expected_understanding":"Gamma rays have the greatest penetrating power — they can pass through packaging and equipment to kill bacteria inside. Alpha and beta particles are stopped by the surface and cannot reach bacteria inside containers or equipment."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A radioactive sample has a half-life of 4 years. How much of a 200 g sample remains after 12 years?","options":[{"label":"A","text":"100 g"},{"label":"B","text":"50 g"},{"label":"C","text":"25 g"},{"label":"D","text":"12.5 g"}],"answer":"C","explanation":"12 years = 3 half-lives. Remaining = 200 × (1/2)³ = 200 × 1/8 = 25 g.","hints":["Number of half-lives = 12/4 = 3","After each half-life, amount halves"]},{"difficulty":"medium","question":"The half-life of a radioactive substance is 10 days. If the initial activity is 1000 Bq, what is the activity after 30 days?","options":[{"label":"A","text":"500 Bq"},{"label":"B","text":"250 Bq"},{"label":"C","text":"125 Bq"},{"label":"D","text":"62.5 Bq"}],"answer":"C","explanation":"30 days = 3 half-lives. Activity = 1000 × (1/2)³ = 1000/8 = 125 Bq.","hints":["30 days ÷ 10 days = 3 half-lives","Activity halves each half-life"]},{"difficulty":"jamb","question":"A radioactive isotope has a half-life of 5 years. What fraction remains after 20 years?","options":[{"label":"A","text":"1/2"},{"label":"B","text":"1/4"},{"label":"C","text":"1/8"},{"label":"D","text":"1/16"}],"answer":"D","explanation":"20 years = 4 half-lives. Remaining fraction = (1/2)⁴ = 1/16.","hints":["20/5 = 4 half-lives","(1/2)⁴ = ?"]}]'::jsonb, '{"min_score":80,"required_sections":["radio_hook_01","radio_intuitive_01","radio_formal_01","radio_formula_01","radio_worked_example_01"]}'::jsonb, '1')
