INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Motion', 'Mechanics', 'Motion — Understanding How Things Move', '["Define distance, displacement, speed, velocity, and acceleration","Distinguish between scalar and vector quantities","Interpret distance-time and velocity-time graphs","Calculate average speed and acceleration from given data"]'::jsonb, 'medium', '20', '[{"id":"motion_hook_01","type":"hook","order":1,"content":{"text":"A car and a motorcycle start from the same point. The car takes 2 hours to travel 100 km. The motorcycle takes 1 hour. Which one is faster? Simple, right? But what if I told you the motorcycle stopped for 30 minutes in between? Now how do you compare them? That''s where understanding motion becomes important — and JAMB loves testing this.","prediction_prompt":"A ball is thrown straight up. At the highest point, is its velocity zero, maximum, or something else? Think carefully before we continue."}},{"id":"motion_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Motion is everywhere. You walk, cars drive, planets orbit. But in physics, we need to be precise about HOW things move. We don''t just say ''it''s fast.'' We measure exactly how far, how fast, and how the speed changes. Think of it like describing a football match — you need to know who scored, when, and by how much.","analogy":"Imagine you''re describing a friend''s journey to school. ''She walked 2 km in 20 minutes'' tells you distance and time. ''She walked at 6 km/h'' tells you speed. ''She started slow, then ran the last bit'' tells you about acceleration. These are all different ways to describe the same motion."}},{"id":"motion_formal_01","type":"formal_explanation","order":3,"content":{"text":"Motion is described using key quantities. Distance is the total path covered (scalar — only magnitude). Displacement is the straight-line distance from start to end, with direction (vector). Speed is distance per unit time (scalar). Velocity is displacement per unit time (vector). Acceleration is the rate of change of velocity (vector).","key_terms":[{"term":"Distance","definition":"Total path length covered. Scalar quantity (no direction). SI unit: metre (m)"},{"term":"Displacement","definition":"Straight-line distance from initial to final position, with direction. Vector quantity. SI unit: metre (m)"},{"term":"Speed","definition":"Distance covered per unit time. Scalar. SI unit: m/s"},{"term":"Velocity","definition":"Displacement per unit time. Vector. SI unit: m/s"},{"term":"Acceleration","definition":"Rate of change of velocity. Vector. SI unit: m/s²"}]}},{"id":"motion_formula_01","type":"formula","order":4,"content":{"formula":"v = u + at","variables":[{"name":"v","description":"Final velocity","unit":"m/s"},{"name":"u","description":"Initial velocity","unit":"m/s"},{"name":"a","description":"Acceleration","unit":"m/s²"},{"name":"t","description":"Time","unit":"s"}],"when_to_use":"When you know initial velocity, acceleration, and time, and need to find final velocity (or any one unknown from the other three).","common_traps":["Confusing speed and velocity. Speed is always positive; velocity can be negative (opposite direction).","Forgetting that acceleration can be negative (deceleration).","Using the wrong equation of motion — there are 3 main ones, pick the one that matches your known/unknown values."],"units_note":"Always convert to SI units: metres, seconds, m/s, m/s². If given km/h, convert to m/s by dividing by 3.6."}},{"id":"motion_interactive_motion_01","type":"interactive","order":5,"content":{"component":"motion_simulator","config":{"max_velocity":50,"max_acceleration":20},"instruction":"Set the initial velocity and acceleration, then press Play. The v-t graph is drawn live — read off the gradient as the acceleration.","prediction_prompt":"If acceleration is negative, will the velocity reach zero and come back? Predict before you press Play."}},{"id":"motion_interactive_projectile_01","type":"interactive","order":6,"content":{"component":"projectile_simulator","config":{"speed":25,"angle":45,"gravity":9.8},"instruction":"Launch at 45°, then at 30°. Compare the range and the maximum height. Then set g to 1.6 (the Moon) and launch again.","prediction_prompt":"Two launches, same speed, angles 30° and 60°. Which one travels further? Only one of them can be right."}},{"id":"motion_worked_example_01","type":"worked_example","order":7,"content":{"scenario":"A car starts from rest and accelerates uniformly at 2 m/s² for 10 seconds. Calculate its final velocity and the distance covered.","given":["u = 0 (starts from rest)","a = 2 m/s²","t = 10 s"],"required":"v (final velocity) and s (distance)","principle":"Use v = u + at for velocity. Use s = ut + ½at² for distance.","steps":[{"explanation":"Calculate final velocity","calculation":"v = u + at = 0 + (2)(10) = 20 m/s"},{"explanation":"Calculate distance","calculation":"s = ut + ½at² = (0)(10) + ½(2)(10)² = 0 + ½(2)(100) = 100 m"}],"answer":"Final velocity = 20 m/s, Distance = 100 m","check":"The car went from 0 to 20 m/s in 10 s. Average speed = 10 m/s. Distance = 10 × 10 = 100 m. ✓"}},{"id":"motion_misconception_01","type":"common_misconception","order":8,"content":{"mistake":"When a ball is thrown up, at the highest point its velocity is maximum.","why_wrong":"At the highest point, the ball momentarily stops before coming back down. Its velocity is ZERO at the top.","correct_model":"Velocity decreases as the ball goes up (gravity acts against it). At the top, v = 0. Then velocity increases in the downward direction as the ball falls."}},{"id":"motion_jamb_01","type":"jamb_insight","order":9,"content":{"focus_area":"JAMB loves giving velocity-time graphs and asking for distance (area under the graph), acceleration (gradient), or interpreting the shape.","trap":"On a v-t graph, the AREA under the line = distance, not the gradient. The GRADIENT = acceleration. Students confuse these two.","tip":"For v-t graphs: gradient = acceleration, area = distance. For s-t graphs: gradient = velocity, area = meaningless.","related_topics":["Forces","Work, energy, power"]}},{"id":"motion_memory_01","type":"memory_hook","order":10,"content":{"text":"The equations of motion: SUVAT. S = ut + ½at², v² = u² + 2as, v = u + at. Think ''SUVAT'' — some use all three.","hook_type":"mnemonic"}},{"id":"motion_reflection_01","type":"reflection","order":11,"content":{"question":"If a car is moving at constant velocity, what is its acceleration? What does the velocity-time graph look like?","expected_understanding":"Acceleration is zero when velocity is constant. The v-t graph is a horizontal line at the velocity value."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A car travels 200 m in 20 s. What is its average speed?","options":[{"label":"A","text":"10 m/s"},{"label":"B","text":"20 m/s"},{"label":"C","text":"40 m/s"},{"label":"D","text":"100 m/s"}],"answer":"A","explanation":"Speed = distance/time = 200/20 = 10 m/s","hints":["Speed = distance ÷ time"]},{"difficulty":"medium","question":"A body starts from rest and accelerates at 3 m/s² for 4 s. What is the distance covered?","options":[{"label":"A","text":"12 m"},{"label":"B","text":"24 m"},{"label":"C","text":"36 m"},{"label":"D","text":"48 m"}],"answer":"B","explanation":"s = ut + ½at² = 0 + ½(3)(4²) = ½(3)(16) = 24 m","hints":["Which equation has s, u, a, and t?","u = 0 (starts from rest)"]},{"difficulty":"jamb","question":"The velocity-time graph of a body is a straight line passing through the origin with gradient 5 m/s². What is the displacement after 4 seconds?","options":[{"label":"A","text":"20 m"},{"label":"B","text":"40 m"},{"label":"C","text":"80 m"},{"label":"D","text":"10 m"}],"answer":"B","explanation":"Gradient = acceleration = 5 m/s². For a v-t graph, displacement = area under the graph. The graph is a triangle with base 4 and height (v = u + at = 0 + 5×4 = 20). Area = ½ × 4 × 20 = 40 m.","hints":["What does the gradient of a v-t graph represent?","Displacement = area under v-t graph","The shape is a triangle — use ½ × base × height"]}]'::jsonb, '{"min_score":80,"required_sections":["motion_hook_01","motion_intuitive_01","motion_formal_01","motion_formula_01","motion_worked_example_01"]}'::jsonb, '1')
