INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Ohm''s law', 'Electricity', 'Ohm''s Law — The Relationship Between Voltage, Current, and Resistance', '["State Ohm''s Law and write its mathematical expression","Define voltage, current, and resistance","Calculate current, voltage, or resistance using Ohm''s Law","Explain what a conductor that obeys Ohm''s Law is called"]'::jsonb, 'medium', '18', '[{"id":"ohm_hook_01","type":"hook","order":1,"content":{"text":"Why does your phone charge slower when you use a cheap cable? Why do thicker wires carry more current? Why does touching both terminals of a battery give you a shock but touching just one doesn''t? All of these come down to one simple law that connects three fundamental quantities in electricity.","prediction_prompt":"If you double the voltage across a resistor, what happens to the current flowing through it? Does it double? Stay the same? Something else?"}},{"id":"ohm_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Imagine water flowing through a pipe. Voltage is like the water pressure — it pushes the water. Current is like the flow rate — how much water passes through. Resistance is like a narrow section of pipe — it restricts flow. More pressure (voltage) = more flow (current). More restriction (resistance) = less flow.","analogy":"Think of a tap. If you open it more (increase voltage), more water flows (increase current). If the pipe is narrow (high resistance), less water flows even with the tap open. Ohm''s Law connects these three: V = IR."}},{"id":"ohm_formal_01","type":"formal_explanation","order":3,"content":{"text":"Ohm''s Law states that the current through a conductor is directly proportional to the potential difference (voltage) across it, provided the temperature and other physical conditions remain constant. Mathematically: V = IR, where V is voltage, I is current, and R is resistance.","key_terms":[{"term":"Voltage (V)","definition":"The potential difference between two points. The ''push'' that moves charges. SI unit: Volt (V)"},{"term":"Current (I)","definition":"The rate of flow of charge. SI unit: Ampere (A)"},{"term":"Resistance (R)","definition":"The opposition to current flow. SI unit: Ohm (Ω)"}]}},{"id":"ohm_formula_01","type":"formula","order":4,"content":{"formula":"V = IR","variables":[{"name":"V","description":"Potential difference (voltage)","unit":"V (Volts)"},{"name":"I","description":"Current","unit":"A (Amperes)"},{"name":"R","description":"Resistance","unit":"Ω (Ohms)"}],"when_to_use":"When you know any two of V, I, R and need to find the third.","common_traps":["Using V = IR when temperature changes — Ohm''s Law only applies when temperature is constant.","Confusing the rearranged forms: I = V/R and R = V/I are the same law.","Forgetting that resistance is a property of the conductor, not of the voltage or current."],"units_note":"V in volts, I in amperes, R in ohms. If given mA, convert to A (1 mA = 0.001 A)."}},{"id":"ohm_interactive_circuit_01","type":"interactive","order":5,"content":{"component":"circuit_simulator","config":{"voltage":12,"resistors":2},"instruction":"Build the circuit in series, then in parallel. Add resistors one at a time and watch R_total, the current and the power change.","prediction_prompt":"In series, adding a resistor makes the current go up or down? In parallel? Predict, then test."}},{"id":"ohm_worked_example_01","type":"worked_example","order":6,"content":{"scenario":"A resistor of 10 Ω is connected across a 6 V battery. Calculate the current flowing through the resistor.","given":["R = 10 Ω","V = 6 V"],"required":"I (current)","principle":"Ohm''s Law: V = IR. Rearrange to find I = V/R.","steps":[{"explanation":"Write Ohm''s Law","calculation":"V = IR"},{"explanation":"Rearrange for I","calculation":"I = V/R"},{"explanation":"Substitute","calculation":"I = 6/10 = 0.6 A"}],"answer":"I = 0.6 A","check":"V = IR = 0.6 × 10 = 6 V ✓"}},{"id":"ohm_misconception_01","type":"common_misconception","order":7,"content":{"mistake":"If voltage is zero, resistance is also zero.","why_wrong":"Resistance is a property of the conductor itself (its material, length, cross-section). It doesn''t depend on whether voltage is applied.","correct_model":"Even with no voltage applied, the resistor still has resistance. It''s like a pipe — even with no water flowing, the pipe is still narrow."}},{"id":"ohm_jamb_01","type":"jamb_insight","order":8,"content":{"focus_area":"JAMB tests Ohm''s Law with circuit calculations. They give you two values and ask for the third. Sometimes they test the concept with a V-I graph (straight line through origin = ohmic conductor).","trap":"JAMB may give current in mA. Always convert to A before using V = IR.","tip":"Remember: V = IR is the fundamental form. I = V/R for finding current. R = V/I for finding resistance. Same law, different arrangement.","related_topics":["Current electricity","Electric fields"]}},{"id":"ohm_memory_01","type":"memory_hook","order":9,"content":{"text":"V = IR. Think of it as a triangle: V on top, I and R below. Cover what you want to find — if you cover I, you get V/R. If you cover R, you get V/I. If you cover V, you get IR.","hook_type":"visualization"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A current of 2 A flows through a 5 Ω resistor. What is the voltage across it?","options":[{"label":"A","text":"2.5 V"},{"label":"B","text":"7 V"},{"label":"C","text":"10 V"},{"label":"D","text":"0.4 V"}],"answer":"C","explanation":"V = IR = 2 × 5 = 10 V","hints":["V = IR","Multiply current by resistance"]},{"difficulty":"medium","question":"A 20 Ω resistor has a current of 250 mA flowing through it. What is the voltage?","options":[{"label":"A","text":"5 V"},{"label":"B","text":"0.5 V"},{"label":"C","text":"50 V"},{"label":"D","text":"12.5 V"}],"answer":"A","explanation":"First convert: 250 mA = 0.25 A. Then V = IR = 0.25 × 20 = 5 V","hints":["Convert mA to A first","250 mA = ? A","Then use V = IR"]},{"difficulty":"jamb","question":"A wire of resistance R is cut into two equal pieces. The two pieces are connected in parallel. What is the equivalent resistance?","options":[{"label":"A","text":"R"},{"label":"B","text":"R/2"},{"label":"C","text":"R/4"},{"label":"D","text":"2R"}],"answer":"C","explanation":"Each piece has resistance R/2 (half the length = half the resistance). Two R/2 in parallel: 1/Req = 1/(R/2) + 1/(R/2) = 2/R + 2/R = 4/R. So Req = R/4.","hints":["Cutting wire in half halves the resistance","Each piece is R/2","Two equal resistors in parallel: Req = R/2n"]}]'::jsonb, '{"min_score":80,"required_sections":["ohm_hook_01","ohm_intuitive_01","ohm_formal_01","ohm_formula_01","ohm_worked_example_01"]}'::jsonb, '1')
