INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Wave motion', 'Waves and Optics', 'Wave Motion — How Energy Travles Without Matter Moving', '["Define waves and distinguish between transverse and longitudinal waves","State the wave equation v = fλ and use it to solve problems","Explain amplitude, frequency, wavelength, and period","Distinguish between mechanical and electromagnetic waves"]'::jsonb, 'medium', '20', '[{"id":"wave_hook_01","type":"hook","order":1,"content":{"text":"When you shout across a valley, your voice reaches the other side — but you didn''t throw anything across. When you turn on a radio, music appears from invisible signals. When you see lightning before hearing thunder, light and sound traveled at different speeds. All of these are waves. But how does energy travel through empty space without any物质 (matter) moving with it?","prediction_prompt":"If you shake a rope up and down once, what shape travels along the rope? Does the rope itself move forward, or does something else travel?"}},{"id":"wave_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Throw a stone into a pond. Ripples spread outward. But the water doesn''t move outward — it moves up and down. The ENERGY moves outward. That''s what a wave is: energy traveling through a medium (or through space) without the medium itself moving permanently.","analogy":"Think of a crowd doing ''the wave'' at a stadium. Each person stands up and sits down, but nobody runs across the stadium. The WAVE moves across the stadium, but the PEOPLE stay in their seats. That''s exactly how waves work."}},{"id":"wave_formal_01","type":"formal_explanation","order":3,"content":{"text":"A wave is a disturbance that transfers energy from one point to another without permanent transfer of matter. Transverse waves: oscillations are perpendicular to the direction of travel (e.g., light, water waves). Longitudinal waves: oscillations are parallel to the direction of travel (e.g., sound, compression waves).","key_terms":[{"term":"Amplitude (A)","definition":"Maximum displacement from the equilibrium position. SI unit: metre (m)"},{"term":"Frequency (f)","definition":"Number of complete oscillations per second. SI unit: Hertz (Hz)"},{"term":"Wavelength (λ)","definition":"Distance between two successive points in phase. SI unit: metre (m)"},{"term":"Period (T)","definition":"Time for one complete oscillation. T = 1/f. SI unit: second (s)"}]}},{"id":"wave_formula_01","type":"formula","order":4,"content":{"formula":"v = fλ","variables":[{"name":"v","description":"Wave speed","unit":"m/s"},{"name":"f","description":"Frequency","unit":"Hz"},{"name":"λ","description":"Wavelength","unit":"m"}],"when_to_use":"When you need to find wave speed, frequency, or wavelength. Applies to ALL waves.","common_traps":["Confusing frequency and period. f = 1/T and T = 1/f.","Forgetting that wave speed depends on the medium, not the frequency.","Mixing up transverse and longitudinal wave properties."],"units_note":"v in m/s, f in Hz (which is 1/s), λ in m. Check that units are consistent."}},{"id":"wave_interactive_wave_01","type":"interactive","order":5,"content":{"component":"wave_simulator","config":{},"instruction":"Change the frequency and the amplitude independently. Note which one changes the pitch (wavelength) and which changes the loudness.","prediction_prompt":"If you halve the frequency, does the wavelength halve or double? Set it up and check."}},{"id":"wave_worked_example_01","type":"worked_example","order":6,"content":{"scenario":"A wave has a frequency of 10 Hz and a wavelength of 0.5 m. Calculate the speed of the wave.","given":["f = 10 Hz","λ = 0.5 m"],"required":"v (wave speed)","principle":"Wave equation: v = fλ","steps":[{"explanation":"Write the wave equation","calculation":"v = fλ"},{"explanation":"Substitute","calculation":"v = 10 × 0.5 = 5 m/s"}],"answer":"v = 5 m/s","check":"If frequency is 10 Hz, 10 wavelengths pass a point each second. Each wavelength is 0.5 m. Total distance = 10 × 0.5 = 5 m. Speed = 5 m/s ✓"}},{"id":"wave_misconception_01","type":"common_misconception","order":7,"content":{"mistake":"If you increase the frequency of a wave, the wavelength stays the same.","why_wrong":"In a given medium, wave speed is constant (determined by the medium). Since v = fλ, if f increases, λ must decrease to keep v constant.","correct_model":"v = fλ and v is fixed by the medium. So f and λ are inversely proportional. Double the frequency → halve the wavelength."}},{"id":"wave_jamb_01","type":"jamb_insight","order":8,"content":{"focus_area":"JAMB tests v = fλ calculations, properties of transverse vs longitudinal waves, and the relationship between frequency, wavelength, and period.","trap":"JAMB may give frequency in kHz or MHz. Always convert to Hz: 1 kHz = 1000 Hz, 1 MHz = 1,000,000 Hz.","tip":"Know your wave equation triangle: v on top, f and λ below. Cover what you want to find.","related_topics":["Sound waves","Light waves","Reflection","Refraction"]}},{"id":"wave_memory_01","type":"memory_hook","order":9,"content":{"text":"v = fλ. Think ''Victor has fλeas'' — v = f × λ. Or ''Very Fast Lambs'' — v, f, λ.","hook_type":"mnemonic"}},{"id":"wave_reflection_01","type":"reflection","order":10,"content":{"question":"If you send a wave from water into a deeper region, what happens to its speed? Its frequency? Its wavelength?","expected_understanding":"Wave speed changes with depth (deeper = faster in most cases). Frequency stays the same (determined by the source). Wavelength changes because v = fλ and v changed while f stayed constant."}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A wave has a frequency of 5 Hz and a wavelength of 2 m. What is its speed?","options":[{"label":"A","text":"2.5 m/s"},{"label":"B","text":"10 m/s"},{"label":"C","text":"7 m/s"},{"label":"D","text":"0.4 m/s"}],"answer":"B","explanation":"v = fλ = 5 × 2 = 10 m/s","hints":["v = fλ","Multiply frequency by wavelength"]},{"difficulty":"medium","question":"A sound wave has a frequency of 440 Hz and travels at 340 m/s. What is its wavelength?","options":[{"label":"A","text":"0.77 m"},{"label":"B","text":"149,600 m"},{"label":"C","text":"780 m"},{"label":"D","text":"1.3 m"}],"answer":"A","explanation":"λ = v/f = 340/440 ≈ 0.77 m","hints":["Rearrange v = fλ to find λ","λ = v/f"]},{"difficulty":"jamb","question":"A wave travels from a shallow region to a deep region in water. Which quantity remains unchanged?","options":[{"label":"A","text":"Speed"},{"label":"B","text":"Wavelength"},{"label":"C","text":"Frequency"},{"label":"D","text":"Amplitude"}],"answer":"C","explanation":"Frequency is determined by the source and does not change when the wave enters a different medium. Speed and wavelength change to maintain v = fλ.","hints":["Which quantity is determined by the source?","Frequency never changes when a wave enters a new medium"]}]'::jsonb, '{"min_score":80,"required_sections":["wave_hook_01","wave_intuitive_01","wave_formal_01","wave_formula_01","wave_worked_example_01"]}'::jsonb, '1')
