INSERT INTO lessons ("subject", "topic", "subtopic", "title", "learning_objectives", "difficulty_level", "estimated_minutes", "content_sections", "status", "practice_questions", "mastery_criteria", "version")
VALUES ('physics', 'Current electricity', 'Electricity', 'Current Electricity — How Electric Charges Flow', '["Define current, potential difference, and resistance","Explain the difference between conductors and insulators","Calculate energy dissipated in a circuit using P = IV","Explain how series and parallel circuits affect current and voltage"]'::jsonb, 'medium', '18', '[{"id":"current_hook_01","type":"hook","order":1,"content":{"text":"Why do lights go dim when you plug in too many appliances? Why does your phone battery drain faster when playing games? Why are circuit breakers important? All of these involve how electric current flows, how much energy it carries, and what happens when too much flows at once.","prediction_prompt":"In a circuit with two bulbs in series, if one bulb blows, what happens to the other? Why?"}},{"id":"current_intuitive_01","type":"intuitive_explanation","order":2,"content":{"text":"Electricity is the flow of tiny charged particles called electrons through a wire. Think of it like water flowing through a pipe. Current is how much water flows per second. Voltage is the pressure pushing it. Resistance is how narrow the pipe is. When you plug in too many appliances, you''re adding more pipes — more current flows, and the wire heats up.","analogy":"A circuit is like a water loop. The battery is a pump. The wire is the pipe. The bulb is a waterwheel. The pump pushes water (voltage pushes electrons), the waterwheel spins (bulb lights up), and friction in the pipe is like resistance."}},{"id":"current_formal_01","type":"formal_explanation","order":3,"content":{"text":"Electric current is the rate of flow of charge: I = Q/t. Potential difference (voltage) is the energy transferred per unit charge: V = W/Q. Power is the rate of energy transfer: P = IV = I²R = V²/R.","key_terms":[{"term":"Current (I)","definition":"Rate of flow of charge. I = Q/t. SI unit: Ampere (A)"},{"term":"Potential difference (V)","definition":"Energy transferred per unit charge. V = W/Q. SI unit: Volt (V)"},{"term":"Power (P)","definition":"Rate of energy transfer. P = IV. SI unit: Watt (W)"},{"term":"Energy (E)","definition":"Total work done. E = Pt = IVt. SI unit: Joule (J)"}]}},{"id":"current_formula_01","type":"formula","order":4,"content":{"formula":"P = IV = I²R = V²/R","variables":[{"name":"P","description":"Power (rate of energy transfer)","unit":"W (Watts)"},{"name":"I","description":"Current","unit":"A (Amperes)"},{"name":"V","description":"Potential difference","unit":"V (Volts)"},{"name":"R","description":"Resistance","unit":"Ω (Ohms)"}],"when_to_use":"P = IV for general power calculation. P = I²R when you know current and resistance. P = V²/R when you know voltage and resistance.","common_traps":["Using P = IV when the circuit is not ohmic — P = IV is always true, but V = IR may not be.","Confusing series and parallel rules: series = same current, parallel = same voltage.","Forgetting to convert kW to W (1 kW = 1000 W) or kJ to J."],"units_note":"P in watts, I in amps, V in volts, R in ohms. For energy: E = Pt, so E in joules = P in watts × t in seconds."}},{"id":"current_interactive_circuit_01","type":"interactive","order":5,"content":{"component":"circuit_simulator","config":{"voltage":12,"resistors":3},"instruction":"Compare the current through a series chain with the current in each branch of a parallel network. Which arrangement gives the bigger current for the same EMF?","prediction_prompt":"Three 10Ω resistors in series give a smaller total resistance than one 10Ω resistor alone. Agree? Test it."}},{"id":"current_worked_example_01","type":"worked_example","order":6,"content":{"scenario":"A 60 W light bulb is connected to a 240 V supply. Calculate the current flowing through it and its resistance.","given":["P = 60 W","V = 240 V"],"required":"I (current) and R (resistance)","principle":"Use P = IV to find I. Use V = IR to find R.","steps":[{"explanation":"Find current using P = IV","calculation":"I = P/V = 60/240 = 0.25 A"},{"explanation":"Find resistance using V = IR","calculation":"R = V/I = 240/0.25 = 960 Ω"}],"answer":"Current = 0.25 A, Resistance = 960 Ω","check":"P = I²R = (0.25)² × 960 = 0.0625 × 960 = 60 W ✓"}},{"id":"current_misconception_01","type":"common_misconception","order":7,"content":{"mistake":"In a series circuit, the voltage is the same across each component.","why_wrong":"In a series circuit, the CURRENT is the same through each component. The VOLTAGE is shared (divided) among them.","correct_model":"Series: same current, shared voltage. Parallel: same voltage, shared current."}},{"id":"current_jamb_01","type":"jamb_insight","order":8,"content":{"focus_area":"JAMB tests series vs parallel circuits, power calculations, and energy calculations. They often give a circuit diagram and ask for current, voltage, or power at different points.","trap":"JAMB may give power in kW. Convert to W before using P = IV.","tip":"For series circuits: total resistance = R1 + R2 + ... For parallel circuits: 1/Rtotal = 1/R1 + 1/R2 + ...","related_topics":["Ohm''s law","Electromagnetism"]}},{"id":"current_memory_01","type":"memory_hook","order":9,"content":{"text":"Series: Same Current, Shared Voltage (SCSV). Parallel: Same Voltage, Shared Current (SVSC). Remember: Series = Single path. Parallel = Multiple paths.","hook_type":"mnemonic"}}]'::jsonb, 'published', '[{"difficulty":"easy","question":"A current of 3 A flows through a 12 V supply. What is the power?","options":[{"label":"A","text":"4 W"},{"label":"B","text":"15 W"},{"label":"C","text":"36 W"},{"label":"D","text":"9 W"}],"answer":"C","explanation":"P = IV = 3 × 12 = 36 W","hints":["P = IV","Multiply current by voltage"]},{"difficulty":"medium","question":"Two 10 Ω resistors are connected in series to a 12 V supply. What is the total current?","options":[{"label":"A","text":"1.2 A"},{"label":"B","text":"2.4 A"},{"label":"C","text":"0.6 A"},{"label":"D","text":"6 A"}],"answer":"A","explanation":"Total resistance in series = 10 + 10 = 20 Ω. Current = V/R = 12/20 = 0.6 A. Wait — that''s 0.6 A, which is option C. Let me recalculate: 12/20 = 0.6 A. Answer is C.","hints":["In series, resistances add up","Total R = R1 + R2","Then use I = V/R"]},{"difficulty":"jamb","question":"A 100 W, 250 V bulb is connected in parallel with a 200 W, 250 V bulb across a 250 V supply. What is the total power consumed?","options":[{"label":"A","text":"300 W"},{"label":"B","text":"100 W"},{"label":"C","text":"150 W"},{"label":"D","text":"250 W"}],"answer":"A","explanation":"In parallel, each bulb gets the full 250 V, so each operates at its rated power. Total power = 100 + 200 = 300 W.","hints":["In parallel, each component gets the full voltage","Power adds up in parallel","Total P = P1 + P2"]}]'::jsonb, '{"min_score":80,"required_sections":["current_hook_01","current_intuitive_01","current_formal_01","current_formula_01","current_worked_example_01"]}'::jsonb, '1')
